export const questions = [{"id":"RP-S-0001","type":"single","qtype":"单选题","stem":"《放射性药品生产检查指南（试行）》的发布单位是（ ）","options":[{"key":"A","text":"国家药品监督管理局"},{"key":"B","text":"国家药品监督管理局特殊药品检查中心"},{"key":"C","text":"国家卫生健康委员会"},{"key":"D","text":"国家药典委员会"}],"answer":["B"],"explanation":"《放射性药品生产检查指南（试行）》由国家药品监督管理局特殊药品检查中心发布。国家药品监督管理局负责全国放射性药品监督管理工作，但本指南的具体发布主体是其下属的特殊药品检查中心；国家卫生健康委员会负责卫生健康管理；国家药典委员会负责药典标准制定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第四条规定：国务院药品监督管理部门负责全国放射性药品监督管理工作。国务院国防科技工业主管部门依据职责负责与放射性药品有关的管理工作。国务院环境保护主管部门负责与放射性药品有关的辐射安全与防护的监督管理工作。\n国家药品监督管理局作为国务院药品监督管理部门，其下属的特殊药品检查中心具体承担放射性药品生产检查指南的制定和发布工作。因此，本指南的发布单位为“国家药品监督管理局特殊药品检查中心”，选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 1 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0002","type":"single","qtype":"单选题","stem":"本指南的施行日期是（ ）","options":[{"key":"A","text":"2024年12月"},{"key":"B","text":"2025年3月1日"},{"key":"C","text":"2020年7月"},{"key":"D","text":"2019年8月"}],"answer":["B"],"explanation":"《放射性药品生产检查指南（试行）》明确自2025年3月1日起施行。该指南的制定和发布背景与《放射性药品管理办法》的修订密切相关，2022年3月29日《放射性药品管理办法》完成第三次修订后，相关配套检查指南陆续出台。题干考查的是指南本身的施行日期，其他选项为干扰项。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》（2022年3月29日第三次修订）第二十八条规定：本办法自发布之日起施行。\n《放射性药品生产检查指南（试行）》作为《放射性药品管理办法》的配套技术指南，由国家药品监督管理局特殊药品检查中心于2024年12月发布，并明确自2025年3月1日起施行。该指南的施行日期独立于《放射性药品管理办法》本身，但两者在时间上具有衔接关系。因此，选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 2 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0003","type":"single","qtype":"单选题","stem":"制定本指南的核心目的是（ ）","options":[{"key":"A","text":"规范放射性药品经营活动"},{"key":"B","text":"为放射性药品生产现场检查提供指导"},{"key":"C","text":"明确放射性药品使用规范"},{"key":"D","text":"监督放射性药品研发过程"}],"answer":["B"],"explanation":"《放射性药品生产检查指南（试行）》的定位是放射性药品生产现场检查的指导性文件，核心目的是为生产现场检查提供指导。规范经营活动、明确使用规范、监督研发过程分别对应经营环节、使用环节和研发环节的管理要求，均不是该指南的主要制定目的。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第一条规定：为了加强放射性药品的管理，根据《中华人民共和国药品管理法》的规定，制定本办法。\n第三条进一步规定：凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n《放射性药品生产检查指南（试行）》是依据《放射性药品管理办法》第三条所涵盖的“生产”环节而制定的配套技术指南，其核心目的即为放射性药品生产现场检查提供具体指导。因此，选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 3 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0004","type":"single","qtype":"单选题","stem":"以下哪项不属于放射性药品的特点（ ）","options":[{"key":"A","text":"放射性"},{"key":"B","text":"恒定性"},{"key":"C","text":"自辐射分解"},{"key":"D","text":"化学量少"}],"answer":["B"],"explanation":"放射性药品通常具有放射性、自辐射分解、化学量少等特点。由于放射性核素会不断衰变，其放射性活度随时间变化，因此“恒定性”不是放射性药品的特点。选项A、C、D均属于放射性药品的典型特点。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n该定义明确了放射性药品的核心属性——含有放射性核素，因此具有“放射性”特点；由于放射性核素会发生衰变，药品的活度不恒定，且衰变过程中可能产生自辐射分解，同时放射性药品中放射性物质的化学量通常极少。而“恒定性”与放射性核素持续衰变的物理规律相悖，因此不属于放射性药品的特点。选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 4 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0005","type":"single","qtype":"单选题","stem":"《中华人民共和国药品管理法》将放射性药品定为（ ）","options":[{"key":"A","text":"普通药品"},{"key":"B","text":"特殊管理的药品"},{"key":"C","text":"处方药"},{"key":"D","text":"非处方药"}],"answer":["B"],"explanation":"《中华人民共和国药品管理法》规定，国家对麻醉药品、精神药品、医疗用毒性药品、放射性药品实行特殊管理。放射性药品因具有放射性和辐射安全风险，被列为特殊管理的药品。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第一条明确：为了加强放射性药品的管理，根据《中华人民共和国药品管理法》的规定，制定本办法。\n《中华人民共和国药品管理法》第五十三条规定：国家对麻醉药品、精神药品、医疗用毒性药品、放射性药品，实行特殊管理。管理办法由国务院制定。\n《放射性药品管理办法》正是依据《药品管理法》第五十三条制定的行政法规，进一步印证了放射性药品属于国家特殊管理的药品这一法律定位。因此，选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 5 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0006","type":"single","qtype":"单选题","stem":"本指南适用于放射性药品哪个环节的检查（ ）","options":[{"key":"A","text":"研发"},{"key":"B","text":"生产"},{"key":"C","text":"经营"},{"key":"D","text":"使用"}],"answer":["B"],"explanation":"《放射性药品生产检查指南（试行）》名称和适用范围均明确指向放射性药品生产环节的现场检查。研发、经营、使用等环节分别有其他管理规范和要求，不属于本指南主要适用环节。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第三条规定：凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n该条将放射性药品的管理环节明确区分为“研究、生产、经营、运输、使用、检验、监督管理”等多个环节。《放射性药品生产检查指南（试行）》是针对其中的“生产”环节制定的专项检查指南，其适用范围明确限定于放射性药品生产环节的现场检查。因此，选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 6 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0007","type":"single","qtype":"单选题","stem":"适用本指南的放射性药品不包括（ ）","options":[{"key":"A","text":"医用放射性核素发生器"},{"key":"B","text":"普通化学药品"},{"key":"C","text":"即时标记放射性药品"},{"key":"D","text":"放射免疫分析药盒"}],"answer":["B"],"explanation":"本指南适用于医用放射性核素发生器、即时标记放射性药品、放射免疫分析药盒等放射性药品相关生产检查。普通化学药品不具有放射性，不属于放射性药品管理范畴，因此不适用本指南。选项A、C、D均属于指南适用对象。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条进一步规定：研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n根据第二条的定义，放射性药品的核心特征是含有放射性核素。医用放射性核素发生器、即时标记放射性药品、放射免疫分析药盒均属于“放射性核素制剂或者其标记药物”的范畴，而普通化学药品不含有放射性核素，不属于放射性药品，因此不适用本指南。选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 7 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0008","type":"single","qtype":"单选题","stem":"以下哪项不是本指南的检查依据（ ）","options":[{"key":"A","text":"《药品经营质量管理规范》"},{"key":"B","text":"《放射性药品管理办法》（2022年修订）"},{"key":"C","text":"《中华人民共和国药典》（2020年版）"},{"key":"D","text":"《药品生产质量管理规范（2010年版）》"}],"answer":["A"],"explanation":"本指南为放射性药品生产检查指南，其检查依据主要包括《放射性药品管理办法》（2022年修订）、《中华人民共和国药典》（2020年版）、《药品生产质量管理规范（2010年版）》等。《药品经营质量管理规范》主要适用于药品经营环节，不是本指南的生产现场检查依据。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第一条规定：为了加强放射性药品的管理，根据《中华人民共和国药品管理法》的规定，制定本办法。\n该办法是放射性药品生产、经营、使用等全环节管理的基本行政法规，自然也是《放射性药品生产检查指南（试行）》的核心检查依据之一。同时，第十条至第十四条详细规定了放射性药品生产企业的开办条件、许可证管理、专业技术人员配备、质量检验机构建立等生产管理要求，这些条款构成了本指南在生产环节进行现场检查的直接法规依据。\n《药品经营质量管理规范》主要规范药品经营环节的质量管理，与生产检查指南的适用范围不同，因此不是本指南的检查依据。选项A正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 8 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0009","type":"single","qtype":"单选题","stem":"《放射性药品管理办法》（2022年修订）的发布日期是（ ）","options":[{"key":"A","text":"2019年8月26日"},{"key":"B","text":"2022年3月29日"},{"key":"C","text":"2020年7月"},{"key":"D","text":"2019年3月"}],"answer":["B"],"explanation":"《放射性药品管理办法》于2022年修订，其发布日期为2022年3月29日。题干考查的是该办法2022年修订版本的发布日期，其他选项为干扰项。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》的公布日期为2022年3月29日。该办法最初于1989年1月13日由中华人民共和国国务院令第25号发布，先后经历2011年、2017年、2022年和2024年四次修订。\n2022年3月29日《国务院关于修改和废止部分行政法规的决定》完成了第三次修订，因此该日期即题干所指“2022年修订”的发布日期。选项B正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 9 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0010","type":"single","qtype":"单选题","stem":"放射性药品生产的核心三环节不包括（ ）","options":[{"key":"A","text":"放射性核素的生产"},{"key":"B","text":"配体的生产"},{"key":"C","text":"放射性核素与配体的结合"},{"key":"D","text":"药品广告推广"}],"answer":["D"],"explanation":"放射性药品生产的核心三环节包括：放射性核素的生产、配体的生产、放射性核素与配体的结合。药品广告推广属于市场宣传和推广行为，不属于放射性药品生产的技术核心环节。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条规定：放射性新药的研制内容，包括工艺路线、质量标准、临床前药理及临床研究。研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、放射性比活度、剂量、剂型、稳定性等。\n从第二条的定义出发，放射性药品的制备离不开放射性核素和配体（标记药物中的非放射性部分），而实际生产中必然涉及“放射性核素的生产”“配体的生产”以及“放射性核素与配体的结合”三个核心技术环节。药品广告推广属于经营推广行为，与生产环节的技术过程无关，因此不属于核心三环节。选项D正确。\n\n---","source":{"file":"单选题/1-10.md","merged":"单选题1-400.md","location":"第 10 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0011","type":"single","qtype":"单选题","stem":"最常用的医用核素发生器是（ ）","options":[{"key":"A","text":"氟[18F]-脱氧葡糖发生器"},{"key":"B","text":"钼[99Mo]-锝[99mTc]发生器"},{"key":"C","text":"碘[125I]-密封籽源发生器"},{"key":"D","text":"磷[32P]-酸钠盐发生器"}],"answer":["B"],"explanation":"钼[99Mo]-锝[99mTc]发生器是核医学临床诊断中最常用的医用放射性核素发生器，可产生锝[99mTc]用于多种显像检查。氟[18F]通常由加速器制备，碘[125I]密封籽源属于植入制品，磷[32P]酸钠盐属于口服溶液，均不是最常用的医用核素发生器。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n钼[99Mo]-锝[99mTc]发生器属于放射性核素制剂的一种，其原理是母体核素钼[99Mo]衰变生成子体核素锝[99mTc]，通过淋洗获得高锝[99mTc]酸钠注射液，再与配套药盒标记制备多种锝[99mTc]放射性药品。该发生器在核医学诊断中应用最广泛。因此，选项B正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 11 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0012","type":"single","qtype":"单选题","stem":"“即时标记”的定义是（ ）","options":[{"key":"A","text":"生产时提前完成放射性标记"},{"key":"B","text":"使用前进行放射性标记"},{"key":"C","text":"运输过程中完成标记"},{"key":"D","text":"储存过程中完成标记"}],"answer":["B"],"explanation":"“即时标记”是指放射性药品在使用前，用发生器洗脱液与配套药盒进行放射性标记制备的过程。其特点是不提前完成标记，而是在临床使用前即时制备，以保证产品的放射化学纯度和活度。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n即时标记放射性药品属于放射性核素标记药物的一种特殊形式，其标记过程发生在使用前，而非生产时提前完成。这种模式可缩短从标记到使用的时间，减少放射性衰变和辐射分解的影响，确保药品质量。因此，选项B正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 12 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0013","type":"single","qtype":"单选题","stem":"放射性药品配套药盒不含有的成分是（ ）","options":[{"key":"A","text":"配体"},{"key":"B","text":"还原剂"},{"key":"C","text":"放射性核素"},{"key":"D","text":"稳定剂"}],"answer":["C"],"explanation":"放射性药品配套药盒通常含有配体、还原剂、稳定剂等非放射性成分，但不含有放射性核素。放射性核素是在使用前通过发生器淋洗液加入，与药盒中的配体进行标记反应。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n配套药盒本身不含放射性核素，属于非放射性组分，其作用是提供标记反应所需的配体、还原剂和稳定剂等。使用时，将发生器淋洗得到的高锝[99mTc]酸钠注射液加入药盒，经还原和标记反应生成锝[99mTc]标记药物。因此，配套药盒中不含有放射性核素，选项C正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 13 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0014","type":"single","qtype":"单选题","stem":"正电子类放射性药品的核心特征是（ ）","options":[{"key":"A","text":"含有发射正电子的放射性核素"},{"key":"B","text":"半衰期极长"},{"key":"C","text":"仅用于治疗"},{"key":"D","text":"无需辐射防护"}],"answer":["A"],"explanation":"正电子类放射性药品的核心特征是含有发射正电子的放射性核素，如氟[18F]、碳[11C]等。这类核素衰变时发射正电子，用于PET显像。其半衰期通常较短，主要用于诊断，且必须进行辐射防护。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n正电子类放射性药品属于放射性核素制剂或标记药物的一种，其核心在于所含放射性核素能够发射正电子。例如氟[18F]脱氧葡糖注射液，利用氟[18F]发射的正电子进行PET显像。正电子类药品半衰期短、主要用于诊断，且操作中需严格辐射防护。因此，选项A正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 14 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0015","type":"single","qtype":"单选题","stem":"热室的主要功能是（ ）","options":[{"key":"A","text":"普通药品生产"},{"key":"B","text":"放射性物质生产与处理（含辐射防护）"},{"key":"C","text":"药品储存"},{"key":"D","text":"药品检验"}],"answer":["B"],"explanation":"热室是放射性药品生产中用于放射性物质生产与处理的专用设施，具备辐射防护功能，可屏蔽射线、防止放射性污染扩散。普通药品生产、药品储存、药品检验均不是热室的主要功能。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n热室正是为满足放射性药品生产过程中辐射防护和废物处理要求而设置的关键设施，用于放射性物质的操作、合成、分装等，并配备铅屏蔽、负压通风、去污系统等。因此，热室的主要功能是放射性物质生产与处理（含辐射防护），选项B正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 15 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0016","type":"single","qtype":"单选题","stem":"卡套的性质是（ ）","options":[{"key":"A","text":"可重复使用的流体管路系统"},{"key":"B","text":"一次性流体管路系统（含合成试剂）"},{"key":"C","text":"放射性核素储存容器"},{"key":"D","text":"辐射防护铅罐"}],"answer":["B"],"explanation":"卡套是一次性流体管路系统，通常包含合成试剂，用于正电子类放射性药品的自动合成。其设计为一次性使用，以避免交叉污染并简化清洁验证。可重复使用、放射性核素储存容器、辐射防护铅罐均不是卡套的性质。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n在正电子类放射性药品生产中，卡套作为自动合成系统的一次性流体管路组件，内含合成所需试剂，可有效防止不同批次间的交叉污染，并减少放射性操作人员的辐射暴露。其一次性使用特性符合放射性药品生产质量管理及辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 16 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0017","type":"single","qtype":"单选题","stem":"本指南中工艺描述的依据是（ ）","options":[{"key":"A","text":"企业内部工艺"},{"key":"B","text":"《中国药典》（2020年版）+行业通用工艺"},{"key":"C","text":"仅检查员经验"},{"key":"D","text":"国际标准"}],"answer":["B"],"explanation":"本指南中工艺描述的依据是《中国药典》（2020年版）及行业通用工艺，以确保检查标准的科学性和规范性。企业内部工艺、检查员经验、国际标准均不是本指南工艺描述的主要依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第五条规定：放射性新药的研制内容，包括工艺路线、质量标准、临床前药理及临床研究。研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、放射性比活度、剂量、剂型、稳定性等。\n《中国药典》（2020年版）是放射性药品质量标准的核心依据，其中收录了多种放射性药品的通用要求及具体品种标准。本指南在描述工艺时，以《中国药典》和行业通用工艺为基础，确保检查要求与法定标准一致。因此，选项B正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 17 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0018","type":"single","qtype":"单选题","stem":"多数放射性核素需制成标记化合物使用的原因是（ ）","options":[{"key":"A","text":"直接使用成本高"},{"key":"B","text":"多数核素无法直接用于诊疗"},{"key":"C","text":"便于运输"},{"key":"D","text":"提高稳定性"}],"answer":["B"],"explanation":"多数放射性核素无法直接用于诊疗，需要制成标记化合物，使其具有靶向性，能够浓聚在特定组织或器官，从而实现诊断或治疗目的。直接使用成本高、便于运输、提高稳定性均不是主要原因。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n该定义明确放射性药品包括“放射性核素制剂”和“其标记药物”。多数放射性核素本身缺乏靶向性，无法直接用于诊断或治疗，必须通过与配体结合制成标记化合物，才能实现特定靶器官显像或治疗。例如锝[99mTc]需与多种配体标记后用于不同脏器显像。因此，选项B正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 18 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0019","type":"single","qtype":"单选题","stem":"钼[99Mo]-锝[99mTc]发生器的俗称是（ ）","options":[{"key":"A","text":"母牛"},{"key":"B","text":"核源"},{"key":"C","text":"种子"},{"key":"D","text":"反应堆"}],"answer":["A"],"explanation":"钼[99Mo]-锝[99mTc]发生器俗称“母牛”，因其母体核素钼[99Mo]衰变产生子体核素锝[99mTc]，通过淋洗获取子体，类似于母牛产奶的过程。核源、种子、反应堆均不是其俗称。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n钼[99Mo]-锝[99mTc]发生器属于放射性核素制剂，其中钼[99Mo]为母体核素，锝[99mTc]为子体核素。在核医学领域，该发生器形象地被称为“母牛”，淋洗过程称为“挤奶”，产生的锝[99mTc]淋洗液用于标记各种配套药盒。因此，选项A正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 19 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0020","type":"single","qtype":"单选题","stem":"《药品生产质量管理规范（2010年版）》在本指南中的角色是（ ）","options":[{"key":"A","text":"参考文件"},{"key":"B","text":"核心检查依据"},{"key":"C","text":"辅助说明"},{"key":"D","text":"无关文件"}],"answer":["B"],"explanation":"《药品生产质量管理规范（2010年版）》是放射性药品生产检查的核心依据之一，本指南在制定时以其为基础，结合放射性药品特殊要求进行细化。参考文件、辅助说明、无关文件均不能准确描述其在本指南中的核心地位。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第一条明确：为了加强放射性药品的管理，根据《中华人民共和国药品管理法》的规定，制定本办法。\n《药品生产质量管理规范（2010年版）》是依据《药品管理法》制定的药品生产质量管理基本规范，适用于所有药品生产企业，包括放射性药品生产企业。本指南在放射性药品生产检查中，将《药品生产质量管理规范（2010年版）》作为核心检查依据，并针对放射性药品的辐射防护、核素衰变、即时标记等特点进行补充规定。因此，选项B正确。\n\n---","source":{"file":"单选题/11-20.md","merged":"单选题1-400.md","location":"第 20 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0021","type":"single","qtype":"单选题","stem":"《中国药典》（2020年版）收录的锝[99mTc]放射性药品注射液有（ ）个品种","options":[{"key":"A","text":"6"},{"key":"B","text":"8"},{"key":"C","text":"10"},{"key":"D","text":"12"}],"answer":["C"],"explanation":"《中国药典》（2020年版）收录的锝[99mTc]放射性药品注射液共有10个品种，包括高锝[99mTc]酸钠注射液、锝[99mTc]甲氧异腈注射液、锝[99mTc]亚甲基二膦酸盐注射液等。这些品种覆盖了核医学诊断中常用的多种显像剂。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n《中国药典》（2020年版）是放射性药品质量标准的法定依据，其中收载了锝[99mTc]放射性药品注射液共10个品种。这些品种均属于放射性核素标记药物，需符合药典规定的性状、鉴别、放射化学纯度、无菌、细菌内毒素等质量要求。因此，选项C正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 21 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0022","type":"single","qtype":"单选题","stem":"锝[99mTc]的半衰期是（ ）","options":[{"key":"A","text":"6.02小时"},{"key":"B","text":"110分钟"},{"key":"C","text":"59.41天"},{"key":"D","text":"20分钟"}],"answer":["A"],"explanation":"锝[99mTc]的半衰期为6.02小时，这是其作为核医学诊断显像剂的重要物理特性，既能保证足够的显像时间，又不会给患者带来过大的辐射剂量。110分钟是氟[18F]的半衰期，59.41天是碘[125I]的半衰期，20分钟是碳[11C]等短半衰期核素的典型值。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n锝[99mTc]是核医学中最常用的放射性核素，其半衰期6.02小时，发射γ射线，适用于SPECT显像。药典及放射性药品标准中均明确规定了锝[99mTc]的核素半衰期等核物理参数，作为质量控制和临床使用的重要依据。因此，选项A正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 22 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0023","type":"single","qtype":"单选题","stem":"制备高锝[99mTc]酸钠注射液的淋洗液是（ ）","options":[{"key":"A","text":"灭菌注射用水"},{"key":"B","text":"0.9%氯化钠注射液"},{"key":"C","text":"氢氧化钠溶液"},{"key":"D","text":"盐酸溶液"}],"answer":["B"],"explanation":"制备高锝[99mTc]酸钠注射液时，使用0.9%氯化钠注射液作为淋洗液，从钼[99Mo]-锝[99mTc]发生器中淋洗出高锝[99mTc]酸钠。灭菌注射用水、氢氧化钠溶液、盐酸溶液均不是标准淋洗液。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n高锝[99mTc]酸钠注射液属于放射性核素制剂，其制备过程为：用0.9%氯化钠注射液淋洗钼[99Mo]-锝[99mTc]发生器，得到高锝[99mTc]酸钠注射液。该淋洗液需符合《中国药典》中氯化钠注射液的质量要求，且淋洗操作应在规定的洁净环境和辐射防护条件下进行。因此，选项B正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 23 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0024","type":"single","qtype":"单选题","stem":"钼[99Mo]的γ射线能量为（ ）","options":[{"key":"A","text":"0.539MeV"},{"key":"B","text":"0.739MeV"},{"key":"C","text":"0.839MeV"},{"key":"D","text":"1.039MeV"}],"answer":["B"],"explanation":"钼[99Mo]衰变时发射的γ射线主要能量为0.739MeV，该能量用于核素鉴别和质量控制。0.539MeV、0.839MeV、1.039MeV均不是钼[99Mo]的特征γ射线能量。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n钼[99Mo]是钼[99Mo]-锝[99mTc]发生器的母体核素，其衰变产生锝[99mTc]并伴随γ射线发射。在放射性药品质量控制中，需使用多道γ谱仪测定钼[99Mo]的γ射线能量，以鉴别核素和检测钼[99Mo]的残留量。药典规定钼[99Mo]的特征γ射线能量为0.739MeV。因此，选项B正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 24 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0025","type":"single","qtype":"单选题","stem":"钼[99Mo]-锝[99mTc]发生器的色谱柱需装入（ ）屏蔽射线","options":[{"key":"A","text":"塑料罐"},{"key":"B","text":"铅罐"},{"key":"C","text":"铁罐"},{"key":"D","text":"铝罐"}],"answer":["B"],"explanation":"钼[99Mo]-锝[99mTc]发生器的色谱柱需装入铅罐以屏蔽射线，保护操作人员和周围环境免受辐射危害。塑料罐、铁罐、铝罐对γ射线的屏蔽效果远不如铅，不能满足辐射防护要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n钼[99Mo]-锝[99mTc]发生器中的钼[99Mo]发射γ射线，需采用高密度材料如铅进行屏蔽。铅罐可有效降低操作位置的辐射剂量率，符合辐射防护最优化原则。因此，发生器的色谱柱需装入铅罐屏蔽射线，选项B正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 25 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0026","type":"single","qtype":"单选题","stem":"锝[99mTc]配套药盒中，还原剂的作用是（ ）","options":[{"key":"A","text":"将低价锝氧化为高价态"},{"key":"B","text":"将高价锝还原为低价态"},{"key":"C","text":"稳定配体结构"},{"key":"D","text":"增加放射性活度"}],"answer":["B"],"explanation":"锝[99mTc]配套药盒中的还原剂（如氯化亚锡）作用是将高价态的高锝[99mTc]酸根（TcO₄⁻，+7价）还原为低价态的锝[99mTc]（如+4价），使其能够与配体结合形成标记化合物。氧化、稳定配体、增加活度均不是还原剂的作用。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n锝[99mTc]配套药盒属于放射性核素标记药物的组成部分，其标记原理为：高锝[99mTc]酸钠注射液中的TcO₄⁻处于高价态，不能直接与配体结合，需加入还原剂（如氯化亚锡）将其还原为低价态，再与药盒中的配体发生螯合反应，形成锝[99mTc]标记药物。因此，还原剂的作用是将高价锝还原为低价态，选项B正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 26 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0027","type":"single","qtype":"单选题","stem":"锝[99mTc]配套药盒本身（ ）","options":[{"key":"A","text":"有放射性"},{"key":"B","text":"无放射性"},{"key":"C","text":"有轻微放射性"},{"key":"D","text":"放射性随储存时间增加"}],"answer":["B"],"explanation":"锝[99mTc]配套药盒本身不含放射性核素，属于非放射性产品，其成分包括配体、还原剂、稳定剂等。放射性核素是在使用前通过淋洗液加入，与药盒中的配体进行标记反应。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n锝[99mTc]配套药盒本身不含有放射性核素，因此不属于放射性药品，而是作为制备放射性药品的配套非放射性组分进行管理。使用时，将高锝[99mTc]酸钠注射液加入药盒，经还原和标记反应生成锝[99mTc]标记药物。药盒在储存过程中无放射性，也不随时间增加放射性。因此，选项B正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 27 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0028","type":"single","qtype":"单选题","stem":"锝[99mTc]配套药盒（冻干粉针剂）的工艺不包括（ ）","options":[{"key":"A","text":"药液配制"},{"key":"B","text":"除菌过滤"},{"key":"C","text":"定量分装"},{"key":"D","text":"高温灭菌"}],"answer":["D"],"explanation":"锝[99mTc]配套药盒（冻干粉针剂）的生产工艺包括药液配制、除菌过滤、定量分装、冷冻干燥等，但不包括高温灭菌。因为药盒中含有对热不稳定的配体和还原剂，高温灭菌会导致其分解失效，故采用无菌生产工艺。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n锝[99mTc]配套药盒作为非放射性配套组分，其生产需符合药品GMP要求。由于药盒中配体和还原剂对热敏感，不能采用最终高温灭菌工艺，而应采用无菌生产工艺，包括药液配制、除菌过滤、定量分装和冷冻干燥等步骤。因此，高温灭菌不属于其工艺，选项D正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 28 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0029","type":"single","qtype":"单选题","stem":"锝[99mTc]甲氧异腈注射液标记时，沸水浴加热时间为（ ）","options":[{"key":"A","text":"1～5分钟"},{"key":"B","text":"5～15分钟"},{"key":"C","text":"15～20分钟"},{"key":"D","text":"20～30分钟"}],"answer":["B"],"explanation":"锝[99mTc]甲氧异腈注射液标记时，需将高锝[99mTc]酸钠注射液加入配套药盒后，在沸水浴中加热5～15分钟，以完成标记反应。加热时间过短标记不完全，过长可能导致产品分解。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n锝[99mTc]甲氧异腈注射液是药典收载的锝[99mTc]标记药物之一，其标记过程需严格按照规定操作。药典中明确规定：取高锝[99mTc]酸钠注射液加入甲氧异腈配套药盒，沸水浴加热5～15分钟，冷却后即得。该加热时间范围是保证放射化学纯度和标记率的关键参数。因此，选项B正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 29 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0030","type":"single","qtype":"单选题","stem":"锝[99mTc]甲氧异腈注射液的淋洗操作环境是（ ）","options":[{"key":"A","text":"A级"},{"key":"B","text":"B级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["C"],"explanation":"锝[99mTc]甲氧异腈注射液的淋洗操作环境为C级洁净区。淋洗过程涉及放射性核素的操作，需在规定的洁净级别下进行，以控制微生物和微粒污染，同时配合辐射防护措施。A级、B级、D级均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，锝[99mTc]甲氧异腈注射液的淋洗操作属于即时标记放射性药品的制备环节，应在C级洁净区进行。该级别可有效控制环境中的微粒和微生物，同时便于实施辐射防护和去污措施。因此，选项C正确。\n\n---","source":{"file":"单选题/21-30.md","merged":"单选题1-400.md","location":"第 30 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0031","type":"single","qtype":"单选题","stem":"氟[18F]脱氧葡糖注射液中氟[18F]的制备方式是（ ）","options":[{"key":"A","text":"反应堆制备"},{"key":"B","text":"发生器制备"},{"key":"C","text":"加速器制备"},{"key":"D","text":"化学合成"}],"answer":["C"],"explanation":"氟[18F]脱氧葡糖注射液中的氟[18F]通常由回旋加速器通过核反应制备，而不是反应堆或发生器。氟[18F]是正电子发射核素，半衰期约110分钟，需通过加速器产生。化学合成是后续标记步骤，不是核素制备方式。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n氟[18F]脱氧葡糖注射液属于正电子类放射性药品，其中氟[18F]核素由加速器制备，通常利用¹⁸O(p,n)¹⁸F核反应。加速器制备的氟[18F]具有高比活度，适合PET显像。反应堆主要用于生产钼[99Mo]、碘[131I]等核素，发生器用于产生锝[99mTc]等。因此，选项C正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 31 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0032","type":"single","qtype":"单选题","stem":"氟[18F]的半衰期约为（ ）","options":[{"key":"A","text":"6.02小时"},{"key":"B","text":"110分钟"},{"key":"C","text":"59.41天"},{"key":"D","text":"20分钟"}],"answer":["B"],"explanation":"氟[18F]的半衰期约为110分钟，这一适中的半衰期使其适合PET显像，既能保证合成和运输时间，又能在患者体内快速衰变。6.02小时是锝[99mTc]的半衰期，59.41天是碘[125I]的半衰期，20分钟是碳[11C]等短半衰期核素的典型值。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n氟[18F]是正电子发射核素，其半衰期约为110分钟，发射正电子后湮灭产生两个511keVγ光子，用于PET显像。药典及放射性药品标准中明确规定了氟[18F]的核素半衰期等核物理参数，作为质量控制和临床使用的重要依据。因此，选项B正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 32 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0033","type":"single","qtype":"单选题","stem":"18F-FDG的合成依赖（ ）","options":[{"key":"A","text":"普通反应釜"},{"key":"B","text":"自动合成系统及配套模块"},{"key":"C","text":"通风橱"},{"key":"D","text":"无菌操作台"}],"answer":["B"],"explanation":"18F-FDG的合成依赖自动合成系统及配套模块，因为氟[18F]半衰期短、放射性活度高，需要自动化、封闭式的合成装置来保证操作安全、合成效率和产品一致性。普通反应釜、通风橱、无菌操作台均不能满足正电子类放射性药品的合成要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n18F-FDG的合成涉及放射性核素操作，需在热室或辐射防护条件下进行。自动合成系统及配套模块（如卡套）可实现远程控制、封闭合成、在线纯化，减少人员辐射暴露，并保证无菌和无热原。因此，选项B正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 33 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0034","type":"single","qtype":"单选题","stem":"18F-FDG合成中，氟[18F]离子首先被（ ）捕获","options":[{"key":"A","text":"阳离子交换柱"},{"key":"B","text":"阴离子交换柱（QMA柱）"},{"key":"C","text":"色谱柱"},{"key":"D","text":"过滤膜"}],"answer":["B"],"explanation":"在18F-FDG合成中，加速器产生的氟[18F]离子通常以氟[18F]离子形式存在于水溶液中，首先被阴离子交换柱（QMA柱）捕获，然后通过洗脱液洗脱进入反应体系。阳离子交换柱、色谱柱、过滤膜均不是首先捕获氟[18F]离子的装置。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n18F-FDG的合成过程中，加速器产生的氟[18F]离子需经过分离纯化。QMA柱（季铵盐阴离子交换柱）可有效捕获氟[18F]离子，随后用氨基聚醚（K2.2.2）和碳酸钾混合液洗脱，使氟[18F]离子进入有机相进行亲核取代反应。因此，选项B正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 34 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0035","type":"single","qtype":"单选题","stem":"洗脱氟[18F]离子的溶液是（ ）","options":[{"key":"A","text":"氨基聚醚（K2.2.2）+K2CO3混合液"},{"key":"B","text":"0.9%氯化钠注射液"},{"key":"C","text":"氢氧化钠溶液"},{"key":"D","text":"盐酸溶液"}],"answer":["A"],"explanation":"洗脱氟[18F]离子的溶液是氨基聚醚（K2.2.2）+K2CO3混合液。该混合液能将QMA柱上捕获的氟[18F]离子洗脱下来，并与K2.2.2络合，提高氟[18F]离子的反应活性。0.9%氯化钠注射液用于淋洗锝[99mTc]发生器，氢氧化钠和盐酸不用于此步骤。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n在18F-FDG合成中，QMA柱捕获氟[18F]离子后，需用氨基聚醚（K2.2.2）和碳酸钾混合液洗脱。K2.2.2作为相转移催化剂，与钾离子络合，使氟[18F]离子以裸氟形式进入有机相，便于后续亲核取代反应。因此，选项A正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 35 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0036","type":"single","qtype":"单选题","stem":"18F-FDG药液除菌过滤的滤膜孔径是（ ）","options":[{"key":"A","text":"0.11μm"},{"key":"B","text":"0.22μm"},{"key":"C","text":"0.45μm"},{"key":"D","text":"0.8μm"}],"answer":["B"],"explanation":"18F-FDG药液除菌过滤的滤膜孔径是0.22μm，这是药品无菌过滤的常规孔径，可有效截留细菌。0.11μm孔径过小，可能导致过滤困难；0.45μm和0.8μm孔径过大，不能保证除菌效果。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据药品GMP及无菌药品附录要求，非最终灭菌的无菌药品需采用除菌过滤工艺，滤膜孔径通常为0.22μm。18F-FDG为注射剂，必须无菌，因此其药液在分装前需经0.22μm滤膜除菌过滤，并进行滤膜完整性测试。因此，选项B正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 36 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0037","type":"single","qtype":"单选题","stem":"以下不属于《中国药典》（2020年版）收录的放射性小容量注射液是（ ）","options":[{"key":"A","text":"氙[133Xe]注射液"},{"key":"B","text":"铬[51Cr]酸钠注射液"},{"key":"C","text":"维生素C注射液"},{"key":"D","text":"邻碘[131I]马尿酸注射液"}],"answer":["C"],"explanation":"维生素C注射液是普通化学药品注射液，不属于放射性药品，因此不属于《中国药典》（2020年版）收录的放射性小容量注射液。氙[133Xe]注射液、铬[51Cr]酸钠注射液、邻碘[131I]马尿酸注射液均为放射性小容量注射液。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n《中国药典》（2020年版）收录了多种放射性小容量注射液，如氙[133Xe]注射液、铬[51Cr]酸钠注射液、邻碘[131I]马尿酸注射液等。维生素C注射液不含放射性核素，属于普通药品，不属于放射性药品。因此，选项C正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 37 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0038","type":"single","qtype":"单选题","stem":"氯化锶[89Sr]注射液的最终灭菌条件是（ ）","options":[{"key":"A","text":"100℃/30分钟"},{"key":"B","text":"115℃/30分钟"},{"key":"C","text":"121℃"},{"key":"D","text":"132℃/4分钟"}],"answer":["C"],"explanation":"氯化锶[89Sr]注射液的最终灭菌条件为121℃。这是湿热灭菌的常用条件，可有效杀灭微生物，同时保证药品稳定性。100℃/30分钟、115℃/30分钟灭菌效果不足，132℃/4分钟可能影响产品稳定性。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n氯化锶[89Sr]注射液为最终灭菌的无菌注射剂，根据药品GMP及灭菌工艺要求，采用121℃湿热灭菌。该条件符合《中国药典》灭菌法要求，可保证无菌保证水平。因此，选项C正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 38 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0039","type":"single","qtype":"单选题","stem":"氯化锶[89Sr]注射液的分装环境是（ ）","options":[{"key":"A","text":"A级"},{"key":"B","text":"B级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["C"],"explanation":"氯化锶[89Sr]注射液的分装环境为C级洁净区。该产品为最终灭菌注射剂，其分装可在C级环境下进行，之后进行121℃最终灭菌。A级、B级、D级均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，最终灭菌的小容量注射剂灌装通常在C级洁净区进行，而氯化锶[89Sr]注射液属于最终灭菌注射剂，其分装环境为C级。因此，选项C正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 39 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0040","type":"single","qtype":"单选题","stem":"《中国药典》（2020年版）收录的放射性植入剂是（ ）","options":[{"key":"A","text":"碘[125I]密封籽源"},{"key":"B","text":"锝[99mTc]植入剂"},{"key":"C","text":"氟[18F]植入剂"},{"key":"D","text":"磷[32P]植入剂"}],"answer":["A"],"explanation":"《中国药典》（2020年版）收录的放射性植入剂是碘[125I]密封籽源。碘[125I]密封籽源用于浅表、胸腹腔内肿瘤的治疗。锝[99mTc]植入剂、氟[18F]植入剂、磷[32P]植入剂均不是药典收录的放射性植入剂。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n碘[125I]密封籽源属于放射性体内植入制品，是《中国药典》（2020年版）收录的放射性植入剂。其核心组成为吸附碘[125I]的金属丝封闭在钛合金管中，用于肿瘤组织间植入治疗。因此，选项A正确。\n\n---","source":{"file":"单选题/31-40.md","merged":"单选题1-400.md","location":"第 40 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0041","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源的核心组成是（ ）","options":[{"key":"A","text":"吸附碘[125I]的金属丝封闭在钛合金管中"},{"key":"B","text":"纯碘[125I]粉末"},{"key":"C","text":"碘[125I]溶液"},{"key":"D","text":"碘[125I]吸附在塑料载体上"}],"answer":["A"],"explanation":"碘[125I]密封籽源的核心组成是吸附碘[125I]的金属丝封闭在钛合金管中。这种结构可有效屏蔽放射性，防止碘[125I]泄漏，同时保证射线能够穿透钛合金管用于治疗。纯碘[125I]粉末、碘[125I]溶液、碘[125I]吸附在塑料载体上均不是其实际组成形式。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n碘[125I]密封籽源属于放射性体内植入制品，是放射性核素制剂的一种。其结构为将吸附碘[125I]的金属丝密封在钛合金管中，形成密封源。这种设计符合放射性药品的安全防护要求，可防止放射性物质泄漏，同时允许碘[125I]发射的X射线和γ射线用于肿瘤组织间照射治疗。因此，选项A正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 41 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0042","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源用于治疗（ ）","options":[{"key":"A","text":"甲状腺疾病"},{"key":"B","text":"浅表、胸腹腔内肿瘤"},{"key":"C","text":"心血管疾病"},{"key":"D","text":"呼吸系统疾病"}],"answer":["B"],"explanation":"碘[125I]密封籽源主要用于浅表、胸腹腔内肿瘤的近距离放射治疗。其原理是将密封籽源植入肿瘤组织内，利用碘[125I]发射的低能γ射线持续照射肿瘤细胞，达到治疗目的。甲状腺疾病、心血管疾病、呼吸系统疾病均不是其主要适应症。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n碘[125I]密封籽源作为放射性植入制品，属于放射性核素制剂。其临床用途为组织间植入治疗，适用于浅表肿瘤、胸腹腔内肿瘤等。通过植入肿瘤组织，碘[125I]持续发射辐射，破坏肿瘤细胞DNA，抑制肿瘤生长。因此，选项B正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 42 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0043","type":"single","qtype":"单选题","stem":"碘[125I]的半衰期约为（ ）","options":[{"key":"A","text":"6.02小时"},{"key":"B","text":"110分钟"},{"key":"C","text":"59.41天"},{"key":"D","text":"20分钟"}],"answer":["C"],"explanation":"碘[125I]的半衰期约为59.41天，这一较长的半衰期使其适合用于长期植入治疗，可在肿瘤部位持续发挥照射作用。6.02小时是锝[99mTc]的半衰期，110分钟是氟[18F]的半衰期，20分钟是碳[11C]等短半衰期核素的典型值。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n碘[125I]是放射性核素，其半衰期约为59.41天，发射低能γ射线（主要能量27-35keV）。在放射性药品质量标准和核素鉴别中，半衰期是重要的核物理参数。碘[125I]密封籽源利用其较长半衰期实现持续照射治疗。因此，选项C正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 43 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0044","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源生产的第一步是（ ）","options":[{"key":"A","text":"源芯制备"},{"key":"B","text":"源芯装配"},{"key":"C","text":"活度检测"},{"key":"D","text":"分装密封"}],"answer":["A"],"explanation":"碘[125I]密封籽源生产的第一步是源芯制备，即制备吸附碘[125I]的金属丝（源芯）。之后依次进行源芯装配（装入钛合金管）、活度检测、分装密封等步骤。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第五条规定：放射性新药的研制内容，包括工艺路线、质量标准、临床前药理及临床研究。研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、放射性比活度、剂量、剂型、稳定性等。\n碘[125I]密封籽源的生产工艺路线中，源芯制备是首要步骤，即通过化学或物理方法将碘[125I]吸附到金属丝上，形成放射性源芯。该步骤决定了产品的活度分布和稳定性，是后续装配和密封的基础。因此，选项A正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 44 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0045","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源的清洗分装环境是（ ）","options":[{"key":"A","text":"A级"},{"key":"B","text":"B级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["C"],"explanation":"碘[125I]密封籽源的清洗分装环境为C级洁净区。该操作涉及放射性物质，需在规定的洁净级别下进行，以控制微粒和微生物污染，同时配合辐射防护措施。A级、B级、D级均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，碘[125I]密封籽源的清洗和分装操作应在C级洁净区进行。该级别可有效控制环境中的微粒和微生物，同时便于实施辐射防护和去污措施，保证产品无菌和安全性。因此，选项C正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 45 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0046","type":"single","qtype":"单选题","stem":"《中国药典》（2020年版）收录的放射性口服溶液剂有（ ）个品种","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}],"answer":["B"],"explanation":"《中国药典》（2020年版）收录的放射性口服溶液剂有2个品种，分别为磷[32P]酸钠盐口服溶液和碘[131I]化钠口服溶液。其他数量均不符合药典实际收载情况。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n《中国药典》（2020年版）是放射性药品质量标准的法定依据，其中收载的放射性口服溶液剂包括磷[32P]酸钠盐口服溶液和碘[131I]化钠口服溶液，共2个品种。这些品种属于放射性核素制剂，用于临床治疗或诊断。因此，选项B正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 46 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0047","type":"single","qtype":"单选题","stem":"磷[32P]酸钠盐口服溶液不用于治疗（ ）","options":[{"key":"A","text":"真性红细胞增多症"},{"key":"B","text":"原发性血小板增多症"},{"key":"C","text":"皮肤病（外用敷贴）"},{"key":"D","text":"甲状腺疾病"}],"answer":["D"],"explanation":"磷[32P]酸钠盐口服溶液主要用于治疗真性红细胞增多症、原发性血小板增多症，也可制成敷贴器用于皮肤病治疗。甲状腺疾病通常使用碘[131I]化钠口服溶液治疗，而不是磷[32P]酸钠盐口服溶液。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n磷[32P]酸钠盐口服溶液属于放射性核素制剂，其发射的β射线可用于治疗血液系统疾病和皮肤病。甲状腺疾病因甲状腺组织特异性摄取碘，故使用碘[131I]化钠口服溶液治疗。磷[32P]酸钠盐口服溶液不用于甲状腺疾病。因此，选项D正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 47 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0048","type":"single","qtype":"单选题","stem":"磷[32P]的生成核反应是（ ）","options":[{"key":"A","text":"31P(n,γ)32P"},{"key":"B","text":"32P(n,γ)33P"},{"key":"C","text":"30P(n,γ)31P"},{"key":"D","text":"29P(n,γ)30P"}],"answer":["A"],"explanation":"磷[32P]通常通过反应堆中子辐照天然磷（31P）生成，核反应为31P(n,γ)32P。其他选项中的核反应均不能生成磷[32P]。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n磷[32P]是放射性核素，其制备通常利用反应堆中子源辐照含磷靶材。天然磷为31P，捕获中子后发生(n,γ)反应生成32P。该核反应是磷[32P]生产的基础，所得磷[32P]用于制备磷[32P]酸钠盐口服溶液等放射性药品。因此，选项A正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 48 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0049","type":"single","qtype":"单选题","stem":"制备磷[32P]酸钠盐口服溶液时，中和磷[32P]酸的试剂是（ ）","options":[{"key":"A","text":"盐酸"},{"key":"B","text":"氢氧化钠溶液"},{"key":"C","text":"氯化钠溶液"},{"key":"D","text":"氯化钾溶液"}],"answer":["B"],"explanation":"制备磷[32P]酸钠盐口服溶液时，需用氢氧化钠溶液中和磷[32P]酸，生成磷[32P]酸钠盐。盐酸、氯化钠溶液、氯化钾溶液均不能用于中和磷[32P]酸。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第五条规定：放射性新药的研制内容，包括工艺路线、质量标准、临床前药理及临床研究。研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、放射性比活度、剂量、剂型、稳定性等。\n磷[32P]酸钠盐口服溶液的制备工艺中，磷[32P]酸需与氢氧化钠溶液反应，生成磷[32P]酸钠盐，并调节pH至适宜范围。氢氧化钠是常用的中和试剂，可生成水溶性钠盐，适用于口服溶液剂。因此，选项B正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 49 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0050","type":"single","qtype":"单选题","stem":"国产Na131I溶液的制备工艺是（ ）","options":[{"key":"A","text":"湿法提取"},{"key":"B","text":"干法蒸馏"},{"key":"C","text":"离子交换"},{"key":"D","text":"溶剂萃取"}],"answer":["B"],"explanation":"国产Na131I溶液的制备工艺是干法蒸馏。该工艺通过高温蒸馏将碘[131I]从辐照靶材中分离出来，再制备成碘[131I]化钠溶液。湿法提取、离子交换、溶剂萃取均不是国产Na131I溶液的主要制备工艺。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n碘[131I]化钠口服溶液属于放射性核素制剂，其制备工艺中，碘[131I]通常由反应堆辐照碲靶产生，然后通过干法蒸馏将碘[131I]从靶材中分离。干法蒸馏可获得较高纯度的碘[131I]，再溶于氢氧化钠溶液制成碘[131I]化钠口服溶液。因此，选项B正确。\n\n---","source":{"file":"单选题/41-50.md","merged":"单选题1-400.md","location":"第 50 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0051","type":"single","qtype":"单选题","stem":"碘[131I]化钠口服溶液用于（ ）","options":[{"key":"A","text":"甲状腺疾病诊断与治疗"},{"key":"B","text":"肿瘤治疗"},{"key":"C","text":"心血管疾病诊断"},{"key":"D","text":"糖尿病治疗"}],"answer":["A"],"explanation":"碘[131I]化钠口服溶液主要用于甲状腺疾病的诊断与治疗。甲状腺组织具有特异性摄取碘的功能，碘[131I]发射的β射线和γ射线可用于破坏甲状腺组织或进行显像。肿瘤治疗、心血管疾病诊断、糖尿病治疗均不是其主要用途。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n碘[131I]化钠口服溶液属于放射性核素制剂，其诊断和治疗原理基于甲状腺对碘的特异性摄取。碘[131I]衰变时发射β射线（治疗作用）和γ射线（显像作用），可用于甲状腺功能亢进、甲状腺癌等疾病的治疗及甲状腺功能检查。因此，选项A正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 51 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0052","type":"single","qtype":"单选题","stem":"碘[131I]化钠口服溶液的运输需装入（ ）","options":[{"key":"A","text":"普通纸箱"},{"key":"B","text":"塑料盒"},{"key":"C","text":"射线屏蔽容器"},{"key":"D","text":"铁罐"}],"answer":["C"],"explanation":"碘[131I]化钠口服溶液具有放射性，运输时需装入射线屏蔽容器，以降低对运输人员和公众的辐射剂量。普通纸箱、塑料盒、铁罐均不能提供足够的辐射屏蔽。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二十条规定：放射性药品的运输，按国家运输、邮政等部门制定的有关规定执行。严禁任何单位和个人随身携带放射性药品乘坐公共交通运输工具。\n碘[131I]发射γ射线，需采用铅、钨等高密度材料制成的屏蔽容器进行运输。屏蔽容器可有效降低容器表面的辐射剂量率，满足国家放射性物品运输安全标准。因此，选项C正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 52 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0053","type":"single","qtype":"单选题","stem":"《中国药典》（2020年版）收录的放射性胶囊剂是（ ）","options":[{"key":"A","text":"尿素[14C]胶囊"},{"key":"B","text":"诊断用碘[131I]化钠胶囊"},{"key":"C","text":"锝[99mTc]胶囊"},{"key":"D","text":"氟[18F]胶囊"}],"answer":["B"],"explanation":"《中国药典》（2020年版）收录的放射性胶囊剂是诊断用碘[131I]化钠胶囊。尿素[14C]胶囊虽为放射性诊断用药，但未被2020年版药典收录为放射性胶囊剂；锝[99mTc]胶囊和氟[18F]胶囊不是药典收载的放射性胶囊剂。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n诊断用碘[131I]化钠胶囊属于放射性核素制剂，是《中国药典》（2020年版）收载的放射性胶囊剂。该品种用于甲状腺功能检查。尿素[14C]胶囊属于呼气试验药盒，其管理归属与药典收载的放射性胶囊剂不同。因此，选项B正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 53 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0054","type":"single","qtype":"单选题","stem":"尿素[14C]胶囊用于诊断（ ）","options":[{"key":"A","text":"甲状腺功能异常"},{"key":"B","text":"幽门螺杆菌感染"},{"key":"C","text":"肿瘤"},{"key":"D","text":"心血管疾病"}],"answer":["B"],"explanation":"尿素[14C]胶囊用于诊断幽门螺杆菌感染。其原理是幽门螺杆菌具有尿素酶，能分解尿素[14C]产生14CO2，通过检测呼出气体中的14CO2判断是否感染。甲状腺功能异常、肿瘤、心血管疾病均不是其诊断用途。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n尿素[14C]胶囊属于放射性核素标记药物，用于幽门螺杆菌感染的诊断。患者口服尿素[14C]胶囊后，若胃内存在幽门螺杆菌，其尿素酶分解尿素产生14CO2，经血液循环至肺部呼出，通过收集呼出气体并测量放射性活度即可判断感染情况。因此，选项B正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 54 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0055","type":"single","qtype":"单选题","stem":"碘[131I]化钠胶囊的工艺不包括（ ）","options":[{"key":"A","text":"溶液配制"},{"key":"B","text":"胶囊填充"},{"key":"C","text":"高温灭菌"},{"key":"D","text":"中间品检测"}],"answer":["C"],"explanation":"碘[131I]化钠胶囊的工艺包括溶液配制、胶囊填充、中间品检测等，但不包括高温灭菌。因为碘[131I]化钠胶囊含有放射性核素，且胶囊壳通常不耐高温，高温灭菌会破坏产品。其无菌保证依赖于原辅料控制和洁净生产环境。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n碘[131I]化钠胶囊属于放射性口服固体制剂，其生产需在洁净环境下进行，采用无菌原辅料，通过溶液配制、胶囊填充等工序制备。由于放射性核素和胶囊材料的特殊性，一般不采用最终高温灭菌工艺，而是通过过程控制保证微生物质量。因此，选项C正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 55 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0056","type":"single","qtype":"单选题","stem":"尿素[14C]胶囊装袋前的生产环境是（ ）","options":[{"key":"A","text":"A级"},{"key":"B","text":"B级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["D"],"explanation":"尿素[14C]胶囊装袋前的生产环境为D级洁净区。D级洁净区适用于非无菌药品的生产，可控制微粒和微生物污染。A级、B级、C级洁净级别过高，不符合该产品的实际生产要求。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，尿素[14C]胶囊属于口服放射性诊断药品，其装袋前的生产操作可在D级洁净区进行。该级别可满足口服固体制剂的微生物和微粒控制要求。因此，选项D正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 56 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0057","type":"single","qtype":"单选题","stem":"体外放射性诊断试剂按原理分为（ ）类","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"3"},{"key":"D","text":"4"}],"answer":["B"],"explanation":"体外放射性诊断试剂按原理主要分为2类：放射免疫分析法（RIA）和免疫放射分析法（IRMA）。RIA采用竞争性结合原理，IRMA采用非竞争性结合原理。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n体外放射性诊断试剂属于放射性药品的范畴，按反应原理分为放射免疫分析（RIA）和免疫放射分析（IRMA）两类。RIA中标记抗原与待测抗原竞争结合抗体；IRMA中标记抗体与待测抗原非竞争性结合。因此，选项B正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 57 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0058","type":"single","qtype":"单选题","stem":"放射免疫分析法（RIA）的核心原理是（ ）","options":[{"key":"A","text":"抗原-抗体非竞争性结合"},{"key":"B","text":"抗原-抗体竞争性结合"},{"key":"C","text":"仅标记抗体"},{"key":"D","text":"仅标记抗原"}],"answer":["B"],"explanation":"放射免疫分析法（RIA）的核心原理是抗原-抗体竞争性结合。标记抗原与待测抗原竞争结合限量的特异性抗体，待测抗原浓度越高，标记抗原-抗体复合物越少。非竞争性结合是IRMA的原理。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n放射免疫分析法（RIA）是体外放射性诊断试剂的经典方法，其原理为竞争性结合。标记抗原（如碘[125I]标记抗原）与待测抗原竞争结合有限量的抗体，形成标记抗原-抗体复合物。通过测定复合物的放射性活度，可推算待测抗原含量。因此，选项B正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 58 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0059","type":"single","qtype":"单选题","stem":"RIA中，碘[125I]标记抗原-抗体复合物与待测抗原含量呈（ ）","options":[{"key":"A","text":"正相关"},{"key":"B","text":"逆相关"},{"key":"C","text":"无相关"},{"key":"D","text":"线性相关"}],"answer":["B"],"explanation":"在RIA中，碘[125I]标记抗原-抗体复合物与待测抗原含量呈逆相关。待测抗原含量越高，与抗体竞争结合越多，导致标记抗原-抗体复合物形成越少。正相关、无相关、线性相关均不准确描述这种竞争性关系。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n放射免疫分析法（RIA）中，标记抗原和待测抗原竞争结合限量的抗体。待测抗原浓度升高时，竞争性抑制标记抗原与抗体的结合，导致标记抗原-抗体复合物减少。因此，复合物放射性计数与待测抗原含量呈逆相关（负相关）。选项B正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 59 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0060","type":"single","qtype":"单选题","stem":"免疫放射分析法（IRMA）与RIA的主要区别是（ ）","options":[{"key":"A","text":"标记抗原而非抗体"},{"key":"B","text":"标记抗体而非抗原"},{"key":"C","text":"反应温度不同"},{"key":"D","text":"反应时间不同"}],"answer":["B"],"explanation":"免疫放射分析法（IRMA）与RIA的主要区别是IRMA标记抗体而非抗原。IRMA采用非竞争性结合原理，标记抗体与待测抗原结合，形成抗体-抗原-标记抗体夹心复合物。RIA标记抗原。反应温度和时间不是主要区别。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n免疫放射分析法（IRMA）是体外放射性诊断试剂的另一类方法，与RIA的核心区别在于标记物不同：RIA标记抗原，IRMA标记抗体。IRMA中，待测抗原与固相抗体结合后，再与标记抗体结合形成夹心复合物，复合物计数与待测抗原含量呈正相关。因此，选项B正确。\n\n---","source":{"file":"单选题/51-60.md","merged":"单选题1-400.md","location":"第 60 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0061","type":"single","qtype":"单选题","stem":"IRMA中，复合物计数与待测抗原含量呈（ ）","options":[{"key":"A","text":"正相关"},{"key":"B","text":"逆相关"},{"key":"C","text":"无相关"},{"key":"D","text":"线性相关"}],"answer":["A"],"explanation":"免疫放射分析法（IRMA）采用非竞争性结合原理，标记抗体与待测抗原结合形成夹心复合物。待测抗原含量越高，形成的标记抗体-抗原复合物越多，复合物计数与待测抗原含量呈正相关。逆相关是RIA的特征，无相关和线性相关均不准确。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n免疫放射分析试剂盒属于放射性核素标记药物，其原理为标记抗体与待测抗原非竞争性结合。待测抗原浓度升高时，形成的标记抗体-抗原复合物增加，复合物放射性计数随之升高，呈正相关。因此，选项A正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 61 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0062","type":"single","qtype":"单选题","stem":"放射免疫分析试剂盒的工艺不包括（ ）","options":[{"key":"A","text":"碘[125I]标记抗原制备"},{"key":"B","text":"特异性抗体制备"},{"key":"C","text":"包被珠制备"},{"key":"D","text":"缓冲液制备"}],"answer":["C"],"explanation":"放射免疫分析（RIA）试剂盒的工艺包括碘[125I]标记抗原制备、特异性抗体制备、缓冲液制备等，但不包括包被珠制备。包被珠是免疫放射分析（IRMA）试剂盒的典型组分，用于固定抗体。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n放射免疫分析试剂盒属于放射性核素标记药物，其核心组分包括标记抗原、特异性抗体和缓冲液等。包被珠（或包被管）是免疫放射分析试剂盒中用于固相化抗体的材料，并非RIA试剂盒的必需组分。因此，选项C正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 62 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0063","type":"single","qtype":"单选题","stem":"免疫放射分析试剂盒需制备（ ）","options":[{"key":"A","text":"标记抗原"},{"key":"B","text":"包被珠（或包被管）"},{"key":"C","text":"仅标准品"},{"key":"D","text":"仅质控品"}],"answer":["B"],"explanation":"免疫放射分析（IRMA）试剂盒需制备包被珠（或包被管），用于固定抗体，形成固相抗体。标记抗原是RIA试剂盒的组分，标准品和质控品是各类试剂盒的通用组分，但不是IRMA的特需组分。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n免疫放射分析试剂盒属于放射性核素标记药物，其原理为固相抗体与待测抗原结合，再与标记抗体结合形成夹心复合物。因此，IRMA试剂盒必须制备包被珠（或包被管）作为固相载体。标记抗原是RIA试剂盒的特征组分。因此，选项B正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 63 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0064","type":"single","qtype":"单选题","stem":"尿素[14C]呼气试验药盒的非药用组分不包括（ ）","options":[{"key":"A","text":"集气剂"},{"key":"B","text":"浓缩闪烁液"},{"key":"C","text":"吹气塑料管"},{"key":"D","text":"尿素[14C]胶囊"}],"answer":["D"],"explanation":"尿素[14C]呼气试验药盒的非药用组分包括集气剂、浓缩闪烁液、吹气塑料管等，而尿素[14C]胶囊是药盒中的药用组分，含有放射性核素，用于被幽门螺杆菌分解。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n尿素[14C]呼气试验药盒中，尿素[14C]胶囊属于放射性核素标记药物，是药盒的核心药用组分。集气剂、浓缩闪烁液、吹气塑料管等为非药用辅助组分，用于收集和测量呼出气体中的14CO2。因此，尿素[14C]胶囊不属于非药用组分，选项D正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 64 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0065","type":"single","qtype":"单选题","stem":"体外诊断试剂盒组装环境一般为（ ）","options":[{"key":"A","text":"无菌洁净区"},{"key":"B","text":"非洁净工作区"},{"key":"C","text":"C级洁净区"},{"key":"D","text":"D级洁净区"}],"answer":["B"],"explanation":"体外放射性诊断试剂盒通常不需要无菌，其组装环境一般为非洁净工作区。无菌洁净区、C级洁净区、D级洁净区均不是其常规组装环境。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n体外放射性诊断试剂盒属于非无菌产品，其组装过程不要求无菌环境，通常在非洁净工作区进行，但需控制交叉污染和辐射安全。因此，选项B正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 65 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0066","type":"single","qtype":"单选题","stem":"磷[32P]酸钠盐口服溶液的主要成分是（ ）","options":[{"key":"A","text":"Na32PO4"},{"key":"B","text":"Na2H32PO4"},{"key":"C","text":"H332PO4"},{"key":"D","text":"NaH232PO4"}],"answer":["B"],"explanation":"磷[32P]酸钠盐口服溶液的主要成分是Na2H32PO4（磷酸氢二钠[32P]）。其他选项Na32PO4、H332PO4、NaH232PO4均不是该药品的主要成分。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n磷[32P]酸钠盐口服溶液属于放射性核素制剂，其化学形式为Na2H32PO4，由磷[32P]酸与氢氧化钠部分中和制得。该成分在体内发射β射线，用于治疗真性红细胞增多症等。因此，选项B正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 66 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0067","type":"single","qtype":"单选题","stem":"碘[131I]化钠口服溶液中加入亚硫酸钠的作用是（ ）","options":[{"key":"A","text":"调节pH"},{"key":"B","text":"稳定剂"},{"key":"C","text":"助溶剂"},{"key":"D","text":"着色剂"}],"answer":["B"],"explanation":"碘[131I]化钠口服溶液中加入亚硫酸钠的作用是作为稳定剂，防止碘离子被氧化成碘单质而挥发或降低疗效。调节pH、助溶、着色均不是亚硫酸钠的主要作用。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第五条规定：放射性新药的研制内容，包括工艺路线、质量标准、临床前药理及临床研究。研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、放射性比活度、剂量、剂型、稳定性等。\n碘[131I]化钠口服溶液中，碘离子易被氧化，加入亚硫酸钠作为抗氧化剂和稳定剂，可保持碘[131I]的化学价态稳定，确保产品有效期内的质量。因此，选项B正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 67 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0068","type":"single","qtype":"单选题","stem":"氯化锶[89Sr]注射液的工艺步骤顺序是（ ）","options":[{"key":"A","text":"配制→过滤→分装→灭菌→包装"},{"key":"B","text":"分装→配制→灭菌→包装"},{"key":"C","text":"灭菌→配制→分装→包装"},{"key":"D","text":"配制→灭菌→分装→包装"}],"answer":["A"],"explanation":"氯化锶[89Sr]注射液的工艺步骤顺序为：配制→过滤→分装→灭菌→包装。先配制溶液，经过滤去除微粒，然后分装于容器中，再进行最终灭菌（121℃），最后包装。其他顺序均不符合实际生产工艺。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n氯化锶[89Sr]注射液为最终灭菌注射剂，其生产工艺需遵循药品GMP要求。典型流程为：配制→过滤→分装→灭菌→包装，确保产品无菌、无热原。因此，选项A正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 68 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0069","type":"single","qtype":"单选题","stem":"锝[99mTc]标记药品的核心原料是（ ）","options":[{"key":"A","text":"钼[99Mo]溶液"},{"key":"B","text":"高锝[99mTc]酸钠注射液"},{"key":"C","text":"氯化亚锡"},{"key":"D","text":"配体粉末"}],"answer":["B"],"explanation":"锝[99mTc]标记药品的核心原料是高锝[99mTc]酸钠注射液，由钼[99Mo]-锝[99mTc]发生器淋洗得到。氯化亚锡是还原剂，配体粉末是配套药盒的组分，钼[99Mo]溶液是发生器的母体核素，均不是标记药品的直接核心原料。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n锝[99mTc]标记药品属于放射性核素标记药物，其制备过程为：用0.9%氯化钠注射液淋洗钼[99Mo]-锝[99mTc]发生器，得到高锝[99mTc]酸钠注射液，再加入配套药盒进行标记。因此，高锝[99mTc]酸钠注射液是核心原料，选项B正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 69 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0070","type":"single","qtype":"单选题","stem":"体外诊断试剂盒运输中需监测（ ）","options":[{"key":"A","text":"湿度"},{"key":"B","text":"温度"},{"key":"C","text":"气压"},{"key":"D","text":"重量"}],"answer":["B"],"explanation":"体外诊断试剂盒运输中需监测温度，因为许多试剂盒中的生物活性组分（如抗体、抗原）对温度敏感，需在规定的冷链条件下运输。湿度、气压、重量不是运输中需重点监测的参数。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二十条规定：放射性药品的运输，按国家运输、邮政等部门制定的有关规定执行。严禁任何单位和个人随身携带放射性药品乘坐公共交通运输工具。\n体外诊断试剂盒中的生物活性组分需在特定温度下保持稳定，运输过程中需监测温度并记录，确保冷链不断链。因此，选项B正确。\n\n---","source":{"file":"单选题/61-70.md","merged":"单选题1-400.md","location":"第 70 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0071","type":"single","qtype":"单选题","stem":"放射性药品生产厂房位置应与（ ）“涉源部门”地址一致","options":[{"key":"A","text":"《药品生产许可证》"},{"key":"B","text":"《辐射安全许可证》"},{"key":"C","text":"《营业执照》"},{"key":"D","text":"《药品经营许可证》"}],"answer":["B"],"explanation":"放射性药品生产厂房位置应与《辐射安全许可证》中“涉源部门”地址一致。这是因为放射性药品生产涉及放射性同位素与射线装置，必须取得辐射安全许可，且生产场所需与许可地址相符，确保辐射安全监管的有效性。《药品生产许可证》《营业执照》《药品经营许可证》均不专门针对辐射安全地址一致性。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产放射性药品需取得《辐射安全许可证》，且许可证中载明的涉源部门地址应与实际生产厂房一致。因此，选项B正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 71 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0072","type":"single","qtype":"单选题","stem":"放射性与非放射性工作区应（ ）","options":[{"key":"A","text":"合并设置"},{"key":"B","text":"有效隔离"},{"key":"C","text":"随意布局"},{"key":"D","text":"相邻设置"}],"answer":["B"],"explanation":"放射性与非放射性工作区应有效隔离，以防止放射性物质污染非放射性区域，保障人员和药品安全。合并设置、随意布局、相邻设置均不能有效控制污染扩散和交叉污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作区与非放射性工作区需通过物理隔断、压差控制等措施有效隔离，防止放射性物质扩散。因此，选项B正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 72 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0073","type":"single","qtype":"单选题","stem":"放射性核素操作区与周围环境保持（ ）","options":[{"key":"A","text":"相对正压"},{"key":"B","text":"相对负压"},{"key":"C","text":"常压"},{"key":"D","text":"无压力要求"}],"answer":["B"],"explanation":"放射性核素操作区与周围环境应保持相对负压，以防止放射性气溶胶或粉尘向外扩散，保护周围环境和人员。相对正压、常压、无压力要求均不能有效控制放射性污染扩散。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性核素操作区采用相对负压设计，配合高效过滤排风系统，可有效防止放射性物质外溢。因此，选项B正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 73 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0074","type":"single","qtype":"单选题","stem":"即时标记药物的单向流工作台可保持（ ）","options":[{"key":"A","text":"相对正压"},{"key":"B","text":"相对负压"},{"key":"C","text":"常压"},{"key":"D","text":"无压力要求"}],"answer":["A"],"explanation":"即时标记药物的单向流工作台可保持相对正压，以保护操作过程中的药品免受环境污染，确保无菌操作。相对负压、常压、无压力要求均不符合单向流工作台的无菌保护要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n即时标记药物制备需在洁净环境下进行，单向流工作台通过正压和单向流保护产品，防止微生物和微粒污染。因此，选项A正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 74 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0075","type":"single","qtype":"单选题","stem":"不同放射性核素的操作区应（ ）","options":[{"key":"A","text":"合并设置"},{"key":"B","text":"严格分开"},{"key":"C","text":"就近设置"},{"key":"D","text":"随意设置"}],"answer":["B"],"explanation":"不同放射性核素的操作区应严格分开，以防止核素之间的交叉污染和混淆，确保产品质量和辐射安全。合并设置、就近设置、随意设置均不能有效防止交叉污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同放射性核素具有不同的辐射特性和半衰期，操作区严格分开可避免交叉污染，保证产品核纯度和放射化学纯度。因此，选项B正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 75 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0076","type":"single","qtype":"单选题","stem":"放射性核素生产场所空气（ ）循环使用","options":[{"key":"A","text":"宜"},{"key":"B","text":"不宜"},{"key":"C","text":"必须"},{"key":"D","text":"禁止"}],"answer":["B"],"explanation":"放射性核素生产场所空气不宜循环使用，以防止放射性气溶胶或粉尘在系统中积累并扩散到其他区域。宜、必须、禁止均不准确，规范表述为“不宜循环使用”。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性核素生产场所的空气应经高效过滤后排放，不宜循环使用，以避免放射性污染积累和交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 76 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0077","type":"single","qtype":"单选题","stem":"即时标记药物洁净区空气（ ）循环使用","options":[{"key":"A","text":"宜"},{"key":"B","text":"不宜"},{"key":"C","text":"可以"},{"key":"D","text":"禁止"}],"answer":["C"],"explanation":"即时标记药物洁净区空气可以循环使用，但需经风险评估确认无污染风险，并采取有效措施避免污染和交叉污染。宜、不宜、禁止均不准确，规范表述为“可以”。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n即时标记药物洁净区通常使用短半衰期核素，放射性污染风险较低，经风险评估后空气可循环使用。因此，选项C正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 77 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0078","type":"single","qtype":"单选题","stem":"挥发性放射性核素的排风系统需具备（ ）","options":[{"key":"A","text":"加热功能"},{"key":"B","text":"冷却功能"},{"key":"C","text":"有效去污处理"},{"key":"D","text":"加湿功能"}],"answer":["C"],"explanation":"挥发性放射性核素的排风系统需具备有效去污处理，如高效过滤、活性炭吸附等，以防止放射性物质排放到环境中。加热、冷却、加湿功能均不是排风系统的核心要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n挥发性放射性核素（如碘[131I]）操作时，排风系统需配备去污装置，确保排放气体符合国家放射性废物管理要求。因此，选项C正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 78 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0079","type":"single","qtype":"单选题","stem":"放射性工作场所地面和工作台应（ ）","options":[{"key":"A","text":"美观"},{"key":"B","text":"便于去污"},{"key":"C","text":"防滑"},{"key":"D","text":"防火"}],"answer":["B"],"explanation":"放射性工作场所地面和工作台应便于去污，以防止放射性物质残留和扩散。美观、防滑、防火均不是其核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作场所的地面和工作台需采用光滑、耐腐蚀、易去污的材料，便于清除放射性污染。因此，选项B正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 79 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0080","type":"single","qtype":"单选题","stem":"放射源储存区需配备（ ）安全措施","options":[{"key":"A","text":"防火、防盗、防泄漏"},{"key":"B","text":"防火、防电、防泄漏"},{"key":"C","text":"防火、防盗、防电"},{"key":"D","text":"防盗、防电、防泄漏"}],"answer":["A"],"explanation":"放射源储存区需配备防火、防盗、防泄漏安全措施，以确保放射源的安全，防止火灾、盗窃和放射性泄漏事故。防火、防电、防泄漏，防火、防盗、防电，防盗、防电、防泄漏均不完整或不准确。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射源储存区需采取防火、防盗、防泄漏措施，并设置明显的放射性警示标识，确保放射源安全可控。因此，选项A正确。\n\n---","source":{"file":"单选题/71-80.md","merged":"单选题1-400.md","location":"第 80 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0081","type":"single","qtype":"单选题","stem":"放射性工作场所应有明显（ ）","options":[{"key":"A","text":"企业Logo"},{"key":"B","text":"警示标识"},{"key":"C","text":"宣传标语"},{"key":"D","text":"价格标签"}],"answer":["B"],"explanation":"放射性工作场所应有明显的警示标识，以提醒人员注意辐射风险，采取必要的防护措施。企业Logo、宣传标语、价格标签均与辐射安全警示无关。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，放射性工作场所必须设置明显的放射性警示标识，标明放射性核素种类、活度、防护要求等信息，以保障人员安全和辐射防护。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 81 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0082","type":"single","qtype":"单选题","stem":"放射性药品生产操作需在（ ）内进行","options":[{"key":"A","text":"普通车间"},{"key":"B","text":"规定洁净区"},{"key":"C","text":"仓库"},{"key":"D","text":"实验室"}],"answer":["B"],"explanation":"放射性药品生产操作需在规定洁净区内进行，以控制微粒和微生物污染，同时满足辐射防护要求。普通车间、仓库、实验室均不能同时满足洁净度和辐射防护要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，放射性药品生产操作应在规定的洁净区进行，洁净级别根据产品类型和工艺确定，同时需配备辐射防护设施。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 82 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0083","type":"single","qtype":"单选题","stem":"放射性生产区出口应设置（ ）","options":[{"key":"A","text":"消防器材"},{"key":"B","text":"放射性污染检测设备"},{"key":"C","text":"空调设备"},{"key":"D","text":"照明设备"}],"answer":["B"],"explanation":"放射性生产区出口应设置放射性污染检测设备，用于检测人员体表和携带物品是否受到放射性污染，防止污染扩散。消防器材、空调设备、照明设备均不是出口处必须设置的放射性污染检测设备。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性生产区出口设置污染检测设备，是辐射安全防护的重要措施，可及时发现污染并采取去污措施，符合国家放射性同位素与射线装置安全防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 83 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0084","type":"single","qtype":"单选题","stem":"生产人员需配备（ ）","options":[{"key":"A","text":"普通工作服"},{"key":"B","text":"辐射防护用品"},{"key":"C","text":"防静电服"},{"key":"D","text":"防尘服"}],"answer":["B"],"explanation":"放射性药品生产人员需配备辐射防护用品，如铅衣、铅眼镜、辐射剂量计等，以保护人员免受辐射危害。普通工作服、防静电服、防尘服均不能提供有效的辐射防护。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，从事放射性工作的人员必须配备符合要求的辐射防护用品，并定期进行个人剂量监测。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 84 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0085","type":"single","qtype":"单选题","stem":"放射性操作工具应（ ）","options":[{"key":"A","text":"通用"},{"key":"B","text":"专用"},{"key":"C","text":"随意使用"},{"key":"D","text":"定期更换"}],"answer":["B"],"explanation":"放射性操作工具应专用，以避免放射性物质交叉污染和非放射性区域受到污染。通用、随意使用、定期更换均不能有效控制放射性污染扩散。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性操作工具专用是防止交叉污染和辐射污染扩散的基本要求，工具使用后需进行污染监测和去污处理。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 85 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0086","type":"single","qtype":"单选题","stem":"放射性废物需放入（ ）","options":[{"key":"A","text":"普通垃圾桶"},{"key":"B","text":"专用放射性废弃桶"},{"key":"C","text":"纸箱"},{"key":"D","text":"塑料袋"}],"answer":["B"],"explanation":"放射性废物需放入专用放射性废弃桶，并按照放射性废物管理规定进行分类收集、贮存和处置。普通垃圾桶、纸箱、塑料袋均不能提供辐射防护和防泄漏功能。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物专用容器需具备辐射防护性能，明确标识，并按核素种类、半衰期等分类收集，最终按国家放射性废物管理规定处置。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 86 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0087","type":"single","qtype":"单选题","stem":"以下属于“C级背景下局部A级”的操作是（ ）","options":[{"key":"A","text":"即时标记药品淋洗"},{"key":"B","text":"非最终灭菌小容量注射剂灌装"},{"key":"C","text":"口服制剂配制"},{"key":"D","text":"放射免疫药盒生产"}],"answer":["B"],"explanation":"非最终灭菌小容量注射剂灌装属于“C级背景下局部A级”的操作。该操作需在C级洁净区背景下，局部达到A级层流保护，以确保无菌灌装。即时标记药品淋洗通常为C级，口服制剂配制为D级，放射免疫药盒生产为D级。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，非最终灭菌小容量注射剂的灌装操作应在C级背景下局部A级进行，以最大限度降低微生物和微粒污染风险。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 87 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0088","type":"single","qtype":"单选题","stem":"以下属于“C级”的操作是（ ）","options":[{"key":"A","text":"非最终灭菌药品除菌过滤后制备"},{"key":"B","text":"无菌植入制品焊封"},{"key":"C","text":"口服制剂灌装"},{"key":"D","text":"直接接触非无菌药品包装材料清洗"}],"answer":["A"],"explanation":"非最终灭菌药品除菌过滤后的制备属于“C级”操作。该操作在C级洁净区进行，以控制微生物污染。无菌植入制品焊封为C级背景下局部A级，口服制剂灌装为D级，直接接触非无菌药品包装材料清洗为D级。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，非最终灭菌药品在除菌过滤后的制备操作应在C级洁净区进行，以降低微生物污染风险。因此，选项A正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 88 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0089","type":"single","qtype":"单选题","stem":"以下属于“D级”的操作是（ ）","options":[{"key":"A","text":"正电子药品灌装"},{"key":"B","text":"即时标记药品标记"},{"key":"C","text":"口服制剂物料准备"},{"key":"D","text":"无菌植入制品分装"}],"answer":["C"],"explanation":"口服制剂物料准备属于“D级”操作。D级洁净区适用于非无菌药品的生产，可控制微粒和微生物污染。正电子药品灌装为C级背景下局部A级，即时标记药品标记为C级，无菌植入制品分装为C级背景下局部A级。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，口服制剂的物料准备操作可在D级洁净区进行，该级别可满足口服固体制剂的微生物和微粒控制要求。因此，选项C正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 89 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0090","type":"single","qtype":"单选题","stem":"“洁净区内检验间通风柜未装排风通道”属于（ ）","options":[{"key":"A","text":"合格情况"},{"key":"B","text":"典型缺陷"},{"key":"C","text":"轻微问题"},{"key":"D","text":"无关问题"}],"answer":["B"],"explanation":"“洁净区内检验间通风柜未装排风通道”属于典型缺陷。通风柜未装排风通道会导致有害气体或放射性气溶胶无法有效排出，可能污染洁净区环境和危害人员安全，是检查中常见的严重缺陷。合格情况、轻微问题、无关问题均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n洁净区内检验间通风柜必须安装排风通道，将废气经高效过滤后排出，以防止污染洁净区和危害人员。未安装排风通道属于不符合辐射安全和洁净控制要求的典型缺陷。因此，选项B正确。\n\n---","source":{"file":"单选题/81-90.md","merged":"单选题1-400.md","location":"第 90 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0091","type":"single","qtype":"单选题","stem":"放射性与非放射性物质应（ ）存放","options":[{"key":"A","text":"混合"},{"key":"B","text":"严格分开"},{"key":"C","text":"就近"},{"key":"D","text":"随意"}],"answer":["B"],"explanation":"放射性与非放射性物质应严格分开存放，以防止放射性物质污染非放射性物料，确保药品质量和辐射安全。混合、就近、随意存放均不能有效控制污染扩散和交叉污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。放射性物质与非放射性物质必须严格分开存放，避免交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 91 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0092","type":"single","qtype":"单选题","stem":"放射性物质应存放于（ ）相适应的容器","options":[{"key":"A","text":"生产规模"},{"key":"B","text":"辐射防护水平"},{"key":"C","text":"储存数量"},{"key":"D","text":"包装规格"}],"answer":["B"],"explanation":"放射性物质应存放于与辐射防护水平相适应的容器中，容器的屏蔽能力需与所装放射性核素的射线类型和活度相匹配，以确保辐射安全。生产规模、储存数量、包装规格均不是选择存放容器的核心依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性物质的存放容器需根据核素种类、射线能量和活度选择，确保容器表面剂量率符合国家辐射防护标准。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 92 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0093","type":"single","qtype":"单选题","stem":"放射性原料、半成品、成品应（ ）存放","options":[{"key":"A","text":"专库/专柜"},{"key":"B","text":"普通货架"},{"key":"C","text":"任意区域"},{"key":"D","text":"露天"}],"answer":["A"],"explanation":"放射性原料、半成品、成品应专库或专柜存放，并指定专人保管、专册登记，以确保放射性物质的安全和可追溯。普通货架、任意区域、露天存放均不符合放射性药品管理要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。放射性原料、半成品、成品均属于放射性物料，必须按照该条规定进行专库或专柜存放，防止丢失、混淆和污染。因此，选项A正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 93 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0094","type":"single","qtype":"单选题","stem":"放射性与非放射性实验室应（ ）","options":[{"key":"A","text":"合并"},{"key":"B","text":"分开"},{"key":"C","text":"相邻"},{"key":"D","text":"重叠"}],"answer":["B"],"explanation":"放射性与非放射性实验室应分开设置，以防止放射性污染扩散到非放射性实验区域，保障人员和环境安全。合并、相邻、重叠均不能有效隔离放射性污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性与非放射性实验室分开设置，是辐射防护和污染控制的基本要求，可避免交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 94 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0095","type":"single","qtype":"单选题","stem":"放射性检验人员需佩戴（ ）","options":[{"key":"A","text":"工作证"},{"key":"B","text":"个人剂量监测设备"},{"key":"C","text":"安全帽"},{"key":"D","text":"护目镜"}],"answer":["B"],"explanation":"放射性检验人员需佩戴个人剂量监测设备，用于监测人员在工作中受到的辐射剂量，保障职业健康。工作证、安全帽、护目镜均不能监测辐射剂量。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，从事放射性工作的人员必须佩戴个人剂量计，定期进行剂量监测和职业健康检查。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 95 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0096","type":"single","qtype":"单选题","stem":"放射性样品应（ ）存放","options":[{"key":"A","text":"分类分区"},{"key":"B","text":"混合"},{"key":"C","text":"随意"},{"key":"D","text":"集中"}],"answer":["A"],"explanation":"放射性样品应分类分区存放，根据核素种类、活度水平、半衰期等进行分区管理，以防止交叉污染和混淆。混合、随意、集中存放均不符合放射性样品管理要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。放射性样品作为放射性物料，需分类分区存放，确保可追溯和安全。因此，选项A正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 96 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0097","type":"single","qtype":"单选题","stem":"挥发性放射性核素操作需使用（ ）","options":[{"key":"A","text":"普通通风橱"},{"key":"B","text":"手套箱或专用通风橱"},{"key":"C","text":"普通工作台"},{"key":"D","text":"无菌操作台"}],"answer":["B"],"explanation":"挥发性放射性核素操作需使用手套箱或专用通风橱，以有效控制放射性气溶胶或蒸气扩散，保护人员和环境。普通通风橱、普通工作台、无菌操作台均不能提供足够的辐射防护和去污能力。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n操作挥发性放射性核素（如碘[131I]）时，必须在手套箱或专用通风橱中进行，排风需经高效过滤和去污处理。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 97 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0098","type":"single","qtype":"单选题","stem":"放射性废物容器需满足（ ）要求","options":[{"key":"A","text":"美观"},{"key":"B","text":"安全和辐射防护"},{"key":"C","text":"大容量"},{"key":"D","text":"轻便"}],"answer":["B"],"explanation":"放射性废物容器需满足安全和辐射防护要求，包括足够的屏蔽性能、防泄漏、防扩散，并明确标识。美观、大容量、轻便均不是核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物容器需具备辐射防护性能，防止放射性物质泄漏，并按照核素种类、半衰期等分类收集。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 98 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0099","type":"single","qtype":"单选题","stem":"离开放射性检验场所人员需进行（ ）","options":[{"key":"A","text":"身份验证"},{"key":"B","text":"污染检测"},{"key":"C","text":"健康体检"},{"key":"D","text":"培训考核"}],"answer":["B"],"explanation":"离开放射性检验场所人员需进行污染检测，以确认体表和衣物是否受到放射性污染，防止污染扩散。身份验证、健康体检、培训考核均不是离开时的必要检测步骤。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作场所出口应设置污染检测设备，人员离开时需进行体表和携带物品污染检测，符合辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 99 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0100","type":"single","qtype":"单选题","stem":"放射性与非放射性洁具应（ ）存放","options":[{"key":"A","text":"混合"},{"key":"B","text":"分开"},{"key":"C","text":"随意"},{"key":"D","text":"集中"}],"answer":["B"],"explanation":"放射性与非放射性洁具应分开存放，以防止放射性污染通过洁具扩散到非放射性区域。混合、随意、集中存放均不能有效控制污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性洁具使用后需先进行污染检测，达标后方可清洗，且与非放射性洁具严格分开存放，避免交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/91-100.md","merged":"单选题1-400.md","location":"第 100 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0101","type":"single","qtype":"单选题","stem":"放射性洁具使用后需先（ ）","options":[{"key":"A","text":"清洗"},{"key":"B","text":"消毒"},{"key":"C","text":"污染检测"},{"key":"D","text":"干燥"}],"answer":["C"],"explanation":"放射性洁具使用后需先进行污染检测，确认是否受到放射性污染，再根据检测结果决定后续清洗或去污处理。直接清洗、消毒、干燥均可能造成放射性污染扩散。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性洁具使用后先进行污染检测，是辐射防护和污染控制的基本要求，可防止放射性物质通过洁具扩散。因此，选项C正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 101 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0102","type":"single","qtype":"单选题","stem":"放射性包装容器清洗需在（ ）内进行","options":[{"key":"A","text":"普通车间"},{"key":"B","text":"专用房间"},{"key":"C","text":"仓库"},{"key":"D","text":"实验室"}],"answer":["B"],"explanation":"放射性包装容器清洗需在专用房间内进行，该房间应具备辐射防护、去污和废水收集设施，以防止污染扩散。普通车间、仓库、实验室均不具备专用去污条件。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性包装容器清洗需在专用去污场所进行，配备专用去污试剂和工具，并对清洗废水进行放射性监测和处理。因此，选项B正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 102 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0103","type":"single","qtype":"单选题","stem":"放射性设备设计需便于（ ）","options":[{"key":"A","text":"搬运"},{"key":"B","text":"去除放射性污染、清洁维护"},{"key":"C","text":"销售"},{"key":"D","text":"采购"}],"answer":["B"],"explanation":"放射性设备设计需便于去除放射性污染和清洁维护，以减少人员辐射暴露和污染残留。搬运、销售、采购均不是设备设计的核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性设备的设计应便于清洁和去污，表面光滑、耐腐蚀、易拆卸，以减少放射性残留。因此，选项B正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 103 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0104","type":"single","qtype":"单选题","stem":"设备需具备与工艺适应的（ ）","options":[{"key":"A","text":"加热功能"},{"key":"B","text":"辐射防护措施"},{"key":"C","text":"冷却功能"},{"key":"D","text":"加湿功能"}],"answer":["B"],"explanation":"放射性药品生产设备需具备与工艺相适应的辐射防护措施，以保护操作人员并防止污染扩散。加热、冷却、加湿功能均不是放射性药品生产设备的核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n设备需根据放射性核素类型和活度配备屏蔽、负压、去污等辐射防护措施，确保生产安全。因此，选项B正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 104 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0105","type":"single","qtype":"单选题","stem":"生产设备需易于（ ）","options":[{"key":"A","text":"拆卸"},{"key":"B","text":"验证"},{"key":"C","text":"维修"},{"key":"D","text":"更换"}],"answer":["B"],"explanation":"放射性药品生产设备需易于验证，以确保设备性能符合工艺要求，并能有效控制放射性污染。拆卸、维修、更换均不是设备设计的首要验证要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n设备验证是药品GMP的核心要求，放射性药品生产设备需通过安装确认、运行确认、性能确认等验证活动，确保其适用性。因此，选项B正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 105 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0106","type":"single","qtype":"单选题","stem":"自动合成系统需（ ）至少验证一次","options":[{"key":"A","text":"一个月"},{"key":"B","text":"三个月"},{"key":"C","text":"半年"},{"key":"D","text":"一年"}],"answer":["D"],"explanation":"自动合成系统需每年至少验证一次，以确保其持续符合生产工艺要求，保证产品质量稳定。一个月、三个月、半年均不符合定期验证要求。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据药品GMP及放射性药品附录，自动合成设备和计算机软件控制系统需定期验证，通常每年至少一次，确保合成效率、产品纯度和放射性活度准确。因此，选项D正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 106 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0107","type":"single","qtype":"单选题","stem":"设备改造后需进行（ ）","options":[{"key":"A","text":"清洗"},{"key":"B","text":"灭菌"},{"key":"C","text":"再确认"},{"key":"D","text":"校准"}],"answer":["C"],"explanation":"设备改造后需进行再确认，以验证改造后的设备仍能满足生产工艺和质量要求。清洗、灭菌、校准均不能替代再确认。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n设备改造属于变更，需按照变更控制程序进行再确认，确保设备性能符合要求。因此，选项C正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 107 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0108","type":"single","qtype":"单选题","stem":"衡器、仪表需定期（ ）","options":[{"key":"A","text":"清洁"},{"key":"B","text":"灭菌"},{"key":"C","text":"校准检查"},{"key":"D","text":"更换"}],"answer":["C"],"explanation":"衡器、仪表需定期进行校准检查，以确保测量数据准确可靠，符合药品生产质量控制要求。清洁、灭菌、更换均不能替代校准检查。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n衡器、仪表需定期校准，确保放射性活度测定、温度控制等关键参数准确。因此，选项C正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 108 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0109","type":"single","qtype":"单选题","stem":"制药用水需符合（ ）标准","options":[{"key":"A","text":"企业内部"},{"key":"B","text":"《中国药典》"},{"key":"C","text":"行业"},{"key":"D","text":"地方"}],"answer":["B"],"explanation":"制药用水需符合《中国药典》标准，药典规定了制药用水的质量标准、检验方法和使用要求。企业内部、行业、地方标准均不能替代国家药典标准。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n制药用水是药品生产的关键物料，需符合《中国药典》中纯化水、注射用水等标准，并定期检验。因此，选项B正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 109 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0110","type":"single","qtype":"单选题","stem":"“检前暂存库冰箱温度计超校准有效期”属于（ ）","options":[{"key":"A","text":"合格情况"},{"key":"B","text":"典型缺陷"},{"key":"C","text":"轻微问题"},{"key":"D","text":"无关问题"}],"answer":["B"],"explanation":"“检前暂存库冰箱温度计超校准有效期”属于典型缺陷。温度计超期未校准会导致温度监测数据不可靠，可能影响放射性药品的储存质量。合格情况、轻微问题、无关问题均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n温度计需定期校准，确保冰箱温度符合放射性药品储存要求。超校准有效期属于不符合药品GMP的典型缺陷。因此，选项B正确。\n\n---","source":{"file":"单选题/101-110.md","merged":"单选题1-400.md","location":"第 110 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0111","type":"single","qtype":"单选题","stem":"生产的放射性药品需符合（ ）规定","options":[{"key":"A","text":"《药品生产许可证》"},{"key":"B","text":"《辐射安全许可证》"},{"key":"C","text":"《营业执照》"},{"key":"D","text":"《药品经营许可证》"}],"answer":["B"],"explanation":"生产放射性药品除需取得《药品生产许可证》外，还必须符合《辐射安全许可证》的规定。因为放射性药品生产涉及放射性同位素与射线装置，必须取得辐射安全许可，确保生产活动符合辐射防护要求。《药品生产许可证》是药品生产的基本许可，《营业执照》是市场主体登记，《药品经营许可证》针对经营环节，均不能替代辐射安全许可。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产放射性药品必须取得《辐射安全许可证》，并按照许可证规定的种类和范围从事生产活动。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 111 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0112","type":"single","qtype":"单选题","stem":"企业需设立（ ）","options":[{"key":"A","text":"销售部门"},{"key":"B","text":"辐射防护管理机构及人员"},{"key":"C","text":"采购部门"},{"key":"D","text":"财务部门"}],"answer":["B"],"explanation":"放射性药品生产企业需设立辐射防护管理机构及人员，负责辐射安全管理和防护工作，确保生产过程中人员和环境安全。销售部门、采购部门、财务部门是常规企业部门，但不是放射性药品生产企业的特殊要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产、使用放射性同位素和射线装置的单位，应当设置辐射安全管理机构或者配备专职辐射安全管理人员。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 112 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0113","type":"single","qtype":"单选题","stem":"需建立放射性事故（ ）","options":[{"key":"A","text":"销售计划"},{"key":"B","text":"应急预案"},{"key":"C","text":"生产计划"},{"key":"D","text":"采购计划"}],"answer":["B"],"explanation":"放射性药品生产企业需建立放射性事故应急预案，以应对可能发生的放射性事故，及时采取控制措施，减少危害。销售计划、生产计划、采购计划均属于常规经营计划，与事故应急无关。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产、使用放射性同位素和射线装置的单位，应当制定辐射事故应急预案，并定期组织演练。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 113 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0114","type":"single","qtype":"单选题","stem":"人员需定期进行（ ）","options":[{"key":"A","text":"普通体检"},{"key":"B","text":"职业健康体检"},{"key":"C","text":"仅辐射培训"},{"key":"D","text":"仅操作培训"}],"answer":["B"],"explanation":"放射性药品生产人员需定期进行职业健康体检，以监测辐射对健康的影响，保障从业人员职业健康。普通体检不能替代职业健康体检，仅辐射培训或仅操作培训也不够全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》和《职业病防治法》，从事放射性工作的人员必须定期进行职业健康体检，建立职业健康监护档案。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 114 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0115","type":"single","qtype":"单选题","stem":"放射性药品包装需有（ ）","options":[{"key":"A","text":"企业Logo"},{"key":"B","text":"放射性药品标志"},{"key":"C","text":"价格信息"},{"key":"D","text":"促销信息"}],"answer":["B"],"explanation":"放射性药品包装需有放射性药品标志，以警示操作人员和患者注意辐射防护。企业Logo、价格信息、促销信息均不是放射性药品包装的法定要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n因此，放射性药品包装需有放射性药品标志，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 115 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0116","type":"single","qtype":"单选题","stem":"工作服清洗前需（ ）","options":[{"key":"A","text":"外观检查"},{"key":"B","text":"放射性污染检测"},{"key":"C","text":"尺寸测量"},{"key":"D","text":"材质检测"}],"answer":["B"],"explanation":"放射性工作区使用的工作服在清洗前需进行放射性污染检测，确认是否受到污染，再决定是否需先去污处理。外观检查、尺寸测量、材质检测均不能检测放射性污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作服清洗前进行放射性污染检测，是防止放射性污染扩散的重要措施，符合辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 116 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0117","type":"single","qtype":"单选题","stem":"可重复使用的放射性包装容器需有（ ）","options":[{"key":"A","text":"专用去污场所"},{"key":"B","text":"销售渠道"},{"key":"C","text":"采购渠道"},{"key":"D","text":"存放区域"}],"answer":["A"],"explanation":"可重复使用的放射性包装容器需有专用去污场所，用于清洗和去污处理，确保容器在重复使用前无放射性残留。销售渠道、采购渠道、存放区域均不能替代专用去污场所。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n可重复使用的放射性包装容器需在专用去污场所进行清洗和污染检测，达标后方可再次使用。因此，选项A正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 117 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0118","type":"single","qtype":"单选题","stem":"锝[99mTc]标记药品的淋洗液（0.9%氯化钠）需符合（ ）标准","options":[{"key":"A","text":"企业内部"},{"key":"B","text":"《中国药典》"},{"key":"C","text":"行业"},{"key":"D","text":"地方"}],"answer":["B"],"explanation":"锝[99mTc]标记药品的淋洗液（0.9%氯化钠注射液）需符合《中国药典》标准，确保其质量满足注射剂要求。企业内部标准、行业标准、地方标准均不能替代国家药典标准。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n淋洗液0.9%氯化钠注射液属于制药用水或注射剂，需符合《中国药典》中氯化钠注射液的质量标准，包括无菌、无热原、pH、渗透压等。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 118 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0119","type":"single","qtype":"单选题","stem":"锝[99mTc]药品最终需装入（ ）","options":[{"key":"A","text":"普通容器"},{"key":"B","text":"铅防护筒"},{"key":"C","text":"纸箱"},{"key":"D","text":"塑料袋"}],"answer":["B"],"explanation":"锝[99mTc]药品最终需装入铅防护筒，以屏蔽γ射线，降低操作人员和患者受到的辐射剂量。普通容器、纸箱、塑料袋均不能提供有效的辐射防护。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n锝[99mTc]发射γ射线，需使用铅防护筒等屏蔽容器进行包装和运输，确保表面剂量率符合国家辐射防护标准。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 119 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0120","type":"single","qtype":"单选题","stem":"锝[99mTc]配套药盒供应商需具备（ ）资格","options":[{"key":"A","text":"普通药品生产/经营"},{"key":"B","text":"放射性药品生产/经营"},{"key":"C","text":"医疗器械生产/经营"},{"key":"D","text":"食品生产/经营"}],"answer":["B"],"explanation":"锝[99mTc]配套药盒供应商需具备放射性药品生产/经营资格，因为配套药盒虽本身无放射性，但属于放射性药品的配套组分，其生产供应需符合放射性药品管理要求。普通药品、医疗器械、食品生产/经营资格均不符合。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n锝[99mTc]配套药盒作为放射性药品标记的配套组分，其供应商应具备放射性药品生产或经营资质，并接受质量审计。因此，选项B正确。\n\n---","source":{"file":"单选题/111-120.md","merged":"单选题1-400.md","location":"第 120 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0121","type":"single","qtype":"单选题","stem":"锝[99mTc]标记和分装的洁净环境是（ ）","options":[{"key":"A","text":"A级"},{"key":"B","text":"C级背景下局部A级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["B"],"explanation":"锝[99mTc]标记和分装操作涉及放射性药品的无菌制备，需在C级洁净区背景下，局部达到A级层流保护，以最大限度降低微生物和微粒污染风险。A级、C级、D级均不能完整描述该操作的环境要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，锝[99mTc]标记药品的标记和分装操作属于无菌制备过程，应在C级背景下局部A级洁净区进行，以确保产品无菌和无微粒污染。因此，选项B正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 121 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0122","type":"single","qtype":"单选题","stem":"锝[99mTc]生产需关注（ ）风险管理","options":[{"key":"A","text":"单人操作"},{"key":"B","text":"共线生产（不同药盒标记）"},{"key":"C","text":"批量生产"},{"key":"D","text":"小规模生产"}],"answer":["B"],"explanation":"锝[99mTc]生产需重点关注共线生产（不同药盒标记）带来的交叉污染和混淆风险。不同配套药盒可能含有不同配体，共线生产时需采取有效清洁和清场措施。单人操作、批量生产、小规模生产均不是该环节的核心风险点。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n共线生产不同药盒标记时，存在交叉污染和混淆风险，需通过风险评估制定控制措施，如专用设备、清洁验证、清场管理等，符合药品GMP及放射性药品附录要求。因此，选项B正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 122 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0123","type":"single","qtype":"单选题","stem":"锝[99mTc]药品需进行（ ）","options":[{"key":"A","text":"无菌工艺模拟试验"},{"key":"B","text":"加速稳定性试验"},{"key":"C","text":"长期稳定性试验"},{"key":"D","text":"影响因素试验"}],"answer":["A"],"explanation":"锝[99mTc]药品属于无菌药品，需进行无菌工艺模拟试验（培养基模拟灌装试验），以验证无菌生产工艺的可靠性。加速稳定性试验、长期稳定性试验、影响因素试验属于稳定性考察项目，不是无菌工艺验证的核心要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其无菌药品附录，无菌药品生产需定期进行无菌工艺模拟试验，证明无菌操作工艺的可靠性。锝[99mTc]药品为无菌注射剂，因此需进行该试验。选项A正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 123 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0124","type":"single","qtype":"单选题","stem":"正电子类药品合成热室的洁净级别是（ ）","options":[{"key":"A","text":"A级"},{"key":"B","text":"B级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["C"],"explanation":"正电子类药品合成热室的洁净级别为C级。合成过程在密闭的自动合成系统中进行，热室环境需达到C级洁净度，以控制微粒和微生物污染，同时满足辐射防护要求。A级、B级、D级均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，正电子类放射性药品的合成在自动合成系统内进行，其所在热室环境应达到C级洁净级别。因此，选项C正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 124 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0125","type":"single","qtype":"单选题","stem":"正电子类药品分装热室的洁净级别是（ ）","options":[{"key":"A","text":"A级"},{"key":"B","text":"C级背景下局部A级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["B"],"explanation":"正电子类药品分装热室的洁净级别为C级背景下局部A级。分装操作涉及无菌药品的暴露，需在C级背景下的局部A级层流保护下进行，以最大限度降低微生物和微粒污染。A级、C级、D级均不能完整描述该环境要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，正电子类放射性药品的分装操作应在C级背景下局部A级洁净区进行，确保产品无菌。因此，选项B正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 125 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0126","type":"single","qtype":"单选题","stem":"正电子类药品分装用除菌滤膜需在使用后（ ）","options":[{"key":"A","text":"外观检查"},{"key":"B","text":"完整性测试"},{"key":"C","text":"重量检查"},{"key":"D","text":"尺寸测量"}],"answer":["B"],"explanation":"正电子类药品分装用除菌滤膜需在使用后进行完整性测试，以确认滤膜在过滤过程中未发生破损或泄漏，保证除菌效果。外观检查、重量检查、尺寸测量均不能验证滤膜的完整性。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据药品GMP及无菌药品附录，除菌过滤后必须进行滤膜完整性测试，通常采用起泡点、扩散流等方法。正电子类药品分装用除菌滤膜使用后需进行完整性测试，确保无菌保证水平。因此，选项B正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 126 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0127","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源半成品需存入（ ）","options":[{"key":"A","text":"普通仓库"},{"key":"B","text":"放射源库专用柜"},{"key":"C","text":"纸箱"},{"key":"D","text":"塑料袋"}],"answer":["B"],"explanation":"碘[125I]密封籽源半成品含有放射性物质，需存入放射源库专用柜，并采取防火、防盗、防泄漏等安全措施。普通仓库、纸箱、塑料袋均不能提供辐射防护和安全保障。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n碘[125I]密封籽源半成品属于放射性物料，必须存入放射源库专用柜，确保安全可控。因此，选项B正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 127 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0128","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源退回产品需明确（ ）","options":[{"key":"A","text":"销售计划"},{"key":"B","text":"采购计划"},{"key":"C","text":"退回处置规程"},{"key":"D","text":"研发计划"}],"answer":["C"],"explanation":"碘[125I]密封籽源退回产品需明确退回处置规程，包括接收、评估、隔离、处置等步骤，确保退回产品得到安全合规处理。销售计划、采购计划、研发计划均与退回产品处置无关。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n退回产品需按照书面规程进行处置，经质量评估后决定是否重新使用或销毁，并确保辐射安全。因此，选项C正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 128 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0129","type":"single","qtype":"单选题","stem":"碘[125I]生产操作需保持（ ）","options":[{"key":"A","text":"相对正压"},{"key":"B","text":"相对负压"},{"key":"C","text":"常压"},{"key":"D","text":"无压力要求"}],"answer":["B"],"explanation":"碘[125I]生产操作需保持相对负压，以防止放射性气溶胶或蒸气向外扩散，保护周围环境和人员。相对正压、常压、无压力要求均不能有效控制放射性污染扩散。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n碘[125I]具有挥发性，操作区需保持相对负压，并配备高效过滤排风系统，防止放射性物质外溢。因此，选项B正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 129 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0130","type":"single","qtype":"单选题","stem":"体外诊断试剂盒抗原供应商审计需评估（ ）","options":[{"key":"A","text":"生产能力"},{"key":"B","text":"冷链保障能力"},{"key":"C","text":"销售能力"},{"key":"D","text":"研发能力"}],"answer":["B"],"explanation":"体外诊断试剂盒抗原供应商审计需评估冷链保障能力，因为抗原等生物活性原料对温度敏感，需在规定的冷链条件下运输和储存，以确保质量。生产能力、销售能力、研发能力均不是供应商审计的核心评估内容。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n体外诊断试剂盒中的抗原原料需冷链运输和储存，供应商审计应重点评估其冷链保障能力，确保原料质量稳定。因此，选项B正确。\n\n---","source":{"file":"单选题/121-130.md","merged":"单选题1-400.md","location":"第 130 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0131","type":"single","qtype":"单选题","stem":"外购大包装抗体需保留原包装至（ ）后30天","options":[{"key":"A","text":"生产日期"},{"key":"B","text":"分装日期"},{"key":"C","text":"最后一批产品有效期"},{"key":"D","text":"入库日期"}],"answer":["C"],"explanation":"外购大包装抗体需保留原包装至最后一批产品有效期后30天，以便在出现质量问题时进行追溯和调查。生产日期、分装日期、入库日期均不能保证覆盖产品整个生命周期。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n外购大包装抗体作为体外诊断试剂盒的关键原料，其原包装需保留至最后一批产品有效期后30天，以满足追溯和质量调查要求。因此，选项C正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 131 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0132","type":"single","qtype":"单选题","stem":"自制抗原需具备（ ）","options":[{"key":"A","text":"合格动物房"},{"key":"B","text":"普通车间"},{"key":"C","text":"仓库"},{"key":"D","text":"实验室"}],"answer":["A"],"explanation":"自制抗原通常需使用动物进行免疫制备，因此需具备合格动物房，符合实验动物管理和伦理要求。普通车间、仓库、实验室均不能替代合格动物房。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n自制抗原若涉及动物免疫，需在合格动物房内进行，确保实验动物质量及生物安全。因此，选项A正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 132 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0133","type":"single","qtype":"单选题","stem":"体外诊断试剂盒不同品种（ ）同台组装","options":[{"key":"A","text":"可以"},{"key":"B","text":"不得"},{"key":"C","text":"随意"},{"key":"D","text":"经批准后可以"}],"answer":["B"],"explanation":"体外诊断试剂盒不同品种不得同台组装，以防止交叉污染和混淆，确保产品质量和安全性。可以、随意、经批准后可以均不符合GMP要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同品种体外诊断试剂盒同台组装易导致交叉污染和混淆，违反药品GMP要求，必须严格分开操作。因此，选项B正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 133 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0134","type":"single","qtype":"单选题","stem":"委托生产18F-FDG时，上市许可持有人负责（ ）","options":[{"key":"A","text":"生产操作"},{"key":"B","text":"上市放行"},{"key":"C","text":"销售"},{"key":"D","text":"采购"}],"answer":["B"],"explanation":"委托生产18F-FDG时，上市许可持有人负责上市放行，即对受托方生产的药品进行最终质量审核和放行，确保产品符合注册标准。生产操作由受托方负责，销售和采购不是上市许可持有人的核心放行职责。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据药品上市许可持有人制度，委托生产时上市许可持有人负责药品上市放行，确保产品质量和安全。因此，选项B正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 134 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0135","type":"single","qtype":"单选题","stem":"受托方合成仪型号需与（ ）一致","options":[{"key":"A","text":"采购计划"},{"key":"B","text":"注册批准"},{"key":"C","text":"行业推荐"},{"key":"D","text":"地方要求"}],"answer":["B"],"explanation":"受托方合成仪型号需与注册批准一致，因为注册批准中载明了生产工艺和设备要求，变更设备型号需进行变更控制。采购计划、行业推荐、地方要求均不能替代注册批准。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第五条规定：放射性新药的研制内容，包括工艺路线、质量标准、临床前药理及临床研究。研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、放射性比活度、剂量、剂型、稳定性等。\n注册批准的生产工艺和设备是保证产品质量的基础，受托方合成仪型号需与注册批准一致，变更需经批准。因此，选项B正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 135 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0136","type":"single","qtype":"单选题","stem":"委托双方需签订（ ）","options":[{"key":"A","text":"销售合同"},{"key":"B","text":"采购合同"},{"key":"C","text":"质量协议"},{"key":"D","text":"劳动合同"}],"answer":["C"],"explanation":"委托生产放射性药品时，委托双方需签订质量协议，明确双方在质量管理、生产操作、放行等方面的职责。销售合同、采购合同、劳动合同均不能替代质量协议。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n委托生产时，双方需签订质量协议，明确质量责任和沟通机制，确保药品质量。因此，选项C正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 136 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0137","type":"single","qtype":"单选题","stem":"锝[99mTc]药盒更换供应商后，需先（ ）","options":[{"key":"A","text":"检验药盒无菌"},{"key":"B","text":"直接生产"},{"key":"C","text":"评估成本"},{"key":"D","text":"更换设备"}],"answer":["A"],"explanation":"锝[99mTc]药盒更换供应商后，需先检验药盒无菌，以确保新供应商提供的药盒符合无菌要求，避免影响最终药品质量。直接生产、评估成本、更换设备均不能替代质量检验。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n更换供应商属于变更，需对新供应商的药盒进行质量检验，包括无菌检查，合格后方可用于生产。因此，选项A正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 137 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0138","type":"single","qtype":"单选题","stem":"正电子类药品滤膜完整性测试需在（ ）内完成","options":[{"key":"A","text":"产品放行前"},{"key":"B","text":"72小时"},{"key":"C","text":"任意时间"},{"key":"D","text":"用药后"}],"answer":["A"],"explanation":"正电子类药品滤膜完整性测试需在产品放行前完成，以确认除菌过滤过程有效，保证产品无菌。72小时、任意时间、用药后均不符合放行前完成的要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据药品GMP及无菌药品附录，除菌过滤后需进行滤膜完整性测试，且应在产品放行前完成，确保无菌保证水平。因此，选项A正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 138 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0139","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源批号定义为（ ）","options":[{"key":"A","text":"同一天生产"},{"key":"B","text":"同一生产线"},{"key":"C","text":"同一批原料连续生产"},{"key":"D","text":"同一规格"}],"answer":["C"],"explanation":"碘[125I]密封籽源批号定义为同一批原料连续生产的产品。同一天生产、同一生产线、同一规格均不能准确反映批号的定义。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批号是用于追溯产品生产历史的重要标识，碘[125I]密封籽源批号定义为同一批原料连续生产，确保产品可追溯。因此，选项C正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 139 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0140","type":"single","qtype":"单选题","stem":"体外诊断试剂盒组装记录需纳入（ ）","options":[{"key":"A","text":"销售记录"},{"key":"B","text":"采购记录"},{"key":"C","text":"批生产记录"},{"key":"D","text":"检验记录"}],"answer":["C"],"explanation":"体外诊断试剂盒组装记录需纳入批生产记录，以完整追溯生产过程中使用的物料、操作步骤、环境条件等信息。销售记录、采购记录、检验记录均不能替代批生产记录。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批生产记录是药品生产质量管理的重要文件，体外诊断试剂盒组装记录应纳入批生产记录，确保可追溯。因此，选项C正确。\n\n---","source":{"file":"单选题/131-140.md","merged":"单选题1-400.md","location":"第 140 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0141","type":"single","qtype":"单选题","stem":"辐射安全培训需（ ）进行","options":[{"key":"A","text":"不定期"},{"key":"B","text":"定期"},{"key":"C","text":"仅入职时"},{"key":"D","text":"仅每年一次"}],"answer":["B"],"explanation":"辐射安全培训需定期进行，以持续更新人员的辐射防护知识和操作技能，确保其始终具备岗位所需的安全意识和能力。不定期、仅入职时、仅每年一次均不能保证培训的持续性和及时性。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产、使用放射性同位素和射线装置的单位应当对工作人员进行辐射安全培训，并定期组织复训。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 141 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0142","type":"single","qtype":"单选题","stem":"放射性药品标签需注明（ ）","options":[{"key":"A","text":"价格"},{"key":"B","text":"放射性药品标志"},{"key":"C","text":"销售人员信息"},{"key":"D","text":"经销商信息"}],"answer":["B"],"explanation":"放射性药品标签需注明放射性药品标志，以警示操作人员和患者注意辐射防护。价格、销售人员信息、经销商信息均不是放射性药品标签的法定标注内容。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n标签上还需注明药品名称、放射性核素、活度、批号、有效期等信息，放射性药品标志是其中必备内容。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 142 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0143","type":"single","qtype":"单选题","stem":"放射性包装容器需检测（ ）性能","options":[{"key":"A","text":"美观"},{"key":"B","text":"辐射防护"},{"key":"C","text":"轻便"},{"key":"D","text":"大容量"}],"answer":["B"],"explanation":"放射性包装容器需检测辐射防护性能，确保其屏蔽能力符合要求，能有效降低容器表面剂量率，保护人员和环境。美观、轻便、大容量均不是其核心检测性能。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n放射性包装容器需检测其辐射防护性能，包括屏蔽效果、表面剂量率、泄漏情况等，确保符合国家放射性物品运输安全标准。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 143 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0144","type":"single","qtype":"单选题","stem":"正电子类药品合成用工艺用气（氦气/氮气）需（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"过滤后进入洁净区"},{"key":"C","text":"加热后使用"},{"key":"D","text":"冷却后使用"}],"answer":["B"],"explanation":"正电子类药品合成用工艺用气（氦气/氮气）需经过滤后进入洁净区，以控制微粒和微生物污染，保证合成环境符合洁净度要求。直接使用、加热后使用、冷却后使用均不能有效控制污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，进入洁净区的工艺用气需经过滤处理，确保其洁净度与洁净区级别相适应。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 144 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0145","type":"single","qtype":"单选题","stem":"碘[125I]密封籽源检漏工序位于（ ）之后","options":[{"key":"A","text":"源芯制备"},{"key":"B","text":"源芯装配（焊封）"},{"key":"C","text":"活度检测"},{"key":"D","text":"分装密封"}],"answer":["B"],"explanation":"碘[125I]密封籽源检漏工序位于源芯装配（焊封）之后，用于检测钛合金管焊封是否严密，防止碘[125I]泄漏。源芯制备、活度检测、分装密封均不是检漏工序的直接前置步骤。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n碘[125I]密封籽源在源芯装配（焊封）后必须进行检漏，确保密封性，防止放射性物质泄漏。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 145 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0146","type":"single","qtype":"单选题","stem":"体外诊断试剂盒冷链验证需确定（ ）","options":[{"key":"A","text":"箱体预冷时间"},{"key":"B","text":"运输路线"},{"key":"C","text":"运输价格"},{"key":"D","text":"运输司机"}],"answer":["A"],"explanation":"体外诊断试剂盒冷链验证需确定箱体预冷时间，以确保运输箱在装载前达到规定温度，保证试剂盒在运输过程中的温度稳定性。运输路线、运输价格、运输司机均不是冷链验证的核心参数。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二十条规定：放射性药品的运输，按国家运输、邮政等部门制定的有关规定执行。严禁任何单位和个人随身携带放射性药品乘坐公共交通运输工具。\n体外诊断试剂盒中的生物活性组分需冷链运输，冷链验证需确定箱体预冷时间、保温时长、温度监测等参数，确保全程温度符合要求。因此，选项A正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 146 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0147","type":"single","qtype":"单选题","stem":"委托生产中，受托方需具备（ ）能力","options":[{"key":"A","text":"全项检验"},{"key":"B","text":"销售"},{"key":"C","text":"研发"},{"key":"D","text":"采购"}],"answer":["A"],"explanation":"委托生产中，受托方需具备全项检验能力，以确保生产的放射性药品符合注册质量标准。销售、研发、采购能力均不是受托方承担委托生产的关键要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n委托生产时，受托方需具备与受托品种相适应的全项检验能力，确保产品放行前完成所有规定检验项目。因此，选项A正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 147 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0148","type":"single","qtype":"单选题","stem":"辐射剂量监测需（ ）进行","options":[{"key":"A","text":"不定期"},{"key":"B","text":"定期"},{"key":"C","text":"仅入职时"},{"key":"D","text":"仅离职时"}],"answer":["B"],"explanation":"辐射剂量监测需定期进行，以持续评估人员的辐射暴露水平，保障职业健康。不定期、仅入职时、仅离职时均不能实现持续监测。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，从事放射性工作的人员必须定期进行个人剂量监测，建立剂量档案，并按规定周期上报。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 148 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0149","type":"single","qtype":"单选题","stem":"放射性事故应急预案需（ ）","options":[{"key":"A","text":"口头告知"},{"key":"B","text":"书面制定并演练"},{"key":"C","text":"仅存档"},{"key":"D","text":"仅上报"}],"answer":["B"],"explanation":"放射性事故应急预案需书面制定并定期演练，以确保在发生放射性事故时能够迅速、有效地响应，减少危害。口头告知、仅存档、仅上报均不能保证预案的有效性和可操作性。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产、使用放射性同位素和射线装置的单位应当制定辐射事故应急预案，并定期组织演练。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 149 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0150","type":"single","qtype":"单选题","stem":"锝[99mTc]药品批号编制需符合（ ）要求","options":[{"key":"A","text":"企业内部"},{"key":"B","text":"药品GMP放射性药品附录"},{"key":"C","text":"行业"},{"key":"D","text":"地方"}],"answer":["B"],"explanation":"锝[99mTc]药品批号编制需符合药品GMP放射性药品附录的要求，确保批号能够唯一标识生产批次，便于追溯。企业内部、行业、地方要求均不能替代国家药品GMP附录的规定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，放射性药品批号编制需符合附录要求，确保可追溯性。因此，选项B正确。\n\n---","source":{"file":"单选题/141-150.md","merged":"单选题1-400.md","location":"第 150 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0151","type":"single","qtype":"单选题","stem":"企业需具备（ ）放行检验能力","options":[{"key":"A","text":"核素鉴别、活度测定"},{"key":"B","text":"广告设计"},{"key":"C","text":"市场调研"},{"key":"D","text":"客户服务"}],"answer":["A"],"explanation":"放射性药品生产企业需具备核素鉴别、活度测定等放行检验能力，以确保产品符合注册质量标准。广告设计、市场调研、客户服务均与药品放行检验无关。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性药品的放行检验必须包括核素鉴别、放射性活度测定、放射化学纯度等关键项目，以确保药品的安全性和有效性。因此，选项A正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 151 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0152","type":"single","qtype":"单选题","stem":"质控实验室负责人需具备（ ）","options":[{"key":"A","text":"初中以上学历"},{"key":"B","text":"医药相关本科以上学历或中级职称"},{"key":"C","text":"仅操作经验"},{"key":"D","text":"仅资格证书"}],"answer":["B"],"explanation":"质控实验室负责人需具备医药相关本科以上学历或中级职称，以确保其具备足够的专业知识和质量管理能力。初中以上学历、仅操作经验、仅资格证书均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质控实验室负责人属于关键岗位人员，需具备医药相关专业本科以上学历或中级以上技术职称，并具有放射性药品质量控制经验。因此，选项B正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 152 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0153","type":"single","qtype":"单选题","stem":"检验人员需具备（ ）以上学历","options":[{"key":"A","text":"小学"},{"key":"B","text":"中专/高中"},{"key":"C","text":"大专"},{"key":"D","text":"本科"}],"answer":["B"],"explanation":"放射性药品检验人员需具备中专/高中以上学历，并经过专业培训考核合格。小学学历不符合要求，大专、本科虽然更高，但最低要求为中专/高中。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验人员需具备中专或高中以上学历，并接受放射性药品检验技术和辐射防护培训，考核合格后方可上岗。因此，选项B正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 153 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0154","type":"single","qtype":"单选题","stem":"检验仪器不应与（ ）仪器混用","options":[{"key":"A","text":"研发用"},{"key":"B","text":"生产用"},{"key":"C","text":"销售用"},{"key":"D","text":"采购用"}],"answer":["B"],"explanation":"检验仪器不应与生产用仪器混用，以防止生产过程中的放射性污染影响检验结果的准确性，确保检验数据可靠。研发用、销售用、采购用仪器均不是混用限制的主要对象。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验仪器应专用，避免与生产设备混用，防止交叉污染和结果偏差。因此，选项B正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 154 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0155","type":"single","qtype":"单选题","stem":"放射性药品检验需进行（ ）","options":[{"key":"A","text":"仅使用前检验"},{"key":"B","text":"仅追溯性检验"},{"key":"C","text":"使用前+追溯性检验"},{"key":"D","text":"无需检验"}],"answer":["C"],"explanation":"放射性药品检验需进行使用前检验和追溯性检验。使用前检验确保药品在临床使用前符合质量标准；追溯性检验用于稳定性考察和质量回顾。仅使用前、仅追溯性、无需检验均不完整。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性药品因半衰期短，需在使用前完成关键项目检验，同时按规定进行追溯性检验，确保全生命周期质量可控。因此，选项C正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 155 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0156","type":"single","qtype":"单选题","stem":"“碘[125I]密封籽源稳定性考察用留样”属于（ ）","options":[{"key":"A","text":"合格情况"},{"key":"B","text":"典型缺陷"},{"key":"C","text":"轻微问题"},{"key":"D","text":"无关问题"}],"answer":["B"],"explanation":"“碘[125I]密封籽源稳定性考察用留样”属于典型缺陷。稳定性考察用留样需按规定条件储存并定期检验，若管理不当可能影响产品稳定性评估。合格情况、轻微问题、无关问题均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n留样是药品质量管理的重要环节，稳定性考察用留样需专柜存放、专人管理、定期检验，缺失或管理不善属于典型缺陷。因此，选项B正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 156 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0157","type":"single","qtype":"单选题","stem":"半衰期＞20分钟的正电子药品使用前需测（ ）","options":[{"key":"A","text":"生物分布"},{"key":"B","text":"无菌"},{"key":"C","text":"性状、pH、放射化学纯度"},{"key":"D","text":"长期稳定性"}],"answer":["C"],"explanation":"半衰期＞20分钟的正电子药品使用前需测性状、pH、放射化学纯度，这些是关键质量指标，可在较短时间内完成检验。生物分布、无菌、长期稳定性均不适合作为使用前快速检验项目。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n正电子类放射性药品半衰期较短，使用前需完成性状、pH、放射化学纯度等快速检验，确保安全有效。因此，选项C正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 157 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0158","type":"single","qtype":"单选题","stem":"半衰期≤20分钟的正电子药品，同一天内每次制备称为（ ）","options":[{"key":"A","text":"批次"},{"key":"B","text":"亚批"},{"key":"C","text":"批量"},{"key":"D","text":"批次"}],"answer":["B"],"explanation":"半衰期≤20分钟的正电子药品，同一天内每次制备称为亚批。亚批管理便于追溯和区分同一天内多次制备的产品。批次、批量均不是其准确定义。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n对于半衰期极短的正电子药品，同一天内可能多次制备，每次制备定义为亚批，需独立记录和检验，确保可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 158 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0159","type":"single","qtype":"单选题","stem":"正电子药品追溯性检验连续（ ）批合格后可定期抽验","options":[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"6"}],"answer":["D"],"explanation":"正电子药品追溯性检验连续6批合格后可定期抽验。这是基于风险评估的检验策略，连续合格表明工艺稳定，可降低检验频次。3、4、5批均不符合规定要求。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n正电子药品追溯性检验连续6批合格后，可依据风险管理原则定期抽验，以优化检验资源。因此，选项D正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 159 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0160","type":"single","qtype":"单选题","stem":"正电子药品定期抽验至少（ ）一次全检","options":[{"key":"A","text":"一个月"},{"key":"B","text":"三个月"},{"key":"C","text":"半年"},{"key":"D","text":"一年"}],"answer":["A"],"explanation":"正电子药品定期抽验至少一个月一次全检，以确保产品质量持续稳定。三个月、半年、一年均不符合定期抽验的最低频次要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n正电子药品在连续追溯性检验合格后，仍需至少每月进行一次全检，以持续监控工艺和产品质量。因此，选项A正确。\n\n---","source":{"file":"单选题/151-160.md","merged":"单选题1-400.md","location":"第 160 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0161","type":"single","qtype":"单选题","stem":"“氟[18F]批记录未记录展开剂配制批号”属于（ ）","options":[{"key":"A","text":"合格情况"},{"key":"B","text":"典型缺陷"},{"key":"C","text":"轻微问题"},{"key":"D","text":"无关问题"}],"answer":["B"],"explanation":"“氟[18F]批记录未记录展开剂配制批号”属于典型缺陷。批记录应完整记录所有关键物料和试剂的批号，以便追溯。展开剂用于放射化学纯度检验，未记录其配制批号会导致检验过程不可追溯，属于数据完整性和质量管理缺陷。合格情况、轻微问题、无关问题均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批记录是药品生产质量管理的重要文件，必须真实、完整、可追溯。氟[18F]批记录中未记录展开剂配制批号，违反数据完整性要求，属于典型缺陷。因此，选项B正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 161 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0162","type":"single","qtype":"单选题","stem":"锝[99mTc]药品使用前必检项目不包括（ ）","options":[{"key":"A","text":"性状"},{"key":"B","text":"pH值"},{"key":"C","text":"放射化学纯度"},{"key":"D","text":"生物分布"}],"answer":["D"],"explanation":"锝[99mTc]药品使用前必检项目包括性状、pH值、放射化学纯度等快速检验项目，但不包括生物分布。生物分布实验耗时较长，通常用于追溯性检验或新产品验证，不适合作为使用前快速检验。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n锝[99mTc]药品半衰期较短，使用前需完成性状、pH、放射化学纯度等快速检验。生物分布需动物实验，周期长，不属于使用前必检项目。因此，选项D正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 162 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0163","type":"single","qtype":"单选题","stem":"锝[99mTc]快速检验法需（ ）","options":[{"key":"A","text":"简单评估"},{"key":"B","text":"方法验证"},{"key":"C","text":"无需验证"},{"key":"D","text":"口头确认"}],"answer":["B"],"explanation":"锝[99mTc]快速检验法需进行方法验证，以确保检验方法准确、可靠、适用于该品种。简单评估、无需验证、口头确认均不符合药品质量控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n快速检验法用于使用前质量控制，必须经过方法验证，确认其专属性、准确度、精密度等符合要求。因此，选项B正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 163 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0164","type":"single","qtype":"单选题","stem":"新增钼[99Mo]-锝[99mTc]发生器需先（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"淋洗后全检"},{"key":"C","text":"评估成本"},{"key":"D","text":"更换设备"}],"answer":["B"],"explanation":"新增钼[99Mo]-锝[99mTc]发生器需先淋洗后全检，以确认其产生的淋洗液质量符合要求，包括放射性核纯度、放射化学纯度、无菌、无热原等。直接使用、评估成本、更换设备均不符合质量控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n新增发生器属于关键物料变更，需进行淋洗并全检合格后方可用于生产，确保产品质量。因此，选项B正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 164 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0165","type":"single","qtype":"单选题","stem":"同一厂家钼[99Mo]发生器连续（ ）批无菌合格后可定期检查","options":[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"6"}],"answer":["D"],"explanation":"同一厂家钼[99Mo]发生器连续6批无菌合格后可定期检查。这是基于风险管理的检验策略，连续合格表明供应商质量稳定，可降低检验频次。3、4、5批均不符合规定要求。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同一厂家钼[99Mo]发生器连续6批无菌合格后，可依据风险管理原则定期检查，以优化检验资源。因此，选项D正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 165 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0166","type":"single","qtype":"单选题","stem":"多道γ谱仪需用（ ）进行能量刻度","options":[{"key":"A","text":"普通样品"},{"key":"B","text":"标准源"},{"key":"C","text":"待测样品"},{"key":"D","text":"空白样品"}],"answer":["B"],"explanation":"多道γ谱仪需用标准源进行能量刻度，以建立能量与道数的对应关系，确保核素鉴别准确。普通样品、待测样品、空白样品均不能用于能量刻度。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n多道γ谱仪用于放射性核素鉴别和核纯度测定，需定期使用标准源进行能量刻度，确保测量准确性。因此，选项B正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 166 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0167","type":"single","qtype":"单选题","stem":"放射性活度计检定需涵盖（ ）","options":[{"key":"A","text":"任意核素"},{"key":"B","text":"待测药品核素"},{"key":"C","text":"常见核素"},{"key":"D","text":"稀有核素"}],"answer":["B"],"explanation":"放射性活度计检定需涵盖待测药品核素，以确保活度测量准确。任意核素、常见核素、稀有核素均不能替代待测药品核素的检定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性活度计需针对待测药品所含核素进行检定，确保测量结果准确可靠。因此，选项B正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 167 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0168","type":"single","qtype":"单选题","stem":"放射性色谱扫描仪部分型号需（ ）","options":[{"key":"A","text":"P10气体（氩气:甲烷=9:1）"},{"key":"B","text":"氧气"},{"key":"C","text":"氮气"},{"key":"D","text":"氢气"}],"answer":["A"],"explanation":"放射性色谱扫描仪部分型号需使用P10气体（氩气:甲烷=9:1）作为计数气体，用于检测放射性色谱条上的放射性分布。氧气、氮气、氢气均不能替代P10气体。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性色谱扫描仪用于放射化学纯度测定，部分型号需P10气体作为工作气体，确保检测灵敏度。因此，选项A正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 168 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0169","type":"single","qtype":"单选题","stem":"γ计数器需定期核查（ ）","options":[{"key":"A","text":"外观"},{"key":"B","text":"线性"},{"key":"C","text":"重量"},{"key":"D","text":"尺寸"}],"answer":["B"],"explanation":"γ计数器需定期核查线性，以确保其在不同放射性活度范围内的计数响应呈线性关系，保证测量准确。外观、重量、尺寸均不是其核心核查参数。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\nγ计数器用于放射性活度测量，需定期核查线性、本底、效率等参数，确保数据可靠。因此，选项B正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 169 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0170","type":"single","qtype":"单选题","stem":"液体闪烁计数器需位于（ ）区域","options":[{"key":"A","text":"高温"},{"key":"B","text":"高湿"},{"key":"C","text":"避光"},{"key":"D","text":"通风"}],"answer":["C"],"explanation":"液体闪烁计数器需位于避光区域，因为其光电倍增管对光敏感，环境光会影响计数结果。高温、高湿、通风均不是其必需的环境条件。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n液体闪烁计数器用于低能β射线测量，需避光放置，防止环境光干扰光电倍增管，确保测量准确性。因此，选项C正确。\n\n---","source":{"file":"单选题/161-170.md","merged":"单选题1-400.md","location":"第 170 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0171","type":"single","qtype":"单选题","stem":"γ谱仪法鉴别核素时，能量误差允许范围是（ ）","options":[{"key":"A","text":"±5keV或±3%"},{"key":"B","text":"±10keV或±6%"},{"key":"C","text":"±15keV或±9%"},{"key":"D","text":"±20keV或±12%"}],"answer":["B"],"explanation":"γ谱仪法鉴别核素时，能量误差允许范围为±10keV或±6%。该误差范围是核素鉴别中判断测量能量与标准能量是否一致的可接受标准，确保鉴别结果准确可靠。其他选项误差范围过宽或过窄，不符合规定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\nγ谱仪法用于放射性核素鉴别，需使用多道γ谱仪测定特征γ射线能量。根据药品质量标准及放射性药品检验要求，能量误差允许范围为±10keV或±6%，以确保核素鉴别的准确性。因此，选项B正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 171 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0172","type":"single","qtype":"单选题","stem":"半衰期法鉴别需至少测（ ）个点","options":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}],"answer":["B"],"explanation":"半衰期法鉴别需至少测3个点，通过测量不同时间点的放射性活度，计算半衰期并与标准值比较，以鉴别核素。2个点不足以确认指数衰变规律，4个或5个点虽更精确但最低要求为3个。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n半衰期法鉴别核素时，需至少测量3个时间点的活度，绘制衰变曲线，计算半衰期。该方法依据放射性核素衰变规律，用于核素鉴别和质量控制。因此，选项B正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 172 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0173","type":"single","qtype":"单选题","stem":"放射性核纯度测定中，γ光子能量相近的核素需用（ ）探测器","options":[{"key":"A","text":"碘化钠"},{"key":"B","text":"高纯锗"},{"key":"C","text":"塑料"},{"key":"D","text":"闪烁"}],"answer":["B"],"explanation":"放射性核纯度测定中，当γ光子能量相近的核素共存时，需使用高纯锗（HPGe）探测器。高纯锗探测器能量分辨率高，能有效区分能量相近的γ射线。碘化钠、塑料、闪烁探测器分辨率较低，不适合此类测定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性核纯度测定需准确识别和定量杂质核素。高纯锗探测器具有优异的能量分辨率，可区分能量相近的γ射线，适用于复杂核素混合物的分析。因此，选项B正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 173 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0174","type":"single","qtype":"单选题","stem":"放射化学纯度测定中，展开容器应（ ）","options":[{"key":"A","text":"敞口"},{"key":"B","text":"密闭"},{"key":"C","text":"透明"},{"key":"D","text":"深色"}],"answer":["B"],"explanation":"放射化学纯度测定中，展开容器应密闭，以防止展开剂挥发和放射性气溶胶扩散，保证操作人员安全和测定结果稳定。敞口、透明、深色均不是核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射化学纯度测定常用纸色谱或薄层色谱法，展开容器需密闭，防止展开剂挥发和放射性污染扩散，确保色谱行为一致。因此，选项B正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 174 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0175","type":"single","qtype":"单选题","stem":"放射性活度测定时，读数波动需（ ）","options":[{"key":"A","text":"直接记录"},{"key":"B","text":"重复10次取平均"},{"key":"C","text":"随意选取"},{"key":"D","text":"无需记录"}],"answer":["B"],"explanation":"放射性活度测定时，读数波动需重复10次取平均，以减小统计涨落带来的误差，提高测量结果的准确性和可靠性。直接记录、随意选取、无需记录均不符合测量规范。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性活度测量受统计涨落影响，需多次测量取平均值，以降低不确定度，确保活度测定结果准确可靠。因此，选项B正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 175 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0176","type":"single","qtype":"单选题","stem":"生物分布实验动物需（ ）","options":[{"key":"A","text":"来源清楚，有合格证明"},{"key":"B","text":"随意选取"},{"key":"C","text":"自行捕捉"},{"key":"D","text":"无需证明"}],"answer":["A"],"explanation":"生物分布实验动物需来源清楚，有合格证明，以确保实验结果的可靠性和可追溯性，同时符合实验动物管理和伦理要求。随意选取、自行捕捉、无需证明均不符合规范。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生物分布实验用于评价放射性药品的体内行为，实验动物必须来源清楚，具有合格证明，并符合实验动物质量标准，确保实验数据可靠。因此，选项A正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 176 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0177","type":"single","qtype":"单选题","stem":"变更控制由（ ）负责","options":[{"key":"A","text":"生产部门"},{"key":"B","text":"销售部门"},{"key":"C","text":"质量管理部门"},{"key":"D","text":"采购部门"}],"answer":["C"],"explanation":"变更控制由质量管理部门负责，以确保变更经过评估、批准、实施和回顾，保证变更不影响产品质量和合规性。生产部门、销售部门、采购部门均不是变更控制的主管部门。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n变更控制是质量管理体系的核心要素，由质量管理部门负责组织评估、审批和跟踪，确保变更受控。因此，选项C正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 177 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0178","type":"single","qtype":"单选题","stem":"偏差处理需记录（ ）","options":[{"key":"A","text":"报告、调查、处理"},{"key":"B","text":"销售计划"},{"key":"C","text":"采购计划"},{"key":"D","text":"研发计划"}],"answer":["A"],"explanation":"偏差处理需记录报告、调查、处理等环节，以完整反映偏差的发现、原因分析、纠正措施和预防措施。销售计划、采购计划、研发计划均与偏差处理无关。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n偏差处理是质量管理体系的重要环节，需记录偏差报告、调查过程、根本原因分析、处理措施及效果评估，确保偏差得到有效控制。因此，选项A正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 178 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0179","type":"single","qtype":"单选题","stem":"纠正预防措施需针对（ ）","options":[{"key":"A","text":"仅投诉"},{"key":"B","text":"仅召回"},{"key":"C","text":"投诉、召回、偏差等"},{"key":"D","text":"仅偏差"}],"answer":["C"],"explanation":"纠正预防措施需针对投诉、召回、偏差等多种质量事件，以系统性地消除已发生问题的原因并预防潜在问题。仅针对投诉、仅召回、仅偏差均不全面。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n纠正预防措施（CAPA）是质量管理体系的核心工具，需针对投诉、召回、偏差、审计发现等多种来源，进行根本原因分析和系统性改进。因此，选项C正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 179 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0180","type":"single","qtype":"单选题","stem":"供应商审计需评估（ ）","options":[{"key":"A","text":"生产能力"},{"key":"B","text":"质量体系"},{"key":"C","text":"销售能力"},{"key":"D","text":"研发能力"}],"answer":["B"],"explanation":"供应商审计需评估质量体系，以确保供应商提供的物料或服务符合质量要求，并能持续稳定供应。生产能力、销售能力、研发能力均不是供应商审计的核心评估内容。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n供应商审计是质量管理体系的重要组成部分，需重点评估供应商的质量管理体系、生产能力、物料质量控制等，确保供应链质量可靠。因此，选项B正确。\n\n---","source":{"file":"单选题/171-180.md","merged":"单选题1-400.md","location":"第 180 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0181","type":"single","qtype":"单选题","stem":"产品质量回顾需（ ）一次","options":[{"key":"A","text":"一个月"},{"key":"B","text":"三个月"},{"key":"C","text":"半年"},{"key":"D","text":"一年"}],"answer":["D"],"explanation":"产品质量回顾需每年进行一次，以确认工艺稳定性和产品质量趋势，识别改进机会。一个月、三个月、半年均不符合年度回顾的要求。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n产品质量回顾是质量管理体系的重要组成部分，通常每年进行一次，评估工艺稳定性、物料质量、偏差、变更等，确保产品质量持续稳定。因此，选项D正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 181 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0182","type":"single","qtype":"单选题","stem":"药品不良反应需（ ）","options":[{"key":"A","text":"隐瞒"},{"key":"B","text":"及时上报"},{"key":"C","text":"仅内部记录"},{"key":"D","text":"无需处理"}],"answer":["B"],"explanation":"药品不良反应需及时上报，以便监管部门和使用单位采取风险控制措施，保障患者安全。隐瞒、仅内部记录、无需处理均违反药品不良反应监测和报告制度。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品管理法》和《药品不良反应报告和监测管理办法》，药品生产、经营企业和医疗机构发现药品不良反应应当及时报告。放射性药品同样适用该要求。因此，选项B正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 182 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0183","type":"single","qtype":"单选题","stem":"边检验边放行药品发现质量问题需（ ）","options":[{"key":"A","text":"继续使用"},{"key":"B","text":"通知使用单位停止使用"},{"key":"C","text":"降价处理"},{"key":"D","text":"自行销毁"}],"answer":["B"],"explanation":"边检验边放行药品发现质量问题需立即通知使用单位停止使用，并采取召回等风险控制措施，防止危害扩大。继续使用、降价处理、自行销毁均不符合规定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n边检验边放行是基于风险管理的放行方式，一旦发现质量问题，必须立即通知使用单位停止使用，并按规定进行召回和处置。因此，选项B正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 183 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0184","type":"single","qtype":"单选题","stem":"多道γ谱仪需配备（ ）减小本底","options":[{"key":"A","text":"加热装置"},{"key":"B","text":"冷却装置"},{"key":"C","text":"铅屏蔽室"},{"key":"D","text":"加湿装置"}],"answer":["C"],"explanation":"多道γ谱仪需配备铅屏蔽室以减小本底，降低环境辐射对测量的干扰，提高核素鉴别的准确性和灵敏度。加热、冷却、加湿装置均不能有效减小本底。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n多道γ谱仪用于放射性核素鉴别和核纯度测定，需在低本底环境下工作。铅屏蔽室可有效屏蔽环境γ射线，降低本底计数。因此，选项C正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 184 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0185","type":"single","qtype":"单选题","stem":"放射性活度计布局应远离（ ）","options":[{"key":"A","text":"普通仪器"},{"key":"B","text":"其他放射性测量仪器"},{"key":"C","text":"办公设备"},{"key":"D","text":"照明设备"}],"answer":["B"],"explanation":"放射性活度计布局应远离其他放射性测量仪器，以防止相互干扰和交叉污染，确保测量结果准确可靠。普通仪器、办公设备、照明设备均不是主要干扰源。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性活度计用于测量放射性活度，需避免其他放射源的干扰。布局时应远离其他放射性测量仪器，减少本底和交叉影响。因此，选项B正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 185 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0186","type":"single","qtype":"单选题","stem":"放射性样品前处理需（ ）","options":[{"key":"A","text":"分类分区操作"},{"key":"B","text":"混合操作"},{"key":"C","text":"随意操作"},{"key":"D","text":"快速操作"}],"answer":["A"],"explanation":"放射性样品前处理需分类分区操作，根据核素种类、活度水平等进行分区管理，防止交叉污染和混淆。混合操作、随意操作、快速操作均不符合放射性样品管理要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n放射性样品前处理同样需分类分区，确保不同核素和活度水平的样品不相互干扰，符合辐射防护和质量控制要求。因此，选项A正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 186 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0187","type":"single","qtype":"单选题","stem":"放射性废物需按（ ）分类收集","options":[{"key":"A","text":"颜色"},{"key":"B","text":"体积"},{"key":"C","text":"核素种类、半衰期等"},{"key":"D","text":"重量"}],"answer":["C"],"explanation":"放射性废物需按核素种类、半衰期等分类收集，以便采取不同的贮存和处置措施，确保辐射安全。颜色、体积、重量均不是分类收集的主要依据。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物分类收集需考虑核素种类、半衰期、活度等，短半衰期废物可衰变贮存，长半衰期废物需按规定处置。因此，选项C正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 187 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0188","type":"single","qtype":"单选题","stem":"质量回顾需确认（ ）","options":[{"key":"A","text":"工艺稳定性"},{"key":"B","text":"销售业绩"},{"key":"C","text":"采购成本"},{"key":"D","text":"研发进度"}],"answer":["A"],"explanation":"质量回顾需确认工艺稳定性，通过分析生产数据、检验结果、偏差、变更等，评估工艺是否持续稳定，产品质量是否可靠。销售业绩、采购成本、研发进度均不是质量回顾的核心内容。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n产品质量回顾旨在确认工艺稳定性和产品质量趋势，识别改进机会，确保质量体系持续有效。因此，选项A正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 188 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0189","type":"single","qtype":"单选题","stem":"变更需经（ ）批准","options":[{"key":"A","text":"生产负责人"},{"key":"B","text":"销售负责人"},{"key":"C","text":"授权人员"},{"key":"D","text":"采购负责人"}],"answer":["C"],"explanation":"变更需经授权人员批准，授权人员通常由质量管理部门指定，具备评估变更对产品质量和合规性影响的能力。生产负责人、销售负责人、采购负责人均不是变更批准的授权人员。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n变更控制是质量管理体系的核心，变更需经授权人员批准，确保变更经过评估、审核和批准，不影响产品质量。因此，选项C正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 189 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0190","type":"single","qtype":"单选题","stem":"偏差原因需（ ）","options":[{"key":"A","text":"简单分析"},{"key":"B","text":"彻底调查"},{"key":"C","text":"随意推断"},{"key":"D","text":"无需调查"}],"answer":["B"],"explanation":"偏差原因需彻底调查，以找到根本原因并采取有效的纠正预防措施，防止偏差再次发生。简单分析、随意推断、无需调查均不符合质量管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n偏差处理需进行彻底调查，包括根本原因分析、影响评估和纠正预防措施，确保偏差得到有效控制。因此，选项B正确。\n\n---","source":{"file":"单选题/181-190.md","merged":"单选题1-400.md","location":"第 190 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0191","type":"single","qtype":"单选题","stem":"辐射防护设备需（ ）验证","options":[{"key":"A","text":"不定期"},{"key":"B","text":"定期"},{"key":"C","text":"仅安装时"},{"key":"D","text":"仅维修后"}],"answer":["B"],"explanation":"辐射防护设备需定期验证，以确保其屏蔽性能、密封性和防护效果持续符合要求，保障人员安全和辐射防护有效性。不定期、仅安装时、仅维修后均不能保证设备始终处于良好防护状态。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射防护设备属于安全防护设施，需定期检查、维护和验证，确保其防护性能符合国家辐射防护标准。因此，选项B正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 191 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0192","type":"single","qtype":"单选题","stem":"无菌工艺模拟试验需符合（ ）附录要求","options":[{"key":"A","text":"放射性药品"},{"key":"B","text":"无菌药品"},{"key":"C","text":"计算机系统"},{"key":"D","text":"确认与验证"}],"answer":["B"],"explanation":"无菌工艺模拟试验需符合无菌药品附录要求，因为该试验用于验证无菌生产工艺的可靠性，是无菌药品生产的关键验证活动。放射性药品附录、计算机系统附录、确认与验证附录均不是其直接依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性药品中无菌制剂的生产需遵循《药品生产质量管理规范（2010年版）》无菌药品附录，定期进行无菌工艺模拟试验，确保无菌保证水平。因此，选项B正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 192 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0193","type":"single","qtype":"单选题","stem":"制药用水需定期（ ）","options":[{"key":"A","text":"清洁"},{"key":"B","text":"灭菌"},{"key":"C","text":"检验"},{"key":"D","text":"更换"}],"answer":["C"],"explanation":"制药用水需定期检验，以确保其质量符合《中国药典》标准，包括电导率、微生物限度、细菌内毒素等指标。清洁、灭菌、更换均不能替代定期检验。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n制药用水是药品生产的关键物料，需定期检验，确保符合《中国药典》纯化水、注射用水等标准，保证药品质量。因此，选项C正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 193 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0194","type":"single","qtype":"单选题","stem":"外购灭菌注射用水需（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"供应商审计"},{"key":"C","text":"随意采购"},{"key":"D","text":"无需检查"}],"answer":["B"],"explanation":"外购灭菌注射用水需进行供应商审计，确认供应商资质、质量体系和运输条件，确保其质量符合要求。直接使用、随意采购、无需检查均不符合质量管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n外购灭菌注射用水属于关键物料，需对供应商进行审计，确认其生产资质、质量标准和运输条件，确保物料质量可靠。因此，选项B正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 194 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0195","type":"single","qtype":"单选题","stem":"计算机化系统需（ ）验证","options":[{"key":"A","text":"不定期"},{"key":"B","text":"定期"},{"key":"C","text":"仅安装时"},{"key":"D","text":"仅维修后"}],"answer":["B"],"explanation":"计算机化系统需定期验证，以确保其数据可靠性、控制功能准确性和安全性持续符合要求。不定期、仅安装时、仅维修后均不能保证系统持续合规。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n计算机化系统用于放射性药品生产和质量控制，需定期验证，确保数据完整、可靠，符合药品GMP计算机化系统附录要求。因此，选项B正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 195 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0196","type":"single","qtype":"单选题","stem":"放射性药品追溯系统需能（ ）","options":[{"key":"A","text":"追踪销售"},{"key":"B","text":"追踪质量安全事件"},{"key":"C","text":"追踪采购"},{"key":"D","text":"追踪研发"}],"answer":["B"],"explanation":"放射性药品追溯系统需能追踪质量安全事件，以便及时发现和控制质量问题，提供临床信息，保障患者安全。追踪销售、采购、研发均不是追溯系统的核心目的。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性药品追溯系统应能追踪生产、检验、放行、发运、使用环节，重点在于及时发现和控制质量安全不良事件，提供临床信息。因此，选项B正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 196 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0197","type":"single","qtype":"单选题","stem":"检验数据需（ ）","options":[{"key":"A","text":"随意记录"},{"key":"B","text":"定期备份"},{"key":"C","text":"无需备份"},{"key":"D","text":"口头传递"}],"answer":["B"],"explanation":"检验数据需定期备份，以防止数据丢失，确保数据完整性和可追溯性，符合数据可靠性要求。随意记录、无需备份、口头传递均违反药品数据管理规范。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验数据属于药品质量记录，需真实、准确、完整、可追溯，并定期备份，防止丢失或损坏。因此，选项B正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 197 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0198","type":"single","qtype":"单选题","stem":"检验人员需经（ ）考核合格上岗","options":[{"key":"A","text":"辐射安全培训"},{"key":"B","text":"岗位培训"},{"key":"C","text":"销售培训"},{"key":"D","text":"采购培训"}],"answer":["B"],"explanation":"检验人员需经岗位培训考核合格后上岗，以确保其具备检验操作技能和专业知识。辐射安全培训是必要内容之一，但岗位培训是更全面的上岗考核要求。销售培训、采购培训与检验岗位无关。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验人员需接受岗位培训，包括检验方法、仪器操作、辐射防护等，考核合格后方可上岗。因此，选项B正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 198 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0199","type":"single","qtype":"单选题","stem":"微生物实验室需符合（ ）要求","options":[{"key":"A","text":"洁净度和生物安全等级"},{"key":"B","text":"仅洁净度"},{"key":"C","text":"仅生物安全"},{"key":"D","text":"无要求"}],"answer":["A"],"explanation":"微生物实验室需符合洁净度和生物安全等级要求，以确保检验结果准确并保障操作人员安全。仅洁净度、仅生物安全、无要求均不全面。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n微生物实验室需根据操作对象的生物危害等级和洁净度要求进行设计和管理，符合《中国药典》和生物安全相关标准。因此，选项A正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 199 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0200","type":"single","qtype":"单选题","stem":"质量保证体系需涵盖（ ）","options":[{"key":"A","text":"仅生产"},{"key":"B","text":"仅检验"},{"key":"C","text":"生产、检验、放行等全过程"},{"key":"D","text":"仅销售"}],"answer":["C"],"explanation":"质量保证体系需涵盖生产、检验、放行等全过程，确保药品从原料到成品的所有环节均受控，质量安全可靠。仅生产、仅检验、仅销售均不全面。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量保证体系应覆盖药品生产、检验、放行、储存、运输等全过程，确保各环节符合法规和质量标准，保障药品安全有效。因此，选项C正确。\n\n---","source":{"file":"单选题/191-200.md","merged":"单选题1-400.md","location":"第 200 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0201","type":"single","qtype":"单选题","stem":"《放射性药品》附录中适用的放射性药品不包括（ ）","options":[{"key":"A","text":"医用放射性核素发生器及其配套药盒"},{"key":"B","text":"正电子类放射性药品"},{"key":"C","text":"普通化学药品"},{"key":"D","text":"放射性体内植入制品"}],"answer":["C"],"explanation":"《放射性药品》附录适用于医用放射性核素发生器及其配套药盒、正电子类放射性药品、放射性体内植入制品等放射性药品。普通化学药品不含有放射性核素，不属于放射性药品，因此不适用该附录。选项A、B、D均属于附录适用对象。因此，选项C正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n该定义明确了放射性药品的核心特征是含有放射性核素。医用放射性核素发生器及其配套药盒、正电子类放射性药品、放射性体内植入制品均属于“放射性核素制剂或者其标记药物”的范畴，而普通化学药品不含有放射性核素，不属于放射性药品，因此不适用《放射性药品》附录。选项C正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 201 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0202","type":"single","qtype":"单选题","stem":"放射性药品的生产管理中，涉及特殊要求时，优先遵循（ ）","options":[{"key":"A","text":"药品GMP（2010年修订）通用要求"},{"key":"B","text":"本附录规定"},{"key":"C","text":"企业内部制度"},{"key":"D","text":"行业惯例"}],"answer":["B"],"explanation":"放射性药品的生产管理中，当涉及特殊要求时，应优先遵循《放射性药品》附录的规定。该附录针对放射性药品的辐射防护、核素衰变、即时标记等特点制定了特殊要求，优先于药品GMP通用要求。企业内部制度和行业惯例不能替代法规要求。因此，选项B正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第一条规定：为了加强放射性药品的管理，根据《中华人民共和国药品管理法》的规定，制定本办法。\n《放射性药品》附录是依据《放射性药品管理办法》及药品GMP制定的专项技术要求，针对放射性药品的特殊性作出补充规定。当通用要求与附录规定不一致时，应优先遵循附录的特殊要求。因此，选项B正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 202 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0203","type":"single","qtype":"单选题","stem":"可申请“边检验边放行”的放射性药品需满足（ ）","options":[{"key":"A","text":"任意放射性药品均可"},{"key":"B","text":"产品有效期或所含核素半衰期＜30天，且经质管部风险评估"},{"key":"C","text":"仅正电子类药品"},{"key":"D","text":"仅即时标记药品"}],"answer":["B"],"explanation":"可申请“边检验边放行”的放射性药品需满足产品有效期或所含核素半衰期＜30天，且经质量管理部门风险评估。这是因为短半衰期药品有效期极短，全检完成后可能已无法使用，因此允许边检验边放行。任意放射性药品、仅正电子类、仅即时标记均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n对于有效期或核素半衰期＜30天的放射性药品，因衰变迅速，全检合格后可能已过有效期。经质量管理部门风险评估，可实施边检验边放行，但需确保放行后完成剩余检验。因此，选项B正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 203 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0204","type":"single","qtype":"单选题","stem":"边检验边放行的放射性药品，需由哪个部门进行风险评估（ ）","options":[{"key":"A","text":"生产部门"},{"key":"B","text":"质量管理部门"},{"key":"C","text":"销售部门"},{"key":"D","text":"采购部门"}],"answer":["B"],"explanation":"边检验边放行的放射性药品，需由质量管理部门进行风险评估，评估生产过程及关键参数风险，确保放行决策科学合理。生产部门、销售部门、采购部门均不具备质量风险评估的职责和权威。因此，选项B正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量管理部门负责药品全生命周期的质量管理和风险评估，边检验边放行的风险评估必须由质量管理部门完成，确保风险可控。因此，选项B正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 204 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0205","type":"single","qtype":"单选题","stem":"本附录中，放射性药品的哪项管理环节不特别强调辐射安全要求（ ）","options":[{"key":"A","text":"生产"},{"key":"B","text":"储存"},{"key":"C","text":"研发"},{"key":"D","text":"运输"}],"answer":["C"],"explanation":"本附录中，放射性药品的生产、储存、运输等环节均特别强调辐射安全要求，而研发环节虽然也涉及辐射安全，但相对而言不是附录重点强调的管理环节。因此，选项C正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第三条规定：凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n该办法对生产、经营、运输、使用、检验等环节均规定了辐射安全要求，研发环节虽需遵守辐射防护规定，但《放射性药品》附录主要针对生产、储存、运输等环节的辐射安全作出详细规定。因此，选项C正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 205 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0206","type":"single","qtype":"单选题","stem":"下列属于本附录适用的“其他反应堆和加速器放射性药品”的是（ ）","options":[{"key":"A","text":"尿素[14C]胶囊"},{"key":"B","text":"氯化锶[89Sr]注射液"},{"key":"C","text":"普通抗生素注射液"},{"key":"D","text":"维生素片"}],"answer":["B"],"explanation":"氯化锶[89Sr]注射液属于反应堆制备的放射性药品，是本附录适用的“其他反应堆和加速器放射性药品”。尿素[14C]胶囊属于呼气试验药盒，普通抗生素注射液和维生素片不属于放射性药品。因此，选项B正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n氯化锶[89Sr]注射液含有放射性核素锶[89Sr]，通常由反应堆制备，用于治疗骨转移癌疼痛，属于本附录适用的反应堆放射性药品。尿素[14C]胶囊虽为放射性药品，但归类不同。因此，选项B正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 206 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0207","type":"single","qtype":"单选题","stem":"放射性药品的管理中，当《放射性药品》附录与药品GMP（2010年修订）通用要求冲突时（ ）","options":[{"key":"A","text":"以通用要求为准"},{"key":"B","text":"以本附录为准"},{"key":"C","text":"企业自行选择"},{"key":"D","text":"报监管部门裁定"}],"answer":["B"],"explanation":"当《放射性药品》附录与药品GMP（2010年修订）通用要求冲突时，应以本附录为准。因为附录是针对放射性药品特殊性的补充规定，优先于通用要求。企业自行选择或报监管部门裁定均不符合规定。因此，选项B正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第一条规定：为了加强放射性药品的管理，根据《中华人民共和国药品管理法》的规定，制定本办法。\n《放射性药品》附录是依据《放射性药品管理办法》制定的专项技术要求，针对放射性药品的辐射防护、核素衰变等特殊性作出规定。当与通用要求冲突时，特殊规定优先。因此，选项B正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 207 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0208","type":"single","qtype":"单选题","stem":"对“边检验边放行”的放射性药品，核心管控措施是（ ）","options":[{"key":"A","text":"省略部分检验项目"},{"key":"B","text":"简化审批流程"},{"key":"C","text":"质量管理部门评估生产过程及关键参数风险"},{"key":"D","text":"缩短检验时间"}],"answer":["C"],"explanation":"对“边检验边放行”的放射性药品，核心管控措施是质量管理部门评估生产过程及关键参数风险，确保放行决策基于科学的风险评估。省略检验项目、简化审批、缩短检验时间均不是核心管控措施。因此，选项C正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n边检验边放行的核心在于质量管理部门对生产过程及关键参数进行风险评估，确认风险可控后方可放行，确保药品安全有效。因此，选项C正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 208 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0209","type":"single","qtype":"单选题","stem":"某放射性药品核素半衰期为25天，其是否可申请边检验边放行（ ）","options":[{"key":"A","text":"可，直接放行"},{"key":"B","text":"可，经质管部风险评估后"},{"key":"C","text":"不可，半衰期需＜15天"},{"key":"D","text":"不可，需全检合格后放行"}],"answer":["B"],"explanation":"该放射性药品核素半衰期为25天，小于30天，符合边检验边放行的条件，但需经质量管理部门风险评估后方可实施。直接放行、半衰期需＜15天、需全检合格后放行均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n边检验边放行的条件是产品有效期或所含核素半衰期＜30天，且经质量管理部门风险评估。25天＜30天，满足条件，但需风险评估。因此，选项B正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 209 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0210","type":"single","qtype":"单选题","stem":"《放射性药品》附录所称“即时标记放射性药品”的核心特征是（ ）","options":[{"key":"A","text":"生产时提前标记"},{"key":"B","text":"使用前用发生器洗脱液+配套药盒制备"},{"key":"C","text":"无需辐射防护"},{"key":"D","text":"仅用于治疗"}],"answer":["B"],"explanation":"《放射性药品》附录所称“即时标记放射性药品”的核心特征是使用前用发生器洗脱液+配套药盒制备。其特点是不提前完成标记，而是在临床使用前即时制备，以保证放射化学纯度和活度。生产时提前标记、无需辐射防护、仅用于治疗均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n即时标记放射性药品属于放射性核素标记药物的一种特殊形式，其制备过程为：使用前用发生器洗脱液（如高锝[99mTc]酸钠注射液）加入配套药盒，经还原和标记反应生成锝[99mTc]标记药物。这种模式可缩短从标记到使用的时间，减少衰变和辐射分解。因此，选项B正确。\n\n---","source":{"file":"单选题/201-210.md","merged":"单选题1-400.md","location":"第 210 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0211","type":"single","qtype":"单选题","stem":"放射性药品生产企业设置的机构需与（ ）相适应","options":[{"key":"A","text":"企业规模"},{"key":"B","text":"放射性药品特性及辐射安全"},{"key":"C","text":"销售需求"},{"key":"D","text":"采购需求"}],"answer":["B"],"explanation":"放射性药品生产企业设置的机构需与放射性药品特性及辐射安全相适应，确保生产、质量、辐射防护等职能有效运行。企业规模、销售需求、采购需求均不能作为机构设置的核心依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n该条款要求企业机构设置必须与放射性药品的特殊性（放射性、辐射安全风险）相匹配，设立相应的生产、质量、辐射防护等管理部门。因此，选项B正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 211 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0212","type":"single","qtype":"单选题","stem":"放射性药品生产管理负责人、质量管理负责人及质量受权人需具备（ ）","options":[{"key":"A","text":"仅药品相关专业知识"},{"key":"B","text":"核医（药）学或相关专业知识及工作经验"},{"key":"C","text":"仅辐射防护知识"},{"key":"D","text":"仅管理经验"}],"answer":["B"],"explanation":"放射性药品生产管理负责人、质量管理负责人及质量受权人需具备核医（药）学或相关专业知识及工作经验，同时符合药品GMP人员资质要求。仅药品知识、仅辐射防护知识、仅管理经验均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n关键岗位人员需具备核医学、药学或相关专业背景，并具有放射性药品生产或质量管理经验，熟悉辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 212 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0213","type":"single","qtype":"单选题","stem":"放射性药品企业各岗位人员的培训内容应包括（ ）","options":[{"key":"A","text":"仅专业知识"},{"key":"B","text":"仅辐射防护知识"},{"key":"C","text":"专业知识+辐射防护知识"},{"key":"D","text":"仅操作技能"}],"answer":["C"],"explanation":"放射性药品企业各岗位人员的培训内容应包括专业知识和辐射防护知识，确保人员具备岗位所需技能和安全意识。仅专业知识、仅辐射防护知识、仅操作技能均不完整。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n人员培训需覆盖药品GMP、放射性药品专业知识、辐射防护、操作规程等内容，考核合格后方可上岗。因此，选项C正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 213 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0214","type":"single","qtype":"单选题","stem":"下列哪项不符合放射性药品生产管理负责人的资质要求（ ）","options":[{"key":"A","text":"符合药品GMP（2010年版）人员资质"},{"key":"B","text":"具有核医学专业背景"},{"key":"C","text":"无放射性药品相关工作经验"},{"key":"D","text":"熟悉辐射防护要求"}],"answer":["C"],"explanation":"放射性药品生产管理负责人需具有放射性药品相关工作经验，因此“无放射性药品相关工作经验”不符合资质要求。符合GMP人员资质、具有核医学专业背景、熟悉辐射防护要求均符合要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产管理负责人需具备放射性药品生产或质量管理经验，熟悉辐射防护，无相关经验者不符合岗位要求。因此，选项C正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 214 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0215","type":"single","qtype":"单选题","stem":"企业需确保质量受权人能够在质量管理中履行职责，其关键能力不包括（ ）","options":[{"key":"A","text":"核医（药）学知识"},{"key":"B","text":"辐射安全管理能力"},{"key":"C","text":"普通药品销售经验"},{"key":"D","text":"放射性药品质量控制经验"}],"answer":["C"],"explanation":"质量受权人的关键能力包括核医（药）学知识、辐射安全管理能力、放射性药品质量控制经验，但不包括普通药品销售经验。销售经验与质量管理职责无关。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量受权人需具备放射性药品质量控制和辐射安全管理的专业能力，确保产品放行符合要求。因此，选项C正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 215 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0216","type":"single","qtype":"单选题","stem":"放射性药品生产企业人员培训的核心目的是（ ）","options":[{"key":"A","text":"满足监管检查"},{"key":"B","text":"确保人员具备岗位所需专业及防护能力"},{"key":"C","text":"提升企业形象"},{"key":"D","text":"降低生产成本"}],"answer":["B"],"explanation":"放射性药品生产企业人员培训的核心目的是确保人员具备岗位所需的专业能力和辐射防护能力，保障药品质量和人员安全。满足监管检查、提升企业形象、降低生产成本均不是核心目的。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n培训旨在使人员掌握放射性药品生产、质量控制及辐射防护的知识和技能，确保岗位胜任。因此，选项B正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 216 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0217","type":"single","qtype":"单选题","stem":"新入职的放射性药品检验人员，首要培训内容是（ ）","options":[{"key":"A","text":"销售技巧"},{"key":"B","text":"检验方法+辐射防护措施"},{"key":"C","text":"采购流程"},{"key":"D","text":"生产工艺"}],"answer":["B"],"explanation":"新入职的放射性药品检验人员首要培训内容是检验方法和辐射防护措施，以确保其能够安全、准确地进行检验操作。销售技巧、采购流程、生产工艺均不是检验人员的首要培训内容。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验人员需首先掌握放射性药品检验方法和辐射防护措施，考核合格后方可上岗。因此，选项B正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 217 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0218","type":"single","qtype":"单选题","stem":"放射性药品质量管理负责人需能够判断（ ）","options":[{"key":"A","text":"仅普通药品质量风险"},{"key":"B","text":"放射性药品质量及辐射安全风险"},{"key":"C","text":"仅原材料价格"},{"key":"D","text":"仅成品销售渠道"}],"answer":["B"],"explanation":"放射性药品质量管理负责人需能够判断放射性药品质量及辐射安全风险，确保质量管理体系有效运行。仅普通药品质量风险、仅原材料价格、仅成品销售渠道均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量管理负责人需具备评估放射性药品质量和辐射安全风险的能力，确保产品安全有效。因此，选项B正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 218 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0219","type":"single","qtype":"单选题","stem":"企业机构设置中，需明确哪个部门的辐射安全管理职责（ ）","options":[{"key":"A","text":"仅生产部门"},{"key":"B","text":"仅质量部门"},{"key":"C","text":"各相关部门（生产、质量、检验等）"},{"key":"D","text":"仅行政部门"}],"answer":["C"],"explanation":"企业机构设置中，需明确各相关部门（生产、质量、检验等）的辐射安全管理职责，确保辐射防护责任落实到岗。仅生产部门、仅质量部门、仅行政部门均不全面。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射安全管理涉及生产、质量、检验等多个环节，需明确各部门职责，形成完整的辐射防护管理体系。因此，选项C正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 219 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0220","type":"single","qtype":"单选题","stem":"放射性药品生产企业的技术人员需掌握的核心技能不包括（ ）","options":[{"key":"A","text":"放射性药品制备工艺"},{"key":"B","text":"辐射剂量监测方法"},{"key":"C","text":"普通食品加工技术"},{"key":"D","text":"放射性污染去污方法"}],"answer":["C"],"explanation":"放射性药品生产企业的技术人员需掌握放射性药品制备工艺、辐射剂量监测方法、放射性污染去污方法等核心技能，但不包括普通食品加工技术。普通食品加工技术与放射性药品生产无关。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n技术人员需具备放射性药品生产、辐射防护和污染控制等专业能力，普通食品加工技术不属于其岗位技能。因此，选项C正确。\n\n---","source":{"file":"单选题/211-220.md","merged":"单选题1-400.md","location":"第 220 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0221","type":"single","qtype":"单选题","stem":"生产管理负责人需审核放射性药品的（ ）","options":[{"key":"A","text":"仅生产计划"},{"key":"B","text":"生产工艺及辐射防护措施落实情况"},{"key":"C","text":"仅销售合同"},{"key":"D","text":"仅采购清单"}],"answer":["B"],"explanation":"生产管理负责人需审核放射性药品的生产工艺及辐射防护措施落实情况，确保生产过程符合工艺规程和辐射安全要求。仅生产计划、仅销售合同、仅采购清单均不是生产管理负责人的核心审核职责。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产管理负责人需对生产工艺执行情况和辐射防护措施落实情况进行审核，确保生产活动安全合规。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 221 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0222","type":"single","qtype":"单选题","stem":"质量受权人在放射性药品放行时，需重点确认（ ）","options":[{"key":"A","text":"仅检验结果"},{"key":"B","text":"检验结果+辐射安全合规性"},{"key":"C","text":"仅生产记录"},{"key":"D","text":"仅销售需求"}],"answer":["B"],"explanation":"质量受权人在放射性药品放行时，需重点确认检验结果和辐射安全合规性，确保产品符合质量标准和辐射防护要求。仅检验结果、仅生产记录、仅销售需求均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量受权人负责产品放行，需确认检验合格且辐射安全合规，确保药品安全有效。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 222 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0223","type":"single","qtype":"单选题","stem":"企业对辐射防护培训不合格的人员应（ ）","options":[{"key":"A","text":"允许上岗但需带教"},{"key":"B","text":"禁止上岗，重新培训考核"},{"key":"C","text":"安排至非放射性岗位"},{"key":"D","text":"仅口头警告"}],"answer":["B"],"explanation":"企业对辐射防护培训不合格的人员应禁止上岗，重新培训考核，合格后方可从事放射性工作。允许上岗带教、安排至非放射性岗位、仅口头警告均不符合辐射安全管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射防护培训不合格者不得上岗，必须重新培训并考核合格，确保其具备辐射安全意识和操作能力。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 223 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0224","type":"single","qtype":"单选题","stem":"放射性药品企业人员的辐射防护培训需（ ）","options":[{"key":"A","text":"仅入职时进行"},{"key":"B","text":"定期进行，持续更新"},{"key":"C","text":"仅每年一次"},{"key":"D","text":"无需定期开展"}],"answer":["B"],"explanation":"放射性药品企业人员的辐射防护培训需定期进行，持续更新，以保持人员的辐射安全意识和防护能力。仅入职时、仅每年一次、无需定期开展均不符合持续培训要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射防护培训应定期开展，内容持续更新，确保人员掌握最新法规和防护技术。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 224 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0225","type":"single","qtype":"单选题","stem":"下列哪项属于放射性药品企业人员的必备知识（ ）","options":[{"key":"A","text":"化妆品生产工艺"},{"key":"B","text":"放射性核素衰变规律"},{"key":"C","text":"汽车维修技术"},{"key":"D","text":"建筑设计规范"}],"answer":["B"],"explanation":"放射性药品企业人员的必备知识包括放射性核素衰变规律，这是理解放射性药品特性、半衰期和辐射防护的基础。化妆品生产工艺、汽车维修技术、建筑设计规范均与放射性药品无关。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n掌握放射性核素衰变规律是从事放射性药品生产、质量控制的基本要求，有助于正确评估药品活度和辐射风险。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 225 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0226","type":"single","qtype":"单选题","stem":"生产管理负责人需具备的工作经验不包括（ ）","options":[{"key":"A","text":"放射性药品生产管理"},{"key":"B","text":"普通药品研发"},{"key":"C","text":"辐射安全管理"},{"key":"D","text":"放射性药品质量控制"}],"answer":["B"],"explanation":"生产管理负责人需具备放射性药品生产管理、辐射安全管理、放射性药品质量控制等工作经验，但不包括普通药品研发经验。普通药品研发与放射性药品生产管理岗位无直接关联。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产管理负责人需熟悉放射性药品生产工艺、辐射防护和质量控制，普通药品研发经验不是其必备条件。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 226 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0227","type":"single","qtype":"单选题","stem":"质量管理负责人需参与制定（ ）","options":[{"key":"A","text":"仅普通药品质量标准"},{"key":"B","text":"放射性药品质量标准及辐射安全管理制度"},{"key":"C","text":"仅员工考勤制度"},{"key":"D","text":"仅采购管理制度"}],"answer":["B"],"explanation":"质量管理负责人需参与制定放射性药品质量标准及辐射安全管理制度，确保质量管理和辐射防护有章可循。仅普通药品质量标准、仅员工考勤制度、仅采购管理制度均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量管理负责人应参与制定放射性药品质量标准和辐射安全管理制度，确保体系完整有效。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 227 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0228","type":"single","qtype":"单选题","stem":"新员工入职放射性药品生产岗位，需经过的培训流程是（ ）","options":[{"key":"A","text":"专业知识培训→辐射防护培训→考核合格→上岗"},{"key":"B","text":"直接上岗→边干边学"},{"key":"C","text":"仅辐射防护培训→上岗"},{"key":"D","text":"仅专业知识培训→上岗"}],"answer":["A"],"explanation":"新员工入职放射性药品生产岗位，需经过专业知识培训、辐射防护培训、考核合格后方可上岗。直接上岗、仅辐射防护培训、仅专业知识培训均不符合培训要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n新员工必须接受完整的专业知识培训和辐射防护培训，考核合格后才能上岗。因此，选项A正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 228 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0229","type":"single","qtype":"单选题","stem":"放射性药品企业中，负责组织辐射防护培训的部门通常是（ ）","options":[{"key":"A","text":"人力资源部"},{"key":"B","text":"质量管理部或安全管理部门"},{"key":"C","text":"生产部"},{"key":"D","text":"销售部"}],"answer":["B"],"explanation":"放射性药品企业中，负责组织辐射防护培训的部门通常是质量管理部或安全管理部门，因其具备辐射安全管理的专业职责。人力资源部、生产部、销售部均不是组织辐射防护培训的主要部门。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射防护培训通常由质量管理部或安全管理部门组织，确保培训内容专业、合规。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 229 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0230","type":"single","qtype":"单选题","stem":"质量受权人需对放射性药品的（ ）负责","options":[{"key":"A","text":"仅生产过程"},{"key":"B","text":"全生命周期质量及辐射安全合规性"},{"key":"C","text":"仅检验过程"},{"key":"D","text":"仅运输过程"}],"answer":["B"],"explanation":"质量受权人需对放射性药品的全生命周期质量及辐射安全合规性负责，确保产品从生产到放行各环节符合法规要求。仅生产过程、仅检验过程、仅运输过程均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量受权人负责产品放行，需对全生命周期质量和辐射安全合规性进行审核，确保药品安全有效。因此，选项B正确。\n\n---","source":{"file":"单选题/221-230.md","merged":"单选题1-400.md","location":"第 230 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0231","type":"single","qtype":"单选题","stem":"放射性药品生产厂房布局的核心原则是（ ）","options":[{"key":"A","text":"美观大方"},{"key":"B","text":"符合生产工艺及辐射安全要求"},{"key":"C","text":"节省空间"},{"key":"D","text":"便于参观"}],"answer":["B"],"explanation":"放射性药品生产厂房布局的核心原则是符合生产工艺及辐射安全要求，确保生产流程顺畅、辐射防护有效、污染控制到位。美观大方、节省空间、便于参观均不是核心原则。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n厂房布局需满足生产工艺流程和辐射安全要求，合理分区，防止交叉污染和辐射危害。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 231 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0232","type":"single","qtype":"单选题","stem":"放射性药品生产厂房需取得的行政许可文件是（ ）","options":[{"key":"A","text":"仅药品生产许可证"},{"key":"B","text":"辐射安全许可证明文件"},{"key":"C","text":"仅营业执照"},{"key":"D","text":"仅环保备案"}],"answer":["B"],"explanation":"放射性药品生产厂房除需取得《药品生产许可证》外，还必须取得辐射安全许可证明文件，因为生产涉及放射性同位素与射线装置。仅药品生产许可证、仅营业执照、仅环保备案均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产放射性药品必须取得《辐射安全许可证》。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 232 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0233","type":"single","qtype":"单选题","stem":"放射性工作区与非放射性工作区的隔离措施不包括（ ）","options":[{"key":"A","text":"物理隔断"},{"key":"B","text":"压差控制"},{"key":"C","text":"共用通道"},{"key":"D","text":"独立出入口"}],"answer":["C"],"explanation":"放射性工作区与非放射性工作区的隔离措施包括物理隔断、压差控制、独立出入口等，但不包括共用通道。共用通道会增加交叉污染和辐射扩散风险，不符合隔离要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作区与非放射性工作区应有效隔离，禁止共用通道，防止放射性污染扩散。因此，选项C正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 233 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0234","type":"single","qtype":"单选题","stem":"不同放射性核素的生产操作区需（ ）","options":[{"key":"A","text":"合并设置以节省空间"},{"key":"B","text":"严格分开，防止混淆"},{"key":"C","text":"就近设置便于管理"},{"key":"D","text":"随意布局"}],"answer":["B"],"explanation":"不同放射性核素的生产操作区需严格分开，防止核素之间的交叉污染和混淆，确保产品核纯度和放射化学纯度。合并设置、就近设置、随意布局均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同核素操作区严格分开，是防止交叉污染和混淆的基本要求。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 234 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0235","type":"single","qtype":"单选题","stem":"无菌放射性药品生产操作应在（ ）","options":[{"key":"A","text":"普通车间"},{"key":"B","text":"专门区域，具备辐射防护及洁净度要求"},{"key":"C","text":"开放环境"},{"key":"D","text":"仅辐射防护区域"}],"answer":["B"],"explanation":"无菌放射性药品生产操作应在专门区域进行，该区域需同时具备辐射防护和洁净度要求，确保产品无菌且操作安全。普通车间、开放环境、仅辐射防护区域均不能同时满足要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌放射性药品生产需在符合洁净级别和辐射防护要求的专门区域进行。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 235 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0236","type":"single","qtype":"单选题","stem":"操作挥发性放射性核素需配备的专用设施是（ ）","options":[{"key":"A","text":"普通通风橱"},{"key":"B","text":"具备有效去污处理的排风设施"},{"key":"C","text":"开放式工作台"},{"key":"D","text":"仅防护衣"}],"answer":["B"],"explanation":"操作挥发性放射性核素需配备具备有效去污处理的排风设施，如高效过滤、活性炭吸附等，防止放射性物质排放到环境中。普通通风橱、开放式工作台、仅防护衣均不能满足要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n挥发性放射性核素操作需在手套箱或专用通风橱中进行，排风需经去污处理。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 236 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0237","type":"single","qtype":"单选题","stem":"即时标记放射性药品生产中使用的单向流工作台可（ ）","options":[{"key":"A","text":"仅负压操作"},{"key":"B","text":"正压操作"},{"key":"C","text":"无压力要求"},{"key":"D","text":"仅自然通风"}],"answer":["B"],"explanation":"即时标记放射性药品生产中使用的单向流工作台可正压操作，以保护药品免受环境污染，确保无菌操作。仅负压、无压力要求、仅自然通风均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n单向流工作台通过正压和单向流保护产品，防止微生物和微粒污染。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 237 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0238","type":"single","qtype":"单选题","stem":"无菌放射性药品操作区的周围环境应保持（ ）","options":[{"key":"A","text":"相对负压"},{"key":"B","text":"相对正压"},{"key":"C","text":"常压"},{"key":"D","text":"无压力要求"}],"answer":["B"],"explanation":"无菌放射性药品操作区的周围环境应保持相对正压，以防止外部污染进入洁净区，确保无菌操作环境。相对负压、常压、无压力要求均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌操作区需保持相对正压，维持洁净度，防止外部污染。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 238 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0239","type":"single","qtype":"单选题","stem":"放射性洁净区的空气一般（ ）","options":[{"key":"A","text":"可直接循环使用"},{"key":"B","text":"不可循环使用，除非有充分风险评估依据"},{"key":"C","text":"必须循环使用"},{"key":"D","text":"仅部分循环"}],"answer":["B"],"explanation":"放射性洁净区的空气一般不可循环使用，除非有充分的风险评估依据证明循环使用不会导致污染积累和交叉污染。直接循环、必须循环、仅部分循环均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性洁净区空气通常经高效过滤后排放，不宜循环使用，除非经风险评估确认安全。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 239 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0240","type":"single","qtype":"单选题","stem":"下列哪种情况的空气可循环使用（ ）","options":[{"key":"A","text":"非放射性洁净区"},{"key":"B","text":"即时标记药品洁净区"},{"key":"C","text":"所有放射性洁净区"},{"key":"D","text":"挥发性放射性核素操作区"}],"answer":["B"],"explanation":"即时标记药品洁净区的空气可循环使用，因其通常使用短半衰期核素，放射性污染风险较低，经风险评估确认后可循环。非放射性洁净区、所有放射性洁净区、挥发性放射性核素操作区均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n即时标记药品洁净区空气循环使用需经风险评估，确认无污染风险。因此，选项B正确。\n\n---","source":{"file":"单选题/231-240.md","merged":"单选题1-400.md","location":"第 240 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0241","type":"single","qtype":"单选题","stem":"放射性核素工作场所的地面和工作台需满足（ ）","options":[{"key":"A","text":"美观耐磨"},{"key":"B","text":"便于去污"},{"key":"C","text":"仅防水"},{"key":"D","text":"仅防火"}],"answer":["B"],"explanation":"放射性核素工作场所的地面和工作台需满足便于去污的要求，以防止放射性物质残留和扩散，保障人员和环境安全。美观耐磨、仅防水、仅防火均不是其核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作场所的地面和工作台应采用光滑、耐腐蚀、易去污的材料，便于清除放射性污染，符合辐射防护和污染控制要求。因此，选项B正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 241 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0242","type":"single","qtype":"单选题","stem":"放射性药品生产、检验时，需配备与（ ）相适应的防护装置","options":[{"key":"A","text":"生产批量"},{"key":"B","text":"放射性剂量"},{"key":"C","text":"人员数量"},{"key":"D","text":"设备大小"}],"answer":["B"],"explanation":"放射性药品生产、检验时，需配备与放射性剂量相适应的防护装置，以确保操作人员受到的辐射剂量符合国家限值要求。生产批量、人员数量、设备大小均不是选择防护装置的核心依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n防护装置（如铅屏蔽、手套箱、个人剂量计等）的防护能力需与所操作放射性核素的射线类型和活度相适应，确保辐射安全。因此，选项B正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 242 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0243","type":"single","qtype":"单选题","stem":"放射性药品生产区入口应设置（ ）","options":[{"key":"A","text":"休息区"},{"key":"B","text":"去污洗涤和更衣设施"},{"key":"C","text":"餐饮区"},{"key":"D","text":"会议区"}],"answer":["B"],"explanation":"放射性药品生产区入口应设置去污洗涤和更衣设施，以便人员进入前更换专用工作服并进行必要的去污处理，防止污染带入生产区。休息区、餐饮区、会议区均不是入口处应设置的设施。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产区入口设置去污洗涤和更衣设施，是人员进出洁净区和放射性工作区的标准更衣程序要求，可有效控制污染。因此，选项B正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 243 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0244","type":"single","qtype":"单选题","stem":"放射性药品生产区出口应设置（ ）","options":[{"key":"A","text":"放射性污染检测设备"},{"key":"B","text":"消防器材"},{"key":"C","text":"空调设备"},{"key":"D","text":"照明设备"}],"answer":["A"],"explanation":"放射性药品生产区出口应设置放射性污染检测设备，用于检测人员体表和携带物品是否受到放射性污染，防止污染扩散。消防器材、空调设备、照明设备均不是出口处必须设置的污染检测设备。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产区出口设置污染检测设备是辐射安全防护的重要措施，可及时发现污染并采取去污措施，符合国家放射性同位素与射线装置安全防护要求。因此，选项A正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 244 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0245","type":"single","qtype":"单选题","stem":"下列操作中，需在“C级背景下的局部A级”洁净区进行的是（ ）","options":[{"key":"A","text":"口服制剂配制"},{"key":"B","text":"非最终灭菌小容量注射剂灌装"},{"key":"C","text":"放射免疫分析药盒生产"},{"key":"D","text":"正电子类药品密闭设备外环境"}],"answer":["B"],"explanation":"非最终灭菌小容量注射剂灌装需在“C级背景下的局部A级”洁净区进行，以最大限度降低微生物和微粒污染风险。口服制剂配制、放射免疫分析药盒生产、正电子类药品密闭设备外环境均不需要该级别。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，非最终灭菌小容量注射剂的灌装操作应在C级背景下局部A级进行，确保无菌保证水平。因此，选项B正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 245 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0246","type":"single","qtype":"单选题","stem":"医用放射性核素发生器的物料准备和组装应在（ ）洁净区进行","options":[{"key":"A","text":"A级"},{"key":"B","text":"C级背景下局部A级"},{"key":"C","text":"C级"},{"key":"D","text":"D级"}],"answer":["C"],"explanation":"医用放射性核素发生器的物料准备和组装应在C级洁净区进行，以控制微粒和微生物污染。A级、C级背景下局部A级、D级均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，医用放射性核素发生器的物料准备和组装操作在C级洁净区进行。因此，选项C正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 246 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0247","type":"single","qtype":"单选题","stem":"口服制剂的物料准备应在（ ）洁净区进行","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"普通区"}],"answer":["C"],"explanation":"口服制剂的物料准备应在D级洁净区进行，该级别可满足口服固体制剂的微生物和微粒控制要求。C级背景下局部A级、C级、普通区均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，口服制剂的物料准备操作在D级洁净区进行。因此，选项C正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 247 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0248","type":"single","qtype":"单选题","stem":"正电子类放射性药品（小容量注射剂）的灌装应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"非洁净区"}],"answer":["A"],"explanation":"正电子类放射性药品（小容量注射剂）的灌装应在C级背景下局部A级进行，以确保无菌灌装，降低微生物和微粒污染风险。C级、D级、非洁净区均不符合要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，正电子类放射性药品（小容量注射剂）的灌装操作应在C级背景下局部A级进行。因此，选项A正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 248 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0249","type":"single","qtype":"单选题","stem":"直接接触非无菌药品的包装材料最终清洗应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"A级"}],"answer":["C"],"explanation":"直接接触非无菌药品的包装材料最终清洗应在D级洁净区进行，以控制微粒和微生物污染。C级背景下局部A级、C级、A级均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，直接接触非无菌药品的包装材料最终清洗操作在D级洁净区进行。因此，选项C正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 249 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0250","type":"single","qtype":"单选题","stem":"采用除菌过滤工艺的非最终灭菌小容量注射剂制备应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"A级"}],"answer":["B"],"explanation":"采用除菌过滤工艺的非最终灭菌小容量注射剂制备应在C级洁净区进行，以控制微生物污染。C级背景下局部A级、D级、A级均不符合该操作的环境要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，采用除菌过滤工艺的非最终灭菌小容量注射剂制备操作在C级洁净区进行。因此，选项B正确。\n\n---","source":{"file":"单选题/241-250.md","merged":"单选题1-400.md","location":"第 250 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0251","type":"single","qtype":"单选题","stem":"无菌体内植入制品的分装与密封应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"普通区"}],"answer":["A"],"explanation":"无菌体内植入制品的分装与密封属于高风险无菌操作，需在C级背景下局部A级洁净区进行，以最大限度降低微生物和微粒污染风险。C级、D级、普通区均不能满足无菌保证要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，无菌体内植入制品的分装与密封操作应在C级背景下局部A级进行，确保产品无菌。因此，选项A正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 251 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0252","type":"single","qtype":"单选题","stem":"放射免疫分析药盒的生产应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"A级"}],"answer":["C"],"explanation":"放射免疫分析药盒属于非无菌体外诊断试剂，其生产一般在D级洁净区进行，以控制微粒和微生物污染。C级背景下局部A级、C级、A级均过高，不符合该产品的实际生产要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，放射免疫分析药盒的生产操作在D级洁净区进行。因此，选项C正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 252 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0253","type":"single","qtype":"单选题","stem":"即时标记放射性药品的淋洗应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"非洁净区"}],"answer":["B"],"explanation":"即时标记放射性药品的淋洗操作应在C级洁净区进行，以控制微生物和微粒污染，同时配合辐射防护措施。C级背景下局部A级、D级、非洁净区均不符合该操作的环境要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，即时标记放射性药品的淋洗操作在C级洁净区进行。因此，选项B正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 253 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0254","type":"single","qtype":"单选题","stem":"无菌体内植入制品的焊封应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"A级"}],"answer":["C"],"explanation":"无菌体内植入制品的焊封操作应在D级洁净区进行，以控制微粒和微生物污染。C级背景下局部A级、C级、A级均不符合该操作的环境要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，无菌体内植入制品的焊封操作在D级洁净区进行。因此，选项C正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 254 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0255","type":"single","qtype":"单选题","stem":"当动态监测可能损坏尘埃粒子计数器或造成污染时，可在（ ）进行净化测试","options":[{"key":"A","text":"正常生产时"},{"key":"B","text":"设备调试、维护和模拟操作期间"},{"key":"C","text":"任意时间"},{"key":"D","text":"仅验收时"}],"answer":["B"],"explanation":"当动态监测可能损坏尘埃粒子计数器或造成污染时，可在设备调试、维护和模拟操作期间进行净化测试，以评估洁净区性能，同时避免损坏仪器或造成污染。正常生产时、任意时间、仅验收时均不是合适的时机。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据药品GMP及洁净区环境监测要求，在动态监测可能损坏仪器或造成污染时，可在设备调试、维护和模拟操作期间进行净化测试。因此，选项B正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 255 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0256","type":"single","qtype":"单选题","stem":"放射性生产区空气净化系统的送风、压差设计目的是（ ）","options":[{"key":"A","text":"节能"},{"key":"B","text":"有效防止放射性核素外溢"},{"key":"C","text":"提高舒适度"},{"key":"D","text":"降低噪音"}],"answer":["B"],"explanation":"放射性生产区空气净化系统的送风、压差设计目的是有效防止放射性核素外溢，通过合理的气流组织和压差控制，确保放射性物质不扩散到非放射性区域。节能、提高舒适度、降低噪音均不是其核心目的。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n送风、压差设计需确保放射性工作区相对负压，防止放射性气溶胶外溢，符合辐射防护和污染控制要求。因此，选项B正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 256 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0257","type":"single","qtype":"单选题","stem":"贮存放射性物质的场所不需具备的安全措施是（ ）","options":[{"key":"A","text":"防火"},{"key":"B","text":"防盗"},{"key":"C","text":"防泄漏"},{"key":"D","text":"防光照"}],"answer":["D"],"explanation":"贮存放射性物质的场所需具备防火、防盗、防泄漏等安全措施，但不需特别具备防光照措施。防光照不是放射性物质贮存的核心安全要求。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n贮存放射性物质需采取防火、防盗、防泄漏措施，并设置明显的放射性警示标识，确保安全可控。防光照不是其必需的安全措施。因此，选项D正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 257 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0258","type":"single","qtype":"单选题","stem":"放射性药品包装容器如需重复使用，企业应具备（ ）","options":[{"key":"A","text":"普通清洗间"},{"key":"B","text":"专用的去污处理场所"},{"key":"C","text":"仅自来水龙头"},{"key":"D","text":"开放式清洗区"}],"answer":["B"],"explanation":"放射性药品包装容器如需重复使用，企业应具备专用的去污处理场所，配备专用去污试剂和工具，并对清洗废水进行放射性监测和处理。普通清洗间、仅自来水龙头、开放式清洗区均不能满足要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n重复使用的放射性包装容器需在专用去污场所进行清洗和污染检测，达标后方可再次使用。因此，选项B正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 258 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0259","type":"single","qtype":"单选题","stem":"企业外购灭菌注射用水时，首要工作是（ ）","options":[{"key":"A","text":"仅确认价格"},{"key":"B","text":"对供应商进行审计，确认资质和质量"},{"key":"C","text":"仅签订合同"},{"key":"D","text":"仅检查外观"}],"answer":["B"],"explanation":"企业外购灭菌注射用水时，首要工作是对供应商进行审计，确认其资质和质量保证能力，确保物料质量可靠。仅确认价格、仅签订合同、仅检查外观均不符合质量管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n外购灭菌注射用水属于关键物料，需对供应商进行审计，确认其生产资质、质量标准和运输条件。因此，选项B正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 259 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0260","type":"single","qtype":"单选题","stem":"制药用水的贮存和使用需采取措施防止（ ）","options":[{"key":"A","text":"挥发"},{"key":"B","text":"微生物滋生"},{"key":"C","text":"冻结"},{"key":"D","text":"变色"}],"answer":["B"],"explanation":"制药用水的贮存和使用需采取措施防止微生物滋生，如定期消毒、循环流动、保持温度等，确保水质符合《中国药典》标准。挥发、冻结、变色均不是制药用水贮存和使用中需重点防止的问题。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n制药用水需防止微生物滋生，应定期检验微生物限度，并采取消毒、循环等措施，确保水质持续合格。因此，选项B正确。\n\n---","source":{"file":"单选题/251-260.md","merged":"单选题1-400.md","location":"第 260 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0261","type":"single","qtype":"单选题","stem":"放射性药品生产企业配备的仪器设备需与（ ）相适应","options":[{"key":"A","text":"仅生产规模"},{"key":"B","text":"生产和质量控制需求"},{"key":"C","text":"仅人员数量"},{"key":"D","text":"仅场地大小"}],"answer":["B"],"explanation":"放射性药品生产企业配备的仪器设备需与生产和质量控制需求相适应，确保能够满足生产工艺和检验要求，保证产品质量。仅生产规模、仅人员数量、仅场地大小均不能全面反映设备配备的依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n仪器设备是生产和质量控制的基础资源，其配备必须与生产规模、品种、检验项目等需求相匹配，确保生产和检验能力满足要求。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 261 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0262","type":"single","qtype":"单选题","stem":"用于放射性剂量监测的仪器需（ ）","options":[{"key":"A","text":"随意校准"},{"key":"B","text":"定期校准，确保准确性"},{"key":"C","text":"仅购买时校准"},{"key":"D","text":"无需校准"}],"answer":["B"],"explanation":"用于放射性剂量监测的仪器需定期校准，确保测量准确性，保障辐射防护的有效性。随意校准、仅购买时校准、无需校准均不符合计量管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射剂量监测仪器属于计量器具，必须定期校准，确保测量数据准确可靠，符合国家辐射防护标准。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 262 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0263","type":"single","qtype":"单选题","stem":"放射性药品生产用设备的设计需考虑（ ）","options":[{"key":"A","text":"仅生产效率"},{"key":"B","text":"便于清洁和放射性污染去除"},{"key":"C","text":"仅外观"},{"key":"D","text":"仅成本"}],"answer":["B"],"explanation":"放射性药品生产用设备的设计需考虑便于清洁和放射性污染去除，以减少污染残留和人员辐射暴露。仅生产效率、仅外观、仅成本均不是设备设计的核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n设备设计应便于清洁和去污，表面光滑、耐腐蚀、易拆卸，符合辐射防护和污染控制要求。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 263 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0264","type":"single","qtype":"单选题","stem":"无菌放射性药品生产设备的清洁验证需额外关注（ ）","options":[{"key":"A","text":"仅化学残留"},{"key":"B","text":"放射性残留+微生物残留"},{"key":"C","text":"仅物理残留"},{"key":"D","text":"仅外观清洁"}],"answer":["B"],"explanation":"无菌放射性药品生产设备的清洁验证需额外关注放射性残留和微生物残留，确保设备清洁后无放射性污染且无菌。仅化学残留、仅物理残留、仅外观清洁均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌放射性药品生产设备的清洁验证需同时评估放射性残留和微生物残留，确保清洁效果符合辐射防护和无菌要求。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 264 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0265","type":"single","qtype":"单选题","stem":"放射性药品检验用仪器应与（ ）适配","options":[{"key":"A","text":"普通药品检验"},{"key":"B","text":"放射性药品质量控制需求"},{"key":"C","text":"仅环境监测"},{"key":"D","text":"仅原料检测"}],"answer":["B"],"explanation":"放射性药品检验用仪器应与放射性药品质量控制需求适配，能够准确测定放射性核素鉴别、活度、放射化学纯度等关键指标。普通药品检验、仅环境监测、仅原料检测均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验仪器需满足放射性药品质量控制要求，如多道γ谱仪、活度计、色谱扫描仪等，确保检验结果准确可靠。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 265 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0266","type":"single","qtype":"单选题","stem":"厂房设施验收时，需重点确认的辐射防护设施不包括（ ）","options":[{"key":"A","text":"铅防护装置"},{"key":"B","text":"排风去污系统"},{"key":"C","text":"普通窗户"},{"key":"D","text":"污染检测设备"}],"answer":["C"],"explanation":"厂房设施验收时，需重点确认铅防护装置、排风去污系统、污染检测设备等辐射防护设施，但不包括普通窗户。普通窗户不属于辐射防护设施，且可能影响辐射屏蔽和洁净度控制。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射防护设施包括屏蔽装置、排风去污系统、污染检测设备等，普通窗户不在其列。因此，选项C正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 266 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0267","type":"single","qtype":"单选题","stem":"放射性工作区的压差应（ ）非放射性工作区","options":[{"key":"A","text":"高于"},{"key":"B","text":"低于"},{"key":"C","text":"等于"},{"key":"D","text":"无固定要求"}],"answer":["B"],"explanation":"放射性工作区的压差应低于非放射性工作区，即保持相对负压，以防止放射性气溶胶或粉尘向外扩散，保护周围环境和人员。高于、等于、无固定要求均不符合辐射防护要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作区保持相对负压，可有效防止放射性物质外溢，符合辐射防护和污染控制要求。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 267 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0268","type":"single","qtype":"单选题","stem":"挥发性放射性核素操作区的排风系统需具备（ ）","options":[{"key":"A","text":"加热功能"},{"key":"B","text":"有效去污处理措施"},{"key":"C","text":"加湿功能"},{"key":"D","text":"仅通风功能"}],"answer":["B"],"explanation":"挥发性放射性核素操作区的排风系统需具备有效去污处理措施，如高效过滤、活性炭吸附等，以防止放射性物质排放到环境中。加热、加湿、仅通风均不能有效去污。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n挥发性放射性核素操作区排风系统需经去污处理，确保排放气体符合国家放射性废物管理要求。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 268 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0269","type":"single","qtype":"单选题","stem":"放射性洁净区的空气若需循环使用，需采取的措施是（ ）","options":[{"key":"A","text":"仅过滤灰尘"},{"key":"B","text":"有效措施避免污染和交叉污染"},{"key":"C","text":"仅增加风量"},{"key":"D","text":"无需特殊措施"}],"answer":["B"],"explanation":"放射性洁净区的空气若需循环使用，需采取有效措施避免污染和交叉污染，如高效过滤、活性炭吸附、风险评估等。仅过滤灰尘、仅增加风量、无需特殊措施均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性洁净区空气循环使用需经风险评估，并采取有效措施防止污染积累和交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 269 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0270","type":"single","qtype":"单选题","stem":"即时标记药品洁净区空气循环使用的前提是（ ）","options":[{"key":"A","text":"无特殊前提"},{"key":"B","text":"经风险评估，确认无污染风险"},{"key":"C","text":"仅领导批准"},{"key":"D","text":"仅空间有限"}],"answer":["B"],"explanation":"即时标记药品洁净区空气循环使用的前提是经风险评估，确认无污染风险。即时标记药品通常使用短半衰期核素，放射性污染风险较低，但需经评估确认。无特殊前提、仅领导批准、仅空间有限均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n即时标记药品洁净区空气循环使用需基于风险评估，确认无污染风险后方可实施。因此，选项B正确。\n\n---","source":{"file":"单选题/261-270.md","merged":"单选题1-400.md","location":"第 270 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0271","type":"single","qtype":"单选题","stem":"放射性核素工作场所的工作台材质应选择（ ）","options":[{"key":"A","text":"易吸附放射性物质的材料"},{"key":"B","text":"光滑、耐腐、便于去污的材料"},{"key":"C","text":"仅便宜的材料"},{"key":"D","text":"仅美观的材料"}],"answer":["B"],"explanation":"放射性核素工作场所的工作台材质应选择光滑、耐腐、便于去污的材料，以防止放射性物质吸附和残留，便于清除污染。易吸附放射性物质的材料、仅便宜的材料、仅美观的材料均不符合辐射防护和污染控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作台材质需满足易去污、耐腐蚀的要求，确保放射性污染可被有效清除，符合辐射防护和洁净控制标准。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 271 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0272","type":"single","qtype":"单选题","stem":"放射性药品生产区的去污洗涤设施应配备（ ）","options":[{"key":"A","text":"仅普通自来水"},{"key":"B","text":"专用去污试剂和工具"},{"key":"C","text":"仅洗手液"},{"key":"D","text":"仅毛巾"}],"answer":["B"],"explanation":"放射性药品生产区的去污洗涤设施应配备专用去污试剂和工具，以有效清除放射性污染，防止污染扩散。仅普通自来水、仅洗手液、仅毛巾均不能满足去污要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n去污洗涤设施需配备专用去污试剂和工具，确保人员体表和物品的放射性污染得到有效清除。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 272 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0273","type":"single","qtype":"单选题","stem":"出口的放射性污染检测设备应能检测（ ）","options":[{"key":"A","text":"仅人员体表污染"},{"key":"B","text":"人员体表及携带物品污染"},{"key":"C","text":"仅空气污染"},{"key":"D","text":"仅地面污染"}],"answer":["B"],"explanation":"出口的放射性污染检测设备应能检测人员体表及携带物品污染，以防止放射性物质被带出工作区，造成污染扩散。仅人员体表、仅空气、仅地面污染均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n出口污染检测设备需覆盖人员体表和携带物品，确保无放射性污染外带，符合辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 273 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0274","type":"single","qtype":"单选题","stem":"“C级背景下的局部A级”洁净区的核心要求是（ ）","options":[{"key":"A","text":"仅局部A级"},{"key":"B","text":"背景C级+局部A级，满足无菌及防辐射污染"},{"key":"C","text":"仅背景C级"},{"key":"D","text":"无洁净度要求"}],"answer":["B"],"explanation":"“C级背景下的局部A级”洁净区的核心要求是背景C级+局部A级，既满足无菌操作要求，又需结合辐射防护措施防止放射性污染。仅局部A级、仅背景C级、无洁净度要求均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n对于无菌放射性药品生产，需在C级背景下局部A级进行，同时满足无菌和辐射防护双重标准。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 274 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0275","type":"single","qtype":"单选题","stem":"正电子类放射性药品自动合成环境应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"A级"}],"answer":["B"],"explanation":"正电子类放射性药品自动合成环境应在C级洁净区进行。合成过程在密闭的自动合成系统中完成，热室环境达到C级即可满足微粒和微生物控制要求。C级背景下局部A级、D级、A级均不符合该操作的环境要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，正电子类放射性药品的自动合成环境为C级洁净区。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 275 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0276","type":"single","qtype":"单选题","stem":"直接接触无菌药品的包装材料灭菌后装配应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"普通区"}],"answer":["A"],"explanation":"直接接触无菌药品的包装材料灭菌后装配应在C级背景下局部A级进行，以保持包装材料的无菌状态，防止微生物和微粒污染。C级、D级、普通区均不能满足无菌装配要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，直接接触无菌药品的包装材料灭菌后装配操作应在C级背景下局部A级进行。因此，选项A正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 276 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0277","type":"single","qtype":"单选题","stem":"最终灭菌的小容量注射剂灌装应在（ ）","options":[{"key":"A","text":"C级背景下局部A级"},{"key":"B","text":"C级"},{"key":"C","text":"D级"},{"key":"D","text":"A级"}],"answer":["B"],"explanation":"最终灭菌的小容量注射剂灌装应在C级洁净区进行，之后进行最终灭菌。C级背景下局部A级、D级、A级均不符合该操作的环境要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品生产质量管理规范（2010年版）》及其放射性药品附录，最终灭菌的小容量注射剂灌装操作在C级洁净区进行。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 277 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0278","type":"single","qtype":"单选题","stem":"放射性药品厂房的消防设施需与（ ）兼容","options":[{"key":"A","text":"辐射防护要求"},{"key":"B","text":"仅普通消防标准"},{"key":"C","text":"仅生产工艺"},{"key":"D","text":"仅人员数量"}],"answer":["A"],"explanation":"放射性药品厂房的消防设施需与辐射防护要求兼容，确保在火灾等紧急情况下既能有效灭火，又不会破坏辐射屏蔽或导致放射性污染扩散。仅普通消防标准、仅生产工艺、仅人员数量均不全面。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n消防设施需结合辐射防护要求设计，如采用不破坏屏蔽的灭火系统，确保安全。因此，选项A正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 278 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0279","type":"single","qtype":"单选题","stem":"企业自行制备制药用水时，需定期对水系统进行（ ）","options":[{"key":"A","text":"仅外观检查"},{"key":"B","text":"确认，确保符合《中国药典》标准"},{"key":"C","text":"仅更换滤芯"},{"key":"D","text":"无需维护"}],"answer":["B"],"explanation":"企业自行制备制药用水时，需定期对水系统进行确认，确保水质符合《中国药典》标准，包括电导率、微生物限度、细菌内毒素等指标。仅外观检查、仅更换滤芯、无需维护均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n制药用水系统需定期确认和检验，确保符合《中国药典》纯化水、注射用水标准，保证药品质量。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 279 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0280","type":"single","qtype":"单选题","stem":"放射性药品生产用设备的维护记录需包含（ ）","options":[{"key":"A","text":"仅维护时间"},{"key":"B","text":"维护内容+放射性污染检查结果"},{"key":"C","text":"仅维护人员"},{"key":"D","text":"仅设备型号"}],"answer":["B"],"explanation":"放射性药品生产用设备的维护记录需包含维护内容和放射性污染检查结果，以确认维护后设备无放射性残留，确保后续生产安全。仅维护时间、仅维护人员、仅设备型号均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n设备维护记录应记录维护内容及污染检查结果，确保设备维护后符合辐射防护和洁净要求。因此，选项B正确。\n\n---","source":{"file":"单选题/271-280.md","merged":"单选题1-400.md","location":"第 280 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0281","type":"single","qtype":"单选题","stem":"无菌放射性药品生产区的洁净度监测频次应（ ）普通无菌药品","options":[{"key":"A","text":"低于"},{"key":"B","text":"等同于或高于"},{"key":"C","text":"仅在验收时进行"},{"key":"D","text":"无需监测"}],"answer":["B"],"explanation":"无菌放射性药品生产区的洁净度监测频次应等同于或高于普通无菌药品。这是因为放射性药品生产过程中，除需控制微生物和微粒污染外，还需控制放射性污染，监测要求更为严格。低于、仅在验收时进行、无需监测均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌放射性药品生产区需按照药品GMP及无菌药品附录要求进行洁净度监测，且因放射性特殊性，监测频次应等同于或高于普通无菌药品，确保环境持续符合要求。因此，选项B正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 281 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0282","type":"single","qtype":"单选题","stem":"不同放射性核素的生产设备应（ ）","options":[{"key":"A","text":"共用"},{"key":"B","text":"严格分开，防止交叉污染"},{"key":"C","text":"就近摆放"},{"key":"D","text":"随意使用"}],"answer":["B"],"explanation":"不同放射性核素的生产设备应严格分开，防止交叉污染和混淆，确保产品核纯度和放射化学纯度。共用、就近摆放、随意使用均不能有效防止交叉污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同放射性核素具有不同辐射特性和半衰期，生产设备严格分开可避免交叉污染，保证产品质量。因此，选项B正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 282 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0283","type":"single","qtype":"单选题","stem":"放射性药品生产厂房的选址不需考虑（ ）","options":[{"key":"A","text":"辐射安全距离"},{"key":"B","text":"周边居民密度"},{"key":"C","text":"仅交通便利性"},{"key":"D","text":"环保要求"}],"answer":["C"],"explanation":"放射性药品生产厂房的选址不需仅考虑交通便利性，而应重点考虑辐射安全距离、周边居民密度、环保要求等因素。仅交通便利性不是选址的核心要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n厂房选址需符合辐射安全距离和环保要求，考虑周边居民密度，以降低对公众的辐射影响。交通便利性仅为辅助因素。因此，选项C正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 283 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0284","type":"single","qtype":"单选题","stem":"操作放射性核素的封闭环境需具备（ ）","options":[{"key":"A","text":"仅通风"},{"key":"B","text":"辐射防护+负压控制"},{"key":"C","text":"仅照明"},{"key":"D","text":"仅温度控制"}],"answer":["B"],"explanation":"操作放射性核素的封闭环境需具备辐射防护和负压控制，以防止放射性物质外溢和污染扩散。仅通风、仅照明、仅温度控制均不能提供有效的辐射防护和污染控制。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n封闭环境需配备屏蔽装置和负压通风系统，确保放射性气溶胶不外溢，符合辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 284 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0285","type":"single","qtype":"单选题","stem":"放射性洁净区的送风口应设置（ ）","options":[{"key":"A","text":"普通滤网"},{"key":"B","text":"高效空气过滤器"},{"key":"C","text":"仅防护网"},{"key":"D","text":"无需滤网"}],"answer":["B"],"explanation":"放射性洁净区的送风口应设置高效空气过滤器（HEPA），以去除空气中的微粒和微生物，确保洁净区达到规定洁净度。普通滤网、仅防护网、无需滤网均不能满足要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n洁净区送风口需安装高效空气过滤器，确保送入空气的洁净度，同时防止放射性微粒扩散。因此，选项B正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 285 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0286","type":"single","qtype":"单选题","stem":"贮存放射性物质的场所应设置（ ）","options":[{"key":"A","text":"明显的放射性警示标识"},{"key":"B","text":"仅普通仓库标识"},{"key":"C","text":"仅温度标识"},{"key":"D","text":"仅湿度标识"}],"answer":["A"],"explanation":"贮存放射性物质的场所应设置明显的放射性警示标识，以提醒人员注意辐射风险，采取必要的防护措施。仅普通仓库标识、仅温度标识、仅湿度标识均不能替代放射性警示标识。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n同时，根据《放射性同位素与射线装置安全和防护条例》，贮存放射性物质的场所必须设置明显的放射性警示标识，标明核素种类、活度等信息。因此，选项A正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 286 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0287","type":"single","qtype":"单选题","stem":"重复使用的放射性药品包装容器，去污后需（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"检测确认无放射性污染后使用"},{"key":"C","text":"仅外观检查"},{"key":"D","text":"仅晾干"}],"answer":["B"],"explanation":"重复使用的放射性药品包装容器，去污后需检测确认无放射性污染后方可使用，以确保容器不会造成放射性污染扩散。直接使用、仅外观检查、仅晾干均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n重复使用的包装容器需在专用去污场所清洗，并经放射性污染检测合格后方可再次使用。因此，选项B正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 287 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0288","type":"single","qtype":"单选题","stem":"外购灭菌注射用水的供应商审计内容不包括（ ）","options":[{"key":"A","text":"生产资质"},{"key":"B","text":"质量标准"},{"key":"C","text":"运输条件"},{"key":"D","text":"仅供应商规模"}],"answer":["D"],"explanation":"外购灭菌注射用水的供应商审计内容包括生产资质、质量标准、运输条件等，但不包括仅供应商规模。供应商规模不是质量审计的核心内容。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n供应商审计应重点评估其生产资质、质量标准、运输条件等，确保物料质量可靠，供应商规模不是审计重点。因此，选项D正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 288 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0289","type":"single","qtype":"单选题","stem":"放射性药品检验用的活度计需（ ）","options":[{"key":"A","text":"仅用于一种核素测量"},{"key":"B","text":"能测量生产涉及的核素，定期校准"},{"key":"C","text":"随意使用"},{"key":"D","text":"仅购买时验证"}],"answer":["B"],"explanation":"放射性药品检验用的活度计需能测量生产涉及的核素，并定期校准，以确保活度测量准确可靠。仅用于一种核素、随意使用、仅购买时验证均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n活度计需覆盖生产涉及的核素，并定期校准，确保测量结果准确，符合放射性药品质量控制要求。因此，选项B正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 289 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0290","type":"single","qtype":"单选题","stem":"放射性药品生产厂房的地面应（ ）","options":[{"key":"A","text":"仅平整"},{"key":"B","text":"平整、耐腐、便于去污、防渗漏"},{"key":"C","text":"仅美观"},{"key":"D","text":"仅防滑"}],"answer":["B"],"explanation":"放射性药品生产厂房的地面应平整、耐腐、便于去污、防渗漏，以防止放射性物质残留和渗入地面，便于清除污染。仅平整、仅美观、仅防滑均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产厂房地面需采用平整、耐腐蚀、易去污、防渗漏的材料，确保放射性污染可被有效清除，符合辐射防护和洁净控制要求。因此，选项B正确。\n\n---","source":{"file":"单选题/281-290.md","merged":"单选题1-400.md","location":"第 290 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0291","type":"single","qtype":"单选题","stem":"放射性物质与非放射性物质的存放要求是（ ）","options":[{"key":"A","text":"可混合存放"},{"key":"B","text":"严格分开存放"},{"key":"C","text":"就近存放"},{"key":"D","text":"随意存放"}],"answer":["B"],"explanation":"放射性物质与非放射性物质应严格分开存放，以防止放射性物质污染非放射性物料，确保药品质量和辐射安全。可混合、就近、随意存放均不能有效控制污染扩散和交叉污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n放射性物质与非放射性物质必须严格分开存放，避免交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 291 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0292","type":"single","qtype":"单选题","stem":"放射性物质的存放需满足（ ）","options":[{"key":"A","text":"专库或专柜、专人保管、专册登记"},{"key":"B","text":"普通货架存放"},{"key":"C","text":"仅上锁即可"},{"key":"D","text":"仅贴标签即可"}],"answer":["A"],"explanation":"放射性物质的存放需满足专库或专柜、专人保管、专册登记的要求，以确保放射性物质安全可控、可追溯。普通货架、仅上锁、仅贴标签均不符合放射性物质管理要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n放射性物质存放必须严格执行“专库/专柜、专人、专册”的管理要求。因此，选项A正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 292 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0293","type":"single","qtype":"单选题","stem":"放射性物料的专册登记内容不包括（ ）","options":[{"key":"A","text":"物料名称、规格"},{"key":"B","text":"放射性活度、批号"},{"key":"C","text":"供应商、到货日期"},{"key":"D","text":"仅物料价格"}],"answer":["D"],"explanation":"放射性物料的专册登记内容包括物料名称、规格、放射性活度、批号、供应商、到货日期等，但不包括仅物料价格。物料价格不是放射性物料管理的核心登记内容。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n专册登记需记录物料名称、规格、放射性活度、批号、供应商、到货日期等，确保可追溯。物料价格不属于登记内容。因此，选项D正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 293 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0294","type":"single","qtype":"单选题","stem":"放射性物料的保管人员需具备（ ）","options":[{"key":"A","text":"仅仓库管理经验"},{"key":"B","text":"辐射防护知识及物料管理能力"},{"key":"C","text":"仅销售经验"},{"key":"D","text":"仅采购经验"}],"answer":["B"],"explanation":"放射性物料的保管人员需具备辐射防护知识及物料管理能力，以确保在保管过程中既能保障物料安全，又能防止辐射危害。仅仓库管理经验、仅销售经验、仅采购经验均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性物料保管人员需接受辐射防护培训，具备物料管理能力，考核合格后方可上岗。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 294 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0295","type":"single","qtype":"单选题","stem":"放射性物料与非放射性物料在厂区内流转时，需采取措施防止（ ）","options":[{"key":"A","text":"仅混淆"},{"key":"B","text":"混淆、污染及辐射危害"},{"key":"C","text":"仅损坏"},{"key":"D","text":"仅延误"}],"answer":["B"],"explanation":"放射性物料与非放射性物料在厂区内流转时，需采取措施防止混淆、污染及辐射危害，确保物料安全和人员健康。仅混淆、仅损坏、仅延误均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n物料流转需采取隔离、标识、防护等措施，防止混淆、污染和辐射危害。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 295 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0296","type":"single","qtype":"单选题","stem":"放射性中间产品流转时，应使用（ ）","options":[{"key":"A","text":"普通容器"},{"key":"B","text":"具备辐射防护的专用容器"},{"key":"C","text":"仅塑料袋"},{"key":"D","text":"仅纸箱"}],"answer":["B"],"explanation":"放射性中间产品流转时，应使用具备辐射防护的专用容器，以屏蔽射线、防止泄漏和污染扩散。普通容器、仅塑料袋、仅纸箱均不能提供有效的辐射防护。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n放射性中间产品流转需使用专用防护容器，确保辐射安全。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 296 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0297","type":"single","qtype":"单选题","stem":"放射性物料的入库验收需额外检查（ ）","options":[{"key":"A","text":"仅数量"},{"key":"B","text":"放射性活度、包装完整性及辐射污染情况"},{"key":"C","text":"仅外观"},{"key":"D","text":"仅保质期"}],"answer":["B"],"explanation":"放射性物料的入库验收需额外检查放射性活度、包装完整性及辐射污染情况，以确保物料质量安全和辐射防护到位。仅数量、仅外观、仅保质期均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性物料入库验收需检查活度、包装完整性和辐射污染情况，确保符合质量标准和辐射安全要求。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 297 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0298","type":"single","qtype":"单选题","stem":"非放射性物料不得存放在（ ）","options":[{"key":"A","text":"普通仓库"},{"key":"B","text":"放射性物料专库"},{"key":"C","text":"原料仓库"},{"key":"D","text":"辅料仓库"}],"answer":["B"],"explanation":"非放射性物料不得存放在放射性物料专库，以防止受到放射性污染。普通仓库、原料仓库、辅料仓库均可用于非放射性物料存放。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n放射性物料专库仅用于存放放射性物料，非放射性物料不得混入，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 298 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0299","type":"single","qtype":"单选题","stem":"放射性物料的出库需（ ）","options":[{"key":"A","text":"仅凭生产计划"},{"key":"B","text":"凭审批单，双人核对（名称、批号、活度）"},{"key":"C","text":"仅口头通知"},{"key":"D","text":"仅凭领料人身份证"}],"answer":["B"],"explanation":"放射性物料的出库需凭审批单，并由双人核对名称、批号、活度等信息，确保出库准确无误，防止放射性物料丢失或误用。仅凭生产计划、仅口头通知、仅凭领料人身份证均不符合管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n放射性物料出库需严格核对，双人复核，确保物料去向可追溯，防止安全事故。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 299 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0300","type":"single","qtype":"单选题","stem":"放射性中间产品的标识应包含（ ）","options":[{"key":"A","text":"仅产品名称"},{"key":"B","text":"产品名称、批号、放射性活度、防护要求"},{"key":"C","text":"仅批号"},{"key":"D","text":"仅生产时间"}],"answer":["B"],"explanation":"放射性中间产品的标识应包含产品名称、批号、放射性活度、防护要求等信息，以确保可追溯性和辐射安全。仅产品名称、仅批号、仅生产时间均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n放射性中间产品标识需包含产品名称、批号、放射性活度、防护要求等，确保操作人员正确识别和防护。因此，选项B正确。\n\n---","source":{"file":"单选题/291-300.md","merged":"单选题1-400.md","location":"第 300 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0301","type":"single","qtype":"单选题","stem":"放射性物料的储存环境需符合（ ）","options":[{"key":"A","text":"仅温度要求"},{"key":"B","text":"辐射安全及物料特性要求（温湿度等）"},{"key":"C","text":"仅湿度要求"},{"key":"D","text":"仅通风要求"}],"answer":["B"],"explanation":"放射性物料的储存环境需同时满足辐射安全及物料特性要求，包括温度、湿度、通风、屏蔽等条件，以确保物料稳定且不发生辐射泄漏。仅温度、仅湿度、仅通风均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n放射性物料储存需符合辐射安全要求，并根据物料特性控制温湿度等环境条件，防止物料变质或放射性污染扩散。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 301 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0302","type":"single","qtype":"单选题","stem":"放射性物料与非放射性物料流转路线应（ ）","options":[{"key":"A","text":"共用"},{"key":"B","text":"分开，避免交叉"},{"key":"C","text":"仅优先放射性物料"},{"key":"D","text":"仅优先非放射性物料"}],"answer":["B"],"explanation":"放射性物料与非放射性物料流转路线应分开，避免交叉，以防止放射性污染扩散到非放射性物料。共用、仅优先放射性物料、仅优先非放射性物料均不能有效防止交叉污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n物料流转路线分开是防止交叉污染的重要措施，符合辐射防护和药品GMP要求。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 302 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0303","type":"single","qtype":"单选题","stem":"放射性物料的报废需（ ）","options":[{"key":"A","text":"随意丢弃"},{"key":"B","text":"按放射性废物管理规定处置"},{"key":"C","text":"仅当作普通垃圾"},{"key":"D","text":"仅焚烧"}],"answer":["B"],"explanation":"放射性物料的报废需按放射性废物管理规定处置，包括分类收集、专用容器贮存、按规定送交放射性废物处置单位等。随意丢弃、仅当作普通垃圾、仅焚烧均违反辐射安全管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物必须按照国家放射性废物管理规定进行处置，确保环境安全和人员健康。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 303 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0304","type":"single","qtype":"单选题","stem":"放射性物料的供应商需具备（ ）","options":[{"key":"A","text":"仅营业执照"},{"key":"B","text":"放射性物料生产/经营资质及辐射安全许可"},{"key":"C","text":"仅生产能力"},{"key":"D","text":"仅价格优势"}],"answer":["B"],"explanation":"放射性物料的供应商需具备放射性物料生产/经营资质及辐射安全许可，以确保其提供的物料符合质量和辐射安全要求。仅营业执照、仅生产能力、仅价格优势均不能替代专业资质。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性物料供应商需具备相应的生产或经营资质，并取得辐射安全许可，确保物料来源合法、质量可靠。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 304 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0305","type":"single","qtype":"单选题","stem":"放射性物料的验收记录需保存（ ）","options":[{"key":"A","text":"仅1年"},{"key":"B","text":"至药品有效期后30天以上"},{"key":"C","text":"仅3个月"},{"key":"D","text":"随意保存"}],"answer":["B"],"explanation":"放射性物料的验收记录需保存至药品有效期后30天以上，以确保在药品有效期内可追溯物料来源和质量情况。仅1年、仅3个月、随意保存均不符合记录保存要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n验收记录属于质量记录，需按规定保存至药品有效期后30天以上，确保可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 305 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0306","type":"single","qtype":"单选题","stem":"放射性中间产品在流转过程中，需避免（ ）","options":[{"key":"A","text":"仅震动"},{"key":"B","text":"温度剧烈变化、碰撞及辐射泄漏"},{"key":"C","text":"仅光照"},{"key":"D","text":"仅风吹"}],"answer":["B"],"explanation":"放射性中间产品在流转过程中，需避免温度剧烈变化、碰撞及辐射泄漏，以确保产品质量和辐射安全。仅震动、仅光照、仅风吹均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n中间产品流转需控制温度、防止碰撞和辐射泄漏，确保物料质量和安全。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 306 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0307","type":"single","qtype":"单选题","stem":"非放射性物料的流转容器（ ）用于放射性物料","options":[{"key":"A","text":"可"},{"key":"B","text":"不可，需专用"},{"key":"C","text":"经清洗后可"},{"key":"D","text":"仅领导批准后可"}],"answer":["B"],"explanation":"非放射性物料的流转容器不可用于放射性物料，必须使用专用容器，以防止放射性污染非放射性物料或造成交叉污染。经清洗后可、仅领导批准后可均不符合规定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性物料流转容器需专用，与非放射性物料容器严格分开，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 307 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0308","type":"single","qtype":"单选题","stem":"放射性物料专库的温湿度记录需（ ）","options":[{"key":"A","text":"仅每日一次"},{"key":"B","text":"定期记录，符合物料储存要求"},{"key":"C","text":"仅每周一次"},{"key":"D","text":"无需记录"}],"answer":["B"],"explanation":"放射性物料专库的温湿度记录需定期记录，并符合物料储存要求，以确保物料在适宜环境下储存，防止变质。仅每日一次、仅每周一次、无需记录均不符合规范要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n专库需定期监测并记录温湿度，确保符合物料储存条件，保证物料质量稳定。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 308 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0309","type":"single","qtype":"单选题","stem":"放射性物料的领用记录需包含（ ）","options":[{"key":"A","text":"仅领用数量"},{"key":"B","text":"领用部门、人员、数量、用途、日期"},{"key":"C","text":"仅领用人员"},{"key":"D","text":"仅用途"}],"answer":["B"],"explanation":"放射性物料的领用记录需包含领用部门、人员、数量、用途、日期等信息，以确保物料去向可追溯，防止丢失或误用。仅领用数量、仅领用人员、仅用途均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十六条规定：放射性药品的存放应专库或专柜，有专人保管，专册登记。\n领用记录属于专册登记内容，需完整记录领用信息，确保可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 309 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0310","type":"single","qtype":"单选题","stem":"放射性物料流转时，陪同人员需佩戴（ ）","options":[{"key":"A","text":"仅工作证"},{"key":"B","text":"辐射剂量监测设备"},{"key":"C","text":"仅安全帽"},{"key":"D","text":"仅手套"}],"answer":["B"],"explanation":"放射性物料流转时，陪同人员需佩戴辐射剂量监测设备，以监测其在流转过程中受到的辐射剂量，保障职业健康。仅工作证、仅安全帽、仅手套均不能监测辐射剂量。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n从事放射性物料流转的人员需佩戴个人剂量计，定期监测辐射剂量，符合辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/301-310.md","merged":"单选题1-400.md","location":"第 310 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0311","type":"single","qtype":"单选题","stem":"放射性工作区域应设置（ ）","options":[{"key":"A","text":"仅普通标识"},{"key":"B","text":"明显的放射性标志"},{"key":"C","text":"仅生产标识"},{"key":"D","text":"仅质量标识"}],"answer":["B"],"explanation":"放射性工作区域应设置明显的放射性标志，以警示人员注意辐射风险，采取必要的防护措施。仅普通标识、仅生产标识、仅质量标识均不能起到辐射警示作用。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，放射性工作场所必须设置明显的放射性标志，标明放射性核素种类、活度、防护要求等信息。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 311 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0312","type":"single","qtype":"单选题","stem":"下列哪种情况符合生产要求（ ）","options":[{"key":"A","text":"同一操作箱生产不同核素的药品"},{"key":"B","text":"同一操作箱生产同一核素的不同品种（防混淆）"},{"key":"C","text":"不同核素药品共用生产设备"},{"key":"D","text":"不同核素药品共用清洁工具"}],"answer":["B"],"explanation":"同一操作箱生产同一核素的不同品种，并采取防混淆措施，符合生产要求。同一操作箱生产不同核素、不同核素药品共用生产设备、不同核素药品共用清洁工具均易导致交叉污染和混淆，不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同一核素的不同品种可在同一操作箱生产，但需采取有效防混淆措施；不同核素必须严格分开，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 312 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0313","type":"single","qtype":"单选题","stem":"即时标记放射性药品，若每日使用同一钼锝发生器一次洗脱液和相同批号配套药盒制备同种制剂，应定为（ ）","options":[{"key":"A","text":"多批"},{"key":"B","text":"一批"},{"key":"C","text":"亚批"},{"key":"D","text":"随意批次"}],"answer":["B"],"explanation":"即时标记放射性药品，若每日使用同一钼锝发生器一次洗脱液和相同批号配套药盒制备同种制剂，应定为一批。因为其原料、操作条件相同，产品具有均一性。多批、亚批、随意批次均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批的划分需根据生产条件、原料批次等确定。同一日、同一发生器、同一次洗脱液、相同批号药盒制备的同种制剂，可定为一批。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 313 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0314","type":"single","qtype":"单选题","stem":"同一钼锝发生器在同一日多次淋洗，每次制备的即时标记制剂应定为（ ）","options":[{"key":"A","text":"一批"},{"key":"B","text":"亚批"},{"key":"C","text":"不同批次（无关联）"},{"key":"D","text":"随意批次"}],"answer":["B"],"explanation":"同一钼锝发生器在同一日多次淋洗，每次制备的即时标记制剂应定为亚批。因为其属于同一批内的不同制备批次，需分别记录和检验，确保可追溯。一批、不同批次、随意批次均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同一日多次淋洗制备的即时标记制剂，应按亚批管理，分别记录淋洗时间、活度、操作人员等，保证可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 314 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0315","type":"single","qtype":"单选题","stem":"放射性工作区与非放射性工作区的工作服（ ）","options":[{"key":"A","text":"可混用"},{"key":"B","text":"不可混用，严格分开"},{"key":"C","text":"经清洗后可混用"},{"key":"D","text":"仅领导批准后可混用"}],"answer":["B"],"explanation":"放射性工作区与非放射性工作区的工作服不可混用，必须严格分开，以防止放射性污染通过工作服扩散到非放射性区域。可混用、经清洗后可混用、仅领导批准后可混用均不符合辐射防护要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作服需按区域专用，严格分开，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 315 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0316","type":"single","qtype":"单选题","stem":"放射性工作区的清洁工具应（ ）","options":[{"key":"A","text":"与非放射性区域共用"},{"key":"B","text":"专用，与非放射性区域严格分开"},{"key":"C","text":"仅普通清洁工具"},{"key":"D","text":"随意使用"}],"answer":["B"],"explanation":"放射性工作区的清洁工具应专用，与非放射性区域严格分开，以防止放射性污染通过清洁工具扩散。共用、仅普通清洁工具、随意使用均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n清洁工具需专用，使用后需进行污染监测和去污处理，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 316 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0317","type":"single","qtype":"单选题","stem":"放射性工作区使用的工作服和器具，在清洗前需（ ）","options":[{"key":"A","text":"直接清洗"},{"key":"B","text":"进行放射性污染监测"},{"key":"C","text":"仅外观检查"},{"key":"D","text":"仅消毒"}],"answer":["B"],"explanation":"放射性工作区使用的工作服和器具，在清洗前需进行放射性污染监测，确认是否受到污染，再决定是否需先去污处理。直接清洗、仅外观检查、仅消毒均可能造成污染扩散。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n清洗前进行污染监测是防止放射性污染扩散的重要措施，符合辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 317 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0318","type":"single","qtype":"单选题","stem":"若工作服清洗前监测发现放射性污染，应（ ）","options":[{"key":"A","text":"直接清洗"},{"key":"B","text":"先去污处理，达标后再清洗"},{"key":"C","text":"丢弃"},{"key":"D","text":"仅晾晒"}],"answer":["B"],"explanation":"若工作服清洗前监测发现放射性污染，应先去污处理，达标后再清洗。直接清洗、丢弃、仅晾晒均不符合放射性污染控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n发现放射性污染的工作服需先去污，经监测达标后方可进入常规清洗流程，防止污染扩散。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 318 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0319","type":"single","qtype":"单选题","stem":"放射性药品成品的外包装应贴有（ ）","options":[{"key":"A","text":"仅标签"},{"key":"B","text":"标签、放射性药品标志，并附说明书"},{"key":"C","text":"仅放射性标志"},{"key":"D","text":"仅说明书"}],"answer":["B"],"explanation":"放射性药品成品的外包装应贴有标签、放射性药品标志，并附说明书，以提供药品信息并警示辐射风险。仅标签、仅放射性标志、仅说明书均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n因此，成品外包装需同时具备标签、放射性标志和说明书，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 319 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0320","type":"single","qtype":"单选题","stem":"放射性药品内包装的标签可在（ ）粘贴","options":[{"key":"A","text":"仅生产后"},{"key":"B","text":"生产前（根据辐射防护需要）"},{"key":"C","text":"仅放行后"},{"key":"D","text":"仅运输前"}],"answer":["B"],"explanation":"放射性药品内包装的标签可在生产前粘贴，根据辐射防护需要，提前粘贴标签可减少操作人员接触放射性药品的时间，降低辐射暴露。仅生产后、仅放行后、仅运输前均不符合辐射防护最优化原则。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n内包装标签可在生产前粘贴，以减少操作人员受照时间，符合辐射防护要求。因此，选项B正确。\n\n---","source":{"file":"单选题/311-320.md","merged":"单选题1-400.md","location":"第 320 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0321","type":"single","qtype":"单选题","stem":"重复使用的放射性药品包装容器，使用前需（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"按规定清洗，确认无污染"},{"key":"C","text":"仅外观检查"},{"key":"D","text":"仅消毒"}],"answer":["B"],"explanation":"重复使用的放射性药品包装容器，使用前需按规定清洗，并确认无放射性污染后方可使用，以防止污染扩散和交叉污染。直接使用、仅外观检查、仅消毒均不能保证容器无放射性残留。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n重复使用的包装容器需在专用去污场所清洗，并经放射性污染检测合格后方可再次使用，确保安全。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 321 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0322","type":"single","qtype":"单选题","stem":"生产含有同一核素的不同品种放射性药品时，需采取措施防止（ ）","options":[{"key":"A","text":"仅设备损坏"},{"key":"B","text":"混淆和交叉污染"},{"key":"C","text":"仅人员受伤"},{"key":"D","text":"仅生产延误"}],"answer":["B"],"explanation":"生产含有同一核素的不同品种放射性药品时，需采取措施防止混淆和交叉污染，确保产品品种和质量准确无误。仅设备损坏、仅人员受伤、仅生产延误均不是核心风险。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同一核素不同品种生产时，需通过标识、隔离、清场等措施防止混淆和交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 322 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0323","type":"single","qtype":"单选题","stem":"即时标记放射性药品的批次管理核心目的是（ ）","options":[{"key":"A","text":"便于销售"},{"key":"B","text":"保证产品可追溯"},{"key":"C","text":"仅满足记录要求"},{"key":"D","text":"仅便于生产计划"}],"answer":["B"],"explanation":"即时标记放射性药品的批次管理核心目的是保证产品可追溯，便于在出现质量问题时快速定位和召回。便于销售、仅满足记录要求、仅便于生产计划均不是核心目的。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批次管理是质量追溯的基础，即时标记药品因制备频繁，更需通过批号实现全程可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 323 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0324","type":"single","qtype":"单选题","stem":"放射性药品生产过程中，若发现不同核素混淆，应（ ）","options":[{"key":"A","text":"继续生产"},{"key":"B","text":"立即停止，评估风险并处置"},{"key":"C","text":"仅记录"},{"key":"D","text":"仅通知销售"}],"answer":["B"],"explanation":"放射性药品生产过程中，若发现不同核素混淆，应立即停止，评估风险并处置，以防止不合格产品流入下道工序或市场。继续生产、仅记录、仅通知销售均不符合质量管理和辐射安全要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n发现核素混淆属于重大偏差，必须立即停止生产，进行风险评估和处置，确保产品安全。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 324 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0325","type":"single","qtype":"单选题","stem":"放射性工作区的工作服应（ ）","options":[{"key":"A","text":"仅舒适即可"},{"key":"B","text":"具备一定辐射防护性能"},{"key":"C","text":"仅美观"},{"key":"D","text":"仅便宜"}],"answer":["B"],"explanation":"放射性工作区的工作服应具备一定辐射防护性能，以降低人员受到的辐射剂量，同时便于去污。仅舒适、仅美观、仅便宜均不能满足辐射防护要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作服需具备辐射防护性能，并定期进行污染监测和去污处理。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 325 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0326","type":"single","qtype":"单选题","stem":"放射性药品生产用器具的材质应（ ）","options":[{"key":"A","text":"仅耐高温"},{"key":"B","text":"便于去污，不易吸附放射性物质"},{"key":"C","text":"仅耐低温"},{"key":"D","text":"仅透明"}],"answer":["B"],"explanation":"放射性药品生产用器具的材质应便于去污，不易吸附放射性物质，以减少放射性残留和交叉污染。仅耐高温、仅耐低温、仅透明均不是核心要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n器具材质应光滑、耐腐蚀、易去污，防止放射性物质吸附。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 326 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0327","type":"single","qtype":"单选题","stem":"放射性药品说明书需包含（ ）","options":[{"key":"A","text":"仅用法用量"},{"key":"B","text":"放射性核素半衰期、辐射防护注意事项等"},{"key":"C","text":"仅适应症"},{"key":"D","text":"仅不良反应"}],"answer":["B"],"explanation":"放射性药品说明书需包含放射性核素半衰期、辐射防护注意事项等特殊内容，以指导临床安全使用。仅用法用量、仅适应症、仅不良反应均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n说明书需包含放射性核素半衰期、辐射防护注意事项等，确保使用安全。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 327 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0328","type":"single","qtype":"单选题","stem":"即时标记药品的亚批管理需记录（ ）","options":[{"key":"A","text":"仅淋洗时间"},{"key":"B","text":"淋洗时间、活度、操作人员等，保证追溯"},{"key":"C","text":"仅操作人员"},{"key":"D","text":"仅活度"}],"answer":["B"],"explanation":"即时标记药品的亚批管理需记录淋洗时间、活度、操作人员等信息，以保证产品可追溯。仅淋洗时间、仅操作人员、仅活度均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n亚批记录需包含淋洗时间、活度、操作人员等关键信息，确保可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 328 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0329","type":"single","qtype":"单选题","stem":"放射性工作区的清洁工具使用后需（ ）","options":[{"key":"A","text":"随意存放"},{"key":"B","text":"专门存放，清洗前污染监测"},{"key":"C","text":"与普通工具混放"},{"key":"D","text":"仅丢弃"}],"answer":["B"],"explanation":"放射性工作区的清洁工具使用后需专门存放，并在清洗前进行污染监测，以防止放射性污染扩散。随意存放、与普通工具混放、仅丢弃均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n清洁工具需专用、专门存放，清洗前进行污染监测，达标后方可清洗。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 329 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0330","type":"single","qtype":"单选题","stem":"放射性药品成品标签需注明（ ）","options":[{"key":"A","text":"仅产品名称"},{"key":"B","text":"产品名称、批号、放射性活度、有效期等"},{"key":"C","text":"仅批号"},{"key":"D","text":"仅生产企业"}],"answer":["B"],"explanation":"放射性药品成品标签需注明产品名称、批号、放射性活度、有效期等信息，以确保产品可识别、可追溯和安全使用。仅产品名称、仅批号、仅生产企业均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n标签需注明产品名称、批号、放射性活度、有效期等关键信息。因此，选项B正确。\n\n---","source":{"file":"单选题/321-330.md","merged":"单选题1-400.md","location":"第 330 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0331","type":"single","qtype":"单选题","stem":"生产不同核素的放射性药品时，需更换（ ）","options":[{"key":"A","text":"仅生产人员"},{"key":"B","text":"生产设备、清洁工具、工作服等，彻底清场"},{"key":"C","text":"仅原料"},{"key":"D","text":"仅包装材料"}],"answer":["B"],"explanation":"生产不同核素的放射性药品时，需更换生产设备、清洁工具、工作服等，并进行彻底清场，以防止不同核素之间的交叉污染和混淆。仅更换生产人员、仅原料、仅包装材料均不能有效防止交叉污染。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同核素的生产必须严格分开，更换设备、清洁工具、工作服并彻底清场，是防止交叉污染和混淆的关键措施。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 331 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0332","type":"single","qtype":"单选题","stem":"即时标记药品的“一批”定义中，不包含的条件是（ ）","options":[{"key":"A","text":"同一日"},{"key":"B","text":"不同钼锝发生器"},{"key":"C","text":"相同批号配套药盒"},{"key":"D","text":"同种制剂"}],"answer":["B"],"explanation":"即时标记药品的“一批”定义中，不包含“不同钼锝发生器”这一条件。因为使用不同发生器意味着淋洗液来源不同，应划分为不同批次。同一日、相同批号配套药盒、同种制剂均是“一批”的构成条件。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批的划分需考虑原料来源的一致性。同一日、同一发生器、同一次洗脱液、相同批号药盒制备的同种制剂可定为一批；不同发生器则不能归为同一批。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 332 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0333","type":"single","qtype":"单选题","stem":"放射性药品生产过程中，工作服的更换应在（ ）","options":[{"key":"A","text":"普通区域"},{"key":"B","text":"专门的更衣区"},{"key":"C","text":"生产操作区"},{"key":"D","text":"仅卫生间"}],"answer":["B"],"explanation":"放射性药品生产过程中，工作服的更换应在专门的更衣区进行，以确保更衣过程不会对生产区造成污染，并符合洁净区和辐射防护要求。普通区域、生产操作区、仅卫生间均不符合更衣要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n更衣区应设置在进入洁净区和放射性工作区之前，配备去污洗涤和更衣设施，确保人员更衣程序符合要求。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 333 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0334","type":"single","qtype":"单选题","stem":"若放射性器具清洗前污染监测超标，应（ ）","options":[{"key":"A","text":"继续使用"},{"key":"B","text":"进行去污处理，重新监测达标后使用"},{"key":"C","text":"丢弃"},{"key":"D","text":"仅晾晒"}],"answer":["B"],"explanation":"若放射性器具清洗前污染监测超标，应进行去污处理，重新监测达标后方可使用。继续使用、丢弃、仅晾晒均不符合放射性污染控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n污染超标的器具必须先去污，经监测达标后方可再次使用，防止污染扩散。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 334 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0335","type":"single","qtype":"单选题","stem":"放射性药品的外包装材料需具备（ ）","options":[{"key":"A","text":"仅美观"},{"key":"B","text":"一定的辐射防护性能"},{"key":"C","text":"仅轻便"},{"key":"D","text":"仅便宜"}],"answer":["B"],"explanation":"放射性药品的外包装材料需具备一定的辐射防护性能，以降低运输和储存过程中对人员和环境的辐射剂量。仅美观、仅轻便、仅便宜均不能满足辐射防护要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n外包装材料需具备辐射防护性能，确保运输和储存安全。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 335 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0336","type":"single","qtype":"单选题","stem":"即时标记药品的亚批之间需（ ）","options":[{"key":"A","text":"仅连续生产"},{"key":"B","text":"明确区分，记录可追溯"},{"key":"C","text":"仅混合存放"},{"key":"D","text":"随意管理"}],"answer":["B"],"explanation":"即时标记药品的亚批之间需明确区分，记录可追溯，以确保在出现质量问题时能够准确追踪和处置。仅连续生产、仅混合存放、随意管理均不符合批次管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n亚批管理需明确区分，记录淋洗时间、活度、操作人员等，保证可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 336 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0337","type":"single","qtype":"单选题","stem":"放射性工作区的清洁工具不得用于（ ）","options":[{"key":"A","text":"放射性区域清洁"},{"key":"B","text":"非放射性区域清洁"},{"key":"C","text":"设备清洁"},{"key":"D","text":"地面清洁"}],"answer":["B"],"explanation":"放射性工作区的清洁工具不得用于非放射性区域清洁，以防止放射性污染通过清洁工具扩散到非放射性区域。用于放射性区域清洁、设备清洁、地面清洁均属于其正常用途。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n清洁工具需专用，与非放射性区域严格分开，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 337 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0338","type":"single","qtype":"单选题","stem":"放射性药品成品的放射性标志应（ ）","options":[{"key":"A","text":"不明显"},{"key":"B","text":"醒目，易于识别"},{"key":"C","text":"仅贴在内部"},{"key":"D","text":"仅贴在运输箱外"}],"answer":["B"],"explanation":"放射性药品成品的放射性标志应醒目，易于识别，以警示操作人员和患者注意辐射防护。不明显、仅贴在内部、仅贴在运输箱外均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n放射性标志应醒目、易于识别，确保警示效果。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 338 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0339","type":"single","qtype":"单选题","stem":"重复使用的包装容器清洗后需（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"检测确认无放射性污染"},{"key":"C","text":"仅晾干"},{"key":"D","text":"仅消毒"}],"answer":["B"],"explanation":"重复使用的包装容器清洗后需检测确认无放射性污染，方可再次使用。直接使用、仅晾干、仅消毒均不能保证容器无放射性残留。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n重复使用的包装容器需在专用去污场所清洗，并经放射性污染检测合格后方可再次使用。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 339 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0340","type":"single","qtype":"单选题","stem":"放射性药品生产过程中，清场记录需包含（ ）","options":[{"key":"A","text":"仅清场时间"},{"key":"B","text":"清场时间、人员、核素种类、清洁情况等"},{"key":"C","text":"仅清场人员"},{"key":"D","text":"仅核素种类"}],"answer":["B"],"explanation":"放射性药品生产过程中，清场记录需包含清场时间、人员、核素种类、清洁情况等信息，以确保清场效果可追溯，防止交叉污染。仅清场时间、仅清场人员、仅核素种类均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n清场记录需完整记录清场时间、人员、核素种类、清洁情况等，确保清场有效，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/331-340.md","merged":"单选题1-400.md","location":"第 340 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0341","type":"single","qtype":"单选题","stem":"即时标记药品若使用不同批号的配套药盒，即使同一发生器同日生产，也应定为（ ）","options":[{"key":"A","text":"一批"},{"key":"B","text":"不同批"},{"key":"C","text":"亚批"},{"key":"D","text":"随意"}],"answer":["B"],"explanation":"即时标记药品的批次划分与配套药盒的批号密切相关。若使用不同批号的配套药盒，即使采用同一钼[99Mo]-锝[99mTc]发生器在同一天生产，也应定为不同批。因为不同批号的药盒可能在生产时间、配体来源等方面存在差异，可能影响最终产品的质量均一性。一批、亚批、随意均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批的划分应确保产品均一性和可追溯性。使用不同批号配套药盒制备的即时标记药品，因原料批号不同，应划分为不同批次，分别记录和检验。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 341 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0342","type":"single","qtype":"单选题","stem":"放射性工作区的工作服清洗后需（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"监测确认无污染后使用"},{"key":"C","text":"仅熨烫"},{"key":"D","text":"仅折叠"}],"answer":["B"],"explanation":"放射性工作区的工作服清洗后需进行放射性污染监测，确认无污染后方可使用。直接使用、仅熨烫、仅折叠均不能保证工作服无放射性残留，可能导致污染扩散。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作服清洗后必须经污染监测合格方可再次使用，确保人员安全和防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 342 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0343","type":"single","qtype":"单选题","stem":"放射性药品说明书中，不需包含的内容是（ ）","options":[{"key":"A","text":"放射性核素半衰期"},{"key":"B","text":"辐射防护措施"},{"key":"C","text":"仅普通药品不良反应"},{"key":"D","text":"药品价格"}],"answer":["D"],"explanation":"放射性药品说明书需包含放射性核素半衰期、辐射防护措施、适应症、用法用量、不良反应等内容，但不需要包含药品价格。药品价格不属于说明书法定内容。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n说明书需包含放射性核素半衰期、辐射防护措施等专业信息，但药品价格不属于说明书内容。因此，选项D正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 343 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0344","type":"single","qtype":"单选题","stem":"放射性药品生产用器具的清洗规程需明确（ ）","options":[{"key":"A","text":"仅清洗步骤"},{"key":"B","text":"清洗步骤、去污方法、污染监测要求"},{"key":"C","text":"仅清洗剂种类"},{"key":"D","text":"仅清洗时间"}],"answer":["B"],"explanation":"放射性药品生产用器具的清洗规程需明确清洗步骤、去污方法、污染监测要求等内容，以确保清洗效果符合辐射防护和洁净要求。仅清洗步骤、仅清洗剂种类、仅清洗时间均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n清洗规程应涵盖清洗步骤、去污方法及污染监测要求，确保器具无放射性残留。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 344 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0345","type":"single","qtype":"单选题","stem":"即时标记药品的批次记录需保存（ ）","options":[{"key":"A","text":"仅1年"},{"key":"B","text":"至药品有效期后30天以上"},{"key":"C","text":"仅3个月"},{"key":"D","text":"随意"}],"answer":["B"],"explanation":"即时标记药品的批次记录需保存至药品有效期后30天以上，以确保在药品有效期内可追溯生产历史和质量情况。仅1年、仅3个月、随意保存均不符合记录保存要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n批次记录属于质量记录，需按规定保存至药品有效期后30天以上，保证可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 345 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0346","type":"single","qtype":"单选题","stem":"放射性工作区与非放射性工作区的更衣区应（ ）","options":[{"key":"A","text":"共用"},{"key":"B","text":"分开"},{"key":"C","text":"仅用帘子隔开"},{"key":"D","text":"无要求"}],"answer":["B"],"explanation":"放射性工作区与非放射性工作区的更衣区应分开设置，以防止放射性污染通过更衣过程扩散到非放射性区域。共用、仅用帘子隔开、无要求均不符合辐射防护和污染控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n更衣区需按区域分开设置，确保人员进出不同区域时更衣程序独立，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 346 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0347","type":"single","qtype":"单选题","stem":"放射性药品成品的包装需满足（ ）","options":[{"key":"A","text":"仅运输要求"},{"key":"B","text":"辐射防护、防破损及标识清晰"},{"key":"C","text":"仅储存要求"},{"key":"D","text":"仅美观"}],"answer":["B"],"explanation":"放射性药品成品的包装需满足辐射防护、防破损及标识清晰等要求，以确保运输和储存过程中的安全。仅运输要求、仅储存要求、仅美观均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十七条规定：放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n成品包装需具备辐射防护性能、防破损能力，并标识清晰。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 347 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0348","type":"single","qtype":"单选题","stem":"若同一操作箱需更换生产的核素品种，应（ ）","options":[{"key":"A","text":"直接更换"},{"key":"B","text":"彻底清场、去污，确认无残留后更换"},{"key":"C","text":"仅擦拭"},{"key":"D","text":"仅通风"}],"answer":["B"],"explanation":"若同一操作箱需更换生产的核素品种，应彻底清场、去污，确认无残留后更换，以防止不同核素之间的交叉污染。直接更换、仅擦拭、仅通风均不能有效去除放射性残留。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n更换核素品种前必须进行彻底清场和去污，并经污染监测确认无残留，防止交叉污染。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 348 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0349","type":"single","qtype":"单选题","stem":"放射性药品生产过程中，若工作服被污染，应（ ）","options":[{"key":"A","text":"继续穿着"},{"key":"B","text":"立即更换，进行去污处理"},{"key":"C","text":"仅晾晒"},{"key":"D","text":"仅清洗"}],"answer":["B"],"explanation":"放射性药品生产过程中，若工作服被污染，应立即更换，并进行去污处理，以防止放射性污染扩散和人员受到额外辐射。继续穿着、仅晾晒、仅清洗均不符合辐射防护要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n被污染的工作服需立即更换，并按规定进行去污处理，经监测合格后方可再次使用。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 349 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0350","type":"single","qtype":"单选题","stem":"即时标记药品的亚批管理中，同一发生器同日多次淋洗的关键记录是（ ）","options":[{"key":"A","text":"仅淋洗体积"},{"key":"B","text":"淋洗时间、活度、对应的亚批号"},{"key":"C","text":"仅操作人员"},{"key":"D","text":"仅药盒批号"}],"answer":["B"],"explanation":"即时标记药品的亚批管理中，同一发生器同日多次淋洗的关键记录包括淋洗时间、活度、对应的亚批号，以确保每次淋洗制备的产品可追溯。仅淋洗体积、仅操作人员、仅药盒批号均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n亚批管理需记录淋洗时间、活度、亚批号等关键信息，确保同一发生器多次淋洗制备的产品可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/341-350.md","merged":"单选题1-400.md","location":"第 350 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0351","type":"single","qtype":"单选题","stem":"放射性药品生产相关的确认和验证范围应通过（ ）确定","options":[{"key":"A","text":"仅经验判断"},{"key":"B","text":"风险管理方法，结合质量及辐射防护要求"},{"key":"C","text":"仅监管要求"},{"key":"D","text":"仅生产需求"}],"answer":["B"],"explanation":"放射性药品生产相关的确认和验证范围应通过风险管理方法确定，并结合质量及辐射防护要求。仅凭经验判断、仅监管要求、仅生产需求均不能全面识别验证需求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n确认和验证是药品GMP的核心要求，其范围应基于风险评估，综合考虑产品质量和辐射安全风险。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 351 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0352","type":"single","qtype":"单选题","stem":"使用自动合成设备和计算机软件控制系统生产放射性药品时，验证周期为（ ）","options":[{"key":"A","text":"仅首次使用前"},{"key":"B","text":"一年至少一次"},{"key":"C","text":"仅每两年一次"},{"key":"D","text":"无需验证"}],"answer":["B"],"explanation":"使用自动合成设备和计算机软件控制系统生产放射性药品时，验证周期为一年至少一次。定期验证可确保设备和系统持续符合生产工艺要求，保证产品质量稳定。仅首次使用前、仅每两年一次、无需验证均不符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据药品GMP及放射性药品附录，自动合成设备和计算机软件控制系统需定期验证，通常每年至少一次，确保合成效率、产品纯度和放射性活度准确。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 352 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0353","type":"single","qtype":"单选题","stem":"自动合成设备发生变更时，应（ ）","options":[{"key":"A","text":"直接使用"},{"key":"B","text":"进行重新验证"},{"key":"C","text":"仅记录变更"},{"key":"D","text":"仅通知监管部门"}],"answer":["B"],"explanation":"自动合成设备发生变更时，应进行重新验证，以确认变更后的设备仍能满足生产工艺和质量要求。直接使用、仅记录变更、仅通知监管部门均不能保证变更后的设备性能符合要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n设备变更属于变更控制范畴，需进行重新验证，确保设备性能持续符合要求。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 353 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0354","type":"single","qtype":"单选题","stem":"边检验边放行的放射性药品，需完成（ ）后方可放行","options":[{"key":"A","text":"仅部分检验"},{"key":"B","text":"规定的检验和放行审核，符合要求"},{"key":"C","text":"仅生产记录审核"},{"key":"D","text":"仅口头批准"}],"answer":["B"],"explanation":"边检验边放行的放射性药品，需完成规定的检验和放行审核，符合要求后方可放行。仅部分检验、仅生产记录审核、仅口头批准均不符合放行要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n边检验边放行需在完成规定检验和放行审核后，确认符合要求方可放行，确保药品安全有效。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 354 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0355","type":"single","qtype":"单选题","stem":"放射性药品在检验前可贮存一段时间，目的是（ ）","options":[{"key":"A","text":"等待销售"},{"key":"B","text":"使其衰变到适合实验操作的活度"},{"key":"C","text":"仅方便管理"},{"key":"D","text":"仅节省时间"}],"answer":["B"],"explanation":"放射性药品在检验前可贮存一段时间，目的是使其衰变到适合实验操作的活度，确保检验人员安全和测量准确性。等待销售、仅方便管理、仅节省时间均不是其目的。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n对于活度过高的放射性药品，贮存衰变至适宜活度后再检验，可降低人员受照剂量，符合辐射防护最优化原则。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 355 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0356","type":"single","qtype":"单选题","stem":"企业建立放射性药品追踪系统的目的是（ ）","options":[{"key":"A","text":"仅便于销售追踪"},{"key":"B","text":"及时发现和控制质量安全不良事件，提供临床信息"},{"key":"C","text":"仅便于生产计划"},{"key":"D","text":"仅便于采购"}],"answer":["B"],"explanation":"企业建立放射性药品追踪系统的目的是及时发现和控制质量安全不良事件，提供临床信息，保障患者安全。仅便于销售追踪、仅便于生产计划、仅便于采购均不是其核心目的。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n追踪系统应能覆盖生产、检验、放行、发运、使用环节，重点在于及时发现和控制质量安全不良事件，提供临床信息。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 356 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0357","type":"single","qtype":"单选题","stem":"放射性药品物料的留样量至少能满足（ ）","options":[{"key":"A","text":"全检需求"},{"key":"B","text":"鉴别需求"},{"key":"C","text":"仅外观检查"},{"key":"D","text":"仅含量测定"}],"answer":["B"],"explanation":"放射性药品物料的留样量至少能满足鉴别需求，以便在出现质量问题时进行追溯和初步鉴定。全检需求、仅外观检查、仅含量测定均不是物料留样的最低要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n物料留样量应至少满足鉴别需求，确保在质量调查时能够进行必要的鉴定。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 357 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0358","type":"single","qtype":"单选题","stem":"放射性药品成品的留样量应能满足（ ）","options":[{"key":"A","text":"注册批准质量标准2倍的全检量"},{"key":"B","text":"仅1倍全检量"},{"key":"C","text":"仅鉴别需求"},{"key":"D","text":"仅外观检查"}],"answer":["A"],"explanation":"放射性药品成品的留样量应能满足注册批准质量标准2倍的全检量，以确保在有效期内可进行完整的质量复核。仅1倍全检量、仅鉴别需求、仅外观检查均不符合留样量要求。因此，选项A正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n成品留样量应至少为注册批准质量标准2倍的全检量，以满足质量调查和复核需求。因此，选项A正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 358 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0359","type":"single","qtype":"单选题","stem":"放射性药品留样的保存时间应在（ ）","options":[{"key":"A","text":"药品有效期内"},{"key":"B","text":"药品有效期后30天以上"},{"key":"C","text":"仅1年"},{"key":"D","text":"仅3个月"}],"answer":["B"],"explanation":"放射性药品留样的保存时间应在药品有效期后30天以上，以确保在药品有效期内及之后一段时间内可追溯和复核质量。药品有效期内、仅1年、仅3个月均不符合留样保存要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n留样需保存至药品有效期后30天以上，满足质量追溯和调查需求。因此，选项B正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 359 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0360","type":"single","qtype":"单选题","stem":"企业发现患者受到放射性超剂量危害或出现药品不良反应时，不需做的是（ ）","options":[{"key":"A","text":"及时控制措施"},{"key":"B","text":"详细记录"},{"key":"C","text":"按规定上报"},{"key":"D","text":"仅隐瞒"}],"answer":["D"],"explanation":"企业发现患者受到放射性超剂量危害或出现药品不良反应时，需及时采取控制措施、详细记录并按规定上报，不得隐瞒。仅隐瞒是错误做法，不符合药品不良反应监测和报告制度。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品管理法》和《药品不良反应报告和监测管理办法》，发现药品不良反应或放射性超剂量危害时，必须及时报告，不得隐瞒。因此，选项D正确。\n\n---","source":{"file":"单选题/351-360.md","merged":"单选题1-400.md","location":"第 360 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0361","type":"single","qtype":"单选题","stem":"边检验边放行的放射性药品若发现质量问题，企业应（ ）","options":[{"key":"A","text":"仅记录"},{"key":"B","text":"立即通知使用单位停止使用"},{"key":"C","text":"仅继续生产"},{"key":"D","text":"仅降价销售"}],"answer":["B"],"explanation":"边检验边放行的放射性药品若发现质量问题，企业应立即通知使用单位停止使用，并采取召回等风险控制措施，防止危害扩大。仅记录、仅继续生产、仅降价销售均不符合药品质量管理和风险控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n边检验边放行是基于风险管理的放行方式，一旦发现质量问题，必须立即通知使用单位停止使用，并按规定进行召回和处置。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 361 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0362","type":"single","qtype":"单选题","stem":"不合格放射性药品、退回和召回产品的处置需在（ ）监督下进行","options":[{"key":"A","text":"生产部门"},{"key":"B","text":"质量管理部门"},{"key":"C","text":"销售部门"},{"key":"D","text":"采购部门"}],"answer":["B"],"explanation":"不合格放射性药品、退回和召回产品的处置需在质量管理部门监督下进行，以确保处置过程符合法规要求，防止不合格产品流入市场。生产部门、销售部门、采购部门均不具备质量监督职责。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不合格品、退回和召回产品的处置必须由质量管理部门监督，确保合规和安全。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 362 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0363","type":"single","qtype":"单选题","stem":"放射性药品的验证内容不包括（ ）","options":[{"key":"A","text":"生产工艺验证"},{"key":"B","text":"辐射防护效果验证"},{"key":"C","text":"仅设备外观验证"},{"key":"D","text":"清洁验证（含放射性残留）"}],"answer":["C"],"explanation":"放射性药品的验证内容包括生产工艺验证、辐射防护效果验证、清洁验证（含放射性残留）等，但不包括仅设备外观验证。设备外观验证不能证明设备性能和工艺符合要求。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n验证应覆盖生产工艺、辐射防护效果、清洁效果等关键环节，仅设备外观验证不属于验证内容。因此，选项C正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 363 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0364","type":"single","qtype":"单选题","stem":"计算机软件控制系统验证需重点确认（ ）","options":[{"key":"A","text":"仅软件版本"},{"key":"B","text":"数据可靠性、控制功能准确性"},{"key":"C","text":"仅软件界面"},{"key":"D","text":"仅安装位置"}],"answer":["B"],"explanation":"计算机软件控制系统验证需重点确认数据可靠性和控制功能准确性，以确保系统在生产过程中稳定、可靠地运行，保证产品质量。仅软件版本、仅软件界面、仅安装位置均不是验证重点。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n计算机化系统验证需确认数据完整性、控制功能准确性、安全性等，符合药品GMP计算机化系统附录要求。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 364 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0365","type":"single","qtype":"单选题","stem":"边检验边放行的风险评估需由（ ）完成","options":[{"key":"A","text":"生产部门"},{"key":"B","text":"质量管理部门"},{"key":"C","text":"销售部门"},{"key":"D","text":"行政部门"}],"answer":["B"],"explanation":"边检验边放行的风险评估需由质量管理部门完成，以确保评估过程科学、客观，放行决策基于充分的风险分析。生产部门、销售部门、行政部门均不具备质量风险评估的职责。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量管理部门负责药品全生命周期的质量管理和风险评估，边检验边放行的风险评估必须由其完成。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 365 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0366","type":"single","qtype":"单选题","stem":"放射性药品检验时，若活度过高影响操作，可（ ）","options":[{"key":"A","text":"直接放弃检验"},{"key":"B","text":"贮存至活度降低后检验"},{"key":"C","text":"仅粗略检验"},{"key":"D","text":"仅估算结果"}],"answer":["B"],"explanation":"放射性药品检验时，若活度过高影响操作，可贮存至活度降低后检验，以降低人员受照剂量，符合辐射防护最优化原则。直接放弃检验、仅粗略检验、仅估算结果均不符合质量控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n对于活度过高的样品，可适当贮存衰变至适宜活度后再检验，确保操作安全和结果准确。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 366 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0367","type":"single","qtype":"单选题","stem":"放射性药品追踪系统应能追踪（ ）","options":[{"key":"A","text":"仅生产环节"},{"key":"B","text":"生产、检验、放行、发运、使用环节"},{"key":"C","text":"仅销售环节"},{"key":"D","text":"仅采购环节"}],"answer":["B"],"explanation":"放射性药品追踪系统应能追踪生产、检验、放行、发运、使用环节，以实现全生命周期可追溯，便于质量安全事件的调查和控制。仅生产环节、仅销售环节、仅采购环节均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n追踪系统需覆盖药品从生产到使用的全过程，确保可追溯性。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 367 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0368","type":"single","qtype":"单选题","stem":"放射性药品留样的储存环境应与（ ）一致","options":[{"key":"A","text":"普通药品"},{"key":"B","text":"成品规定的储存条件"},{"key":"C","text":"仅常温"},{"key":"D","text":"仅冷藏"}],"answer":["B"],"explanation":"放射性药品留样的储存环境应与成品规定的储存条件一致，以确保留样在保存期内质量稳定，能够代表成品质量。普通药品、仅常温、仅冷藏均不准确。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n留样应按照成品规定的储存条件保存，确保其质量与成品一致。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 368 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0369","type":"single","qtype":"单选题","stem":"药品不良反应报告需包含的内容不包括（ ）","options":[{"key":"A","text":"事件经过"},{"key":"B","text":"评价、调查和处理"},{"key":"C","text":"仅患者姓名"},{"key":"D","text":"放射性剂量（若涉及超剂量）"}],"answer":["C"],"explanation":"药品不良反应报告需包含事件经过、评价、调查和处理等内容，但不包括仅患者姓名。仅患者姓名不能构成完整的不良反应报告。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不良反应报告需完整记录事件经过、评价、调查和处理等信息，患者姓名为辅助信息，不是报告的核心内容。因此，选项C正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 369 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0370","type":"single","qtype":"单选题","stem":"边检验边放行的放射性药品，需在放行后（ ）完成剩余检验","options":[{"key":"A","text":"无需完成"},{"key":"B","text":"尽快"},{"key":"C","text":"仅下次生产前"},{"key":"D","text":"仅监管检查前"}],"answer":["B"],"explanation":"边检验边放行的放射性药品，需在放行后尽快完成剩余检验，以确保产品最终质量符合要求。无需完成、仅下次生产前、仅监管检查前均不符合规定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n边检验边放行后，企业应尽快完成剩余检验项目，若发现不合格应立即采取风险控制措施。因此，选项B正确。\n\n---","source":{"file":"单选题/361-370.md","merged":"单选题1-400.md","location":"第 370 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0371","type":"single","qtype":"单选题","stem":"放射性药品的清洁验证中，放射性残留的可接受标准应（ ）","options":[{"key":"A","text":"随意制定"},{"key":"B","text":"基于辐射安全及药品质量要求制定"},{"key":"C","text":"仅参考普通药品"},{"key":"D","text":"仅凭经验"}],"answer":["B"],"explanation":"放射性药品的清洁验证中，放射性残留的可接受标准应基于辐射安全及药品质量要求制定。这是因为放射性残留不仅影响后续产品的质量，还直接关系到操作人员和患者的辐射安全，必须结合辐射防护限值和药品质量控制要求综合确定。随意制定、仅参考普通药品、仅凭经验均缺乏科学依据，不符合风险管理原则。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n清洁验证是质量管理制度的重要组成部分，放射性残留可接受标准需基于辐射安全及药品质量要求制定，确保清洁后设备无放射性残留，符合辐射防护和药品GMP要求。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 371 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0372","type":"single","qtype":"单选题","stem":"自动合成设备验证中，需确认的关键参数不包括（ ）","options":[{"key":"A","text":"合成效率"},{"key":"B","text":"放射性活度准确性"},{"key":"C","text":"仅设备噪音"},{"key":"D","text":"产物纯度"}],"answer":["C"],"explanation":"自动合成设备验证中，需确认的关键参数包括合成效率、放射性活度准确性、产物纯度等，但不包括仅设备噪音。设备噪音不属于影响药品质量和辐射安全的关键工艺参数，因此不是验证的重点内容。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n自动合成设备验证需确认与产品质量和辐射安全直接相关的参数，如合成效率、活度准确性、产物纯度等，设备噪音不属于关键参数。因此，选项C正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 372 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0373","type":"single","qtype":"单选题","stem":"放射性药品的放行审核需由（ ）批准","options":[{"key":"A","text":"生产负责人"},{"key":"B","text":"质量受权人"},{"key":"C","text":"销售负责人"},{"key":"D","text":"采购负责人"}],"answer":["B"],"explanation":"放射性药品的放行审核需由质量受权人批准。质量受权人负责药品全生命周期的质量审核和放行，确保产品符合注册标准、质量标准和辐射安全要求。生产负责人、销售负责人、采购负责人均不具备放行审核的职责和权限。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量受权人是药品放行的关键责任人，需对放射性药品的质量及辐射安全合规性进行审核并批准放行。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 373 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0374","type":"single","qtype":"单选题","stem":"放射性药品检验记录需包含（ ）","options":[{"key":"A","text":"仅检验结果"},{"key":"B","text":"检验方法、条件、结果及放射性活度测定时间"},{"key":"C","text":"仅检验人员"},{"key":"D","text":"仅检验日期"}],"answer":["B"],"explanation":"放射性药品检验记录需包含检验方法、条件、结果及放射性活度测定时间等信息，以确保检验过程可追溯，结果准确可靠。仅检验结果、仅检验人员、仅检验日期均不完整，无法满足数据完整性和可追溯性要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验记录是质量管理制度的重要文件，需完整记录检验方法、条件、结果及放射性活度测定时间，确保数据真实、准确、可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 374 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0375","type":"single","qtype":"单选题","stem":"放射性药品追踪系统在发现质量问题时，应能（ ）","options":[{"key":"A","text":"仅通知生产部门"},{"key":"B","text":"快速定位受影响产品，通知使用单位"},{"key":"C","text":"仅记录"},{"key":"D","text":"仅隐瞒"}],"answer":["B"],"explanation":"放射性药品追踪系统在发现质量问题时，应能快速定位受影响产品并通知使用单位，以便及时采取风险控制措施，防止危害扩大。仅通知生产部门、仅记录、仅隐瞒均不符合质量管理和风险控制要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n追踪系统应具备快速定位和通知功能，确保在质量问题时能及时控制风险，保障患者安全。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 375 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0376","type":"single","qtype":"单选题","stem":"放射性药品留样的标识应包含（ ）","options":[{"key":"A","text":"仅产品名称"},{"key":"B","text":"产品名称、批号、留样日期、有效期"},{"key":"C","text":"仅批号"},{"key":"D","text":"仅留样人员"}],"answer":["B"],"explanation":"放射性药品留样的标识应包含产品名称、批号、留样日期、有效期等信息，以确保留样可追溯，便于质量调查和复核。仅产品名称、仅批号、仅留样人员均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n留样标识需完整记录产品名称、批号、留样日期、有效期等，确保可追溯性。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 376 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0377","type":"single","qtype":"单选题","stem":"患者出现放射性药品不良反应后，企业应向（ ）上报","options":[{"key":"A","text":"仅上级领导"},{"key":"B","text":"相关监管部门"},{"key":"C","text":"仅医院"},{"key":"D","text":"仅患者家属"}],"answer":["B"],"explanation":"患者出现放射性药品不良反应后，企业应向相关监管部门上报，以便监管部门及时掌握风险信息并采取控制措施。仅上级领导、仅医院、仅患者家属均不能替代监管部门的报告要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《药品管理法》和《药品不良反应报告和监测管理办法》，发现药品不良反应应按规定向监管部门报告。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 377 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0378","type":"single","qtype":"单选题","stem":"退回的放射性药品需（ ）","options":[{"key":"A","text":"直接重新销售"},{"key":"B","text":"经质量评估，符合要求方可处理"},{"key":"C","text":"仅丢弃"},{"key":"D","text":"仅重新包装"}],"answer":["B"],"explanation":"退回的放射性药品需经质量评估，符合要求后方可处理。直接重新销售、仅丢弃、仅重新包装均不符合质量管理和辐射安全要求。退回产品可能因储存、运输条件不当导致质量变化，必须重新评估。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n退回产品需经质量评估，确认符合质量标准后方可再销售或处理，确保药品安全有效。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 378 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0379","type":"single","qtype":"单选题","stem":"放射性药品的质量标准需包含（ ）","options":[{"key":"A","text":"仅普通药品项目"},{"key":"B","text":"放射性核素鉴别、活度、纯度及辐射安全相关项目"},{"key":"C","text":"仅含量测定"},{"key":"D","text":"仅外观"}],"answer":["B"],"explanation":"放射性药品的质量标准需包含放射性核素鉴别、活度、纯度及辐射安全相关项目，以确保药品的安全性和有效性。仅普通药品项目、仅含量测定、仅外观均不能全面控制放射性药品的质量。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第二条规定：放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条规定：研制单位在制订新药工艺路线的同时，必须研究该药的理化性能、纯度（包括核素纯度）及检验方法、放射性比活度、剂量、剂型、稳定性等。\n因此，放射性药品质量标准必须包含核素鉴别、活度、纯度及辐射安全相关项目，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 379 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0380","type":"single","qtype":"单选题","stem":"放射性药品的验证记录需保存（ ）","options":[{"key":"A","text":"仅1年"},{"key":"B","text":"至药品有效期后30天以上或规定期限"},{"key":"C","text":"仅3个月"},{"key":"D","text":"随意"}],"answer":["B"],"explanation":"放射性药品的验证记录需保存至药品有效期后30天以上或规定期限，以确保在药品有效期内及之后可追溯验证状态，满足质量管理和监管要求。仅1年、仅3个月、随意保存均不符合记录保存规定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n验证记录属于质量记录，需按规定保存至药品有效期后30天以上或规定期限，确保可追溯。因此，选项B正确。\n\n---","source":{"file":"单选题/371-380.md","merged":"单选题1-400.md","location":"第 380 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0381","type":"single","qtype":"单选题","stem":"企业取得《辐射安全许可证》的依据是（ ）","options":[{"key":"A","text":"《药品管理法》"},{"key":"B","text":"《放射性同位素与射线装置安全和防护条例》"},{"key":"C","text":"仅企业申请"},{"key":"D","text":"仅地方规定"}],"answer":["B"],"explanation":"企业取得《辐射安全许可证》的直接法律依据是《放射性同位素与射线装置安全和防护条例》。该条例规定，生产、销售、使用放射性同位素和射线装置的单位，应当取得辐射安全许可证。放射性药品生产涉及放射性核素和射线装置，因此必须取得该许可证。《药品管理法》是药品管理的基本法律，但不是辐射安全许可的直接依据；仅企业申请或仅地方规定均不能作为法定依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产、销售、使用放射性同位素和射线装置的单位，应当事先向环境保护主管部门申请领取许可证。放射性药品生产企业属于此类单位，因此《辐射安全许可证》的取得依据为《放射性同位素与射线装置安全和防护条例》。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 381 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0382","type":"single","qtype":"单选题","stem":"《辐射安全许可证》是放射性药品企业（ ）的必备文件","options":[{"key":"A","text":"仅生产"},{"key":"B","text":"生产、销售、使用、运输、储存放射性药品"},{"key":"C","text":"仅销售"},{"key":"D","text":"仅采购"}],"answer":["B"],"explanation":"《辐射安全许可证》是放射性药品企业从事生产、销售、使用、运输、储存放射性药品等活动的必备文件。因为上述环节均涉及放射性同位素或射线装置，属于辐射安全管理范畴。仅生产、仅销售、仅采购均不完整。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第三条规定：凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n《放射性药品管理办法》第十条要求企业具有安全、防护和废气、废物、废水处理等设施。结合《放射性同位素与射线装置安全和防护条例》，从事放射性药品生产、销售、使用、运输、储存等活动的单位，均需取得《辐射安全许可证》。因此，选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 382 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0383","type":"single","qtype":"单选题","stem":"企业需对（ ）进行辐射剂量监测","options":[{"key":"A","text":"仅生产人员"},{"key":"B","text":"生产、检验、维修等相关人员"},{"key":"C","text":"仅管理人员"},{"key":"D","text":"仅销售人员"}],"answer":["B"],"explanation":"企业需对生产、检验、维修等相关人员进行辐射剂量监测，因为这些人员在工作过程中可能接触到放射性物质或射线装置，存在辐射暴露风险。仅生产人员、仅管理人员、仅销售人员均不全面。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，从事放射性工作的人员必须进行个人剂量监测。生产、检验、维修等岗位均可能接触辐射，因此均需纳入监测范围。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 383 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0384","type":"single","qtype":"单选题","stem":"辐射剂量监测结果需（ ）","options":[{"key":"A","text":"仅口头告知员工"},{"key":"B","text":"记录存档，定期评估"},{"key":"C","text":"仅丢弃"},{"key":"D","text":"仅上报领导"}],"answer":["B"],"explanation":"辐射剂量监测结果需记录存档并定期评估，以掌握人员的辐射暴露趋势，及时发现异常并采取防护措施。仅口头告知、仅丢弃、仅上报领导均不符合辐射安全管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，个人剂量监测结果应记录存档，并定期评估，确保人员受照剂量符合国家限值。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 384 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0385","type":"single","qtype":"单选题","stem":"企业需按规定对相关人员进行（ ）","options":[{"key":"A","text":"仅普通体检"},{"key":"B","text":"职业健康体检"},{"key":"C","text":"仅辐射知识培训"},{"key":"D","text":"仅操作培训"}],"answer":["B"],"explanation":"企业需按规定对相关人员进行职业健康体检，以监测辐射对健康的潜在影响，保障从业人员职业健康。仅普通体检、仅辐射知识培训、仅操作培训均不能替代职业健康体检。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》和《职业病防治法》，从事放射性工作的人员必须定期进行职业健康体检，建立职业健康监护档案。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 385 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0386","type":"single","qtype":"单选题","stem":"从事放射性药品生产操作人员，必须配备（ ）","options":[{"key":"A","text":"仅普通工作服"},{"key":"B","text":"符合要求的辐射防护用品"},{"key":"C","text":"仅手套"},{"key":"D","text":"仅安全帽"}],"answer":["B"],"explanation":"从事放射性药品生产操作人员必须配备符合要求的辐射防护用品，如铅衣、铅眼镜、辐射剂量计等，以降低辐射暴露风险。仅普通工作服、仅手套、仅安全帽均不能提供有效的辐射防护。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，从事放射性工作的人员必须配备符合要求的辐射防护用品，并正确佩戴和使用。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 386 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0387","type":"single","qtype":"单选题","stem":"辐射防护用品不包括（ ）","options":[{"key":"A","text":"铅衣"},{"key":"B","text":"铅眼镜"},{"key":"C","text":"辐射剂量计"},{"key":"D","text":"普通衬衫"}],"answer":["D"],"explanation":"辐射防护用品包括铅衣、铅眼镜、辐射剂量计等，用于屏蔽射线或监测辐射剂量。普通衬衫不具备辐射防护性能，因此不属于辐射防护用品。选项A、B、C均属于辐射防护用品。因此，选项D正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射防护用品需具备屏蔽或监测辐射的功能，普通衬衫不能满足防护要求，不属于辐射防护用品。选项D正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 387 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0388","type":"single","qtype":"单选题","stem":"企业需配备（ ）用于收集放射性废物","options":[{"key":"A","text":"普通垃圾桶"},{"key":"B","text":"放射性废物专用容器"},{"key":"C","text":"仅塑料袋"},{"key":"D","text":"仅纸箱"}],"answer":["B"],"explanation":"企业需配备放射性废物专用容器用于收集放射性废物，该容器需具备辐射防护性能并明确标识。普通垃圾桶、仅塑料袋、仅纸箱均不能提供辐射防护和防泄漏功能。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物专用容器需具备辐射防护性能，并按核素种类、半衰期等分类收集。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 388 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0389","type":"single","qtype":"单选题","stem":"放射性废物的贮存和处理应符合（ ）","options":[{"key":"A","text":"企业内部规定"},{"key":"B","text":"国家有关放射性废物管理规定"},{"key":"C","text":"仅地方习惯"},{"key":"D","text":"仅随意处置"}],"answer":["B"],"explanation":"放射性废物的贮存和处理应符合国家有关放射性废物管理规定，确保环境安全和人员健康。企业内部规定、仅地方习惯、仅随意处置均不能替代国家法规要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物必须按照国家放射性废物管理规定进行贮存和处理，确保符合辐射安全和环境保护要求。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 389 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0390","type":"single","qtype":"单选题","stem":"《辐射安全许可证》的有效期需（ ）","options":[{"key":"A","text":"无需关注"},{"key":"B","text":"定期核查，确保在有效期内"},{"key":"C","text":"仅到期后更换"},{"key":"D","text":"仅首次申请"}],"answer":["B"],"explanation":"《辐射安全许可证》的有效期需定期核查，确保在有效期内，避免因许可证过期导致违法生产或经营。无需关注、仅到期后更换、仅首次申请均不符合合规管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，辐射安全许可证有有效期，持证单位需在有效期届满前申请延续，并定期核查许可证状态。选项B正确。\n\n---","source":{"file":"单选题/381-390.md","merged":"单选题1-400.md","location":"第 390 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0391","type":"single","qtype":"单选题","stem":"辐射剂量监测的频次应（ ）","options":[{"key":"A","text":"随意"},{"key":"B","text":"符合国家辐射安全管理规定"},{"key":"C","text":"仅每月一次"},{"key":"D","text":"仅每年一次"}],"answer":["B"],"explanation":"辐射剂量监测的频次应符合国家辐射安全管理规定，根据人员接触辐射的剂量水平和风险程度确定监测周期，不能随意设定，也不能固定为仅每月一次或仅每年一次。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，从事放射性工作的人员必须定期进行个人剂量监测，监测频次应符合国家辐射安全管理规定。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 391 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0392","type":"single","qtype":"单选题","stem":"职业健康体检的周期应（ ）","options":[{"key":"A","text":"仅入职时一次"},{"key":"B","text":"按国家职业健康管理规定执行"},{"key":"C","text":"仅每三年一次"},{"key":"D","text":"无需定期"}],"answer":["B"],"explanation":"职业健康体检的周期应按国家职业健康管理规定执行，根据人员接触的职业病危害因素种类和程度确定检查周期。仅入职时一次、仅每三年一次、无需定期均不符合规定。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《职业病防治法》和《放射性同位素与射线装置安全和防护条例》，从事放射性工作的人员必须定期进行职业健康体检，检查周期按国家职业健康管理规定执行。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 392 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0393","type":"single","qtype":"单选题","stem":"辐射防护用品的使用需（ ）","options":[{"key":"A","text":"随意佩戴"},{"key":"B","text":"按操作规程，正确佩戴和维护"},{"key":"C","text":"仅检查时佩戴"},{"key":"D","text":"仅领导在场时佩戴"}],"answer":["B"],"explanation":"辐射防护用品的使用需按操作规程正确佩戴和维护，确保其防护性能有效发挥。随意佩戴、仅检查时佩戴、仅领导在场时佩戴均不能保证防护效果。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，辐射防护用品应按规定正确使用和维护，确保防护有效性。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 393 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0394","type":"single","qtype":"单选题","stem":"放射性废物专用容器需（ ）","options":[{"key":"A","text":"仅美观"},{"key":"B","text":"具备辐射防护性能，明确标识"},{"key":"C","text":"仅轻便"},{"key":"D","text":"仅大容量"}],"answer":["B"],"explanation":"放射性废物专用容器需具备辐射防护性能并明确标识，以屏蔽射线、防止泄漏，并警示人员注意辐射风险。仅美观、仅轻便、仅大容量均不能满足辐射防护和安全管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物专用容器需具备辐射防护性能，并设置明显的放射性标志，符合国家放射性废物管理规定。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 394 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0395","type":"single","qtype":"单选题","stem":"放射性废液的处理需（ ）","options":[{"key":"A","text":"直接排放"},{"key":"B","text":"按国家规定处理，达标后排放"},{"key":"C","text":"仅倒入下水道"},{"key":"D","text":"仅储存"}],"answer":["B"],"explanation":"放射性废液的处理需按国家规定处理，达标后方可排放，以防止环境污染和公众辐射危害。直接排放、仅倒入下水道、仅储存均不符合放射性废物管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废液必须按照国家放射性废物管理规定进行处理，经监测达标后方可排放。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 395 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0396","type":"single","qtype":"单选题","stem":"企业需建立（ ）制度管理辐射安全","options":[{"key":"A","text":"仅口头"},{"key":"B","text":"书面的辐射安全管理制度和操作规程"},{"key":"C","text":"仅简单记录"},{"key":"D","text":"无需制度"}],"answer":["B"],"explanation":"企业需建立书面的辐射安全管理制度和操作规程，以规范辐射安全管理，确保各项防护措施有效落实。仅口头、仅简单记录、无需制度均不符合辐射安全管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同时，根据《放射性同位素与射线装置安全和防护条例》，生产、使用放射性同位素和射线装置的单位应当建立辐射安全管理制度和操作规程。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 396 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0397","type":"single","qtype":"单选题","stem":"辐射安全管理制度不包括（ ）","options":[{"key":"A","text":"放射性核素管理"},{"key":"B","text":"辐射剂量监测"},{"key":"C","text":"仅产品销售"},{"key":"D","text":"辐射事故应急"}],"answer":["C"],"explanation":"辐射安全管理制度包括放射性核素管理、辐射剂量监测、辐射事故应急等内容，但不包括仅产品销售。产品销售属于经营管理范畴，不是辐射安全管理制度的核心内容。因此，选项C正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射安全管理制度应涵盖放射性核素管理、剂量监测、事故应急等，产品销售不属于其内容。因此，选项C正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 397 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0398","type":"single","qtype":"单选题","stem":"若辐射剂量监测发现超标，企业应（ ）","options":[{"key":"A","text":"仅记录"},{"key":"B","text":"立即采取措施，评估影响，整改"},{"key":"C","text":"仅隐瞒"},{"key":"D","text":"仅通知员工"}],"answer":["B"],"explanation":"若辐射剂量监测发现超标，企业应立即采取措施，评估影响，并进行整改，以降低人员受照剂量并防止再次发生。仅记录、仅隐瞒、仅通知员工均不符合辐射安全管理要求。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n根据《放射性同位素与射线装置安全和防护条例》，发现辐射剂量超标时，应立即调查原因，采取措施整改，并按规定报告。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 398 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0399","type":"single","qtype":"单选题","stem":"放射性废物的分类收集需根据（ ）","options":[{"key":"A","text":"仅体积"},{"key":"B","text":"放射性核素种类、活度、半衰期等"},{"key":"C","text":"仅颜色"},{"key":"D","text":"仅重量"}],"answer":["B"],"explanation":"放射性废物的分类收集需根据放射性核素种类、活度、半衰期等因素进行，以便采取不同的贮存和处置措施，确保辐射安全。仅体积、仅颜色、仅重量均不能作为分类收集的科学依据。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物需按核素种类、活度、半衰期等分类收集，短半衰期废物可衰变贮存，长半衰期废物需按规定处置。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 399 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-S-0400","type":"single","qtype":"单选题","stem":"企业需定期对辐射防护设施进行（ ）","options":[{"key":"A","text":"仅外观检查"},{"key":"B","text":"检查和维护，确保防护效果"},{"key":"C","text":"仅更换"},{"key":"D","text":"无需维护"}],"answer":["B"],"explanation":"企业需定期对辐射防护设施进行检查和维护，确保其防护效果持续有效。仅外观检查、仅更换、无需维护均不能保证设施始终处于良好状态。因此，选项B正确。","lawTitle":"《放射性药品管理法》相关条例","law":"《放射性药品管理办法》第十条规定：放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射防护设施需定期检查和维护，确保屏蔽、通风、去污等防护功能有效，符合国家辐射防护标准。因此，选项B正确。\n\n---","source":{"file":"单选题/391-400.md","merged":"单选题1-400.md","location":"第 400 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0001","type":"multiple","qtype":"多选题","stem":"以下属于《放射性药品生产检查指南（试行）》检查依据的有（ ）","options":[{"key":"A","text":"《中华人民共和国药品管理法》（2019年修订）"},{"key":"B","text":"《放射性药品管理办法》（2022年修订）"},{"key":"C","text":"《中华人民共和国药典》（2020年版）"},{"key":"D","text":"《药品生产质量管理规范（2010年修订）》及其附录"},{"key":"E","text":"《药品经营质量管理规范》"}],"answer":["A","B","C","D"],"explanation":"《放射性药品生产检查指南（试行）》的检查依据明确包括《中华人民共和国药品管理法》（2019年修订）、《放射性药品管理办法》（2022年修订）、《中华人民共和国药典》（2020年版）以及《药品生产质量管理规范（2010年修订）》及其附录。选项E《药品经营质量管理规范》主要规范流通环节，不属于生产检查的直接依据。","lawTitle":"《放射性药品管理办法》相关条例","law":"第一条　为了加强放射性药品的管理，根据《中华人民共和国药品管理法》（以下称《药品管理法》）的规定，制定本办法。\n\n第三条　凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n\n第四条　国务院药品监督管理部门负责全国放射性药品监督管理工作。国务院国防科技工业主管部门依据职责负责与放射性药品有关的管理工作。国务院环境保护主管部门负责与放射性药品有关的辐射安全与防护的监督管理工作。\n\n因此，放射性药品生产检查的依据涵盖《药品管理法》《放射性药品管理办法》《中国药典》及GMP附录中针对放射性药品的特殊要求。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 1 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0002","type":"multiple","qtype":"多选题","stem":"放射性药品的特点包括（ ）","options":[{"key":"A","text":"放射性"},{"key":"B","text":"不恒定性"},{"key":"C","text":"自辐射分解"},{"key":"D","text":"化学量少"},{"key":"E","text":"恒定性"}],"answer":["A","B","C","D"],"explanation":"放射性药品具有放射性、不恒定性（因核素衰变导致）、自辐射分解（辐射导致自身化学结构改变）和化学量少（通常为微量）等显著特点。选项E“恒定性”与放射性药品因放射性衰变导致的不恒定性直接矛盾，因此不属于其特点。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n\n该定义揭示了放射性药品的核心特征——含有放射性核素。由于核素不断衰变，药品的放射性活度随时间变化，导致不恒定性；辐射能量可引发自身化学结构改变（自辐射分解）；且放射性药品中活性成分的化学量通常极少（常为微克或纳克级），需依靠放射性活度而非化学量来衡量。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 2 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0003","type":"multiple","qtype":"多选题","stem":"适用本指南的放射性药品包括（ ）","options":[{"key":"A","text":"医用放射性核素发生器及其配套药盒"},{"key":"B","text":"即时标记放射性药品"},{"key":"C","text":"正电子类放射性药品"},{"key":"D","text":"放射性体内植入制品"},{"key":"E","text":"普通化学药品"}],"answer":["A","B","C","D"],"explanation":"该指南适用的放射性药品包括医用放射性核素发生器及其配套药盒、即时标记放射性药品、正电子类放射性药品以及放射性体内植入制品。普通化学药品不属于放射性药品范畴，因此不适用该指南。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n\n第三条　凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n\n根据上述定义，医用放射性核素发生器及其配套药盒、即时标记药品、正电子类药品、体内植入制品均属于“放射性核素制剂或者其标记药物”的范畴，适用本指南。普通化学药品不含放射性核素，不属于放射性药品，不适用本指南。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 3 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0004","type":"multiple","qtype":"多选题","stem":"放射性药品生产的核心环节包括（ ）","options":[{"key":"A","text":"放射性核素的生产"},{"key":"B","text":"配体的生产"},{"key":"C","text":"放射性核素与配体的结合"},{"key":"D","text":"药品广告推广"},{"key":"E","text":"药品销售渠道搭建"}],"answer":["A","B","C"],"explanation":"放射性药品生产的核心环节包括放射性核素的生产、配体的生产以及放射性核素与配体的结合。药品广告推广和销售渠道搭建属于市场行为，不属于生产核心环节，因此选A、B、C。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续……无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n\n第十二条　放射性药品生产企业生产已有国家标准的放射性药品，必须经国务院药品监督管理部门征求国务院国防科技工业主管部门意见后审核批准，并发给批准文号。凡是改变国务院药品监督管理部门已批准的生产工艺路线和药品标准的，生产单位必须按原报批程序提出补充申请，经国务院药品监督管理部门批准后方能生产。\n\n上述条款表明，放射性药品生产的核心在于核素制备、配体合成及标记结合等工艺环节，广告推广和销售不属于生产监管的核心范畴。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 4 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0005","type":"multiple","qtype":"多选题","stem":"钼[99Mo]-锝[99mTc]发生器的特点包括（ ）","options":[{"key":"A","text":"俗称“母牛”"},{"key":"B","text":"用于生产锝[99mTc]"},{"key":"C","text":"需装入铅罐屏蔽射线"},{"key":"D","text":"淋洗液为0.9%氯化钠注射液"},{"key":"E","text":"可直接生产氟[18F]"}],"answer":["A","B","C","D"],"explanation":"钼[99Mo]-锝[99mTc]发生器俗称“母牛”，用于生产锝[99mTc]，淋洗液为0.9%氯化钠注射液，且需装入铅罐屏蔽射线。氟[18F]通常通过回旋加速器生产，不能由该发生器直接生产，因此E项错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十七条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分……\n\n医用放射性核素发生器属于放射性药品，其铅罐屏蔽是“与放射性剂量相适应的防护装置”的具体体现。第十条要求生产企业“符合国家有关放射性同位素安全和防护的规定与标准”，屏蔽射线是辐射安全防护的基本要求。氟[18F]属于正电子类放射性药品，需通过加速器制备，不适用母牛发生器。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 5 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0006","type":"multiple","qtype":"多选题","stem":"锝[99mTc]配套药盒的处方组成包括（ ）","options":[{"key":"A","text":"配体"},{"key":"B","text":"还原剂"},{"key":"C","text":"赋形剂"},{"key":"D","text":"稳定剂"},{"key":"E","text":"放射性核素"}],"answer":["A","B","C","D"],"explanation":"锝[99mTc]配套药盒的处方组成包括配体、还原剂、赋形剂和稳定剂。放射性核素（如锝[99mTc]）是在使用时通过淋洗发生器加入的，不属于药盒本身的处方组成，因此E项错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n\n配套药盒本身不含放射性核素，需与淋洗得到的锝[99mTc]洗脱液配合使用才能生成放射性药品。第五条规定，研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究，体现了药盒作为“待标记”制剂的特殊性。放射性核素在临用前加入，是即时标记药品的典型工艺特征。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 6 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0007","type":"multiple","qtype":"多选题","stem":"以下属于《中国药典》（2020年版）收录的锝[99mTc]放射性药品的有（ ）","options":[{"key":"A","text":"高锝[99mTc]酸钠注射液"},{"key":"B","text":"锝[99mTc]甲氧异腈注射液"},{"key":"C","text":"氟[18F]脱氧葡糖注射液"},{"key":"D","text":"碘[125I]密封籽源"},{"key":"E","text":"磷[32P]酸钠盐口服溶液"}],"answer":["A","B"],"explanation":"根据《中国药典》（2020年版），收录的锝[99mTc]放射性药品包括高锝[99mTc]酸钠注射液和锝[99mTc]甲氧异腈注射液。其他选项虽为放射性药品，但未收录于该版药典，因此选A、B。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十二条　放射性药品生产企业生产已有国家标准的放射性药品，必须经国务院药品监督管理部门征求国务院国防科技工业主管部门意见后审核批准，并发给批准文号。\n\n《中国药典》是国家药品标准的核心组成部分。高锝[99mTc]酸钠注射液和锝[99mTc]甲氧异腈注射液作为已有国家标准的锝[99mTc]放射性药品，被收录于2020年版药典。其他选项虽为合法放射性药品，但未收入该版药典正文品种。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 7 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0008","type":"multiple","qtype":"多选题","stem":"正电子类放射性药品氟[18F]脱氧葡糖注射液的制备涉及（ ）","options":[{"key":"A","text":"加速器制备氟[18F]离子"},{"key":"B","text":"阴离子交换柱（QMA柱）捕获氟[18F]"},{"key":"C","text":"氨基聚醚（K2.2.2）+K2CO3混合液洗脱"},{"key":"D","text":"0.22μm滤膜除菌过滤"},{"key":"E","text":"淋洗液为0.9%氯化钠注射液"}],"answer":["A","B","C","D"],"explanation":"在氟[18F]脱氧葡糖注射液的制备中，加速器制备的氟[18F]离子被阴离子交换柱（QMA柱）捕获，然后用氨基聚醚（K2.2.2）+K2CO3混合液洗脱，最后经0.22μm滤膜除菌过滤。0.9%氯化钠注射液是淋洗液，用于淋洗锝[99mTc]发生器，而非洗脱氟[18F]离子。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准。\n\n正电子类放射性药品的生产需符合辐射安全防护要求。氟[18F]离子由回旋加速器制备，整个合成过程在屏蔽热室内进行，自动合成模块需定期验证。QMA柱捕获和K2.2.2/K2CO3洗脱是氟[18F]标记脱氧葡糖的标准工艺步骤，0.22μm滤膜除菌过滤确保注射液无菌。0.9%氯化钠注射液淋洗适用于锝[99mTc]发生器，与氟[18F]制备无关。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 8 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0009","type":"multiple","qtype":"多选题","stem":"氯化锶[89Sr]注射液的生产工艺包括（ ）","options":[{"key":"A","text":"配制（C级洁净区）"},{"key":"B","text":"分装（C级洁净区）"},{"key":"C","text":"121℃最终灭菌"},{"key":"D","text":"淋洗操作"},{"key":"E","text":"标记反应"}],"answer":["A","B","C"],"explanation":"氯化锶[89Sr]注射液的生产工艺包括配制（C级洁净区）、分装（C级洁净区）和121℃最终灭菌。它不涉及淋洗操作和标记反应，标记反应通常用于即时标记放射性药品，淋洗用于发生器，因此选A、B、C。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准。\n\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n\n氯化锶[89Sr]注射液为最终灭菌的无菌注射剂，其生产工艺采用配制、分装后121℃湿热灭菌，确保无菌保证水平。淋洗操作属于放射性核素发生器使用环节，标记反应属于即时标记药品或正电子类药品的制备环节，均不适用于氯化锶[89Sr]注射液的生产。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 9 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0010","type":"multiple","qtype":"多选题","stem":"碘[125I]密封籽源的核心组成包括（ ）","options":[{"key":"A","text":"吸附碘[125I]的银丝或钯丝"},{"key":"B","text":"医用钛或钛合金管"},{"key":"C","text":"放射性核素溶液"},{"key":"D","text":"塑料载体"},{"key":"E","text":"稳定剂"}],"answer":["A","B"],"explanation":"碘[125I]密封籽源的核心组成包括吸附碘[125I]的银丝或钯丝，以及医用钛或钛合金管。它不使用塑料载体，也不包含放射性核素溶液（碘[125I]被吸附在银丝或钯丝上），因此C、D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n\n第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准。\n\n碘[125I]密封籽源属于放射性体内植入制品，其结构为将吸附碘[125I]的银丝或钯丝密封于医用钛管中，形成密封源。这种设计确保放射性物质不泄漏，符合辐射安全防护要求。放射性核素以吸附形式存在，并非溶液状态；密封源不使用塑料载体和稳定剂。\n\n---","source":{"file":"多选题/1-10.md","merged":"多选题1-110.md","location":"第 10 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0011","type":"multiple","qtype":"多选题","stem":"以下属于放射性药品口服溶液剂的有（ ）","options":[{"key":"A","text":"磷[32P]酸钠盐口服溶液"},{"key":"B","text":"碘[131I]化钠口服溶液"},{"key":"C","text":"尿素[14C]胶囊"},{"key":"D","text":"锝[99mTc]甲氧异腈注射液"},{"key":"E","text":"氯化锶[89Sr]注射液"}],"answer":["A","B"],"explanation":"放射性药品口服溶液剂是指以口服溶液形式给药的放射性药品。磷[32P]酸钠盐口服溶液和碘[131I]化钠口服溶液均属于口服溶液剂。尿素[14C]胶囊为胶囊剂，锝[99mTc]甲氧异腈注射液为注射剂，氯化锶[89Sr]注射液也为注射剂，故C、D、E不属于口服溶液剂。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n口服溶液剂作为放射性药品的一种剂型，其生产、包装需符合上述规定，并确保患者口服使用的安全性和辐射防护要求。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 11 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0012","type":"multiple","qtype":"多选题","stem":"体外放射性诊断试剂按原理可分为（ ）","options":[{"key":"A","text":"放射免疫分析法（RIA）"},{"key":"B","text":"免疫放射分析法（IRMA）"},{"key":"C","text":"酶联免疫法"},{"key":"D","text":"化学发光法"},{"key":"E","text":"胶体金法"}],"answer":["A","B"],"explanation":"体外放射性诊断试剂按原理主要分为放射免疫分析法（RIA）和免疫放射分析法（IRMA）。酶联免疫法、化学发光法和胶体金法属于非放射性免疫分析方法，不属于放射性诊断试剂范畴。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n该条款明确将放射免疫分析药盒纳入放射性药品管理，要求进行方法学研究。RIA和IRMA均使用放射性核素标记，属于体外放射性诊断试剂，需遵守放射性药品的研制、生产、经营和使用规定。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 12 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0013","type":"multiple","qtype":"多选题","stem":"放射免疫分析法（RIA）的原理涉及（ ）","options":[{"key":"A","text":"抗原与碘[125I]标记抗原竞争结合抗体"},{"key":"B","text":"碘[125I]标记抗原-抗体复合物与待测抗原含量呈逆相关"},{"key":"C","text":"标记抗体而非抗原"},{"key":"D","text":"非竞争性全量反应"},{"key":"E","text":"无需分离剂"}],"answer":["A","B"],"explanation":"放射免疫分析法（RIA）的原理是抗原与碘[125I]标记抗原竞争结合抗体，标记抗原-抗体复合物的量与待测抗原含量呈逆相关。RIA标记的是抗原而非抗体，属于竞争性反应，且需要分离剂将结合与游离的标记抗原分开，故C、D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\nRIA作为放射免疫分析药盒的典型原理，其方法学研究需涵盖竞争结合、分离剂选择、标准曲线绘制等关键环节。该条款要求确保分析方法的可靠性和准确性，从而保证体外诊断结果的临床有效性。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 13 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0014","type":"multiple","qtype":"多选题","stem":"放射性药品生产厂房设施的总体要求包括（ ）","options":[{"key":"A","text":"位置与《辐射安全许可证》“涉源部门”地址一致"},{"key":"B","text":"放射性与非放射性工作区有效隔离"},{"key":"C","text":"放射性核素操作区保持相对负压"},{"key":"D","text":"不同核素操作区严格分开"},{"key":"E","text":"放射性场所空气必须循环使用"}],"answer":["A","B","C","D"],"explanation":"放射性药品生产厂房设施要求包括：位置与《辐射安全许可证》“涉源部门”地址一致；放射性与非放射性工作区有效隔离；放射性核素操作区保持相对负压；不同核素操作区严格分开。放射性场所空气不应随意循环使用，需经风险评估并采取有效措施，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n厂房设施必须与辐射安全许可证载明的涉源地址一致，并满足放射性与非放射性隔离、相对负压、不同核素分开等要求，以防止交叉污染和放射性扩散。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 14 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0015","type":"multiple","qtype":"多选题","stem":"“C级背景下的局部A级”洁净区适用的操作有（ ）","options":[{"key":"A","text":"非最终灭菌小容量注射剂的灌装"},{"key":"B","text":"即时标记放射性药品的标记和灌装"},{"key":"C","text":"无菌体内植入制品的分装与密封"},{"key":"D","text":"口服制剂的配制"},{"key":"E","text":"放射免疫分析药盒生产"}],"answer":["A","B","C"],"explanation":"“C级背景下的局部A级”适用于高风险无菌操作，如非最终灭菌小容量注射剂的灌装、即时标记放射性药品的标记和灌装、无菌体内植入制品的分装与密封。口服制剂配制和放射免疫分析药盒生产通常不需要局部A级环境，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌放射性药品的生产需符合药品GMP无菌附录要求。局部A级环境用于保证关键操作的无菌性，减少微生物和微粒污染风险。即时标记药品的标记和灌装、非最终灭菌注射剂灌装、无菌植入制品分装密封均属于高风险操作，需在C级背景下的局部A级进行。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 15 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0016","type":"multiple","qtype":"多选题","stem":"“C级”洁净区适用的操作有（ ）","options":[{"key":"A","text":"采用除菌过滤工艺的非最终灭菌小容量注射剂制备"},{"key":"B","text":"医用放射性核素发生器的物料准备和组装"},{"key":"C","text":"正电子类药品自动合成环境"},{"key":"D","text":"即时标记药品的淋洗"},{"key":"E","text":"无菌植入制品的焊封"}],"answer":["A","B","C","D"],"explanation":"“C级”洁净区适用于：采用除菌过滤工艺的非最终灭菌小容量注射剂制备、医用放射性核素发生器的物料准备和组装、正电子类药品自动合成环境、即时标记药品的淋洗。无菌植入制品的焊封通常需要在更高洁净级别（如局部A级）下进行，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\nC级洁净区用于控制微生物和微粒污染，但不要求局部A级。即时标记药品的淋洗可在C级进行，而标记和灌装则需局部A级。正电子类药品自动合成环境、发生器物料准备和组装、除菌过滤前制备等操作均可在C级下进行。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 16 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0017","type":"multiple","qtype":"多选题","stem":"仓储区贮存放射性物质的要求包括（ ）","options":[{"key":"A","text":"与非放射性物质严格分开"},{"key":"B","text":"专用场所及容器（适配辐射防护）"},{"key":"C","text":"防泄漏措施"},{"key":"D","text":"明显警示标识"},{"key":"E","text":"专库/专柜、专人管理"}],"answer":["A","B","C","D","E"],"explanation":"仓储区贮存放射性物质的要求包括：与非放射性物质严格分开；使用专用场所及适配辐射防护的容器；采取防泄漏措施；设置明显警示标识；实行专库/专柜、专人管理。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n仓储区贮存放射性物质必须与非放射性物质严格分开，使用专用场所和适配辐射防护的容器，采取防泄漏措施，设置明显警示标识，并实行专库/专柜、专人管理，以防止丢失、被盗和泄漏。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 17 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0018","type":"multiple","qtype":"多选题","stem":"质量控制区实验室的要求包括（ ）","options":[{"key":"A","text":"放射性与非放射性实验室分开"},{"key":"B","text":"检验人员佩戴个人剂量监测设备"},{"key":"C","text":"仪器布局合理，避免相互干扰"},{"key":"D","text":"放射性样品分类分区存放"},{"key":"E","text":"配备去污试剂及器具"}],"answer":["A","B","C","D","E"],"explanation":"质量控制区实验室要求包括：放射性与非放射性实验室分开；检验人员佩戴个人剂量监测设备；仪器布局合理，避免相互干扰；放射性样品分类分区存放；配备去污试剂及器具。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n质量控制实验室必须将放射性与非放射性实验室分开，检验人员需佩戴个人剂量监测设备，仪器布局合理，放射性样品分类分区存放，并配备去污试剂及器具，以确保检验安全和结果准确。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 18 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0019","type":"multiple","qtype":"多选题","stem":"放射性药品生产设备的要求包括（ ）","options":[{"key":"A","text":"具备辐射防护措施"},{"key":"B","text":"便于去除放射性污染"},{"key":"C","text":"自动合成系统一年至少验证一次"},{"key":"D","text":"经改造后需再确认"},{"key":"E","text":"与物料接触表面光洁耐腐蚀"}],"answer":["A","B","C","D","E"],"explanation":"放射性药品生产设备要求包括：具备辐射防护措施；便于去除放射性污染；自动合成系统一年至少验证一次；经改造后需再确认；与物料接触表面光洁耐腐蚀。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产设备需符合辐射防护和药品GMP要求，便于清洁和去污。自动合成系统等关键设备需定期验证，变更后需再确认，确保设备性能稳定可靠。与物料接触表面应光洁耐腐蚀，以减少放射性残留和交叉污染。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 19 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0020","type":"multiple","qtype":"多选题","stem":"辐射安全管理的核心要求包括（ ）","options":[{"key":"A","text":"设立辐射防护管理机构及人员"},{"key":"B","text":"建立放射性事故应急预案"},{"key":"C","text":"人员辐射剂量监测及职业健康体检"},{"key":"D","text":"工作服清洗前进行放射性污染检测"},{"key":"E","text":"可重复使用包装容器有专用去污场所"}],"answer":["A","B","C","D","E"],"explanation":"辐射安全管理的核心要求包括：设立辐射防护管理机构及人员；建立放射性事故应急预案；人员辐射剂量监测及职业健康体检；工作服清洗前进行放射性污染检测；可重复使用包装容器有专用去污场所。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n辐射安全管理要求设立专门机构及人员，制定应急预案，对人员进行剂量监测和健康体检。工作服清洗前需进行放射性污染检测，可重复使用包装容器需有专用去污场所，以防止放射性污染扩散。\n\n---","source":{"file":"多选题/11-20.md","merged":"多选题1-110.md","location":"第 20 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0021","type":"multiple","qtype":"多选题","stem":"锝[99mTc]即时标记药品生产的关键要求包括（ ）","options":[{"key":"A","text":"淋洗操作在C级洁净区"},{"key":"B","text":"标记和分装在C级背景下局部A级"},{"key":"C","text":"配套药盒供应商具备放射性药品资质"},{"key":"D","text":"制定铅防护筒管理制度"},{"key":"E","text":"进行无菌工艺模拟试验"}],"answer":["A","B","C","D","E"],"explanation":"锝[99mTc]即时标记药品生产的关键要求包括：淋洗操作在C级洁净区进行；标记和分装在C级背景下局部A级进行；配套药盒供应商需具备放射性药品资质；制定铅防护筒管理制度；进行无菌工艺模拟试验。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n即时标记药品的生产需在相应洁净级别下操作，淋洗在C级，标记和灌装在C级背景下局部A级，以确保无菌。配套药盒供应商需具备放射性药品资质，铅防护筒管理是辐射防护的具体措施，无菌工艺模拟试验是验证无菌工艺有效性的必要手段。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 21 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0022","type":"multiple","qtype":"多选题","stem":"正电子类放射性药品生产的关键要求包括（ ）","options":[{"key":"A","text":"合成热室为C级，分装热室为C级背景下局部A级"},{"key":"B","text":"自动合成模块一年至少验证一次"},{"key":"C","text":"定期进行手套完整性测试"},{"key":"D","text":"除菌滤膜使用后进行完整性测试"},{"key":"E","text":"工艺用气进入合成热室前过滤"}],"answer":["A","B","C","D","E"],"explanation":"正电子类放射性药品生产的关键要求包括：合成热室为C级，分装热室为C级背景下局部A级；自动合成模块一年至少验证一次；定期进行手套完整性测试；除菌滤膜使用后进行完整性测试；工艺用气进入合成热室前过滤。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n正电子类药品生产需在屏蔽热室中进行，合成热室为C级，分装热室为C级背景下局部A级。自动合成模块需定期验证，手套完整性测试和除菌滤膜完整性测试是保证无菌和防止污染的关键措施，工艺用气需经过滤后进入热室。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 22 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0023","type":"multiple","qtype":"多选题","stem":"碘[125I]密封籽源生产的关键要求包括（ ）","options":[{"key":"A","text":"半成品、成品存入放射源库专用柜"},{"key":"B","text":"制定退回产品处置规程"},{"key":"C","text":"生产操作在手套箱/通风橱（负压）"},{"key":"D","text":"定期确认气体过滤系统效率"},{"key":"E","text":"在线检测功能定期验证"}],"answer":["A","B","C","D","E"],"explanation":"碘[125I]密封籽源生产的关键要求包括：半成品、成品存入放射源库专用柜；制定退回产品处置规程；生产操作在手套箱/通风橱（负压）中进行；定期确认气体过滤系统效率；在线检测功能定期验证。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n碘[125I]密封籽源属于放射性体内植入制品，其半成品和成品需存入放射源库专用柜，防止丢失和泄漏。生产操作需在负压手套箱或通风橱中进行，气体过滤系统需定期确认效率，在线检测功能需定期验证，退回产品需按规程处置。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 23 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0024","type":"multiple","qtype":"多选题","stem":"体外放射性诊断试剂盒生产的关键要求包括（ ）","options":[{"key":"A","text":"抗原/抗体供应商审计含冷链能力"},{"key":"B","text":"不同品种不同台组装"},{"key":"C","text":"更换品种彻底清场"},{"key":"D","text":"冷链运输温度监测"},{"key":"E","text":"委托运输评估冷链能力"}],"answer":["A","B","C","D","E"],"explanation":"体外放射性诊断试剂盒生产的关键要求包括：抗原/抗体供应商审计含冷链能力；不同品种不同台组装；更换品种彻底清场；冷链运输温度监测；委托运输评估冷链能力。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n体外放射性诊断试剂盒生产需对原料供应商进行审计，确保冷链能力；不同品种需在不同台组装，更换品种彻底清场，防止交叉污染；冷链运输需进行温度监测，委托运输需评估冷链能力，以保证试剂盒质量。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 24 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0025","type":"multiple","qtype":"多选题","stem":"委托生产18F-FDG注射液的要求包括（ ）","options":[{"key":"A","text":"上市许可持有人负责上市放行（可电子签名）"},{"key":"B","text":"受托方合成仪型号与注册一致"},{"key":"C","text":"受托方具备全项检验能力"},{"key":"D","text":"签订质量协议"},{"key":"E","text":"原料入厂验收核对信息"}],"answer":["A","B","C","D","E"],"explanation":"委托生产18F-FDG注射液的要求包括：上市许可持有人负责上市放行（可电子签名）；受托方合成仪型号与注册一致；受托方具备全项检验能力；签订质量协议；原料入厂验收核对信息。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十二条　放射性药品生产企业生产已有国家标准的放射性药品，必须经国务院药品监督管理部门征求国务院国防科技工业主管部门意见后审核批准，并发给批准文号。凡是改变国务院药品监督管理部门已批准的生产工艺路线和药品标准的，生产单位必须按原报批程序提出补充申请，经国务院药品监督管理部门批准后方能生产。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n委托生产需签订质量协议，明确双方责任。受托方合成仪型号需与注册一致，具备全项检验能力。上市许可持有人负责上市放行，原料入厂需验收核对信息，确保产品质量可追溯。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 25 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0026","type":"multiple","qtype":"多选题","stem":"放射性药品质量控制的特点包括（ ）","options":[{"key":"A","text":"具备核素鉴别、活度测定等放行检验能力"},{"key":"B","text":"实验室负责人需本科/中级职称"},{"key":"C","text":"检验仪器不与生产用混用"},{"key":"D","text":"产品检验包括使用前+追溯性检验"},{"key":"E","text":"稳定性考察需单独留样"}],"answer":["A","B","C","D","E"],"explanation":"放射性药品质量控制的特点包括：具备核素鉴别、活度测定等放行检验能力；实验室负责人需本科/中级职称；检验仪器不与生产用混用；产品检验包括使用前+追溯性检验；稳定性考察需单独留样。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性药品质量控制需具备核素鉴别、活度测定等能力，实验室负责人需具备相应学历和职称。检验仪器应专用，产品检验包括使用前检验和追溯性检验，稳定性考察需单独留样，以确保药品质量。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 26 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0027","type":"multiple","qtype":"多选题","stem":"正电子类药品质量控制的要求包括（ ）","options":[{"key":"A","text":"半衰期＞20分钟：使用前测性状、pH、放射化学纯度、活度"},{"key":"B","text":"半衰期≤20分钟：同一天制备定义为批，每次为亚批"},{"key":"C","text":"连续6批全检合格后可定期抽验（至少每月1次）"},{"key":"D","text":"配备活度计、γ能谱仪等仪器"},{"key":"E","text":"检验数据定期备份"}],"answer":["A","B","C","D","E"],"explanation":"正电子类药品质量控制的要求包括：半衰期＞20分钟者，使用前测性状、pH、放射化学纯度、活度；半衰期≤20分钟者，同一天制备定义为批，每次为亚批；连续6批全检合格后可定期抽验（至少每月1次）；配备活度计、γ能谱仪等仪器；检验数据定期备份。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n正电子类药品半衰期短，质量控制需根据半衰期制定检验策略。半衰期＞20分钟者需使用前检验；半衰期≤20分钟者按天分批，连续6批全检合格后可定期抽验。需配备活度计、γ能谱仪等仪器，检验数据定期备份，确保可追溯。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 27 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0028","type":"multiple","qtype":"多选题","stem":"锝[99mTc]药品质量控制的要求包括（ ）","options":[{"key":"A","text":"使用前必检：性状、pH、放射化学纯度、活度、颗粒大小"},{"key":"B","text":"边检验边放行：无菌、细菌内毒素"},{"key":"C","text":"新增发生器淋洗液需全检"},{"key":"D","text":"连续6批发生器无菌合格后可定期检查"},{"key":"E","text":"新换药盒批号需验证性全检"}],"answer":["A","B","C","D","E"],"explanation":"锝[99mTc]药品质量控制的要求包括：使用前必检性状、pH、放射化学纯度、活度、颗粒大小；边检验边放行无菌、细菌内毒素；新增发生器淋洗液需全检；连续6批发生器无菌合格后可定期检查；新换药盒批号需验证性全检。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n锝[99mTc]药品使用前需检验性状、pH、放射化学纯度、活度、颗粒大小。无菌和细菌内毒素可边检验边放行。新增发生器淋洗液需全检，连续6批无菌合格后可定期检查。新换药盒批号需验证性全检，确保质量稳定。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 28 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0029","type":"multiple","qtype":"多选题","stem":"多道γ谱仪的检查要求包括（ ）","options":[{"key":"A","text":"用标准源进行能量与效率刻度"},{"key":"B","text":"制定期间核查规程"},{"key":"C","text":"保存完整谱图及原始数据"},{"key":"D","text":"配备铅屏蔽室"},{"key":"E","text":"探测器包括碘化钠、高纯锗类型"}],"answer":["A","B","C","D","E"],"explanation":"多道γ谱仪的检查要求包括：用标准源进行能量与效率刻度；制定期间核查规程；保存完整谱图及原始数据；配备铅屏蔽室；探测器包括碘化钠、高纯锗类型。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n多道γ谱仪是放射性药品质量控制的关键设备，需用标准源进行能量与效率刻度，制定期间核查规程，保存完整谱图及原始数据。铅屏蔽室用于降低本底，探测器类型包括碘化钠和高纯锗，以满足不同核素鉴别需求。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 29 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0030","type":"multiple","qtype":"多选题","stem":"放射性活度计的检查要求包括（ ）","options":[{"key":"A","text":"定期检定（含待测核素）"},{"key":"B","text":"配备长寿命监督源"},{"key":"C","text":"数据可打印/连接计算机保存"},{"key":"D","text":"远离其他放射性测量仪器"},{"key":"E","text":"必要时增加铅屏蔽"}],"answer":["A","B","C","D","E"],"explanation":"放射性活度计的检查要求包括：定期检定（含待测核素）；配备长寿命监督源；数据可打印/连接计算机保存；远离其他放射性测量仪器；必要时增加铅屏蔽。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性活度计需定期检定，检定范围应包含待测核素。配备长寿命监督源用于日常核查。数据应可打印或连接计算机保存，以便追溯。活度计应远离其他放射性测量仪器，避免干扰；必要时增加铅屏蔽，降低本底。\n\n---","source":{"file":"多选题/21-30.md","merged":"多选题1-110.md","location":"第 30 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0031","type":"multiple","qtype":"多选题","stem":"放射性核素鉴别的方法包括（ ）","options":[{"key":"A","text":"γ谱仪法（能量误差±10keV或±6%）"},{"key":"B","text":"半衰期法（至少3个点，误差≤±5%）"},{"key":"C","text":"质量吸收系数法（误差≤±10%）"},{"key":"D","text":"外观鉴别法"},{"key":"E","text":"重量法"}],"answer":["A","B","C"],"explanation":"放射性核素鉴别的方法包括γ谱仪法（能量误差±10keV或±6%）、半衰期法（至少3个点，误差≤±5%）和质量吸收系数法（误差≤±10%）。外观鉴别法和重量法不能用于放射性核素鉴别，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性核素鉴别是放射性药品质量控制的核心内容，需采用γ谱仪法、半衰期法、质量吸收系数法等专门方法，确保核素种类准确无误。这些方法的研究和标准制定需符合国家药品标准要求。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 31 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0032","type":"multiple","qtype":"多选题","stem":"放射性核纯度测定的要求包括（ ）","options":[{"key":"A","text":"样品形状/大小与标准源一致"},{"key":"B","text":"几何位置与效率刻度时一致"},{"key":"C","text":"确保核杂质有效检出（主峰计数足够）"},{"key":"D","text":"能量相近核素用高纯锗探测器"},{"key":"E","text":"能量差别大核素用碘化钠探测器"}],"answer":["A","B","C","D","E"],"explanation":"放射性核纯度测定的要求包括：样品形状/大小与标准源一致；几何位置与效率刻度时一致；确保核杂质有效检出（主峰计数足够）；能量相近核素用高纯锗探测器；能量差别大核素用碘化钠探测器。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性核纯度测定需保证测量条件一致，确保核杂质有效检出。根据核素能量差异选择合适探测器：能量相近用高纯锗探测器，能量差别大用碘化钠探测器。这些要求是药品质量标准的重要组成部分。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 32 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0033","type":"multiple","qtype":"多选题","stem":"放射化学纯度测定的要求包括（ ）","options":[{"key":"A","text":"纸色谱/薄层色谱容器密闭"},{"key":"B","text":"注明对照品来源"},{"key":"C","text":"保存检验数据及谱图"},{"key":"D","text":"可采用高效液相色谱法"},{"key":"E","text":"氟[18F]脱氧葡糖用乙腈-水（95:5）展开"}],"answer":["A","B","C","D","E"],"explanation":"放射化学纯度测定的要求包括：纸色谱/薄层色谱容器密闭；注明对照品来源；保存检验数据及谱图；可采用高效液相色谱法；氟[18F]脱氧葡糖用乙腈-水（95:5）展开。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射化学纯度测定是放射性药品质量控制的关键项目，需在密闭容器中进行色谱操作，防止放射性挥发；对照品来源需明确；检验数据和谱图需完整保存。高效液相色谱法可用于特定品种，氟[18F]脱氧葡糖采用乙腈-水（95:5）展开系统。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 33 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0034","type":"multiple","qtype":"多选题","stem":"放射性活（浓）度测定的要求包括（ ）","options":[{"key":"A","text":"样品活度在活度计测量范围内"},{"key":"B","text":"记录活度读数及测定时间"},{"key":"C","text":"读数波动时重复10次取平均"},{"key":"D","text":"测浓度用计量移液器取样"},{"key":"E","text":"锝[99mTc]活度计范围3.7×10⁵～3.7×10¹⁰ Bq"}],"answer":["A","B","C","D","E"],"explanation":"放射性活（浓）度测定的要求包括：样品活度在活度计测量范围内；记录活度读数及测定时间；读数波动时重复10次取平均；测浓度用计量移液器取样；锝[99mTc]活度计范围3.7×10⁵～3.7×10¹⁰ Bq。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性活度测定是放射性药品放行检验的关键项目。样品活度需在活度计测量范围内，记录读数和测定时间，读数波动时重复10次取平均。测浓度需使用计量移液器取样。锝[99mTc]活度计测量范围通常为3.7×10⁵～3.7×10¹⁰ Bq，确保测量准确可靠。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 34 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0035","type":"multiple","qtype":"多选题","stem":"生物分布试验的要求包括（ ）","options":[{"key":"A","text":"制定操作规程"},{"key":"B","text":"实验动物有合格证明"},{"key":"C","text":"选用合适仪器测定"},{"key":"D","text":"实验人员有相应资质"},{"key":"E","text":"实验环境符合国家要求"}],"answer":["A","B","C","D","E"],"explanation":"生物分布试验的要求包括：制定操作规程；实验动物有合格证明；选用合适仪器测定；实验人员有相应资质；实验环境符合国家要求。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生物分布试验是放射性药品质量控制的重要项目，用于评价药品在体内的分布和靶向性。需制定操作规程，使用有合格证明的实验动物，选用合适仪器测定，实验人员需具备相应资质，实验环境需符合国家要求，确保试验结果科学可靠。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 35 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0036","type":"multiple","qtype":"多选题","stem":"质量保证的核心要求包括（ ）","options":[{"key":"A","text":"建立变更控制系统"},{"key":"B","text":"建立偏差处理规程"},{"key":"C","text":"建立纠正预防措施系统"},{"key":"D","text":"年度产品质量回顾"},{"key":"E","text":"药品不良反应监测上报"}],"answer":["A","B","C","D","E"],"explanation":"质量保证的核心要求包括：建立变更控制系统；建立偏差处理规程；建立纠正预防措施系统；年度产品质量回顾；药品不良反应监测上报。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n质量保证体系需涵盖变更控制、偏差处理、纠正预防措施、年度产品质量回顾和药品不良反应监测上报。这些要求是药品GMP的核心内容，也是放射性药品质量管理制度的重要组成部分，确保药品安全有效和质量稳定。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 36 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0037","type":"multiple","qtype":"多选题","stem":"以下属于放射性药品典型缺陷的有（ ）","options":[{"key":"A","text":"洁净区通风柜无排风通道"},{"key":"B","text":"检前暂存库冰箱温度计超校准期"},{"key":"C","text":"更换锝[99mTc]药盒未完成无菌检验即生产"},{"key":"D","text":"碘[125I]籽源稳定性考察用留样"},{"key":"E","text":"氟[18F]批记录未记展开剂配制批号"}],"answer":["A","B","C","D","E"],"explanation":"放射性药品典型缺陷包括：洁净区通风柜无排风通道；检前暂存库冰箱温度计超校准期；更换锝[99mTc]药盒未完成无菌检验即生产；碘[125I]籽源稳定性考察用留样；氟[18F]批记录未记展开剂配制批号。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n上述缺陷均违反了放射性药品生产质量管理要求：通风柜无排风通道违反辐射防护和洁净区要求；温度计超校准期影响检验准确性；未完成无菌检验即生产违反质量放行程序；稳定性考察用留样违反留样管理；批记录缺失违反数据可靠性要求。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 37 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0038","type":"multiple","qtype":"多选题","stem":"放射性药品包装标签需注明的信息包括（ ）","options":[{"key":"A","text":"药品名称、规格"},{"key":"B","text":"放射性活度、批号"},{"key":"C","text":"有效期、批准文号"},{"key":"D","text":"生产企业名称"},{"key":"E","text":"放射性药品标志"}],"answer":["A","B","C","D","E"],"explanation":"放射性药品包装标签需注明的信息包括：药品名称、规格；放射性活度、批号；有效期、批准文号；生产企业名称；放射性药品标志。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n标签必须注明药品名称、规格、放射性活度、批号、有效期、批准文号、生产企业名称等信息，并贴有放射性药品标志，以警示辐射风险，确保使用安全。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 38 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0039","type":"multiple","qtype":"多选题","stem":"医用放射性核素发生器的生产工艺包括（ ）","options":[{"key":"A","text":"冷柱制备组装（C级）"},{"key":"B","text":"钼[99Mo]溶液配制（C+A）"},{"key":"C","text":"钼[99Mo]溶液灌注（C+A）"},{"key":"D","text":"贴标签、试通"},{"key":"E","text":"装入铅罐屏蔽"}],"answer":["A","B","C","D","E"],"explanation":"医用放射性核素发生器的生产工艺包括：冷柱制备组装（C级）；钼[99Mo]溶液配制（C+A）；钼[99Mo]溶液灌注（C+A）；贴标签、试通；装入铅罐屏蔽。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n医用放射性核素发生器生产需在相应洁净级别下进行：冷柱制备组装在C级，钼[99Mo]溶液配制和灌注在C级背景下局部A级。生产完成后需贴标签、试通，并装入铅罐屏蔽，确保辐射安全。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 39 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0040","type":"multiple","qtype":"多选题","stem":"碘[131I]化钠口服溶液的制备工艺包括（ ）","options":[{"key":"A","text":"国产采用干法蒸馏工艺"},{"key":"B","text":"稀释至合适浓度"},{"key":"C","text":"调节pH值"},{"key":"D","text":"加入亚硫酸钠/硫代硫酸钠稳定剂"},{"key":"E","text":"装入射线屏蔽容器"}],"answer":["A","B","C","D","E"],"explanation":"碘[131I]化钠口服溶液的制备工艺包括：国产采用干法蒸馏工艺；稀释至合适浓度；调节pH值；加入亚硫酸钠/硫代硫酸钠稳定剂；装入射线屏蔽容器。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n碘[131I]化钠口服溶液制备需采用干法蒸馏工艺，稀释至合适浓度，调节pH值，加入亚硫酸钠/硫代硫酸钠作为稳定剂，最后装入射线屏蔽容器。这些工艺步骤确保药品质量稳定和辐射安全，包装需符合防护要求。\n\n---","source":{"file":"多选题/31-40.md","merged":"多选题1-110.md","location":"第 40 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0041","type":"multiple","qtype":"多选题","stem":"尿素[14C]呼气试验药盒的组成包括（ ）","options":[{"key":"A","text":"尿素[14C]胶囊"},{"key":"B","text":"集气剂"},{"key":"C","text":"浓缩闪烁液"},{"key":"D","text":"吹气用塑料管"},{"key":"E","text":"检测仪"}],"answer":["A","B","C","D"],"explanation":"尿素[14C]呼气试验药盒的组成包括尿素[14C]胶囊、集气剂、浓缩闪烁液和吹气用塑料管。检测仪属于配套仪器，不属于药盒本身组成部分，因此E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n尿素[14C]呼气试验药盒属于放射性诊断药品，其组成需满足诊断准确性和使用便利性要求。药盒中包含的尿素[14C]胶囊为放射性核素制剂，集气剂、浓缩闪烁液和吹气用塑料管为配套辅助材料，检测仪为独立设备，不纳入药盒管理。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 41 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0042","type":"multiple","qtype":"多选题","stem":"放射性药品生产操作区洁净度级别的“D级”适用操作包括（ ）","options":[{"key":"A","text":"口服制剂物料准备、配制"},{"key":"B","text":"正电子类药品密闭设备外环境"},{"key":"C","text":"无菌植入制品焊封"},{"key":"D","text":"直接接触非无菌药品包装材料清洗"},{"key":"E","text":"放射免疫分析药盒生产"}],"answer":["A","B","C","D","E"],"explanation":"“D级”洁净区适用于：口服制剂物料准备、配制；正电子类药品密闭设备外环境；无菌植入制品焊封；直接接触非无菌药品包装材料清洗；放射免疫分析药盒生产。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产操作区洁净度级别需根据产品风险确定。D级适用于非无菌或低风险操作，如口服制剂物料准备、正电子类药品密闭设备外环境、无菌植入制品焊封、非无菌包装材料清洗及放射免疫分析药盒生产。企业需建立相应管理制度，确保洁净区符合要求。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 42 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0043","type":"multiple","qtype":"多选题","stem":"放射性废物处理的要求包括（ ）","options":[{"key":"A","text":"专用废弃桶存放"},{"key":"B","text":"按核素种类、半衰期分类收集"},{"key":"C","text":"存放于适配辐射防护的场所"},{"key":"D","text":"达到排放标准后按环保处置"},{"key":"E","text":"挥发性废物容器密闭/存通风橱"}],"answer":["A","B","C","D","E"],"explanation":"放射性废物处理的要求包括：专用废弃桶存放；按核素种类、半衰期分类收集；存放于适配辐射防护的场所；达到排放标准后按环保处置；挥发性废物容器密闭/存通风橱。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n放射性废物处理需使用专用废弃桶，按核素种类和半衰期分类收集，存放于辐射防护达标场所。达到排放标准后按环保要求处置。挥发性废物需密闭容器或存于通风橱中，防止放射性气体扩散。企业应建立废物管理制度和应急预案。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 43 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0044","type":"multiple","qtype":"多选题","stem":"检验人员的资质要求包括（ ）","options":[{"key":"A","text":"至少中专/高中以上学历"},{"key":"B","text":"具备放射性药品专业知识"},{"key":"C","text":"接受岗位培训"},{"key":"D","text":"考核合格上岗"},{"key":"E","text":"定期复训"}],"answer":["A","B","C","D"],"explanation":"检验人员的资质要求包括：至少中专/高中以上学历；具备放射性药品专业知识；接受岗位培训；考核合格上岗。定期复训属于持续培训要求，但题目问“资质要求”，通常指上岗前的基本条件，故E不选。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n检验人员需具备中专/高中以上学历，掌握放射性药品专业知识，接受岗位培训并考核合格后方可上岗。企业应配备与检验相适应的专业技术人员，确保质量控制有效。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 44 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0045","type":"multiple","qtype":"多选题","stem":"计算机化系统验证的要求包括（ ）","options":[{"key":"A","text":"自动合成设备系统一年至少验证一次"},{"key":"B","text":"变更后重新验证"},{"key":"C","text":"确保数据可靠性"},{"key":"D","text":"分装器数据传输完整性确认"},{"key":"E","text":"用户权限确认"}],"answer":["A","B","C","D","E"],"explanation":"计算机化系统验证的要求包括：自动合成设备系统一年至少验证一次；变更后重新验证；确保数据可靠性；分装器数据传输完整性确认；用户权限确认。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n计算机化系统验证是药品GMP的重要组成部分。自动合成设备系统需每年验证，变更后重新验证。需确保数据可靠性，分装器数据传输完整性需确认，用户权限需明确。这些措施保证计算机化系统稳定可靠，数据真实完整可追溯。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 45 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0046","type":"multiple","qtype":"多选题","stem":"边检验边放行药品的质量保证要求包括（ ）","options":[{"key":"A","text":"发现质量问题立即通知停止使用"},{"key":"B","text":"建立药品追踪系统"},{"key":"C","text":"向临床提供信息和技术指导"},{"key":"D","text":"明确边放行的检验项目"},{"key":"E","text":"规定检验周期"}],"answer":["A","B","C","D","E"],"explanation":"边检验边放行药品的质量保证要求包括：发现质量问题立即通知停止使用；建立药品追踪系统；向临床提供信息和技术指导；明确边放行的检验项目；规定检验周期。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n边检验边放行是放射性药品的特殊放行方式，需建立追踪系统，明确检验项目和周期。发现质量问题立即通知停止使用，并向临床提供信息和技术指导，确保患者安全。企业需建立严格质量管理制度。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 46 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0047","type":"multiple","qtype":"多选题","stem":"产品质量回顾的要求包括（ ）","options":[{"key":"A","text":"每年按品种进行"},{"key":"B","text":"确认工艺稳定性"},{"key":"C","text":"确认原辅料/成品标准适用性"},{"key":"D","text":"有操作规程及记录"},{"key":"E","text":"回顾偏差、投诉、召回情况"}],"answer":["A","B","C","D","E"],"explanation":"产品质量回顾的要求包括：每年按品种进行；确认工艺稳定性；确认原辅料/成品标准适用性；有操作规程及记录；回顾偏差、投诉、召回情况。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n产品质量回顾是质量保证体系的重要环节。每年按品种进行，确认工艺稳定性和标准适用性。需有操作规程及记录，回顾偏差、投诉、召回情况，以持续改进质量体系，确保放射性药品安全有效。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 47 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0048","type":"multiple","qtype":"多选题","stem":"药品不良反应监测的要求包括（ ）","options":[{"key":"A","text":"建立管理制度及操作程序"},{"key":"B","text":"及时控制不良反应"},{"key":"C","text":"详细记录事件经过、调查、处理"},{"key":"D","text":"按规定上报"},{"key":"E","text":"定期回顾分析"}],"answer":["A","B","C","D"],"explanation":"药品不良反应监测的要求包括：建立管理制度及操作程序；及时控制不良反应；详细记录事件经过、调查、处理；按规定上报。定期回顾分析属于后续管理要求，题目问基本要求，故E不选。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n药品不良反应监测需建立管理制度和操作程序，及时控制不良反应，详细记录事件经过、调查和处理，并按规定上报。企业应制定应急预案，确保患者安全。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 48 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0049","type":"multiple","qtype":"多选题","stem":"锝[99mTc]配套药盒的生产工艺包括（ ）","options":[{"key":"A","text":"药液配制（C级）"},{"key":"B","text":"除菌过滤（C+A）"},{"key":"C","text":"定量分装（C+A）"},{"key":"D","text":"冷冻干燥（A级）"},{"key":"E","text":"压盖包装（C+A）"}],"answer":["A","B","C","D","E"],"explanation":"锝[99mTc]配套药盒的生产工艺包括：药液配制（C级）；除菌过滤（C+A）；定量分装（C+A）；冷冻干燥（A级）；压盖包装（C+A）。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n锝[99mTc]配套药盒生产需在相应洁净级别下进行：药液配制在C级，除菌过滤、定量分装、压盖包装在C级背景下局部A级，冷冻干燥在A级。企业需建立严格质量管理制度，确保药盒无菌、无热原，满足即时标记药品生产要求。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 49 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0050","type":"multiple","qtype":"多选题","stem":"氟[18F]脱氧葡糖注射液的合成工艺包括（ ）","options":[{"key":"A","text":"氟[18F]离子制备（回旋加速器）"},{"key":"B","text":"QMA柱捕获氟[18F]"},{"key":"C","text":"氟化三氟甘露糖并水解"},{"key":"D","text":"纯化、调节pH"},{"key":"E","text":"0.22μm滤膜除菌"}],"answer":["A","B","C","D","E"],"explanation":"氟[18F]脱氧葡糖注射液的合成工艺包括：氟[18F]离子制备（回旋加速器）；QMA柱捕获氟[18F]；氟化三氟甘露糖并水解；纯化、调节pH；0.22μm滤膜除菌。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n氟[18F]脱氧葡糖注射液为正电子类放射性药品，合成工艺包括加速器制备氟[18F]离子、QMA柱捕获、氟化水解、纯化调pH、0.22μm滤膜除菌。企业需符合辐射安全和药品GMP要求，配备专业技术人员和安全防护设施，确保产品质量和辐射安全。\n\n---","source":{"file":"多选题/41-50.md","merged":"多选题1-110.md","location":"第 50 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0051","type":"multiple","qtype":"多选题","stem":"放射性药品留样的要求包括（ ）","options":[{"key":"A","text":"结合品种特点制定规程"},{"key":"B","text":"稳定性考察样品单独留存"},{"key":"C","text":"留样标识清楚"},{"key":"D","text":"留样环境符合要求"},{"key":"E","text":"留样记录完整"}],"answer":["A","B","C","D","E"],"explanation":"放射性药品留样要求包括：结合品种特点制定规程；稳定性考察样品单独留存；留样标识清楚；留样环境符合要求；留样记录完整。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n留样管理是质量管理制度的重要组成部分。企业应结合放射性药品半衰期短、辐射防护要求高等特点，制定留样规程。稳定性考察样品需单独留存，留样标识应清楚，留样环境需符合辐射防护和药品储存要求，留样记录应完整可追溯。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 51 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0052","type":"multiple","qtype":"多选题","stem":"辐射防护用品包括（ ）","options":[{"key":"A","text":"铅衣"},{"key":"B","text":"铅眼镜"},{"key":"C","text":"铅砖"},{"key":"D","text":"铅玻璃"},{"key":"E","text":"个人剂量计"}],"answer":["A","B","C","D","E"],"explanation":"辐射防护用品包括铅衣、铅眼镜、铅砖、铅玻璃和个人剂量计。铅砖和铅玻璃用于屏蔽设施，铅衣和铅眼镜用于个人防护，个人剂量计用于监测人员受照剂量。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n企业需配备与辐射防护相适应的用品，包括个人防护装备（铅衣、铅眼镜）和屏蔽设施（铅砖、铅玻璃）。个人剂量计用于监测人员受照剂量，是辐射安全管理的必要措施，符合国家有关放射性同位素安全和防护的规定。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 52 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0053","type":"multiple","qtype":"多选题","stem":"以下属于放射性药品的有（ ）","options":[{"key":"A","text":"高锝[99mTc]酸钠注射液"},{"key":"B","text":"氟[18F]脱氧葡糖注射液"},{"key":"C","text":"碘[125I]密封籽源"},{"key":"D","text":"磷[32P]酸钠盐口服溶液"},{"key":"E","text":"尿素[14C]胶囊"}],"answer":["A","B","C","D","E"],"explanation":"高锝[99mTc]酸钠注射液、氟[18F]脱氧葡糖注射液、碘[125I]密封籽源、磷[32P]酸钠盐口服溶液和尿素[14C]胶囊均含有放射性核素，用于临床诊断或治疗，属于放射性药品。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n上述品种均含有放射性核素（锝[99mTc]、氟[18F]、碘[125I]、磷[32P]、碳[14C]），分别以注射液、密封籽源、口服溶液、胶囊等形式用于诊断或治疗，符合放射性药品定义，属于《放射性药品管理办法》管理范围。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 53 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0054","type":"multiple","qtype":"多选题","stem":"放射性药品生产中“防止交叉污染”的措施包括（ ）","options":[{"key":"A","text":"不同核素操作区严格分开"},{"key":"B","text":"操作工具专用"},{"key":"C","text":"放射性与非放射性洁具分开"},{"key":"D","text":"更换品种彻底清场"},{"key":"E","text":"放射性样品分类存放"}],"answer":["A","B","C","D","E"],"explanation":"防止交叉污染的措施包括：不同核素操作区严格分开；操作工具专用；放射性与非放射性洁具分开；更换品种彻底清场；放射性样品分类存放。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n防止交叉污染是质量管理制度的核心内容。不同核素操作区需严格分开，操作工具和洁具应专用，更换品种需彻底清场，放射性样品应分类存放，以避免核素间交叉污染和非放射性污染，确保药品质量和辐射安全。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 54 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0055","type":"multiple","qtype":"多选题","stem":"正电子类药品追溯性检验的要求包括（ ）","options":[{"key":"A","text":"制定追溯性检验规程"},{"key":"B","text":"明确放置衰变时间"},{"key":"C","text":"至少每月一次全检"},{"key":"D","text":"连续6批合格后可定期抽验"},{"key":"E","text":"记录完整可追溯"}],"answer":["A","B","C","D","E"],"explanation":"正电子类药品追溯性检验的要求包括：制定追溯性检验规程；明确放置衰变时间；至少每月一次全检；连续6批合格后可定期抽验；记录完整可追溯。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n正电子类药品半衰期短，追溯性检验需制定规程，明确放置衰变时间，至少每月一次全检。连续6批合格后可定期抽验，记录需完整可追溯，以确保药品质量稳定，符合国家药品标准要求。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 55 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0056","type":"multiple","qtype":"多选题","stem":"锝[99mTc]药品快速检验法的要求包括（ ）","options":[{"key":"A","text":"进行方法验证"},{"key":"B","text":"有验证记录"},{"key":"C","text":"定期再验证"},{"key":"D","text":"与法定方法比对"},{"key":"E","text":"记录完整"}],"answer":["A","B","C"],"explanation":"锝[99mTc]药品快速检验法的要求包括：进行方法验证；有验证记录；定期再验证。与法定方法比对和记录完整属于一般要求，但题目明确答案为A、B、C，故D、E不选。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n快速检验法需经过方法验证，并有验证记录，定期再验证，以确保检验结果准确可靠。这是质量管理制度对检验方法的要求，符合放射性药品质量控制特点。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 56 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0057","type":"multiple","qtype":"多选题","stem":"放射性药品外包装材料的要求包括（ ）","options":[{"key":"A","text":"具有辐射防护性能"},{"key":"B","text":"符合国家相关规定"},{"key":"C","text":"做好检测记录"},{"key":"D","text":"可重复使用的需专用去污"},{"key":"E","text":"与药品性质适配"}],"answer":["A","B","C","D","E"],"explanation":"放射性药品外包装材料的要求包括：具有辐射防护性能；符合国家相关规定；做好检测记录；可重复使用的需专用去污；与药品性质适配。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n外包装材料需具有辐射防护性能，符合国家相关规定，做好检测记录。可重复使用的包装容器需专用去污，防止放射性污染扩散。包装材料应与药品性质适配，确保安全实用。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 57 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0058","type":"multiple","qtype":"多选题","stem":"无菌工艺模拟试验的要求包括（ ）","options":[{"key":"A","text":"结合产品工艺特点"},{"key":"B","text":"符合药品GMP无菌药品附录"},{"key":"C","text":"有操作规程及记录"},{"key":"D","text":"定期进行"},{"key":"E","text":"覆盖关键操作步骤"}],"answer":["A","B","C","D","E"],"explanation":"无菌工艺模拟试验的要求包括：结合产品工艺特点；符合药品GMP无菌药品附录；有操作规程及记录；定期进行；覆盖关键操作步骤。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌工艺模拟试验需结合产品工艺特点，符合药品GMP无菌药品附录要求，有操作规程及记录，定期进行，覆盖关键操作步骤，以验证无菌工艺的有效性，确保无菌放射性药品质量。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 58 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0059","type":"multiple","qtype":"多选题","stem":"放射性药品生产中“数据可靠性”的要求包括（ ）","options":[{"key":"A","text":"检验数据定期备份"},{"key":"B","text":"谱图及原始数据保存完整"},{"key":"C","text":"电子记录有安全措施"},{"key":"D","text":"校准记录保存"},{"key":"E","text":"批生产记录完整"}],"answer":["A","B","C","D","E"],"explanation":"数据可靠性的要求包括：检验数据定期备份；谱图及原始数据保存完整；电子记录有安全措施；校准记录保存；批生产记录完整。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n数据可靠性是质量管理制度的关键要素。检验数据需定期备份，谱图及原始数据保存完整，电子记录需有安全措施，校准记录和批生产记录需完整保存，确保数据真实、准确、完整、可追溯，符合药品GMP和数据可靠性要求。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 59 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0060","type":"multiple","qtype":"多选题","stem":"以下属于放射性药品生产“典型缺陷”的有（ ）","options":[{"key":"A","text":"A级层流标记热室未装风机报警"},{"key":"B","text":"活度计与控制电脑数据传输未确认"},{"key":"C","text":"体外诊断试剂盒不同品种同台组装"},{"key":"D","text":"生物分布实验动物无合格证明"},{"key":"E","text":"变更未按规定评估审批"}],"answer":["A","B","C","D","E"],"explanation":"放射性药品生产典型缺陷包括：A级层流标记热室未装风机报警；活度计与控制电脑数据传输未确认；体外诊断试剂盒不同品种同台组装；生物分布实验动物无合格证明；变更未按规定评估审批。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n上述缺陷均违反质量管理制度：A级层流未装报警违反无菌保障要求；数据传输未确认影响数据可靠性；不同品种同台组装易致交叉污染；实验动物无合格证明违反生物分布试验要求；变更未评估审批违反变更控制程序。企业需建立严格管理制度，确保生产合规。\n\n---","source":{"file":"多选题/51-60.md","merged":"多选题1-110.md","location":"第 60 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0061","type":"multiple","qtype":"多选题","stem":"本附录适用的放射性药品包括（ ）","options":[{"key":"A","text":"医用放射性核素发生器及其配套药盒"},{"key":"B","text":"正电子类放射性药品"},{"key":"C","text":"放射性体内植入制品"},{"key":"D","text":"即时标记放射性药品"},{"key":"E","text":"普通化学药品"}],"answer":["A","B","C","D"],"explanation":"本附录适用的放射性药品包括医用放射性核素发生器及其配套药盒、正电子类放射性药品、放射性体内植入制品和即时标记放射性药品。普通化学药品不含放射性核素，不属于放射性药品，因此不适用本附录。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第三条　凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n根据上述定义，医用放射性核素发生器及其配套药盒、正电子类药品、放射性体内植入制品和即时标记药品均属于“放射性核素制剂或者其标记药物”的范畴，适用本附录。普通化学药品不含放射性核素，不适用本办法。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 61 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0062","type":"multiple","qtype":"多选题","stem":"放射性药品可申请“边检验边放行”的条件包括（ ）","options":[{"key":"A","text":"产品有效期＜30天"},{"key":"B","text":"所含核素半衰期＜30天"},{"key":"C","text":"企业质量管理部门风险评估"},{"key":"D","text":"任意放射性药品"},{"key":"E","text":"仅正电子类药品"}],"answer":["A","B","C"],"explanation":"放射性药品可申请“边检验边放行”的条件包括：产品有效期＜30天；所含核素半衰期＜30天；企业质量管理部门进行风险评估。并非任意放射性药品或仅正电子类药品均可申请，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n“边检验边放行”是放射性药品因半衰期短、有效期短而采取的特殊放行方式。企业质量管理部门需进行风险评估，确认产品有效期和核素半衰期符合条件，并建立严格的质量管理制度，确保放行后质量可控。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 62 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0063","type":"multiple","qtype":"多选题","stem":"放射性药品生产管理负责人、质量管理负责人及质量受权人需具备的资质有（ ）","options":[{"key":"A","text":"符合《药品生产质量管理规范》（2010年修订）相关资质"},{"key":"B","text":"核医（药）学或相关专业知识"},{"key":"C","text":"放射性药品相关工作经验"},{"key":"D","text":"仅普通药品管理经验"},{"key":"E","text":"仅销售经验"}],"answer":["A","B","C"],"explanation":"放射性药品生产管理负责人、质量管理负责人及质量受权人需具备：符合《药品生产质量管理规范》（2010年修订）相关资质；核医（药）学或相关专业知识；放射性药品相关工作经验。仅普通药品管理经验或仅销售经验不满足要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n企业需配备与放射性药品相适应的专业技术人员，关键人员除符合GMP资质外，还需具备核医（药）学知识及放射性药品工作经验，以确保生产质量管理符合辐射安全和药品质量要求。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 63 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0064","type":"multiple","qtype":"多选题","stem":"企业各岗位人员的培训内容应涵盖（ ）","options":[{"key":"A","text":"岗位相关专业知识"},{"key":"B","text":"辐射防护知识"},{"key":"C","text":"销售技巧"},{"key":"D","text":"采购流程"},{"key":"E","text":"放射性污染处理方法"}],"answer":["A","B","E"],"explanation":"企业各岗位人员的培训内容应涵盖岗位相关专业知识、辐射防护知识和放射性污染处理方法。销售技巧和采购流程不属于放射性药品生产岗位人员的通用培训内容，故C、D错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n企业应对各岗位人员进行培训，内容涵盖岗位专业知识、辐射防护知识和放射性污染处理方法，确保人员具备相应能力，符合辐射安全和药品GMP要求。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 64 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0065","type":"multiple","qtype":"多选题","stem":"放射性药品厂房设施的总体要求包括（ ）","options":[{"key":"A","text":"符合生产工艺及辐射安全要求"},{"key":"B","text":"取得辐射安全许可证明文件"},{"key":"C","text":"放射性与非放射性工作区有效隔离"},{"key":"D","text":"不同核素操作区严格分开"},{"key":"E","text":"仅考虑生产效率"}],"answer":["A","B","C","D"],"explanation":"放射性药品厂房设施总体要求包括：符合生产工艺及辐射安全要求；取得辐射安全许可证明文件；放射性与非放射性工作区有效隔离；不同核素操作区严格分开。仅考虑生产效率不符合法规要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n厂房设施必须符合生产工艺和辐射安全要求，取得辐射安全许可证明文件，放射性与非放射性工作区有效隔离，不同核素操作区严格分开，以确保药品质量和辐射安全。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 65 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0066","type":"multiple","qtype":"多选题","stem":"操作放射性核素的环境要求有（ ）","options":[{"key":"A","text":"相对负压"},{"key":"B","text":"具备辐射防护措施"},{"key":"C","text":"封闭环境"},{"key":"D","text":"相对正压"},{"key":"E","text":"开放式工作台"}],"answer":["A","B","C"],"explanation":"操作放射性核素的环境要求包括：相对负压；具备辐射防护措施；封闭环境。相对正压和开放式工作台会导致放射性物质扩散，不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n操作放射性核素需在相对负压、封闭的环境中进行，并具备辐射防护措施，以防止放射性物质扩散和污染环境。企业需配备安全防护设施，符合国家有关放射性同位素安全和防护的规定。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 66 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0067","type":"multiple","qtype":"多选题","stem":"下列属于“C级背景下的局部A级”洁净区适用的操作有（ ）","options":[{"key":"A","text":"非最终灭菌小容量注射剂的灌装"},{"key":"B","text":"即时标记放射性药品的标记"},{"key":"C","text":"无菌体内植入制品的分装与密封"},{"key":"D","text":"医用核素发生器的灌装"},{"key":"E","text":"口服制剂的配制"}],"answer":["A","B","C","D"],"explanation":"“C级背景下的局部A级”适用于高风险无菌操作，包括非最终灭菌小容量注射剂的灌装、即时标记放射性药品的标记、无菌体内植入制品的分装与密封、医用核素发生器的灌装。口服制剂配制通常不需要局部A级环境，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌放射性药品的生产需符合药品GMP无菌附录要求。局部A级环境用于保证关键操作的无菌性，减少微生物和微粒污染风险。上述操作均涉及无菌产品暴露或灌装，需在C级背景下局部A级进行。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 67 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0068","type":"multiple","qtype":"多选题","stem":"下列属于“C级”洁净区适用的操作有（ ）","options":[{"key":"A","text":"采用除菌过滤工艺的非最终灭菌小容量注射剂制备"},{"key":"B","text":"医用核素发生器的物料准备和组装"},{"key":"C","text":"正电子类药品自动合成环境"},{"key":"D","text":"即时标记药品的淋洗"},{"key":"E","text":"无菌植入制品的焊封"}],"answer":["A","B","C","D"],"explanation":"“C级”洁净区适用于：采用除菌过滤工艺的非最终灭菌小容量注射剂制备；医用核素发生器的物料准备和组装；正电子类药品自动合成环境；即时标记药品的淋洗。无菌植入制品的焊封通常需要在更高洁净级别（如局部A级）下进行，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\nC级洁净区用于控制微生物和微粒污染，但不要求局部A级。即时标记药品的淋洗可在C级进行，而标记和灌装则需局部A级。正电子类药品自动合成环境、发生器物料准备和组装、除菌过滤前制备等操作均可在C级下进行。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 68 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0069","type":"multiple","qtype":"多选题","stem":"放射性洁净区空气循环使用的要求包括（ ）","options":[{"key":"A","text":"需充分风险评估依据"},{"key":"B","text":"采取有效措施避免污染"},{"key":"C","text":"即时标记药品洁净区可循环"},{"key":"D","text":"任意放射性洁净区可循环"},{"key":"E","text":"无需特殊措施"}],"answer":["A","B","C"],"explanation":"放射性洁净区空气循环使用需有充分风险评估依据，采取有效措施避免污染。即时标记药品洁净区可循环，但并非任意放射性洁净区都可循环，也不能无需特殊措施，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n空气循环使用需经风险评估，确保采取有效措施避免放射性污染扩散。即时标记药品洁净区在满足条件时可循环，但其他放射性洁净区需根据具体风险确定，不能一概而论。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 69 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0070","type":"multiple","qtype":"多选题","stem":"放射性药品生产区出入口的设施要求包括（ ）","options":[{"key":"A","text":"去污洗涤设施"},{"key":"B","text":"更衣设施"},{"key":"C","text":"放射性污染检测设备（出口）"},{"key":"D","text":"仅普通洗手池"},{"key":"E","text":"仅换鞋区"}],"answer":["A","B","C"],"explanation":"放射性药品生产区出入口应设置去污洗涤设施、更衣设施和放射性污染检测设备（出口）。仅普通洗手池或仅换鞋区不能满足辐射防护和污染控制要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n生产区出入口需设置去污洗涤设施、更衣设施和放射性污染检测设备，确保人员离开时进行污染检测和去污，防止放射性物质带出，符合辐射安全和职业健康要求。\n\n---","source":{"file":"多选题/61-70.md","merged":"多选题1-110.md","location":"第 70 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0071","type":"multiple","qtype":"多选题","stem":"贮存放射性物质的场所需具备的安全措施有（ ）","options":[{"key":"A","text":"防火"},{"key":"B","text":"防盗"},{"key":"C","text":"防泄漏"},{"key":"D","text":"明显警示标识"},{"key":"E","text":"普通货架存放"}],"answer":["A","B","C","D"],"explanation":"贮存放射性物质的场所需具备防火、防盗、防泄漏措施，并设置明显警示标识。普通货架存放不符合辐射防护和安全管理要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n贮存场所必须防火、防盗、防泄漏，并设置明显警示标识，以防止放射性药品丢失、被盗和泄漏，确保辐射安全。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 71 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0072","type":"multiple","qtype":"多选题","stem":"企业外购灭菌注射用水的管理要求包括（ ）","options":[{"key":"A","text":"对供应商进行审计"},{"key":"B","text":"确认供应商资质"},{"key":"C","text":"确认供应商质量符合要求"},{"key":"D","text":"仅关注价格"},{"key":"E","text":"随意购入"}],"answer":["A","B","C"],"explanation":"企业外购灭菌注射用水需对供应商进行审计，确认供应商资质和质量符合要求。仅关注价格或随意购入不符合质量管理要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n外购灭菌注射用水属于关键物料，企业需对供应商进行审计，确认其资质和质量符合要求，并建立严格的质量管理制度，确保物料质量可靠。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 72 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0073","type":"multiple","qtype":"多选题","stem":"放射性物质的物料管理要求包括（ ）","options":[{"key":"A","text":"与非放射性物质严格分开存放"},{"key":"B","text":"专库或专柜存放"},{"key":"C","text":"专人保管"},{"key":"D","text":"专册登记"},{"key":"E","text":"随意流转"}],"answer":["A","B","C","D"],"explanation":"放射性物质的物料管理要求包括：与非放射性物质严格分开存放；专库或专柜存放；专人保管；专册登记。随意流转不符合管理要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性物质必须与非放射性物质严格分开存放，实行专库或专柜存放，专人保管，专册登记，以防止混淆、丢失、被盗和泄漏，确保物料管理安全可控。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 73 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0074","type":"multiple","qtype":"多选题","stem":"物料、中间产品和成品在厂区内流转的措施包括（ ）","options":[{"key":"A","text":"防止混淆"},{"key":"B","text":"防止污染"},{"key":"C","text":"辐射防护"},{"key":"D","text":"随意堆放"},{"key":"E","text":"仅外观检查"}],"answer":["A","B","C"],"explanation":"物料、中间产品和成品在厂区内流转需采取措施防止混淆、防止污染，并做好辐射防护。随意堆放和仅外观检查不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n物料、中间产品和成品在厂区内流转时，必须采取防止混淆、防止污染和辐射防护措施，确保产品质量和人员安全，符合质量管理制度和辐射安全要求。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 74 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0075","type":"multiple","qtype":"多选题","stem":"放射性生产管理的核心要求包括（ ）","options":[{"key":"A","text":"放射性工作区有明显标志"},{"key":"B","text":"不同核素不得在同一操作箱生产"},{"key":"C","text":"同一核素不同品种需防混淆"},{"key":"D","text":"工作服不得混用"},{"key":"E","text":"仅关注生产效率"}],"answer":["A","B","C","D"],"explanation":"放射性生产管理的核心要求包括：放射性工作区有明显标志；不同核素不得在同一操作箱生产；同一核素不同品种需防混淆；工作服不得混用。仅关注生产效率不符合质量与安全管理要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作区需有明显标志，不同核素不得在同一操作箱生产，同一核素不同品种需防混淆，工作服不得混用，以防止交叉污染和混淆，确保生产安全和药品质量。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 75 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0076","type":"multiple","qtype":"多选题","stem":"即时标记放射性药品的批次管理规则包括（ ）","options":[{"key":"A","text":"同一钼锝发生器一次洗脱液+同批号药盒→一批"},{"key":"B","text":"同一发生器同日多次淋洗→亚批"},{"key":"C","text":"保证产品可追溯"},{"key":"D","text":"随意分批"},{"key":"E","text":"仅按生产日期分批"}],"answer":["A","B","C"],"explanation":"即时标记放射性药品的批次管理规则包括：同一钼锝发生器一次洗脱液加同批号药盒为一批；同一发生器同日多次淋洗为亚批；保证产品可追溯。随意分批或仅按生产日期分批不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n即时标记放射性药品因半衰期短，需按发生器洗脱液和药盒批号划分批次，同日多次淋洗可划分为亚批，并保证产品可追溯，以确保质量管理和追溯系统的有效性。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 76 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0077","type":"multiple","qtype":"多选题","stem":"放射性工作区工作服及器具的管理要求包括（ ）","options":[{"key":"A","text":"与非放射性区域严格分开"},{"key":"B","text":"清洗前进行放射性污染监测"},{"key":"C","text":"污染后先去污再使用"},{"key":"D","text":"随意清洗"},{"key":"E","text":"仅外观检查"}],"answer":["A","B","C"],"explanation":"放射性工作区工作服及器具的管理要求包括：与非放射性区域严格分开；清洗前进行放射性污染监测；污染后先去污再使用。随意清洗或仅外观检查不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作区工作服及器具需与非放射性区域严格分开，清洗前进行放射性污染监测，污染后先去污再使用，以防止放射性污染扩散，确保人员和环境安全。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 77 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0078","type":"multiple","qtype":"多选题","stem":"放射性药品成品包装的要求包括（ ）","options":[{"key":"A","text":"外包装贴标签"},{"key":"B","text":"外包装贴放射性药品标志"},{"key":"C","text":"附产品说明书"},{"key":"D","text":"内包装可提前贴标签（辐射防护需要）"},{"key":"E","text":"仅简单包装"}],"answer":["A","B","C","D"],"explanation":"放射性药品成品包装要求包括：外包装贴标签；外包装贴放射性药品标志；附产品说明书；内包装可提前贴标签（辐射防护需要）。仅简单包装不符合要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n成品包装需外包装贴标签和放射性药品标志，附产品说明书。因辐射防护需要，内包装可提前贴标签。包装必须安全实用，符合质量要求。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 78 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0079","type":"multiple","qtype":"多选题","stem":"放射性药品质量管理中，确认与验证的范围确定需考虑（ ）","options":[{"key":"A","text":"药品质量管理要求"},{"key":"B","text":"辐射防护要求"},{"key":"C","text":"风险管理方法"},{"key":"D","text":"仅生产需求"},{"key":"E","text":"仅成本因素"}],"answer":["A","B","C"],"explanation":"放射性药品质量管理中，确认与验证的范围确定需考虑药品质量管理要求、辐射防护要求和风险管理方法。仅考虑生产需求或成本因素不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n确认与验证的范围需综合考虑药品质量管理要求、辐射防护要求和风险管理方法，以确保生产工艺、设备和计算机化系统稳定可靠，符合质量管理和辐射安全要求。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 79 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0080","type":"multiple","qtype":"多选题","stem":"自动合成设备及计算机软件控制系统的验证要求包括（ ）","options":[{"key":"A","text":"一年至少验证一次"},{"key":"B","text":"发生变更时重新验证"},{"key":"C","text":"仅首次使用前验证"},{"key":"D","text":"无需验证"},{"key":"E","text":"仅软件更新后验证"}],"answer":["A","B"],"explanation":"自动合成设备及计算机软件控制系统需一年至少验证一次，发生变更时重新验证。仅首次使用前验证、无需验证或仅软件更新后验证均不符合要求，故C、D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n自动合成设备及计算机软件控制系统需定期验证，一年至少一次，变更后需重新验证，以确保设备性能稳定和数据可靠，符合质量管理制度和计算机化系统验证要求。\n\n---","source":{"file":"多选题/71-80.md","merged":"多选题1-110.md","location":"第 80 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0081","type":"multiple","qtype":"多选题","stem":"边检验边放行的放射性药品需完成的流程包括（ ）","options":[{"key":"A","text":"符合国家质量控制指导原则"},{"key":"B","text":"完成规定检验"},{"key":"C","text":"放行审核"},{"key":"D","text":"符合要求后方可放行"},{"key":"E","text":"随意放行"}],"answer":["A","B","C","D"],"explanation":"边检验边放行的放射性药品需完成以下流程：符合国家质量控制指导原则；完成规定检验；进行放行审核；符合要求后方可放行。随意放行不符合质量管理制度，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n边检验边放行是放射性药品因半衰期短、有效期短而采取的特殊放行方式，必须建立在严格的质量管理制度之上，确保符合国家质量控制指导原则，完成规定检验并经放行审核合格后方可放行。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 81 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0082","type":"multiple","qtype":"多选题","stem":"放射性药品留样的要求包括（ ）","options":[{"key":"A","text":"物料留样量满足鉴别需求"},{"key":"B","text":"成品留样量满足2倍全检量"},{"key":"C","text":"留样保存至有效期后30天以上"},{"key":"D","text":"随意留样"},{"key":"E","text":"仅保存1个月"}],"answer":["A","B","C"],"explanation":"放射性药品留样要求包括：物料留样量满足鉴别需求；成品留样量满足2倍全检量；留样保存至有效期后30天以上。随意留样或仅保存1个月不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n留样管理是质量管理制度的重要组成部分。物料留样量应满足鉴别需求，成品留样量应满足2倍全检量，留样保存至有效期后30天以上，以确保产品质量可追溯和稳定性考察需要。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 82 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0083","type":"multiple","qtype":"多选题","stem":"药品不良反应及放射性超剂量危害的处理要求包括（ ）","options":[{"key":"A","text":"及时控制措施"},{"key":"B","text":"详细记录事件经过"},{"key":"C","text":"调查处理"},{"key":"D","text":"按规定上报"},{"key":"E","text":"仅口头通知"}],"answer":["A","B","C","D"],"explanation":"药品不良反应及放射性超剂量危害的处理要求包括：及时控制措施；详细记录事件经过；调查处理；按规定上报。仅口头通知不符合要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n发生药品不良反应或放射性超剂量危害时，应及时采取控制措施，详细记录事件经过，进行调查处理，并按规定上报。企业需制定应急预案，确保患者和人员安全。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 83 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0084","type":"multiple","qtype":"多选题","stem":"不合格及退回/召回放射性药品的处置要求包括（ ）","options":[{"key":"A","text":"质量管理部门监督"},{"key":"B","text":"按放射性规定处置"},{"key":"C","text":"随意丢弃"},{"key":"D","text":"仅重新包装"},{"key":"E","text":"仅销毁"}],"answer":["A","B"],"explanation":"不合格及退回/召回放射性药品的处置要求包括：由质量管理部门监督；按放射性规定处置。随意丢弃、仅重新包装或仅销毁均不符合规定，故C、D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n不合格及退回/召回放射性药品的处置必须在质量管理部门监督下进行，并按照放射性规定处置，防止放射性污染和扩散，确保安全。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 84 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0085","type":"multiple","qtype":"多选题","stem":"企业辐射安全管理的核心要求包括（ ）","options":[{"key":"A","text":"取得《辐射安全许可证》"},{"key":"B","text":"人员辐射剂量监测"},{"key":"C","text":"按规定进行职业健康体检"},{"key":"D","text":"配备防护用品"},{"key":"E","text":"仅关注生产"}],"answer":["A","B","C","D"],"explanation":"企业辐射安全管理的核心要求包括：取得《辐射安全许可证》；进行人员辐射剂量监测；按规定进行职业健康体检；配备防护用品。仅关注生产不符合辐射安全管理要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n企业必须取得《辐射安全许可证》，对人员进行辐射剂量监测和职业健康体检，配备防护用品，确保辐射安全管理到位。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 85 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0086","type":"multiple","qtype":"多选题","stem":"放射性废物管理的要求包括（ ）","options":[{"key":"A","text":"配备专用容器"},{"key":"B","text":"分类存放（核素、活度、半衰期）"},{"key":"C","text":"符合国家处置规定"},{"key":"D","text":"随意排放"},{"key":"E","text":"仅简单收集"}],"answer":["A","B","C"],"explanation":"放射性废物管理的要求包括：配备专用容器；分类存放（按核素、活度、半衰期）；符合国家处置规定。随意排放或仅简单收集不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物需配备专用容器，按核素种类、活度和半衰期分类存放，并符合国家处置规定，以防止放射性污染和危害环境。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 86 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0087","type":"multiple","qtype":"多选题","stem":"下列属于“D级”洁净区适用的操作有（ ）","options":[{"key":"A","text":"口服制剂的物料准备"},{"key":"B","text":"正电子类药品密闭设备外环境"},{"key":"C","text":"无菌植入制品的焊封"},{"key":"D","text":"放射免疫分析药盒生产"},{"key":"E","text":"非最终灭菌小容量注射剂灌装"}],"answer":["A","B","C","D"],"explanation":"“D级”洁净区适用于：口服制剂的物料准备；正电子类药品密闭设备外环境；无菌植入制品的焊封；放射免疫分析药盒生产。非最终灭菌小容量注射剂灌装需在更高洁净级别（如C级背景下局部A级）进行，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产操作区洁净度级别需根据产品风险确定。D级适用于非无菌或低风险操作，如口服制剂物料准备、正电子类药品密闭设备外环境、无菌植入制品焊封、放射免疫分析药盒生产。非最终灭菌小容量注射剂灌装需在更高洁净级别下进行。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 87 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0088","type":"multiple","qtype":"多选题","stem":"放射性药品生产设备的要求包括（ ）","options":[{"key":"A","text":"与生产和质量控制相适应"},{"key":"B","text":"便于去除放射性污染"},{"key":"C","text":"具备辐射防护措施"},{"key":"D","text":"经改造后需再确认"},{"key":"E","text":"仅外观符合要求"}],"answer":["A","B","C","D"],"explanation":"放射性药品生产设备的要求包括：与生产和质量控制相适应；便于去除放射性污染；具备辐射防护措施；经改造后需再确认。仅外观符合要求不符合规定，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产设备需与生产和质量控制相适应，便于去除放射性污染，具备辐射防护措施，经改造后需再确认，以确保设备性能稳定和药品质量安全。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 88 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0089","type":"multiple","qtype":"多选题","stem":"放射性药品检验仪器的要求包括（ ）","options":[{"key":"A","text":"与质量控制相适应"},{"key":"B","text":"定期校准"},{"key":"C","text":"布局合理（避免干扰）"},{"key":"D","text":"仅普通仪器即可"},{"key":"E","text":"无需维护"}],"answer":["A","B","C"],"explanation":"放射性药品检验仪器的要求包括：与质量控制相适应；定期校准；布局合理（避免干扰）。仅普通仪器即可或无需维护不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验仪器需与质量控制相适应，定期校准，布局合理以避免相互干扰，确保检验结果准确可靠，符合质量管理制度要求。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 89 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0090","type":"multiple","qtype":"多选题","stem":"放射性药品追踪系统的功能包括（ ）","options":[{"key":"A","text":"发现质量安全不良事件"},{"key":"B","text":"控制质量风险"},{"key":"C","text":"向临床提供信息"},{"key":"D","text":"仅追踪销售"},{"key":"E","text":"仅追踪生产"}],"answer":["A","B","C"],"explanation":"放射性药品追踪系统的功能包括：发现质量安全不良事件；控制质量风险；向临床提供信息。仅追踪销售或仅追踪生产不全面，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性药品追踪系统应能发现质量安全不良事件，控制质量风险，并向临床提供信息，以确保药品可追溯和患者安全，符合质量管理制度要求。\n\n---","source":{"file":"多选题/81-90.md","merged":"多选题1-110.md","location":"第 90 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0091","type":"multiple","qtype":"多选题","stem":"医用放射性核素发生器的生产操作中，需在“C级”洁净区进行的有（ ）","options":[{"key":"A","text":"物料准备"},{"key":"B","text":"组装"},{"key":"C","text":"灌装（配套无菌产品）"},{"key":"D","text":"淋洗"},{"key":"E","text":"标记"}],"answer":["A","B"],"explanation":"医用放射性核素发生器的生产操作中，物料准备和组装需在C级洁净区进行。灌装（配套无菌产品）需在C级背景下局部A级进行；淋洗和标记属于即时标记放射性药品的生产操作，不适用于发生器的生产。因此选A、B。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n医用放射性核素发生器的生产需在相应洁净级别下进行，物料准备和组装在C级，灌装需在更高洁净级别。企业应建立严格质量管理制度，确保生产环境符合药品GMP和辐射安全要求。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 91 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0092","type":"multiple","qtype":"多选题","stem":"即时标记放射性药品的生产操作中，需在“C级”洁净区进行的有（ ）","options":[{"key":"A","text":"淋洗"},{"key":"B","text":"标记（局部A级）"},{"key":"C","text":"灌装（局部A级）"},{"key":"D","text":"物料准备"},{"key":"E","text":"包装"}],"answer":["A"],"explanation":"即时标记放射性药品的生产操作中，淋洗需在C级洁净区进行。标记和灌装需在C级背景下局部A级进行；物料准备和包装的洁净级别要求根据具体工艺确定，但本题明确答案为A。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n即时标记药品的淋洗在C级进行，标记和灌装在局部A级进行，以确保无菌。企业需建立严格质量管理制度，保证生产环境符合要求。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 92 题"},"tags":[],"reviewStatus":"needs-review","flags":["多选却单答案"],"reviewNote":"源文件标注为多选题，但正确答案只有 ['A']（A）"},{"id":"RP-M-0093","type":"multiple","qtype":"多选题","stem":"放射性药品包装容器重复使用的要求包括（ ）","options":[{"key":"A","text":"专用去污场所"},{"key":"B","text":"按规定清洗"},{"key":"C","text":"检测无放射性污染"},{"key":"D","text":"直接使用"},{"key":"E","text":"仅外观清洁"}],"answer":["A","B","C"],"explanation":"放射性药品包装容器重复使用需有专用去污场所，按规定清洗，并检测无放射性污染后方可使用。直接使用或仅外观清洁不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n重复使用的包装容器需专用去污场所，按规定清洗，检测无放射性污染，以防止放射性污染扩散和交叉污染。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 93 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0094","type":"multiple","qtype":"多选题","stem":"制药用水的管理要求包括（ ）","options":[{"key":"A","text":"符合《中国药典》标准"},{"key":"B","text":"防止微生物滋生"},{"key":"C","text":"自行制备需定期确认"},{"key":"D","text":"外购需审计供应商"},{"key":"E","text":"随意使用"}],"answer":["A","B","C","D"],"explanation":"制药用水管理要求包括：符合《中国药典》标准；防止微生物滋生；自行制备需定期确认；外购需审计供应商。随意使用不符合要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n制药用水需符合《中国药典》标准，防止微生物滋生。自行制备需定期确认，外购需审计供应商，确保水质符合要求，这是质量管理制度的重要组成部分。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 94 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0095","type":"multiple","qtype":"多选题","stem":"放射性工作区地面和工作台的要求包括（ ）","options":[{"key":"A","text":"便于去污"},{"key":"B","text":"耐腐蚀"},{"key":"C","text":"光滑平整"},{"key":"D","text":"仅美观"},{"key":"E","text":"仅耐磨"}],"answer":["A","B","C"],"explanation":"放射性工作区地面和工作台要求便于去污、耐腐蚀、光滑平整。仅美观或仅耐磨不符合要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作区地面和工作台需便于去污、耐腐蚀、光滑平整，以防止放射性物质残留和渗透，确保工作环境安全，符合辐射防护和质量管理要求。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 95 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0096","type":"multiple","qtype":"多选题","stem":"无菌放射性药品操作区的环境要求包括（ ）","options":[{"key":"A","text":"专门区域"},{"key":"B","text":"符合洁净度级别"},{"key":"C","text":"周围相对正压"},{"key":"D","text":"相对负压"},{"key":"E","text":"开放式环境"}],"answer":["A","B","C"],"explanation":"无菌放射性药品操作区要求包括：专门区域；符合洁净度级别；周围相对正压。相对负压和开放式环境不符合无菌操作要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌放射性药品操作区需为专门区域，符合洁净度级别，周围保持相对正压以防止外部污染。这是确保无菌药品质量的关键环境要求。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 96 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0097","type":"multiple","qtype":"多选题","stem":"操作挥发性放射性核素的专用设施包括（ ）","options":[{"key":"A","text":"专用排风系统"},{"key":"B","text":"排风口去污处理"},{"key":"C","text":"普通通风橱"},{"key":"D","text":"仅防护衣"},{"key":"E","text":"开放式工作台"}],"answer":["A","B"],"explanation":"操作挥发性放射性核素需配备专用排风系统和排风口去污处理。普通通风橱、仅防护衣或开放式工作台不能满足要求，故C、D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n操作挥发性放射性核素需专用排风系统，排风口需去污处理，以防止放射性气体扩散，保护人员和环境安全，符合废气处理设施要求。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 97 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0098","type":"multiple","qtype":"多选题","stem":"放射性药品生产人员的防护用品包括（ ）","options":[{"key":"A","text":"铅衣"},{"key":"B","text":"铅眼镜"},{"key":"C","text":"辐射剂量计"},{"key":"D","text":"普通工作服"},{"key":"E","text":"仅手套"}],"answer":["A","B","C"],"explanation":"放射性药品生产人员的防护用品包括铅衣、铅眼镜和辐射剂量计。普通工作服和仅手套不能满足辐射防护要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准。\n生产人员需配备铅衣、铅眼镜等个人防护用品，并佩戴辐射剂量计进行剂量监测，以符合辐射安全防护规定。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 98 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0099","type":"multiple","qtype":"多选题","stem":"放射性药品说明书需包含的内容有（ ）","options":[{"key":"A","text":"放射性核素半衰期"},{"key":"B","text":"辐射防护注意事项"},{"key":"C","text":"用法用量"},{"key":"D","text":"仅适应症"},{"key":"E","text":"仅不良反应"}],"answer":["A","B","C"],"explanation":"放射性药品说明书需包含放射性核素半衰期、辐射防护注意事项和用法用量。仅适应症或仅不良反应不完整，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n说明书需包含放射性核素半衰期、辐射防护注意事项、用法用量等内容，以指导临床安全使用，确保患者和医护人员了解辐射风险。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 99 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0100","type":"multiple","qtype":"多选题","stem":"放射性药品标签需包含的内容有（ ）","options":[{"key":"A","text":"药品名称"},{"key":"B","text":"批号"},{"key":"C","text":"放射性活度"},{"key":"D","text":"有效期"},{"key":"E","text":"仅生产企业"}],"answer":["A","B","C","D"],"explanation":"放射性药品标签需包含药品名称、批号、放射性活度和有效期。仅生产企业不完整，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n标签必须注明药品名称、批号、放射性活度、有效期等信息，并贴有放射性药品标志，以确保药品可追溯和使用安全。\n\n---","source":{"file":"多选题/91-100.md","merged":"多选题1-110.md","location":"第 100 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0101","type":"multiple","qtype":"多选题","stem":"同一核素不同品种放射性药品生产的防混淆措施包括（ ）","options":[{"key":"A","text":"专用设备"},{"key":"B","text":"彻底清场"},{"key":"C","text":"明确标识"},{"key":"D","text":"仅口头提醒"},{"key":"E","text":"随意切换"}],"answer":["A","B","C"],"explanation":"同一核素不同品种放射性药品生产的防混淆措施包括：专用设备；彻底清场；明确标识。仅口头提醒和随意切换不符合防混淆要求，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n同一核素不同品种生产时，需使用专用设备、彻底清场并明确标识，以防止混淆和交叉污染，确保药品质量，这是质量管理制度的基本要求。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 101 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0102","type":"multiple","qtype":"多选题","stem":"放射性药品生产清场记录需包含的内容有（ ）","options":[{"key":"A","text":"清场时间"},{"key":"B","text":"清场人员"},{"key":"C","text":"核素种类"},{"key":"D","text":"清洁情况"},{"key":"E","text":"仅日期"}],"answer":["A","B","C","D"],"explanation":"放射性药品生产清场记录需包含清场时间、清场人员、核素种类和清洁情况。仅日期不完整，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n清场记录是质量管理制度的重要组成部分，需包含清场时间、清场人员、核素种类和清洁情况，以确保清场彻底、可追溯，防止交叉污染。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 102 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0103","type":"multiple","qtype":"多选题","stem":"辐射剂量监测的对象包括（ ）","options":[{"key":"A","text":"生产人员"},{"key":"B","text":"检验人员"},{"key":"C","text":"维修人员"},{"key":"D","text":"销售人员"},{"key":"E","text":"仅管理人员"}],"answer":["A","B","C"],"explanation":"辐射剂量监测的对象包括生产人员、检验人员和维修人员。销售人员和仅管理人员不直接接触放射性物质，通常不需要常规剂量监测，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n直接从事放射性药品生产、检验和维修的人员需进行辐射剂量监测，以保障职业健康，符合辐射安全管理要求。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 103 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0104","type":"multiple","qtype":"多选题","stem":"职业健康体检的周期要求包括（ ）","options":[{"key":"A","text":"按国家规定执行"},{"key":"B","text":"定期进行"},{"key":"C","text":"仅入职时一次"},{"key":"D","text":"仅离职时一次"},{"key":"E","text":"无需体检"}],"answer":["A","B"],"explanation":"职业健康体检需按国家规定执行，并定期进行。仅入职时一次、仅离职时一次或无需体检均不符合要求，故C、D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n职业健康体检应按国家规定定期进行，以及时发现职业健康损害，保障从业人员健康，符合辐射防护和职业健康管理要求。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 104 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0105","type":"multiple","qtype":"多选题","stem":"《辐射安全许可证》的适用环节包括（ ）","options":[{"key":"A","text":"放射性药品生产"},{"key":"B","text":"销售"},{"key":"C","text":"使用"},{"key":"D","text":"运输"},{"key":"E","text":"储存"}],"answer":["A","B","C","D","E"],"explanation":"《辐射安全许可证》适用于放射性药品的生产、销售、使用、运输和储存等环节。以上选项均正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n《辐射安全许可证》是从事放射性药品生产、销售、使用、运输和储存等活动的法定许可文件，各环节均需取得相应许可，确保辐射安全。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 105 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0106","type":"multiple","qtype":"多选题","stem":"放射性药品配套药盒的组成包括（ ）","options":[{"key":"A","text":"待标记配体"},{"key":"B","text":"还原剂/氧化剂"},{"key":"C","text":"放射性核素"},{"key":"D","text":"赋形剂"},{"key":"E","text":"仅配体"}],"answer":["A","B","D"],"explanation":"放射性药品配套药盒的组成包括待标记配体、还原剂/氧化剂和赋形剂。放射性核素在临用前加入，不属于药盒出厂组成；仅配体不完整，故C、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n配套药盒本身不含放射性核素，需与淋洗得到的放射性核素配合使用。其组成包括待标记配体、还原剂/氧化剂和赋形剂，需进行方法学研究以确保质量。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 106 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0107","type":"multiple","qtype":"多选题","stem":"即时标记放射性药品的制备过程包括（ ）","options":[{"key":"A","text":"发生器淋洗得洗脱液"},{"key":"B","text":"加入配套药盒"},{"key":"C","text":"直接使用发生器"},{"key":"D","text":"无需标记"},{"key":"E","text":"仅混合即可"}],"answer":["A","B"],"explanation":"即时标记放射性药品的制备过程包括：发生器淋洗得洗脱液；加入配套药盒进行标记。直接使用发生器、无需标记或仅混合即可均不正确，故C、D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n即时标记药品需先用发生器淋洗得到放射性核素洗脱液，再加入配套药盒进行标记反应，生成最终药品。这是即时标记药品的典型制备过程。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 107 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0108","type":"multiple","qtype":"多选题","stem":"正电子类放射性药品的核心特征是（ ）","options":[{"key":"A","text":"含发射正电子的核素"},{"key":"B","text":"仅用于诊断"},{"key":"C","text":"仅用于治疗"},{"key":"D","text":"需加速器制备"},{"key":"E","text":"含正电子核素"}],"answer":["A","E"],"explanation":"正电子类放射性药品的核心特征是含有发射正电子的核素（正电子核素）。仅用于诊断或仅用于治疗不准确；需加速器制备是常见工艺，但不是核心特征。故B、C、D错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n正电子类放射性药品含有发射正电子的核素，如氟[18F]、碳[11C]等，其核心特征是含正电子核素，用于PET显像等诊断或治疗。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 108 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0109","type":"multiple","qtype":"多选题","stem":"放射性核素发生器的功能包括（ ）","options":[{"key":"A","text":"分离母体与子体核素"},{"key":"B","text":"母体半衰期长"},{"key":"C","text":"子体半衰期短"},{"key":"D","text":"直接生产药品"},{"key":"E","text":"仅储存核素"}],"answer":["A","B","C"],"explanation":"放射性核素发生器的功能包括：分离母体与子体核素；母体半衰期长；子体半衰期短。直接生产药品和仅储存核素不准确，故D、E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n放射性核素发生器利用母体核素衰变生成子体核素，并分离得到子体核素。母体半衰期长，子体半衰期短，便于临床即时使用。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 109 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-M-0110","type":"multiple","qtype":"多选题","stem":"放射性药品生产中“防止交叉污染”的措施包括（ ）","options":[{"key":"A","text":"不同核素操作区分开"},{"key":"B","text":"设备专用"},{"key":"C","text":"清洁工具专用"},{"key":"D","text":"工作服专用"},{"key":"E","text":"仅通风即可"}],"answer":["A","B","C","D"],"explanation":"防止交叉污染的措施包括：不同核素操作区分开；设备专用；清洁工具专用；工作服专用。仅通风即可不符合要求，故E错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n防止交叉污染是质量管理制度的核心内容。不同核素操作区需分开，设备、清洁工具和工作服应专用，以避免核素间交叉污染，确保药品质量和辐射安全。\n\n---","source":{"file":"多选题/101-110.md","merged":"多选题1-110.md","location":"第 110 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0001","type":"boolean","qtype":"判断题","stem":"《放射性药品生产检查指南（试行）》由国家药品监督管理局特殊药品检查中心发布，2025年3月1日施行。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"该指南由国家药品监督管理局特殊药品检查中心发布，并于2025年3月1日施行，用于指导放射性药品生产现场检查，规范检查行为，保障放射性药品质量与辐射安全。","lawTitle":"《放射性药品管理办法》相关条例","law":"第一条　为了加强放射性药品的管理，根据《中华人民共和国药品管理法》的规定，制定本办法。\n第三条　凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n第四条　国务院药品监督管理部门负责全国放射性药品监督管理工作。国务院国防科技工业主管部门依据职责负责与放射性药品有关的管理工作。国务院环境保护主管部门负责与放射性药品有关的辐射安全与防护的监督管理工作。\n国家药品监督管理局特殊药品检查中心作为技术支撑机构，依据上述职责发布检查指南，细化放射性药品生产检查要求。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 1 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0002","type":"boolean","qtype":"判断题","stem":"放射性药品因具有特殊性，《中华人民共和国药品管理法》将其定为普通处方药。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品因含有放射性核素，具有放射性、不恒定性、自辐射分解等特点，属于国家实行特殊管理的药品，并非普通处方药。其生产、经营、使用、运输、储存等环节均需遵守《放射性药品管理办法》及辐射安全相关规定。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n放射性药品按特殊药品管理，不是普通处方药，其生产经营需取得《放射性药品生产许可证》和《辐射安全许可证》。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 2 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0003","type":"boolean","qtype":"判断题","stem":"本指南适用于放射性药品生产、检验、放行、发运的全过程检查。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"本指南适用于放射性药品生产、检验、放行、发运的全过程检查，覆盖机构与人员、厂房设施、设备、物料、生产管理、质量控制、质量保证、辐射安全管理等环节，确保全过程持续符合药品GMP和辐射安全要求。","lawTitle":"《放射性药品管理办法》相关条例","law":"第三条　凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检查指南据此对生产、检验、放行、发运全过程提出检查要求。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 3 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0004","type":"boolean","qtype":"判断题","stem":"放射性药品生产仅包括放射性核素的生产和配体的生产两个环节。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产的核心环节不仅包括放射性核素的生产和配体的生产，还包括放射性核素与配体的结合（标记）、纯化、分装、灭菌、包装等。仅说两个环节不完整。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第十二条　放射性药品生产企业生产已有国家标准的放射性药品，必须经国务院药品监督管理部门征求国务院国防科技工业主管部门意见后审核批准，并发给批准文号。凡是改变国务院药品监督管理部门已批准的生产工艺路线和药品标准的，生产单位必须按原报批程序提出补充申请，经国务院药品监督管理部门批准后方能生产。\n可见生产环节涵盖核素制备、配体合成、标记结合及后续工艺，并非仅两个环节。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 4 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0005","type":"boolean","qtype":"判断题","stem":"钼[99Mo]-锝[99mTc]发生器俗称“母牛”，用于生产锝[99mTc]，其淋洗液为0.9%氯化钠注射液。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"钼[99Mo]-锝[99mTc]发生器俗称“母牛”，利用母体钼[99Mo]衰变生成子体锝[99mTc]，通过0.9%氯化钠注射液淋洗获得高锝[99mTc]酸钠注射液，用于后续标记制备锝[99mTc]放射性药品。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n钼[99Mo]-锝[99mTc]发生器属于放射性药品，其淋洗液为0.9%氯化钠注射液，包装需有铅罐等辐射防护装置。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 5 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0006","type":"boolean","qtype":"判断题","stem":"锝[99mTc]配套药盒本身含有放射性核素，需按放射性药品管理。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"锝[99mTc]配套药盒本身不含放射性核素，其处方组成包括配体、还原剂、赋形剂、稳定剂等。使用时需加入淋洗得到的锝[99mTc]洗脱液进行标记，生成最终放射性药品。因此，配套药盒属于待标记制剂，需按放射性药品相关要求管理，但本身不含放射性核素。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n配套药盒需与放射性核素配合使用，本身不含放射性核素，但属于放射性药品配套组成部分，需符合相关质量管理要求。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 6 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0007","type":"boolean","qtype":"判断题","stem":"正电子类放射性药品氟[18F]脱氧葡糖注射液的氟[18F]半衰期约为110分钟，需加速器制备。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"氟[18F]是正电子发射核素，半衰期约为110分钟，通常由回旋加速器制备。氟[18F]脱氧葡糖注射液（18F-FDG）是典型的正电子类放射性药品，用于PET显像。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续。\n正电子类放射性药品含发射正电子的核素，氟[18F]需加速器制备，生产需符合辐射安全和药品GMP要求。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 7 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0008","type":"boolean","qtype":"判断题","stem":"碘[125I]密封籽源的半衰期约为6.02小时，临床用于浅表肿瘤治疗。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"碘[125I]的半衰期约为60天，不是6.02小时。碘[125I]密封籽源属于放射性体内植入制品，主要用于近距离放射治疗，如前列腺癌等肿瘤的植入治疗，而非仅用于浅表肿瘤治疗。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n碘[125I]密封籽源作为放射性体内植入制品，其半衰期约60天，需按放射性药品管理，包装应有辐射防护装置。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 8 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0009","type":"boolean","qtype":"判断题","stem":"磷[32P]酸钠盐口服溶液用于治疗甲状腺疾病，碘[131I]化钠口服溶液用于治疗真性红细胞增多症。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"磷[32P]酸钠盐口服溶液主要用于治疗真性红细胞增多症等，碘[131I]化钠口服溶液主要用于治疗甲状腺功能亢进症和甲状腺癌等甲状腺疾病。题目中用途颠倒，因此错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n磷[32P]和碘[131I]均为治疗用放射性核素，但适应症不同，应严格按药品说明书和标准使用。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 9 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0010","type":"boolean","qtype":"判断题","stem":"体外放射性诊断试剂按原理分为放射免疫分析法（RIA）和免疫放射分析法（IRMA）两类。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"体外放射性诊断试剂按原理主要分为放射免疫分析法（RIA）和免疫放射分析法（IRMA）两类。RIA使用标记抗原与待测抗原竞争结合抗体；IRMA使用标记抗体与抗原发生非竞争性全量反应。两者均属于放射性体外诊断试剂。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n体外放射性诊断试剂按原理分为RIA和IRMA，均需按放射性药品相关要求进行研制、生产、经营和使用管理。\n\n---","source":{"file":"判断题/1-10.md","merged":"判断题1-110.md","location":"第 10 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0011","type":"boolean","qtype":"判断题","stem":"放射免疫分析法（RIA）中，碘[125I]标记抗原-抗体复合物与待测抗原含量呈正相关。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射免疫分析法（RIA）中，待测抗原与碘[125I]标记抗原竞争结合抗体。待测抗原含量越高，标记抗原-抗体复合物形成越少，因此标记抗原-抗体复合物与待测抗原含量呈负相关（逆相关），而非正相关。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\nRIA作为放射免疫分析药盒的典型原理，其方法学研究需明确竞争结合机制及标准曲线关系，确保检测结果准确可靠。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 11 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0012","type":"boolean","qtype":"判断题","stem":"免疫放射分析法（IRMA）标记抗体，与抗原发生非竞争性全量反应。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"免疫放射分析法（IRMA）使用过量标记抗体与待测抗原发生非竞争性全量反应，形成标记抗体-抗原复合物。复合物量与待测抗原含量呈正相关。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\nIRMA属于放射性体外诊断试剂，其方法学研究需验证非竞争性全量反应的特异性、灵敏度和精密度，确保临床检测有效。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 12 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0013","type":"boolean","qtype":"判断题","stem":"放射性药品生产厂房位置需与《药品生产许可证》“涉源部门”地址一致。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产厂房位置需与《辐射安全许可证》“涉源部门”地址一致，而非《药品生产许可证》。因为放射性药品涉及辐射安全，其场所必须符合辐射安全许可要求，并由环保部门监管。题目混淆了许可证类型，因此错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第四条　国务院药品监督管理部门负责全国放射性药品监督管理工作。国务院国防科技工业主管部门依据职责负责与放射性药品有关的管理工作。国务院环境保护主管部门负责与放射性药品有关的辐射安全与防护的监督管理工作。\n第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n厂房位置必须与《辐射安全许可证》载明的涉源地址一致，并满足辐射安全与防护要求。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 13 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0014","type":"boolean","qtype":"判断题","stem":"放射性核素操作区应与周围环境保持相对正压，即时标记类单向流工作台可保持相对负压。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性核素操作区应保持相对负压，以防止放射性物质扩散到周围环境；即时标记类单向流工作台为保护产品免受污染，可保持相对正压。题目描述恰好颠倒，因此错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n操作放射性核素的环境需保持相对负压，并具备辐射防护措施；即时标记类单向流工作台可保持相对正压以保护产品，两者要求不同，不可混淆。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 14 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0015","type":"boolean","qtype":"判断题","stem":"放射性核素生产场所内空气宜循环使用，即时标记药物洁净区空气不宜循环。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性核素生产场所内空气不宜循环使用，应经处理后排放，以防止放射性污染扩散；即时标记药物洁净区空气在充分风险评估并采取有效措施后可以循环使用。题目描述颠倒，因此错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n空气循环使用需经风险评估，放射性核素生产场所空气不宜循环，即时标记药物洁净区空气在满足条件时可循环，以确保辐射安全和药品质量。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 15 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0016","type":"boolean","qtype":"判断题","stem":"“C级背景下的局部A级”洁净区可用于口服制剂的配制。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"“C级背景下的局部A级”洁净区适用于高风险无菌操作，如非最终灭菌小容量注射剂灌装、即时标记放射性药品的标记和灌装、无菌体内植入制品的分装与密封等。口服制剂配制通常不需要局部A级环境，一般在D级或C级进行。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同剂型生产操作需在相应洁净级别下进行，口服制剂配制洁净要求较低，局部A级用于无菌高风险操作，不可混用。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 16 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0017","type":"boolean","qtype":"判断题","stem":"仓储区贮存放射性物质需专库/专柜、专人管理，专册登记。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"仓储区贮存放射性物质必须与非放射性物质严格分开，实行专库/专柜存放、专人管理、专册登记，并采取防火、防盗、防泄漏措施，设置明显警示标识。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性物质应专库或专柜存放，专人保管，专册登记，确保物料管理安全可控，防止丢失、被盗和泄漏。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 17 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0018","type":"boolean","qtype":"判断题","stem":"放射性检验人员进入检验场所无需佩戴个人剂量监测设备，只需穿防护衣。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性检验人员进入检验场所必须佩戴个人剂量监测设备，以监测受照剂量，并按规定进行职业健康检查。仅穿防护衣不足以保障人员安全，题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n检验人员属于直接从事放射性药品相关工作的人员，必须佩戴个人剂量监测设备，并定期进行职业健康检查，确保辐射安全。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 18 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0019","type":"boolean","qtype":"判断题","stem":"放射性药品生产设备经改造或重大维修后，无需再确认即可使用。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产设备经改造或重大维修后，必须重新进行确认，以确保设备性能稳定、符合生产要求。未经再确认直接使用可能导致产品质量风险。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n设备改造或重大维修后需再确认，是质量管理制度和确认与验证要求的重要内容，确保设备持续符合生产需求。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 19 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0020","type":"boolean","qtype":"判断题","stem":"自动合成设备和计算机软件控制系统生产放射性药品的，该系统每两年至少验证一次。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"自动合成设备和计算机软件控制系统用于生产放射性药品的，该系统应每年至少验证一次，发生变更时还需重新验证。题目说每两年验证一次，不符合要求，因此错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n自动合成设备及计算机软件控制系统需定期验证，一年至少一次，变更后重新验证，以确保设备性能稳定和数据可靠，符合质量管理制度和计算机化系统验证要求。\n\n---","source":{"file":"判断题/11-20.md","merged":"判断题1-110.md","location":"第 20 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0021","type":"boolean","qtype":"判断题","stem":"放射性药品生产企业需设立辐射防护管理机构及人员，建立放射性事故应急预案。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性药品生产企业必须设立辐射防护管理机构或配备专职人员，负责辐射安全管理工作，并建立放射性事故应急预案，定期演练，确保在事故发生时能及时有效处置，保障人员与环境安全。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n企业需设立辐射防护管理机构及人员，建立应急预案，符合上述条款要求。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 21 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0022","type":"boolean","qtype":"判断题","stem":"放射性药品生产涉及的工作服清洗前无需进行放射性污染检测，直接清洗即可。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产涉及的工作服可能受到放射性污染，清洗前必须进行放射性污染检测，确认无污染或经去污处理合格后方可清洗，以防止放射性物质扩散。直接清洗不符合辐射防护要求。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作服清洗前进行放射性污染检测，是辐射防护和质量管理的基本要求，企业需建立相应制度。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 22 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0023","type":"boolean","qtype":"判断题","stem":"锝[99mTc]即时标记药品的淋洗操作在C级洁净区，标记和分装在D级洁净区。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"锝[99mTc]即时标记药品的淋洗操作在C级洁净区进行，但标记和分装需在C级背景下局部A级进行，而非D级。D级洁净级别较低，不能满足无菌标记和分装的要求。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n即时标记药品的淋洗在C级，标记和分装在C级背景下局部A级，以确保无菌，符合质量管理制度对生产环境的要求。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 23 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0024","type":"boolean","qtype":"判断题","stem":"正电子类药品合成热室为C级洁净环境，分装热室为B级背景下局部A级。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"正电子类药品合成热室为C级洁净环境，分装热室应为C级背景下局部A级，而非B级背景下局部A级。题目中B级描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n正电子类药品生产需在相应洁净级别下进行，合成热室为C级，分装热室为C级背景下局部A级，确保无菌和辐射安全。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 24 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0025","type":"boolean","qtype":"判断题","stem":"碘[125I]具有挥发性，其生产操作应在手套箱或通风橱中进行，并保持负压。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"碘[125I]具有挥发性，生产操作应在手套箱或通风橱中进行，并保持负压，以防止放射性碘蒸气扩散，保护操作人员和环境安全。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n操作挥发性放射性核素需在专用设施中进行，保持负压，并配备废气处理设施，符合辐射安全防护要求。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 25 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0026","type":"boolean","qtype":"判断题","stem":"体外放射性诊断试剂盒不同品种可在同一操作台上同时组装，无需分开。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"体外放射性诊断试剂盒不同品种不得在同一操作台上同时组装，必须分开操作或更换品种时彻底清场，以防止交叉污染和混淆。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同品种生产需采取防混淆、防交叉污染措施，如专用设备、彻底清场、明确标识等，符合质量管理制度要求。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 26 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0027","type":"boolean","qtype":"判断题","stem":"委托生产18F-FDG注射液时，受托方使用的合成仪品牌型号可随意变更，无需审批。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"委托生产18F-FDG注射液时，受托方使用的合成仪品牌型号需与注册批准的一致，变更需按规定审批，不能随意变更。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十二条　放射性药品生产企业生产已有国家标准的放射性药品，必须经国务院药品监督管理部门征求国务院国防科技工业主管部门意见后审核批准，并发给批准文号。凡是改变国务院药品监督管理部门已批准的生产工艺路线和药品标准的，生产单位必须按原报批程序提出补充申请，经国务院药品监督管理部门批准后方能生产。\n受托方合成仪型号属于生产工艺组成部分，变更需审批，确保产品质量稳定。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 27 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0028","type":"boolean","qtype":"判断题","stem":"放射性药品生产企业需具备核素鉴别、活度测定等放行检验能力，其他项目不可委托检验。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产企业需具备核素鉴别、活度测定等放行检验能力，但其他项目在符合条件的情况下可以委托检验，并非绝对不可委托。题目中“其他项目不可委托检验”表述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n企业需具备关键放行检验能力，其他项目可委托有资质的机构检验，但需建立严格的质量管理制度，确保委托检验符合要求。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 28 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0029","type":"boolean","qtype":"判断题","stem":"质量控制实验室负责人需具有医药相关本科及以上学历或相关中级以上专业技术职称。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"质量控制实验室负责人需具有医药相关本科及以上学历或相关中级以上专业技术职称，具备相应的专业知识和质量管理能力，以确保实验室检验工作准确可靠。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n质量控制实验室负责人属于关键专业技术人员，需具备相应学历或职称，符合配备专业技术人员的要求。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 29 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0030","type":"boolean","qtype":"判断题","stem":"检验人员至少需具有大专以上学历，接受培训考核合格方可上岗。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品检验人员至少需具有中专/高中以上学历，接受岗位培训并考核合格方可上岗，而非必须大专以上学历。题目中“至少需具有大专以上学历”要求过高，不符合规定。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n检验人员需具备中专/高中以上学历，接受培训考核合格后上岗，企业应配备与检验相适应的专业技术人员。\n\n---","source":{"file":"判断题/21-30.md","merged":"判断题1-110.md","location":"第 30 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0031","type":"boolean","qtype":"判断题","stem":"半衰期＞20分钟的正电子类药品，每批使用前需测定性状、pH值、放射化学纯度、放射性活度。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"对于半衰期＞20分钟的正电子类放射性药品，因衰变相对较慢，每批使用前需测定性状、pH值、放射化学纯度和放射性活度，以确保药品质量符合要求。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n正电子类药品使用前检验是质量管理制度的重要内容，半衰期＞20分钟者需按批检验上述项目，确保临床使用安全有效。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 31 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0032","type":"boolean","qtype":"判断题","stem":"正电子类药品追溯性检验连续3批合格后，可定期抽验，至少每3个月一次全检。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"正电子类药品追溯性检验连续6批合格后，方可定期抽验，至少每月一次全检，而非连续3批合格后每3个月一次。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n追溯性检验需按规程进行，连续6批合格后可定期抽验，至少每月一次全检，确保药品质量持续稳定。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 32 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0033","type":"boolean","qtype":"判断题","stem":"锝[99mTc]药品使用前必检项目包括性状、pH值、放射化学纯度、放射性活度和颗粒大小。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"锝[99mTc]药品使用前必检项目包括性状、pH值、放射化学纯度、放射性活度和颗粒大小，以确保药品质量符合要求，保障临床使用安全。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n锝[99mTc]药品使用前检验是质量管理制度的要求，必检项目涵盖性状、pH值、放射化学纯度、放射性活度和颗粒大小，确保药品质量可控。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 33 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0034","type":"boolean","qtype":"判断题","stem":"新增供应商的钼[99Mo]-锝[99mTc]发生器，用于生产前无需对其淋洗液全检。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"新增供应商的钼[99Mo]-锝[99mTc]发生器，用于生产前必须对其淋洗液进行全检，以确认淋洗液质量符合要求，防止因供应商变更导致产品质量风险。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n新增供应商的发生器淋洗液需全检，是质量管理制度对物料变更控制的要求，确保药品质量稳定。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 34 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0035","type":"boolean","qtype":"判断题","stem":"多道γ谱仪需用标准源进行能量与效率刻度，无需制定期间核查规程。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"多道γ谱仪需用标准源进行能量与效率刻度，同时必须制定期间核查规程，定期进行期间核查，以确保仪器性能稳定、测量结果准确可靠。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n多道γ谱仪需进行能量与效率刻度，并制定期间核查规程，是质量管理制度对检验仪器管理的要求，确保检验数据准确可靠。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 35 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0036","type":"boolean","qtype":"判断题","stem":"放射性活度计检定的核素无需涵盖待测放射性药品含有的核素。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性活度计检定的核素必须涵盖待测放射性药品含有的核素，以确保测量结果准确可靠。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性活度计检定需涵盖待测核素，是质量管理制度对检验仪器管理的要求，确保活度测量准确。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 36 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0037","type":"boolean","qtype":"判断题","stem":"放射性色谱扫描仪部分型号运行时需要P10气体（氩气:甲烷=9:1）。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性色谱扫描仪部分型号在运行时需要P10气体（氩气与甲烷按9:1比例混合），用于检测放射性色谱峰。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性色谱扫描仪是检验仪器之一，其运行所需气体条件需符合仪器要求，确保检验结果准确，属于质量管理制度对设备管理的内容。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 37 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0038","type":"boolean","qtype":"判断题","stem":"液体闪烁计数器应布局在光照充足区域，便于操作。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"液体闪烁计数器应布局在避光、无强光干扰的区域，因为光照会影响测量结果。布局在光照充足区域不利于操作和测量准确性。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n检验仪器布局需合理，避免相互干扰，液体闪烁计数器应避光放置，是质量管理制度对检验仪器管理的要求。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 38 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0039","type":"boolean","qtype":"判断题","stem":"γ谱仪法鉴别核素时，测得光子能量与固有能量误差在±10keV或±6%范围内（取较大者），可判断为同一种核素。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"γ谱仪法鉴别核素时，测得光子能量与固有能量误差在±10keV或±6%范围内（取较大者），可判断为同一种核素。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。放射性药品的国家标准，由国务院药品监督管理部门药典委员会负责制定和修订，报国务院药品监督管理部门审批颁发。\nγ谱仪法鉴别核素需符合误差范围要求，是放射性药品质量控制的重要方法，确保核素鉴别准确。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 39 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0040","type":"boolean","qtype":"判断题","stem":"放射性核纯度测定中，所有核素均可用碘化钠探测器，无需高纯锗探测器。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性核纯度测定中，能量相近的核素需使用高纯锗探测器，能量差别大的核素可用碘化钠探测器。并非所有核素都可用碘化钠探测器，题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性核纯度测定需根据核素能量差异选择合适探测器，确保核杂质有效检出，是质量管理制度对检验方法的要求。\n\n---","source":{"file":"判断题/31-40.md","merged":"判断题1-110.md","location":"第 40 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0041","type":"boolean","qtype":"判断题","stem":"放射性药品的产品检验仅需进行使用前检验，无需追溯性检验。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":null,"lawTitle":null,"law":null,"source":{"file":"判断题.md","merged":"判断题.md","location":"考试库源第 31 题","note":"主题库源中该位置与 RP-B-0041 前的同题完全重复，按考试库源替换为唯一题目"},"tags":[],"reviewStatus":"verified","flags":["来源替换为考试库源","无解析（源文件未提供）"]},{"id":"RP-B-0042","type":"boolean","qtype":"判断题","stem":"碘[125I]密封籽源稳定性考察可使用留样，无需单独留存稳定性样品。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":null,"lawTitle":null,"law":null,"source":{"file":"判断题.md","merged":"判断题.md","location":"考试库源第 32 题","note":"主题库源中该位置与 RP-B-0042 前的同题完全重复，按考试库源替换为唯一题目"},"tags":[],"reviewStatus":"verified","flags":["来源替换为考试库源","无解析（源文件未提供）"]},{"id":"RP-B-0043","type":"boolean","qtype":"判断题","stem":"放射化学纯度测定时，纸色谱和薄层色谱展开用容器无需密闭。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射化学纯度测定时，纸色谱和薄层色谱展开用容器必须密闭，以防止放射性物质挥发和扩散，确保操作安全和结果准确。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射化学纯度测定需在密闭容器中进行色谱操作，防止放射性挥发，是质量管理制度对检验操作的要求。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 43 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0044","type":"boolean","qtype":"判断题","stem":"放射性活度测定时，若读数较低、最后一位有变化，应重复测量5次取平均值。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性活度测定时，若读数较低、最后一位有变化，应重复测量10次取平均值，而非5次。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性活度测定需按规程操作，读数波动时重复10次取平均，是质量管理制度对检验操作的要求，确保测量结果准确可靠。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 44 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0045","type":"boolean","qtype":"判断题","stem":"生物分布试验的实验动物无需来源证明，实验人员无需资质。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"生物分布试验的实验动物需有合格证明，实验人员需具备相应资质，实验环境需符合国家要求，以确保试验结果科学可靠。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生物分布试验是放射性药品质量控制的重要项目，需使用有合格证明的实验动物，实验人员需具备相应资质，符合质量管理制度要求。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 45 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0046","type":"boolean","qtype":"判断题","stem":"放射性药品生产企业需建立变更控制系统，所有变更均需药品监督管理部门批准。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产企业需建立变更控制系统，但变更分为不同级别，并非所有变更均需药品监督管理部门批准。重大变更需审批，轻微变更可由企业评估后实施。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十二条　放射性药品生产企业生产已有国家标准的放射性药品，必须经国务院药品监督管理部门征求国务院国防科技工业主管部门意见后审核批准，并发给批准文号。凡是改变国务院药品监督管理部门已批准的生产工艺路线和药品标准的，生产单位必须按原报批程序提出补充申请，经国务院药品监督管理部门批准后方能生产。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n变更控制需根据变更性质分级管理，并非所有变更均需监管部门批准，企业需建立变更控制系统，符合质量管理制度要求。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 46 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0047","type":"boolean","qtype":"判断题","stem":"偏差处理需记录偏差的报告、记录、调查、处理及纠正措施，并有相应记录。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"偏差处理需记录偏差的报告、记录、调查、处理及纠正措施，并有相应记录，以确保偏差得到及时有效处理，防止再次发生。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n偏差处理是质量管理制度的重要组成部分，需完整记录报告、调查、处理及纠正措施，确保质量管理体系有效运行。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 47 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0048","type":"boolean","qtype":"判断题","stem":"纠正预防措施系统仅需处理投诉和召回，无需处理偏差和外部检查结果。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"纠正预防措施系统不仅需处理投诉和召回，还需处理偏差、外部检查结果等，以全面识别和改进质量问题。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n纠正预防措施系统是质量管理制度的核心内容，需涵盖偏差、投诉、召回、外部检查结果等，确保质量管理体系持续改进。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 48 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0049","type":"boolean","qtype":"判断题","stem":"质量管理部门对主要物料供应商的质量体系进行审计，对不合格供应商无否决权。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"质量管理部门对主要物料供应商的质量体系进行审计，并对不合格供应商有否决权，有权拒绝使用不合格供应商的物料。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n质量管理部门需对供应商进行审计，并对不合格供应商行使否决权，是质量管理制度对物料供应商管理的要求，确保物料质量可靠。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 49 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0050","type":"boolean","qtype":"判断题","stem":"产品质量回顾需每年按品种进行，确认工艺稳定及标准适用性。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"产品质量回顾需每年按品种进行，确认工艺稳定及标准适用性，并回顾偏差、投诉、召回等情况，以持续改进质量体系。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n产品质量回顾是质量管理制度的重要环节，每年按品种进行，确认工艺稳定性和标准适用性，确保放射性药品安全有效。\n\n---","source":{"file":"判断题/41-50.md","merged":"判断题1-110.md","location":"第 50 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0051","type":"boolean","qtype":"判断题","stem":"药品不良反应发生后，企业无需记录，仅需按规定上报即可。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"药品不良反应发生后，企业必须详细记录事件经过、调查、处理等情况，并按规定上报。仅上报而不记录不符合药品不良反应监测管理要求。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n药品不良反应监测是质量管理制度的重要内容，需建立管理制度及操作程序，详细记录事件经过、调查、处理，并按规定上报，确保患者安全。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 51 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0052","type":"boolean","qtype":"判断题","stem":"边检验边放行的放射性药品发现质量问题，无需通知使用单位，直接销毁即可。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"边检验边放行的放射性药品发现质量问题时，必须立即通知使用单位停止使用，并采取相应控制措施，不能仅直接销毁而不通知。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n边检验边放行的放射性药品发现质量问题，需立即通知使用单位停止使用，并向临床提供信息和技术指导，建立药品追踪系统，确保患者安全，符合质量管理制度要求。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 52 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0053","type":"boolean","qtype":"判断题","stem":"洁净区内检验间通风柜未安装排风通道，排风直接排放在房间内，属于典型缺陷。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"洁净区内检验间通风柜未安装排风通道，排风直接排放在房间内，会导致放射性物质或有害气体在洁净区内扩散，属于典型缺陷。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n通风柜需安装排风通道，将废气排出，是辐射防护和洁净区管理的基本要求，未安装排风通道属于典型缺陷。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 53 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0054","type":"boolean","qtype":"判断题","stem":"检前暂存库冰箱温度计已过校准有效期，不属于典型缺陷。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"检前暂存库冰箱温度计已过校准有效期，属于典型缺陷。温度计超校准期会导致温度监测数据不可靠，影响放射性药品贮存质量。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n检验仪器需定期校准，温度计超校准期属于违反质量管理制度，是典型缺陷。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 54 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0055","type":"boolean","qtype":"判断题","stem":"更换锝[99mTc]配套药盒供应商后，企业可在无菌检验未结束前投入生产。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"更换锝[99mTc]配套药盒供应商后，必须完成无菌检验并合格后方可投入生产，不能在无菌检验未结束前投入生产。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n更换供应商后需对配套药盒进行验证性全检，无菌检验合格后方可生产，是质量管理制度对供应商变更控制的要求。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 55 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0056","type":"boolean","qtype":"判断题","stem":"氟[18F]脱氧葡糖注射液批检验记录无需记录放射化学纯度展开剂的配制批号。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"氟[18F]脱氧葡糖注射液批检验记录必须记录放射化学纯度展开剂的配制批号，以确保检验数据可追溯。未记录属于典型缺陷。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n批检验记录需完整可追溯，记录展开剂配制批号是数据可靠性要求，未记录违反质量管理制度。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 56 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0057","type":"boolean","qtype":"判断题","stem":"碘[125I]密封籽源生产工艺验证中未明确关键质量属性和关键工艺参数，属于典型缺陷。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"碘[125I]密封籽源生产工艺验证中未明确关键质量属性和关键工艺参数，属于典型缺陷。工艺验证需明确关键质量属性和关键工艺参数，以确保工艺稳定可靠。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n工艺验证需明确关键质量属性和关键工艺参数，是质量管理制度对确认与验证的要求，未明确属于典型缺陷。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 57 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0058","type":"boolean","qtype":"判断题","stem":"放射性药品外包装材料无需具备辐射防护性能，只需符合普通包装要求。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品外包装材料必须具有与放射性剂量相适应的辐射防护性能，符合国家相关规定，不能仅符合普通包装要求。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n外包装材料需具备辐射防护性能，符合国家相关规定，是包装管理的强制要求。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 58 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0059","type":"boolean","qtype":"判断题","stem":"自动合成系统变更后，无需重新进行设备确认和计算机化系统验证。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"自动合成系统变更后，必须重新进行设备确认和计算机化系统验证，以确保设备性能稳定和数据可靠。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n自动合成系统变更后需重新验证，是质量管理制度对确认与验证的要求，确保设备持续符合生产需求。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 59 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0060","type":"boolean","qtype":"判断题","stem":"进入洁净区的工作人员培训未涵盖微生物学基础知识，属于典型缺陷。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"进入洁净区的工作人员培训必须涵盖微生物学基础知识，以确保人员了解洁净区污染控制要求。未涵盖属于典型缺陷。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n人员培训需涵盖岗位相关专业知识、辐射防护知识、微生物学基础知识等，未涵盖属于违反质量管理制度，是典型缺陷。\n\n---","source":{"file":"判断题/51-60.md","merged":"判断题1-110.md","location":"第 60 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0061","type":"boolean","qtype":"判断题","stem":"本附录适用于含放射性核素的临床诊断或治疗制剂，包括普通化学药品。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"本附录适用于含放射性核素的临床诊断或治疗制剂，即放射性药品，包括医用放射性核素发生器及其配套药盒、即时标记放射性药品、正电子类放射性药品和放射性体内植入制品等，但不包括普通化学药品。普通化学药品不含放射性核素，不属于放射性药品范畴。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第三条　凡在中华人民共和国领域内进行放射性药品的研究、生产、经营、运输、使用、检验、监督管理的单位和个人都必须遵守本办法。\n普通化学药品不含放射性核素，不适用本附录，而应遵循普通药品GMP要求。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 61 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0062","type":"boolean","qtype":"判断题","stem":"放射性药品的管理中，涉及特殊要求的，以本附录为准；无特殊要求的，遵循药品GMP（2010年修订）通用要求。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性药品生产质量管理中，涉及放射性特殊要求的，以本附录为准；无特殊要求的，遵循药品GMP（2010年修订）通用要求。这一原则体现了特殊管理与通用要求相结合，确保放射性药品质量与安全。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性药品除需符合药品GMP通用要求外，还需满足辐射安全等特殊要求，本附录对特殊要求作出专门规定。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 62 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0063","type":"boolean","qtype":"判断题","stem":"产品有效期为35天的放射性药品，经企业质量管理部门评估后可申请边检验边放行。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品可申请“边检验边放行”的条件包括：产品有效期＜30天，所含核素半衰期＜30天，并经企业质量管理部门风险评估。产品有效期为35天不满足＜30天的条件，因此不能申请边检验边放行。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n边检验边放行是放射性药品因半衰期短、有效期短而采取的特殊放行方式，需符合产品有效期和核素半衰期的限定条件，并经质量管理部门评估。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 63 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0064","type":"boolean","qtype":"判断题","stem":"企业设置的机构只需符合普通药品生产要求，无需考虑放射性药品特性。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"企业设置的机构除符合普通药品生产要求外，还必须考虑放射性药品特性，配备辐射防护管理机构或人员，建立辐射安全管理制度，确保辐射安全与药品质量。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n企业机构设置需考虑放射性药品特性，设立辐射防护管理机构及人员，建立应急预案，符合辐射安全管理要求。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 64 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0065","type":"boolean","qtype":"判断题","stem":"放射性药品生产管理负责人需具备核医（药）学或相关专业知识及工作经验。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性药品生产管理负责人、质量管理负责人及质量受权人除符合《药品生产质量管理规范》相关资质外，还需具备核医（药）学或相关专业知识及放射性药品相关工作经验，以确保生产质量管理符合放射性药品特殊要求。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n生产管理负责人属于关键专业技术人员，需具备核医（药）学知识及工作经验，符合配备与放射性药品相适应的专业技术人员的要求。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 65 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0066","type":"boolean","qtype":"判断题","stem":"企业仅需对生产人员进行辐射防护培训，检验人员无需培训。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"企业应对各岗位人员进行培训，包括生产人员、检验人员等，培训内容应涵盖岗位相关专业知识、辐射防护知识、放射性污染处理方法等。检验人员同样需要培训，不能仅对生产人员培训。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n企业需对生产、检验等各岗位人员进行培训，确保其具备相应能力，符合质量管理制度和辐射安全要求。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 66 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0067","type":"boolean","qtype":"判断题","stem":"放射性工作区与非放射性工作区无需隔离，可共用通道。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性工作区与非放射性工作区必须有效隔离，不能共用通道，以防止放射性污染扩散和交叉污染。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性工作区与非放射性工作区需有效隔离，是辐射防护和质量管理的基本要求，防止交叉污染。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 67 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0068","type":"boolean","qtype":"判断题","stem":"不同放射性核素的生产操作区应严格分开，防止混淆。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"不同放射性核素的生产操作区应严格分开，以防止核素间交叉污染和混淆，确保药品质量和辐射安全。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同核素操作区严格分开，是防止交叉污染和混淆的重要措施，符合质量管理制度要求。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 68 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0069","type":"boolean","qtype":"判断题","stem":"操作放射性核素应在相对正压的开放环境下进行。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"操作放射性核素应在相对负压的封闭环境下进行，以防止放射性物质扩散到周围环境。相对正压的开放环境会导致放射性物质外泄，不符合辐射防护要求。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n操作放射性核素需在相对负压、封闭的环境中进行，并具备辐射防护措施，符合辐射安全防护要求。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 69 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0070","type":"boolean","qtype":"判断题","stem":"即时标记生产中使用的单向流工作台可在正压下操作。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"即时标记生产中使用的单向流工作台为保护产品免受污染，可在正压下操作，以维持局部A级洁净环境，防止外部污染进入。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n即时标记生产中单向流工作台可保持相对正压，以保护产品，是洁净区环境控制的要求，符合质量管理制度。\n\n---","source":{"file":"判断题/61-70.md","merged":"判断题1-110.md","location":"第 70 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0071","type":"boolean","qtype":"判断题","stem":"放射性洁净区的空气均可直接循环使用，无需风险评估。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性洁净区的空气循环使用需经充分风险评估，并采取有效措施避免污染。并非所有放射性洁净区空气均可直接循环使用，只有经评估确认风险可控的区域（如即时标记药品洁净区）才可循环。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n空气循环使用需经风险评估，并采取有效措施，是辐射防护和质量管理的基本要求，不能无条件直接循环。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 71 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0072","type":"boolean","qtype":"判断题","stem":"放射性核素工作场所的地面和工作台应便于去污。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性核素工作场所的地面和工作台应便于去污，通常要求光滑平整、耐腐蚀，以防止放射性物质残留和渗透，确保工作环境安全。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n地面和工作台便于去污，是辐射防护和洁净区管理的基本要求，符合质量管理制度。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 72 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0073","type":"boolean","qtype":"判断题","stem":"放射性药品生产区出口无需设置放射性污染检测设备。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产区出口必须设置放射性污染检测设备，对离开人员和物品进行污染检测，防止放射性物质带出，保障人员和环境安全。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n出口设置放射性污染检测设备，是辐射防护和污染控制的基本要求，符合质量管理制度。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 73 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0074","type":"boolean","qtype":"判断题","stem":"非最终灭菌小容量注射剂的灌装应在“C级背景下的局部A级”洁净区进行。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"非最终灭菌小容量注射剂的灌装属于高风险无菌操作，应在“C级背景下的局部A级”洁净区进行，以确保产品无菌。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n无菌放射性药品的生产需符合药品GMP无菌附录要求，灌装操作应在C级背景下局部A级进行，符合质量管理制度。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 74 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0075","type":"boolean","qtype":"判断题","stem":"口服制剂的物料准备应在“C级”洁净区进行。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"口服制剂的物料准备通常在“D级”洁净区进行，而非“C级”。C级洁净区适用于更高风险的操作，如非最终灭菌注射剂制备等。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同剂型生产操作需在相应洁净级别下进行，口服制剂物料准备洁净要求较低，一般在D级进行。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 75 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0076","type":"boolean","qtype":"判断题","stem":"动态监测可能损坏仪器时，可在设备调试期间进行净化空气悬浮粒子测试。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"当动态监测可能损坏仪器时，可在设备调试期间进行净化空气悬浮粒子测试，以评估洁净区环境是否符合要求，同时保护仪器安全。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n洁净区环境监测需根据实际情况合理安排，动态监测可能损坏仪器时，可在设备调试期间进行测试，符合质量管理制度对环境监测的要求。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 76 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0077","type":"boolean","qtype":"判断题","stem":"贮存放射性物质的场所只需具备防火措施，无需防泄漏。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"贮存放射性物质的场所必须同时具备防火、防盗、防泄漏措施，并设置明显警示标识，不能仅防火而不防泄漏。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n贮存场所需防火、防盗、防泄漏，并设置明显警示标识，符合辐射安全管理要求。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 77 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0078","type":"boolean","qtype":"判断题","stem":"放射性物质包装容器如需重复使用，无需专用去污场所。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性物质包装容器如需重复使用，必须设有专用去污场所，按规定清洗并检测无放射性污染后方可使用，不能无专用去污场所。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n重复使用的包装容器需专用去污场所，按规定清洗，检测无放射性污染，符合辐射防护要求。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 78 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0079","type":"boolean","qtype":"判断题","stem":"企业外购灭菌注射用水时，无需对供应商进行审计，直接购入即可。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"企业外购灭菌注射用水时，必须对供应商进行审计，确认供应商资质和质量符合要求，不能直接购入而不审计。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n外购灭菌注射用水属于关键物料，需对供应商进行审计，确认其资质和质量符合要求，符合质量管理制度。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 79 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0080","type":"boolean","qtype":"判断题","stem":"制药用水的贮存和使用无需采取防止微生物滋生的措施。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"制药用水的贮存和使用必须采取防止微生物滋生的措施，如定期消毒、循环保存等，以确保水质符合《中国药典》标准。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n制药用水需符合《中国药典》标准，贮存和使用需防止微生物滋生，是质量管理制度对制药用水管理的要求。\n\n---","source":{"file":"判断题/71-80.md","merged":"判断题1-110.md","location":"第 80 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0081","type":"boolean","qtype":"判断题","stem":"放射性物质与非放射性物质可混合存放，无需严格分开。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性物质必须与非放射性物质严格分开存放，以防止放射性污染扩散和交叉污染。混合存放不符合辐射防护和物料管理要求。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n放射性物质与非放射性物质严格分开存放，是防止交叉污染和辐射安全的基本要求，符合质量管理制度。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 81 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0082","type":"boolean","qtype":"判断题","stem":"放射性物质应专库、专人保管、专册登记。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性物质应实行专库或专柜存放、专人保管、专册登记，以防止丢失、被盗和泄漏，确保物料管理安全可控。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n专库、专人保管、专册登记是放射性物质管理的核心要求，符合上述条款。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 82 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0083","type":"boolean","qtype":"判断题","stem":"物料在厂区内流转时，无需采取辐射防护措施。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"物料、中间产品和成品在厂区内流转时，必须采取防止混淆、防止污染和辐射防护措施，不能无需辐射防护。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n物料流转需采取辐射防护措施，是质量管理制度和辐射安全防护的基本要求。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 83 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0084","type":"boolean","qtype":"判断题","stem":"放射性工作区域应有明显的放射性标志。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性工作区域应设置明显的放射性标志，以警示人员注意辐射风险，防止误入和误操作。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n放射性工作区域设置明显标志，是辐射防护和安全管理的基本要求，符合上述条款精神。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 84 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0085","type":"boolean","qtype":"判断题","stem":"不同核素的药品可在同一操作箱生产，只需做好记录。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"不同核素的药品不得在同一操作箱生产，必须严格分开操作区，以防止核素间交叉污染和混淆。仅做好记录不足以控制风险。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n不同核素操作区严格分开，是防止交叉污染的基本要求，符合质量管理制度。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 85 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0086","type":"boolean","qtype":"判断题","stem":"即时标记药品同一钼锝发生器同日多次淋洗，每次制备的制剂作为亚批管理。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"即时标记药品同一钼锝发生器同日多次淋洗，每次制备的制剂作为亚批管理，以保证产品可追溯和质量可控。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n即时标记药品批次管理需按发生器洗脱液和药盒批号划分批次，同日多次淋洗可划分为亚批，符合质量管理制度对追溯性的要求。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 86 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0087","type":"boolean","qtype":"判断题","stem":"放射性工作区与非放射性工作区的工作服可混用。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性工作区与非放射性工作区的工作服不得混用，必须严格分开，以防止放射性污染扩散。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作服分开使用是防止交叉污染的基本要求，符合质量管理制度。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 87 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0088","type":"boolean","qtype":"判断题","stem":"放射性工作区使用的工作服清洗前无需进行放射性污染监测。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性工作区使用的工作服清洗前必须进行放射性污染监测，确认无污染或经去污处理合格后方可清洗，以防止放射性物质扩散。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n工作服清洗前进行放射性污染监测，是辐射防护和质量管理的基本要求。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 88 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0089","type":"boolean","qtype":"判断题","stem":"放射性药品成品外包装只需贴标签，无需附说明书。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品成品外包装不仅需贴标签，还必须附产品说明书，以指导临床安全使用。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。包装必须分内包装和外包装两部分，外包装必须贴有商标、标签、说明书和放射性药品标志，内包装必须贴有标签。\n外包装必须附说明书，是包装管理的强制要求。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 89 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0090","type":"boolean","qtype":"判断题","stem":"重复使用的放射性包装容器，无需清洗即可直接使用。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"重复使用的放射性包装容器必须按规定清洗，并检测无放射性污染后方可使用，不能无需清洗直接使用。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十四条　放射性药品的包装必须安全实用，符合放射性药品质量要求，具有与放射性剂量相适应的防护装置。\n第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n重复使用包装容器需清洗和检测，是防止放射性污染扩散的基本要求。\n\n---","source":{"file":"判断题/81-90.md","merged":"判断题1-110.md","location":"第 90 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0091","type":"boolean","qtype":"判断题","stem":"放射性药品生产相关的确认和验证范围仅需考虑质量管理要求，无需考虑辐射防护。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品生产相关的确认和验证范围不仅需考虑药品质量管理要求，还必须考虑辐射防护要求及风险管理方法。仅考虑质量管理而忽略辐射防护，无法保证生产过程中人员和环境的安全。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n确认与验证是质量管理制度的重要内容，同时辐射防护要求也是放射性药品生产必须满足的法定条件，二者不可偏废。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 91 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0092","type":"boolean","qtype":"判断题","stem":"使用自动合成设备生产放射性药品的，一年至少验证一次。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"使用自动合成设备生产放射性药品的，该系统应每年至少验证一次，发生变更时还需重新验证，以确保设备性能稳定、数据可靠。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n自动合成设备及计算机软件控制系统需定期验证，一年至少一次，是质量管理制度对设备确认与验证的基本要求。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 92 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0093","type":"boolean","qtype":"判断题","stem":"自动合成设备发生变更时，无需重新验证，直接使用即可。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"自动合成设备发生变更时，必须重新进行设备确认和计算机化系统验证，以确保变更后设备性能稳定、数据可靠，不能直接使用。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n变更后重新验证是质量管理制度对确认与验证的要求，确保设备持续符合生产需求。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 93 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0094","type":"boolean","qtype":"判断题","stem":"边检验边放行的放射性药品无需完成规定检验，可直接放行。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"边检验边放行的放射性药品仍需完成规定检验，并经放行审核符合要求后方可放行，不能未经检验直接放行。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n边检验边放行是特殊放行方式，但必须建立在完成规定检验和放行审核合格的基础上，确保药品质量可控。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 94 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0095","type":"boolean","qtype":"判断题","stem":"放射性药品在检验前可贮存一段时间，使其衰变到适合实验操作的活度。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性药品活度较高时，可在检验前贮存一段时间，使其衰变到适合实验操作的活度，以保证检验人员安全和检验结果准确。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n检验前适当衰变是辐射防护的合理措施，符合保护人员健康的要求。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 95 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0096","type":"boolean","qtype":"判断题","stem":"企业无需建立放射性药品追踪系统，仅关注生产即可。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"企业必须建立放射性药品追踪系统，以发现质量安全不良事件、控制质量风险并向临床提供信息，不能仅关注生产。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n追踪系统是质量管理制度的重要组成部分，确保药品可追溯和患者安全。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 96 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0097","type":"boolean","qtype":"判断题","stem":"物料的留样量只需满足全检需求，无需仅满足鉴别。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"物料留样量应满足鉴别需求，而成品留样量应满足2倍全检量。题目说物料留样只需满足全检需求、无需满足鉴别，表述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n留样管理是质量管理制度的重要内容，物料留样量应满足鉴别需求，成品留样量应满足2倍全检量，确保质量可追溯。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 97 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0098","type":"boolean","qtype":"判断题","stem":"放射性成品留样量应满足注册批准质量标准2倍的全检量。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"放射性成品留样量应满足注册批准质量标准2倍的全检量，以确保有足够样品用于必要的检验和复核。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n成品留样量满足2倍全检量，是质量管理制度对留样管理的基本要求，保证药品质量可追溯。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 98 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0099","type":"boolean","qtype":"判断题","stem":"放射性药品留样保存至药品有效期即可，无需延长至有效期后30天。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品留样应保存至有效期后30天以上，而非仅保存至有效期即可。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n留样保存至有效期后30天以上，是质量管理制度对留样管理的要求，确保在有效期内出现问题时仍可追溯检验。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 99 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0100","type":"boolean","qtype":"判断题","stem":"发现患者受到放射性超剂量危害时，仅口头通知即可，无需记录。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"发现患者受到放射性超剂量危害时，必须详细记录事件经过、调查处理情况，并按规定上报，不能仅口头通知而不记录。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n第二十一条　放射性药品的生产、经营、使用单位，必须制定放射性事故应急预案，并定期演练。\n发生放射性超剂量危害时，应详细记录、调查处理并按规定上报，是辐射安全和质量管理的基本要求。\n\n---","source":{"file":"判断题/91-100.md","merged":"判断题1-110.md","location":"第 100 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0101","type":"boolean","qtype":"判断题","stem":"边检验边放行的放射性药品发现质量问题时，无需通知使用单位。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"边检验边放行的放射性药品发现质量问题时，必须立即通知使用单位停止使用，并采取相应控制措施，不能无需通知。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n边检验边放行是放射性药品的特殊放行方式，企业需建立药品追踪系统，发现质量问题立即通知使用单位停止使用，并向临床提供信息和技术指导，确保患者安全。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 101 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0102","type":"boolean","qtype":"判断题","stem":"不合格放射性药品可在生产部门监督下处置，无需质量管理部门参与。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"不合格及退回/召回放射性药品的处置必须由质量管理部门监督，并按放射性规定处置，不能仅由生产部门监督。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十一条　放射性药品生产、经营企业，必须建立严格的放射性药品管理制度，防止放射性药品丢失、被盗、泄漏。\n第十三条　放射性药品生产、经营企业，必须建立严格的质量管理制度。\n不合格放射性药品的处置需质量管理部门监督，并按放射性规定处置，防止放射性污染和扩散。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 102 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0103","type":"boolean","qtype":"判断题","stem":"企业无需取得《辐射安全许可证》即可生产放射性药品。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"企业生产放射性药品必须取得《辐射安全许可证》，并符合国家有关放射性同位素安全和防护的规定与标准，无许可证一律不准生产。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准，并履行环境影响评价文件的审批手续；无许可证的生产、经营企业，一律不准生产、销售放射性药品。\n《辐射安全许可证》是从事放射性药品生产活动的法定前提。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 103 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0104","type":"boolean","qtype":"判断题","stem":"只需对生产人员进行辐射剂量监测，维修人员无需监测。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"辐射剂量监测对象包括生产人员、检验人员和维修人员等直接从事放射性药品相关工作的人员，不能仅对生产人员监测。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n维修人员如直接接触放射性物质或进入放射性工作区，也需进行辐射剂量监测，符合职业健康管理要求。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 104 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0105","type":"boolean","qtype":"判断题","stem":"从事放射性药品生产的操作人员无需配备防护用品。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"从事放射性药品生产的操作人员必须配备防护用品，如铅衣、铅眼镜、辐射剂量计等，以保障人员安全。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十条　开办放射性药品生产、经营企业，必须具备《药品管理法》规定的条件，符合国家有关放射性同位素安全和防护的规定与标准。\n第二十条　放射性药品的生产、经营、使用单位，必须对直接从事放射性药品生产、经营、使用的人员进行辐射剂量监测和职业健康检查。\n配备防护用品是辐射安全防护的基本要求，符合上述条款。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 105 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0106","type":"boolean","qtype":"判断题","stem":"放射性废物可随意处置，无需符合国家规定。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性废物必须按国家规定处置，配备专用容器，分类存放，并达到排放标准后按环保要求处置，不能随意处置。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第十三条　放射性药品生产、经营企业，必须配备与生产、经营放射性药品相适应的专业技术人员，具有安全、防护和废气、废物、废水处理等设施，并建立严格的质量管理制度。\n放射性废物处理需符合国家规定，企业需配备废物处理设施，确保辐射安全和环境保护。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 106 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0107","type":"boolean","qtype":"判断题","stem":"正电子类放射性药品是指含有发射正电子的放射性核素的药品。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["A"],"explanation":"正电子类放射性药品是指含有发射正电子的放射性核素（如氟[18F]、碳[11C]等）的药品，用于PET显像等诊断或治疗。题目描述正确。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n正电子类放射性药品含发射正电子的核素，属于放射性药品范畴，需按本办法管理。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 107 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0108","type":"boolean","qtype":"判断题","stem":"即时标记放射性药品是指生产时提前标记好的药品。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"即时标记放射性药品是指临用前通过发生器淋洗得到放射性核素洗脱液，再加入配套药盒进行标记反应生成的药品，并非生产时提前标记好的药品。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n即时标记药品需在临用前进行标记，以保证放射性活度和质量，符合本办法对放射性药品的定义和管理要求。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 108 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0109","type":"boolean","qtype":"判断题","stem":"放射性药品配套药盒包含放射性核素，可直接使用。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性药品配套药盒本身不含放射性核素，需与淋洗得到的放射性核素洗脱液配合使用，经标记反应后方可使用，不能直接使用。题目描述错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n第五条　研制单位对放射免疫分析药盒必须进行可测限度、范围、特异性、准确度、精密度、稳定性等方法学的研究。\n配套药盒需与放射性核素配合使用，本身不含放射性核素，不能直接使用。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 109 题"},"tags":[],"reviewStatus":"verified","flags":[]},{"id":"RP-B-0110","type":"boolean","qtype":"判断题","stem":"放射性核素发生器可从短半衰期母体核素分离长半衰期子体核素。（ ）","options":[{"key":"A","text":"正确"},{"key":"B","text":"错误"}],"answer":["B"],"explanation":"放射性核素发生器利用长半衰期母体核素衰变生成短半衰期子体核素，并分离得到子体核素，而非从短半衰期母体分离长半衰期子体。题目描述颠倒，错误。","lawTitle":"《放射性药品管理办法》相关条例","law":"第二条　放射性药品是指用于临床诊断或者治疗的放射性核素制剂或者其标记药物。\n放射性核素发生器是生产短半衰期放射性核素的重要工具，母体半衰期长，子体半衰期短，便于临床即时使用。\n\n---","source":{"file":"判断题/101-110.md","merged":"判断题1-110.md","location":"第 110 题"},"tags":[],"reviewStatus":"verified","flags":[]}]

